        \begin{array}{l}
            \left\{
            \begin{array}{lcll}
            \argmin_{\mathbf{w}} & \rm{risk}_i(\mathbf{R}^T\mathbf{w}) + \mathcal{L}(\mathbf{w}) & & \\
            \text{s.t.} & \mathbf{w}^T{\boldsymbol \mu} \geq \mu_{\min} & & \\
            & \mathbf{A} \mathbf{w} \geq \mathbf{b} & & \\
            & \rm{risk}_{j}(\mathbf{R}^T\mathbf{w}) \leq \rm{risk}_j^{\max}, \forall \; i\neq j & &
            \end{array}
            \right.
        \end{array}
        $
        &
        $\displaystyle
        \begin{array}{l}
            \left\{
            \begin{array}{lcll}
            \argmax_{\mathbf{w}} & \mathbf{w}^T{\boldsymbol \mu} - \mathcal{L}(\mathbf{w}) & & \\
            \text{s.t.} & \mathbf{A} \mathbf{w} \geq \mathbf{b} & & \\
            & \rm{risk}_{j}(\mathbf{R}^T\mathbf{w}) \leq \rm{risk}_j^{\max},  \forall \; j & &
            \end{array}
            \right.
        \end{array}
        $ \\
        \\
        \textbf{Maximize Utility}  &
        \textbf{Maximize Ratio} \\
        %%%%%%%%%%% MAXIMIMIZE UTILITY %%%%%%%%%%%
        $\displaystyle
        \begin{array}{l}
            \left\{
            \begin{array}{lcll}
            \argmax_{\mathbf{w}} & \mathbf{w}^T\mu - \lambda \times \rm{risk}_i(\mathbf{R}^T\mathbf{w}) - \mathcal{L}(\mathbf{w}) & & \\
            \text{s.t.} & \mathbf{w}^T\mu \ge \mu_{\min} & & \\
            & \mathbf{A} \mathbf{w} \geq \mathbf{b} & & \\
            & \rm{risk}_{j}(\mathbf{R}^T\mathbf{w}) \leq \rm{risk}_j^{\max},  \forall \; j & &
