            \argmax_{\mathbf{w}} & \dfrac{\mathbf{w}^T{\boldsymbol \mu}}{\rm{risk}_{i}(\mathbf{R}^T\mathbf{w})} - \mathcal{L}(\mathbf{w}) & & \\
            \text{s.t.} & \mathbf{w}^T\mu \geq \mu_{\min} & & \\
            & \mathbf{A} \mathbf{w} \geq \mathbf{b} & & \\
            & \rm{risk}_{j}(\mathbf{R}^T\mathbf{w}) \leq \rm{risk}_j^{\max},  \forall \; j & &
