    \centering
    \includegraphics[width = .45\textwidth]{rossler_01_appli_orbites_fig-crop.pdf}
    \put(-180,140){\large \textbf{A}}
    \includegraphics[width = .45\textwidth]{rossler_01b_appli_orbites_fig-crop.pdf}
