    \label{fig:rossler_01ab_appli_orbites}
\end{figure}

\begin{figure}[htb]
    \centering
    \includegraphics[width = .45\textwidth]{rossler_01c_appli_orbites_fig-crop.pdf}
    \put(-182,150){\large \textbf{A}}
    \qquad \qquad \includegraphics[width = .3\textwidth, trim=0 5cm 0 0]{gabarit_trois_bandes.pdf}
    \put(-120,140){\large \textbf{B}}
    \\\medskip
    \qquad \qquad \includegraphics[width = .5\textwidth]{rossler_01c_Nins_1011_101110_fig-crop.pdf}
    \put(-220,30){\large \textbf{C}} \hfill \null
    \caption{
    \textbf{Topological characterisation of the Rössler attractor considering three distinct branches.}
    A. First return map of a Poincaré section with two components, separating out the additional decreasing branch. From branch $0$, only transition to branch $\overline{1}$ are possible.
    B. Template with three branches including a separation between the two components. The separation between $1$ and $\overline{1}$ is virtual as it is underlined by dashed line. \eqref{eq:rossler_trois_bandes} is the linking matrix describing this template.
    C. Linking graph used to theoretically compute linking numbers between orbits $N_\text{insertion}=2$ \eqref{eq:n_insertion}.}
    \label{fig:rossler_01c_appli_orbites}
