\begin{remark}
    The only prerequisite for initiating the distributed optimization algorithm is knowledge of the graph diameter $d(\mathcal{G})$. Importantly, $d(\mathcal{G})$  can be efficiently estimated in a distributed manner using standard algorithms such as max-consensus \cite{Garin2012} in $2d(\mathcal{G})$ steps. This opens the possibility to address occasional changes in the graph, e.g., link failures or node failures.
\end{remark}
\subsection{Distributed Node Weight Update}
\label{subsec: distributed node weight update}
Solving \cref{eq: overall iterative algorithm for node weighted Laplacian 1} via the gradient algorithm requires taking derivatives of the Lagrangian with respect to the $\mathbf{w}$. This needs the derivative of the largest and Fiedler eigenvalues. The following theorem guarantees that the projected gradient descent converges to the global minimizer of the sub-problem for \cref{eq: overall iterative algorithm for node weighted Laplacian 1}.
\begin{theorem}
    \label{theorem: distributed node weight update}
    Suppose ${\mathbf{w}}(0)> 0,{\sigma}\geq 0,{\rho}>0$. Consider the following dynamics:
    \begin{gather}
        \label{eq: distributed node weight update}
        {w}_i(t+1)=\max\left\{
        w_i(t)-\gamma \frac{\partial {\mathscr{L}}_{{\rho}}}{\partial {w}_i}\left(
        \mathbf{w}(t),\sigma
        \right),0
        \right\}
        ,\ i=1,\cdots,N,
    \end{gather}
    where $\gamma>0$ is the step size. For sufficiently small $\gamma$, the algorithm converges to the global optimal solution of \cref{eq: overall iterative algorithm for node weighted Laplacian 1}.
\end{theorem}

The convergence of \cref{eq: distributed node weight update} follows from that the augmented Lagrangian function is a convex function in $\mathbf{w}$ (demonstrated in \cref{subsubsec: Adjusting the Weights on the Nodes}) and the projected gradient descent converges to the global minimum of a convex function. To obtain the derivatives, we rely on the following lemma to find the derivative of the eigenvalue.
\begin{lemma}
    \label[lemma]{lemma: derivative of the eigenvalue} \cite{Magnus1985} Consider a Hermitian matrix $H(x)\in\mathbb{S}^N$ whose components are differentiable functions of $x$. Suppose the eigenvalue $\lambda(H(x))$ is simple, the differential of the eigenvalue with respect to $x$ is:
    \begin{gather*}
        \frac{\partial {\lambda}\left(H(x)\right)}{\partial x}={u}^T\frac{\partial H(x)}{\partial x}{u},
    \end{gather*}
    where ${u}$ is the eigenvectors corresponding to the eigenvalue $\lambda$ with $\|u\|=1$.
\end{lemma}


\begin{remark}
    In \cref{lemma: derivative of the eigenvalue}, the eigenvalue $\lambda(H(x))$ is required to be simple, for which the gradient is well defined. In some cases, the eigenvalues of interest may be repeated, e.g., star graph, cycle graph, complete graph, etc. The eigenvalues are continuous, but not differentiable \cite{Clarke1990} in such cases. We obtain the same result by leveraging the subgradient method. The details are discussed in \cref{sec: non-simple eigenvalues}.
\end{remark}

Denote the unit eigevector corresponding to a simple eigenvalue $\lambda(\hat{\mathcal{L}}_{{\mathbf{w}}})$ of weighted Laplacian matrix $\hat{\mathcal{L}}_{{\mathbf{w}}}$ as $v$.
With \cref{lemma: derivative of the eigenvalue,eq: node weighted Laplacian matrix 2}, the differential of the eigenvalue $\lambda(
    {\hat{\mathcal{L}}}_{{\mathbf{w}}}
    )$ with respect to the $i$th node weight ${w}_i$ is:
\begin{align*}
    \frac{\partial \lambda\left(
        {\hat{L}}_{{\mathbf{w}}}
        \right)}{\partial {w}_i}
     & ={v}^T\left\{
    \frac{\partial}{\partial w_i}\diag({\mathbf{w}})^{\frac{1}{2}}\mathcal{L}\diag({\mathbf{w}})^{\frac{1}{2}}+\diag({\mathbf{w}})^{\frac{1}{2}}\mathcal{L}\frac{\partial}{\partial w_i}\diag({\mathbf{w}})^{\frac{1}{2}}
    \right\}{v},                                                                                    \\
     & =\begin{bmatrix}
            0                       &
            \cdots                  &
            {w}_i^{-\frac{1}{2}}v_i &
            \cdots                  &
            0
        \end{bmatrix}\mathcal{L}\diag(\mathbf{w})^{\frac{1}{2}}v =v_i\sum_{j\in\mathcal{N}_i}\left[
    v_i-\left(\frac{w_j}{w_i}\right)^{\frac{1}{2}}v_j
    \right].
\end{align*}
where $v_i$ is the $i$th entry of the eigenvector $v$. With above relation, the partial derivative of the augmented Lagrangian \cref{eq: overall iterative algorithm for node weighted Laplacian 1} with respect to the $i$th node weight, ${w}_i$, is:
\begin{gather}
    \label{eq: partial derivative of the augmented Lagrangian}
    \begin{aligned}
        \frac{\partial {\mathscr{L}}_{{\rho}}}{\partial {w}_i}({\mathbf{w}},{\sigma})
         & =\frac{\partial \lambda_N\left(
            \hat{\mathcal{L}}_{{\mathbf{w}}}
            \right)}{\partial {w}_i}-{\rho}\left[
            {\max}\left\{
            0,1-\lambda_2\left(
            {\hat{\mathcal{L}}}_{{\mathbf{w}}}
            \right)+\frac{{\sigma}}{{\rho}}
            \right\}
            \right]\frac{\partial \lambda_2\left(
            \hat{\mathcal{L}}_{{\mathbf{w}}}
        \right)}{\partial {w}_i}                     \\
         & =\bar{v}_i \sum_{j\in\mathcal{N}_i}\left[
        \bar{v}_i-\left(\frac{w_j}{w_i}\right)^{\frac{1}{2}}\bar{v}_j
        \right]-\rho\left[
            \max\left\{
            0,1-\lambda_2\left(
            \hat{\mathcal{L}}_{{\mathbf{w}}}
            \right)+\frac{{\sigma}}{{\rho}}
            \right\}
            \right]\underline{v}_i \sum_{j\in\mathcal{N}_i}\left[
        \underline{v}_i-\left(\frac{w_j}{w_i}\right)^{\frac{1}{2}}\underline{v}_j
        \right].
    \end{aligned}
\end{gather}
where $\bar{v},\underline{v}$ are the unit eigenvectors corresponding to the largest and Fiedler eigenvalues, and $\bar{v}_i,\underline{v}_i$ mean the $i$th entry of the $\bar{v},\underline{v}$, respectively. The derivative of the augmented Lagrangian function with respect to the $i$th node weight ${w}_i$ requires the neighbors' weights $w_j$, the $i$th and $j$th entries of the unit largest and Fiedler eigenvectors, as well as the Fiedler eigenvalue. This property allows the distributed implementation of the weight updates.

For full distribution update, at each step of \cref{eq: distributed node weight update}, the $i$th agent should get the following information ready for calculation and to share with its neighbor:
\begin{inlineenum}
    \item The $i$th entry of the largest and Fiedler eigenvectors,
    \item The Fiedler value of $\mathcal{L}_\mathbf{w}$,
    \item Lagrangian multiplier $\sigma$ and parameter $\rho$, which are fixed during the iteration of \cref{eq: overall iterative algorithm for node weighted Laplacian 1} and shared among the network.
\end{inlineenum}

The first information is obtained inside the inner iteration, where the power iteration is employed to estimate the largest and Fiedler eigenvectors. Once the eigenvectors are estimated, the Fiedler value can be obtained simply by the definition of the eigenvalue. The parameter $\rho$ is a fixed constant that is set beforehand. The Lagrangian multiplier $\sigma$, on the other hand, relies on the uniform estimation of the Fiedler value and is updated by \cref{eq: overall iterative algorithm for node weighted Laplacian 2}. If each agent's copy of $\sigma$ starts with the same initial value, it will remain the same as long as every agent's estimation of the Fiedler value is the same, by \cref{eq: overall iterative algorithm for node weighted Laplacian 2}.
\subsection{Eigen-pair Estimation}
\label{subsec: Eigen-pair Estimation}
Time step $t$ is used to denote the steps in the update of \cref{eq: distributed node weight update}. Once $\mathbf{w}(t)$ is updated, new eigenvalues and eigenvectors for the new weighted Laplacian matrix $\mathcal{L}_{\mathbf{w}(t)}$ are required to be estimated. For this, the outer iteration $t$ is paused, and the inner iteration $T$ is started. Once the estimates are converged within the stopping criteria, the outer iteration $t$ is resumed using \cref{eq: distributed node weight update}.

The estimator is composed of three parts: the largest eigen-pair estimator, the Fiedler eigen-pair estimator, and the normalization block. Estimating the largest eigen-pair is leveraging the power iteration algorithm for the extreme eigenvalues, which can be performed in a distributed manner. The Fiedler eigen-pair estimator, on the other hand, is more challenging, for which we modify the ideas proposed by Bertrand et al \cite{Bertrand2013}. The normalization block is to distributedly find the eigenvectors with Euclidean norm equal to one.
\subsubsection{Max-consensus}

The power iteration requires vector normalization, particularly Euclidean, which is computationally intensive in distributed systems. To address this problem, we employ the max-consensus algorithm to obtain the infinity norm in finite time.

\begin{lemma}
    \label{lemma: max consensus} \cite{Lucchese2015,Nejad2009}
    Consider a graph $\mathcal{G}=(\mathcal{V},\mathcal{E})$, a vector $p\in\mathbb{R}^{|\mathcal{V}|}$ with the $i$th entry initialized on $i$th agent to be $p_i(0)$.  With the max-consensus algorithm \cref{eq: pure max consensus}:
    \begin{gather}
        \label{eq: pure max consensus}
        p_i(T+1)=\max_{j\in\mathcal{N}_i}\left\{
        p_j(T),p_i(T)
        \right\},\ \forall i\in\mathcal{V},
    \end{gather}
    the vector $p$ converges to the $\left\|p(0)\right\|_\infty\mathbf{1}_{|\mathcal{V}|}$ in at most $d(\mathcal{G})$ steps, i.e. $ p(T)=\left\|p(0)\right\|_\infty\mathbf{1}_{|\mathcal{V}|},\forall T\geq d(\mathcal{G})$.
\end{lemma}

As discussed in \cite{Garin2012}, the diameter of the graph can be estimated within $2d(\mathcal{G})$ iterations. With the knowledge of the graph diameter, the max-consensus algorithm can be terminated at most $d(\mathcal{G})$ steps. In this paper, we repeatedly employ the max-consensus algorithm to normalize the eigenvectors of the weighted Laplacian matrix.


\subsubsection{Largest Eigen-pair Estimator}
\label{subsec: Finding the largest eigenvalue}
A variation of the well-known power iteration method \cite{Corso1997,Lin2010} is used, due to the ease for distributed implementation. It only involves distributed elementary matrix-vector multiplication and scalar multiplication. Once converged, $\lambda_N$ can be obtained easily (\cref{subsec: Finding the eigenvalue}). Consider the following modified power iteration formula:
\begin{gather}
    \label{eq: central distributed power iteration using infty norm}
    \hat{x}(T+1)=\frac{\hat{\mathcal{L}}_\mathbf{w}x(T)}{\left\|\hat{\mathcal{L}}_\mathbf{w}x(T)\right\|_\infty}.
\end{gather}

Here, we rely on the max-consensus algorithm employed in \cref{eq: central distributed power iteration using infty norm} for normalization, which is a simple scaling of the 2-norm typically used. After each multiplication, the scaling will be done via the max-consensus algorithm in $d(\mathcal{G})$ steps.

First, a multiplication of the weighted Laplacian matrix $\hat{\mathcal{L}}_\mathbf{w}$ with the vector $x$ is performed, which is a distributed operation:
\begin{gather}
    \label{eq: distributed multiplication of the weighted Laplacian matrix}
    \left[
        \hat{\mathcal{L}}_\mathbf{w}x(T)
        \right]_i=w_i^{\frac{1}{2}}\sum_{j\in\mathcal{N}_i} \left[
    w_{i}^{\frac{1}{2}}x_i(T)-w_j^{\frac{1}{2}}x_j(T)
    \right],\ \forall i\in\mathcal{V},
\end{gather}
where the notation $[\cdot]_i$ means the $i$th entry of the vector. Then, the max-consensus algorithm \cref{eq: pure max consensus} is used to find the infinity norm of the vector $\hat{\mathcal{L}}_\mathbf{w}x(T+1)$, which takes $d(\mathcal{G})$ steps. Finally, the vector is normalized by dividing the infinity norm, which takes another step. Then $T$ becomes $T+1$ and the process is repeated. The iteration convergence ratio is known to be $\left({\lambda_{N-1}(\mathcal{L}_{\mathbf{w}})}/{\lambda_{N}(\mathcal{L}_{\mathbf{w}})}\right)$.


\subsubsection{Fiedler Eigen-pair Estimator}
The Fiedler eigen-pair is the second smallest eigenvalue of the matrix $\hat{\mathcal{L}}_\mathbf{w}$, and a method of ruling out the natural zero eigenvalue is needed. We leverage the idea proposed by Bertrand et al. \cite{Bertrand2013} and modify it for node weighted Laplacian matrix as well as the max consensus. Consider the auxiliary matrix
$$\mathcal{L}^c_\mathbf{w}=I-\frac{1}{\alpha}\hat{\mathcal{L}}_\mathbf{w},$$
where $\alpha>\frac{\lambda_2(\hat{\mathcal{L}}_\mathbf{w})+\lambda_N(\hat{\mathcal{L}}_\mathbf{w})}{2}$, such that $1-\frac{1}{\alpha}\lambda_2\left(
    \hat{\mathcal{L}}_\mathbf{w}
    \right)$ is the second extreme eigenvalue. A practical choice can be
\begin{gather}
    \alpha = \left\{
    \begin{array}{lc}
        \lambda_N(\mathcal{L}_\mathbf{w})                                & \text{if } \lambda_N(\mathcal{L}_\mathbf{w}) \text{ is found } \\
        \displaystyle\max_{i=\{1,\dots,N\}} 2\sum_{j\in\mathcal{N}_i}w_i & \text{otherwise}
    \end{array}
    \right.,
\end{gather}
The second value is found by applying the Gershgorin circle theorem \cite{Horn2012} for the weighted Laplacian matrix $\mathcal{L}_\mathbf{w}$, which can be distributed to every agent using max-consensus. With the appropriate choice of $\alpha$, consider the following dynamics
\begin{gather}
    \label{eq: central Fiedler eigen-pair estimator}
    y(T+1)=\left\{
    \begin{array}{lc}
        \frac{\hat{\mathcal{L}}_\mathbf{w} y(T)}{\left\|\hat{\mathcal{L}}_\mathbf{w} y(T)\right\|_\infty} & \qquad T \text{ mod } p=0, \\[4mm]
        \frac{\mathcal{L}^c_\mathbf{w} y(T)}{\left\|\mathcal{L}^c_\mathbf{w} y(T)\right\|_\infty}         & \qquad \text{otherwise},
    \end{array}
    \right.
\end{gather}
Recall the range space of $\hat{\mathcal{L}}_{\mathbf{w}}$ defined in \cref{eq: range space of the node weighted Laplacian matrix}. The main idea in \cref{eq: central Fiedler eigen-pair estimator} is to only search in the space $\mathcal{S}$, in which the Fiedler eigenvector of $\hat{\mathcal{L}}_{\mathbf{w}}$ corresponds to the extreme eigenvalue of the matrix $\mathcal{L}^c_\mathbf{w}$. Ideally, this can be done by multiplying $\hat{\mathcal{L}}_\mathbf{w}$ once, which corresponds to the case $p=\infty$, after which $y(T)\in\mathcal{S}$ for all following updates. However, in practice, the calculation error inevitably introduces the direction $\diag(\mathbf{w})^{-\frac{1}{2}}\mathbf{1}_N$ back, which will be amplified during the multiplication of $\mathcal{L}^c_\mathbf{w}$. Therefore, from time to time (every $p$ round), $\hat{\mathcal{L}}_{\mathbf{w}}$ is introduced to eliminate the $\diag(\mathbf{w})^{-\frac{1}{2}}\mathbf{1}_N$ in $y(T)$.

As demonstrated in \cite{Bertrand2013}, a rather tight bound can be obtained by choosing $p$ to be
\begin{gather}
    p\geq \frac{\alpha}{\lambda_2(\mathcal{L}_\mathbf{w})}=\frac{\lambda_N(\mathcal{L}_\mathbf{w})}{\lambda_2(\mathcal{L}_\mathbf{w})},
\end{gather}
which is exactly the loss function of the optimization problem here. In the very first iteration, when the agents know nothing about $\lambda_2(\mathcal{L})$, a lower bound \cite{Lu2007} of $\lambda_2(\mathcal{L})$ can be replaced to obtain $p$:
\begin{gather}
    \label{eq: choice of p with lower bound}
    \lambda_2(\mathcal{L}) \geq \frac{4d(\mathcal{G})}{d(\mathcal{G})+1}\Rightarrow p\geq\left\lceil \frac{\lambda_N(\mathcal{L})\left[d(\mathcal{G})+1\right]}{4d(\mathcal{G})}\right\rceil.
\end{gather}

The distributed implementation of \cref{eq: central Fiedler eigen-pair estimator} follows the same argument as the largest eigen-pair estimator in \cref{eq: distributed multiplication of the weighted Laplacian matrix}:
\begin{gather*}
    \left[
        \mathcal{L}^c_\mathbf{w}y(T)
        \right]_i= y_i(T)-\frac{1}{\alpha} w_i^{\frac{1}{2}}\sum_{j\in\mathcal{N}_i}\left[
    w_i^{\frac{1}{2}}y_i(T)-w_j^{\frac{1}{2}}y_j(T)
    \right],\ \forall i\in\mathcal{V}.
\end{gather*}
\subsubsection{Normalization}
When applying the gradient of the augmented Lagrangian method \cref{eq: partial derivative of the augmented Lagrangian}, it is necessary for the eigenvectors to satisfy the unit Euclidean-norm condition ($\|x\|_2 = 1$) as stated in \cref{lemma: derivative of the eigenvalue}, instead of the infinity norm used above. For this, an additional normalization step is then required. To apply the $l_2$ normalization, a consensus on the square of the states is performed using the original Laplacian matrix $\mathcal{L}$ as the communication matrix:
\begin{subequations}
    \label{Normalization procedure}
    \begin{align}
        \label{Normalization procedure for x}
        \tilde{x}_i(T+1) & = \tilde{x}_i(T) - \frac{1}{\beta} \sum_{j \in \mathcal{N}_i}  \left[ \tilde{x}_i(T) - \tilde{x}_j(T) \right], \\
        \label{Normalization procedure for y}
        \tilde{y}_i(T+1) & = \tilde{y}_i(T) - \frac{1}{\beta} \sum_{j \in \mathcal{N}_i}  \left[ \tilde{y}_i(T) - \tilde{y}_j(T) \right],
    \end{align}
\end{subequations}
where $x^*,y^*$ are the limit vectors obtained through \cref{eq: central distributed power iteration using infty norm,eq: central Fiedler eigen-pair estimator}, and initial conditions are $\tilde{x}_i(0) = (x_i^*)^2$ and $\tilde{y}_i(0) = (y_i^*)^2, \forall i\in\mathcal{V}$. As stated in the motivating example \cref{eq: optimal stepsize for real average consensus}, the optimal choice of $\beta$ is:
\begin{gather*}
    \beta=\frac{\lambda_N(\mathcal{L})+\lambda_2(\mathcal{L})}{2},
\end{gather*}
which should be distributedly available to all agents after each estimation of the largest and Fiedler eigen-pairs.
