\bmsection{Optimization Approaches}%
\label{sec: Optimization Approaches}
\vspace*{12pt}
The problems discussed in this paper can be framed as convex optimization problems. Some constraints are imposed to ensure the uniqueness of the optimal solution. It is well-known that the convex optimization problem can be solved by various methods, such as the interior point method, the penalty and barrier method, the primal-dual method, etc \cite{Luenberger2008}. Because the optimal solution is expected to be on the boundary of the search space, the augmented Lagrangian method is introduced. To further guarantee the positivity of the weights, the projected gradient descent method is introduced to facilitate solving the subproblem in the augmented Lagrangian method.
\bmsubsection{Augmented Lagrangian Method}
\label{subsec: Augmented Lagrangian Method}
Consider the following optimization problem:
\begin{gather}
    \label{eq: general optimization problem}
    \begin{aligned}
        \min_{x}    & \quad f(x) \\
        \text{s.t.} & \left\{
        \begin{array}{l}
            h(x) = 0, \\
            g(x)\leq 0.
        \end{array}
        \right.
    \end{aligned}
\end{gather}
where $h(x)\in\mathbb{R}^m$ and $g(x)\in\mathbb{R}^p$ are the equality and inequality constraints, respectively. Define the augmented Lagrangian function as:
\begin{gather*}
    \mathscr{L}_{\rho}(x, \mu, \sigma) = f(x) + \sum_{i=1}^m\frac{\rho}{2}\left[
        h_i(x) + \frac{\mu_i}{\rho}
        \right]^2 + \sum_{j=1}^p\frac{\rho}{2}\left[
        \max\left\{
        0, g_j(x) + \frac{\sigma_j}{\rho}
        \right\}
        \right]^2,
\end{gather*}

The augmented Lagrangian method is an iterative method solving the following subproblems:
\begin{gather*}
    \begin{aligned}
        x^{k+1}        & = \argmin_{x} \mathscr{L}_{\rho}(x, \mu^k,\sigma^k) &               \\
        \mu^{k+1}_i    & = \mu^k_i + \rho h_i(x^{k+1}),                      & i=1,\cdots,m, \\
        \sigma^{k+1}_j & = {\max}\left\{
        \sigma^k_j  + \rho g_j(x^{k+1}),0
        \right\},      & j=1,\cdots,p.
    \end{aligned}
\end{gather*}

Paper \cite{Birgin2014} shows that the augmented Lagrangian method converges to the points that satisfy the Karush-Kuhn-Tucker conditions of the original optimization problem; that is, in convex optimization problems, the augmented Lagrangian method converges to the global optimal solution.

\subsection{Projected Gradient Descent}
\label{subsec: Projected Gradient Descent}
It is common that the search space of the subproblem in the augmented Lagrangian method is a convex set. In this paper, the convex set is the non-negative orthant. Consider the following optimization problem:
\begin{gather}
    \label{eq: optimization problem w/ convex set}
        \min_{x}  f(x), \quad  s.t.   x\in\mathcal{X},
\end{gather}
where $\mathcal{X}$ is a closed convex set. Define the projection operator as $
    \mathcal{P}_{\mathcal{X}}(x) = \argmin_{y\in\mathcal{X}}\|y-x\|_2.
$
The unique existence of the projection operator follows from the Hilbert projection theorem \cite{Dimitri2015}. The projection gradient descent method is:
\begin{gather*}
    x^{k+1}= \mathcal{P}_{\mathcal{X}}\left[
        x^k-\alpha \nabla f(x^k)
        \right],
\end{gather*}
where $\alpha>0$ is the step size. The descent property of the projection gradient descent method follows by letting $z=x^k-\alpha \nabla f(x^k),x^{k+1}=\mathcal{P}_{\mathcal{X}}\left(
    z
    \right),$ and $x=x^k$  in Projection Theorem \cite{Ciarlet2013,Dimitri2015}:
\begin{gather*}
    \label{eq: Bourbaki-Cheney-Goldstein inequality}
    \langle z-\mathcal{P}_{\mathcal{X}}(z),x-\mathcal{P}_{\mathcal{X}}(z)\rangle \leq 0,\forall x \in \mathcal{X},\\
    \left\langle x^k-\alpha \nabla f(x^k)-x^{k+1},x^k-x^{k+1}\right\rangle \leq 0,\\
    \alpha\left\langle \nabla f(x^k),x^{k+1}-x^k\right\rangle \leq -\left\|x^k-x^{k+1}\right\|^2\leq 0.
\end{gather*}
Therefore, the projection gradient descent method is guaranteed to converge to the optimal solution for the convex optimization problem.
\bmsection{On optimization problems}%
\bmsubsection{Proof that \cref{eq: optimal stepsize for real average consensus} is the solution to \cref{eq: min max problem for average consensus}}
\label{sec: Optimization Approaches.1a}
\begin{proof}
    With \cref{assumption: undirected connected graph}, the eigenvalues of Laplacian can be ordered $0< \lambda_2(\mathcal{L})\leq \cdots \leq \lambda_N(\mathcal{L})$. Problem \cref{eq: optimal stepsize for real average consensus} can be rewritten as the following problem using the slack variable $\eta$:
    \begin{gather*}
        \min_{r\in\mathbb{R}_+}  \quad \eta   \quad
        \text{s.t. }            \quad  \left\{
        \begin{array}{lc}
            -\eta\leq 1-\frac{1}{r}\lambda_i(\mathcal{L}), & \quad \forall i=\{2,\cdots, N\} \\
            1-\frac{1}{r}\lambda_i(\mathcal{L})\leq \eta,  & \quad \forall i=\{2,\cdots, N\}
        \end{array}
        \right.
    \end{gather*}

    Since $\eta$ is greater than any $1-\frac{1}{r}\lambda_i(\mathcal{L})$, it is equivalent to bound it from below using the maximum value of $1-\frac{1}{r}\lambda_i(\mathcal{L})$, which yields $\eta\geq  1-\frac{1}{r}\lambda_2(\mathcal{L})$. Similarly, the negative $\eta$ needs to be bounded by the minimum, which yields $-\eta\leq 1-\frac{1}{r}\lambda_N(\mathcal{L})$. Therefore, an equivalent problem is:
    \begin{gather*}
        \min_{r\in\mathbb{R}_+}  \quad \eta    \quad
        \text{s.t. }             \quad  \left\{
        \begin{array}{l}
            -\eta\leq 1-\frac{1}{r}\lambda_N(\mathcal{L}), \\
            1-\frac{1}{r}\lambda_2(\mathcal{L})\leq \eta,
        \end{array}
        \right.
    \end{gather*}

    The Lagrangian function associated with the above problem is:
    \begin{gather*}
        \mathcal{L}(r,\eta,\mu_1,\mu_2)=\eta+\mu_1\left(
        \frac{1}{r}\lambda_N(\mathcal{L})-1-\eta
        \right)+\mu_2\left(
        1-\frac{1}{r}\lambda_2(\mathcal{L})-\eta
        \right),
    \end{gather*}
    where $\mu_1,\mu_2$ are the Lagrange multipliers. The KKT conditions for the above problem are:
    \begin{subequations}
        \label{eq: KKT conditions for min max problem}
        \begin{align}
            \label{eq: KKT conditions for min max problem 1}
            \frac{\partial \mathcal{L}}{\partial \eta}  =1-\mu_1-\mu_2                                                                    & =0,     \\
            \label{eq: KKT conditions for min max problem 2}
            \frac{\partial \mathcal{L}}{\partial r}     =-\frac{\mu_1}{r^2}\lambda_N(\mathcal{L})+\frac{\mu_2}{r^2}\lambda_2(\mathcal{L}) & =0,     \\
            \label{eq: KKT conditions for min max problem 3}
            \mu_1\left(
            \frac{1}{r}\lambda_N(\mathcal{L})-1-\eta
            \right)                                                                                                                       & =0,     \\
            \label{eq: KKT conditions for min max problem 4}
            \mu_2\left(
            1-\frac{1}{r}\lambda_2(\mathcal{L})-\eta
            \right)                                                                                                                       & =0,     \\
            \label{eq: KKT conditions for min max problem 5}
            \mu_1,\mu_2                                                                                                                   & \geq 0.
        \end{align}
    \end{subequations}

    Solving \cref{eq: KKT conditions for min max problem 1,eq: KKT conditions for min max problem 2} finds that $\mu_1=\frac{\lambda_2(\mathcal{L})}{\lambda_2(\mathcal{L})+\lambda_N(\mathcal{L})},\mu_2=\frac{\lambda_N(\mathcal{L})}{\lambda_2(\mathcal{L})+\lambda_N(\mathcal{L})}$, with which \cref{eq: KKT conditions for min max problem 3,eq: KKT conditions for min max problem 4} together imply \cref{eq: optimal stepsize for real average consensus}
\end{proof}

\bmsubsection{The LMI formulation of the problem}
\label{subsec: LMI formulation}
It can be shown that not only are the problems \cref{eq: modified finite conditional number problem for node weighted Laplacian} convex, but they can also be framed into LMI problems, and solved by modern SDP methods. This section serves as an alternate way to demonstrate that the problem discussed in the paper is convex. Furthermore, the optimal solution found by the LMI formulation will be used as the benchmark to evaluate the performance of the distributed algorithms. For the node weight optimization problem, adopt the notation as in the proof of \cref{lemma: convexity of the optimization problem}. The problem \cref{eq: modified finite conditional number problem for node weighted Laplacian} can be rewritten as:
\begin{gather}
    \label{eq: LMI formulation for node weight optimization}
    \min_{{\mathbf{w}}\in\mathbf{R}^N_+}  \quad {\kappa}\quad
    \text{s.t.}                               \quad {\kappa} I_{N-1}\succeq C^T\diag\left(
    \hat{\mathbf{w}}
    \right)C\succeq I_{N-1}.
\end{gather}

On the other hand, if one were to investigate the traditional edge weight, one can refer to papers \cite{Xiao2004,Shafi2012}. For completeness, here we also provide the LMI formulation for the edge weight optimization problem.
\begin{gather}
    \label{eq: LMI formulation for edge weight optimization}
    \min_{{\mathbf{w}}\in\mathbf{R}^N_+} {\kappa}, \quad \text{s.t.}  \quad {\kappa} I_{N}\succeq \mathcal{B}^T\diag\left(
    \hat{\mathbf{w}}
    \right)\mathcal{B}\succeq I_{N}-\frac{1}{N}\mathbf{1}_N\mathbf{1}_N^T.
\end{gather}

\bmsection{Algorithm related}
\subsection{Simulation parameters}
\label{subsec: Simulation parameters}
The key parameters are given in \cref{tab: parameter settings}. The overall optimization is considered to reach an optimal point when the absolute relative error of the Lagrange multiplier is less than the tolerance, e.g., $\left|\sigma^{k+1}-\sigma^k\right|\leq \varepsilon_{\sigma}$. For the outer iteration, the stopping criterion for the weight update in\cref{eq: overall iterative algorithm for node weighted Laplacian 1} is determined by any of the following conditions:
\begin{inlineenum}
    \item the maximum number of descent steps $t\leq t_{\max}$ is reached;
    \item the relative change in the objective function is less than the tolerance $\left|\lambda_N\left[
            \hat{\mathcal{L}}_{\mathbf{w}(t+1)}
            \right]-\lambda_N\left[
            \hat{\mathcal{L}}_{\mathbf{w}(t)}
            \right]\right|\leq \varepsilon_{\lambda_N}$;
    \item the relative change in the infinity norm satisfies $        \left\|
        \mathbf{w}(t+1)-\mathbf{w}(t)
        \right\|_\infty\leq \varepsilon_{\mathbf{w}}$ for four consecutive iterations.
\end{inlineenum}

On the other hand, the inner iteration for the eigen-pair estimation is considered to converge when the relative change in the eigenvalues is less than the tolerance, e.g., $x(T+1)-x(T)\leq \varepsilon_{x}$. The normalization process is considered to converge when the relative change in the normalized entries is less than the tolerance, e.g., $\left|\tilde{x}_i(T+1)-\tilde{x}_i(T)\right|\leq \varepsilon_{\tilde{x}}$. In the following simulation, an extra 50 steps are added to the bound of the periodic number $p$ in \cref{eq: choice of p with lower bound} to ensure the fast convergence of the Fielder eigenvector.

