$\pmb{J}_{CLE}$ = jacobian(RF-QRC) \Comment*[r]{Jacobian of the quantum circuit is computed in {Pennylane}\citep{bergholm2018pennylane} as in Eq.~\ref{eq:5qrca}}
\textit{Evolve the hidden state and GSVs simultaneously.}\\
\textit{Skip the initial transients for $N_{w}$ time steps}.\\
$n \gets 0$ \Comment*[r]{Increment the number of QR decompositions}
\For{$i = 0 : N_{tr}$}{
$\pmb{r}(t_{i+1}) = f(\pmb{r}(t_{i}))$  \Comment*[r]{QRC state update as in Eq.~\ref{eq:3c3}}
% $\pmb{u}(t_{i+1})= \pmb{u}_{in}(t_{i+1})$ \Comment*[r]{Input from training data}
$\pmb{J} \gets \pmb{J}(\pmb{r}(t_{i}))$ \Comment*[r]{The updated Jacobian}
$\pmb{W} \gets \pmb{J}\pmb{W}$ \Comment*[r]{The variational equation}
$\pmb{Q},\pmb{R} \gets QR{(\pmb{W})}$ \Comment*[r]{QR at every time step}
$\pmb{W} \gets \pmb{Q}$ \\

  \If{$i > N_{w}$}{
    $\pmb{\Lambda}[:,n] \gets$ log(diag$[\pmb{R}])/dt$ \Comment*[r]{Save Finite time LEs} 
    $\pmb{\tilde{R}}[:,:,n] \gets \pmb{R}$ \Comment*[r]{Save \pmb{R}}
    % $\pmb{\tilde{Q}}[:,:,n] \gets \pmb{Q}$ \Comment*[r]{Save \pmb{Q}}
    $n = n+1$; \\
    \textbf{end}
  }
  \textbf{end}
}
$\lambda_{j} = \sum^{N_{QR}}_{i=0} \Lambda[j,i]/N_{train}$ \Comment*[r]{The \textit{j}th Conditional Lyapunov exponent}
$\lambda_{CLE} = \max(\lambda_{j})$ \Comment*[r]{The largest Conditional Lyapunov exponent}
}
\end{algorithm}

First, Figure~\ref{fig:c4_LEs} (a) shows the  LEs inferred in closed loop for the Lorenz-63 system for $\epsilon$ in the range \{0,1\}. For $\epsilon$ $>$ 0.2, the spectrum is accurately inferred. For $\epsilon$ $<$ 0.2, only the positive and zero LEs are captured correctly. This is because, when the leak rate is small, the reservoir dynamics are slow, which means that the RF-QRC struggles to capture fast decaying perturbations associated with the negative LE. 

In Figure~\ref{fig:c4_LEs} (b), we show the maximum CLEs and LEs for the same $\epsilon$ as in Figure~\ref{fig:c4_LEs} (a). The magnitude of the maximum CLE grows with the leak rate $\epsilon$. For slower reservoir dynamics, when the maximum CLE is larger than most negative LE of the driving signal (max $\lambda_{CLE} > \lambda^{*}$, i.e., condition (ii) in Table~\ref{tab: CLE_GS}), the reservoir is unable to capture the negative LEs accurately. This leads to an incorrect increase in the Kaplan-Yorke dimension \citep{hart2024attractor}. Increasing the user-defined leak rate enables the tuning of the maximum CLE, thereby satisfying condition (iii) of Table~\ref{tab: CLE_GS}, which provides an accurate prediction of the entire spectrum. The same conclusion holds for the higher-dimensional Lorenz-96 system (Appendix~\ref{sec:appl96_qrc}).

