    $n = n+1$; \\
    \textbf{end}
  }
  \textbf{end}
}
$\lambda_{j} = \sum^{N_{QR}}_{i=0} \Lambda[j,i]/N_{test}$ \Comment*[r]{The \textit{j}th Lyapunov exponent}
\end{algorithm}

\section{Physical systems}
%\label{sec:AppL63}
\label{app:AppL96}

The Lorenz-63 system \citep{75462} is a reduced-order model of thermal convection flow governed by 
%
\begin{align}\label{eq:3A}
\begin{split}
    \frac{dx_{1}}{dt} = \sigma \, (x_{2}-x_{1})
\end{split}
\end{align}
\begin{align}\label{eq:3B}
\begin{split}
    \frac{dx_{2}}{dt} = x_{1} \, (\rho-x_{3}) - x_{2}, 
\end{split}
\end{align}
\begin{align}\label{eq:3C}
\begin{split}
    \frac{dx_{3}}{dt} =  x_{1}x_{2}-\beta{x_{3}},
\end{split}
\end{align}
%
where $\sigma$, $\rho$, $\beta$ are system parameters. We take [$\sigma$ , $\rho$ , $\beta$] = [10, 28, 8/3] to ensure chaotic behavior of the system. 
The Lorenz-96 model \citep{75462} is a system of coupled ordinary differential equations that describes the large-scale behavior of the mid-latitude atmosphere, and the transfer of a scalar atmospheric quantity, governed by 

\begin{align}\label{eq:18}
    \frac{dx_{i}}{dt} =  (x_{i+1}-x_{i-2}) \, x_{i-1}-{x_{i}} + F  , \quad \quad \quad i = 1, \dotsc ,m
\end{align}
%
where $F$ is the external body forcing term which we set to $F = 8$ to achieve chaotic behavior. We apply periodic boundary conditions, i.e. $x_{1} = x_{m+1}$, and study the reduced order model of Lorenz-96 with ten and twenty dimensions corresponding to $m=10$ and $m=20$. 

\section{Stability analysis of a 10-dimensional Lorenz-96 model}\label{sec:appl96_qrc}

We extend the analysis about designing practical quantum reservoirs, shown in Section~\ref{sec:prac_qrc} for the Lorenz-63 system, to the 10-dimensional Lorenz-96 system. Specifically, we analyse the influence of the leak rate hyperparameter $\epsilon$ and the magnitude of the maximum conditional Lyapunov exponent  on the ability of the reservoir to infer Lyapunov exponents on the unseen test data set. The training procedure is the same as described in Section~\ref{sec:l96} and other model hyperparameters are shown in Table~\ref{tab: param_RFQRC}. 
In Figure~\ref{fig:l96_10D_comb}a, we vary the leak rate from $\epsilon=0.001$ to $\epsilon = 1.0$ and compute the inferred Lyapunov exponents of the model. In Figure~\ref{fig:l96_10D_comb} b, the colour bar indicates the maximum $\lambda_{CLE}$ value associated with the corresponding leak rate in Figure~\ref{fig:l96_10D_comb} a. These results are in line with the findings of the previous analysis from Section~\ref{sec:prac_qrc}. The  maximum CLEs and their effects on the inference task are shown in Figure~\ref{fig:l96_10D_comb} b. When the reservoir dynamics are faster and the leak rate is closer to 1, the reservoir over-predicts the positive and under-predicts the negative Lyapunov exponents. Because the reservoir dynamics are faster, the reservoir is also very sensitive to noise in this region. Therefore, depending on the learning tasks and form of noise, the rate of reservoir dynamics must be carefully tuned with the hyperparameter leak rate. 

