\section {Orbit spaces over graded $R$-subalgebras of $R[t]$ for $\dim(R) = 2$}
Let $R$ be a ring of dimension $2$ and $A$ be a graded $R$-subalgebra of $R[t]$. This section focuses on studying the orbit space $\frac{\Um_3(A, IA)}{\E_3(A, IA)}$ where $I \subset \rad(R)$ is an ideal of $R$. We recall the Swan-Weibel map, which is essential to the developments in this section.

%Suppose $R$ is a local ring of dimension $2$, $A$ is a graded $R$-subalgebra of the polynomial algebra $R[t]$ and $I$ is a homogeneous ideal of $A$. 
%In this section, we show that  $\frac{\Um_{3}(A, I)}{\E_3(A, I)}$ has the property $\P_k$ whenever $2k R = R$. 

\subsection{The Swan-Weibel map}\label{SW}
Let $A= \oplus_{i\geq 0} A_i$ be a graded ring such that $A_0=R$. The  Swan-Weibel homomorphism $\psi: A \rightarrow A[t]$ is defined by $\psi(a_0+a_1\cdots+a_r) = a_0+a_1t\cdots+a_rt^r$ for $a_i \in A_i$. Assume that $\phi_m :A[t]\rightarrow A$, $\phi_m(p(t)) =  p(m)$ for $m=0,1$ are the evaluation maps, $\i: R \rightarrow A$ is the inclusion map and $\eta: A\rightarrow A/A_+= R$ is the natural quotient map. Consider the following commutative diagram:

\[
\xymatrix{
    R \ar[rd]_{Id} \ar[r]^{\i} & A \ar[r]^{\psi} \ar[d]_{\eta} 
      \ar@/^1.5pc/[rr]^{Id} & A[t] \ar[d]^{\phi_0} \ar[r]^{\phi_1} & A   \\    
    & R \ar[r]^{\i} & A  &  
}
\]

By Karoubi's result \cite[Corollary 3.2]{vasershtein1974serre}, the natural inclusion $A \rightarrow A[t]$ induces an isomorphism $\W_{\SL}(A) \rightarrow \W_{\SL}(A[t])$. Therefore, the following lemma is a consequence of \cite[Lemma 5.7]{anderson1978projective}.
\begin{lemma}\label{34} 
Let $A = \oplus_{i\geq 0} A_i$ be a graded ring such that $A_0 = R$ and $2R=R$. Then $W_{\SL}(A) \cong W_{\SL}(R)$.
\end{lemma}

Let $\eta_* : \W_{\E}(A) \rightarrow \W_E(R)$ be the map induced by $\eta$. In order to streamline the discussion, we set $\NW_{\E}(A) = \ker \eta_*$.

%Let $A$ be a graded $R$-subalgebra of $R[t]$. In order to streamline the discussion, we adopt the following notation. 
%$$\NW_{\E}(A) = \ker\big(W_{\E}(A)\rightarrow \W_{\E}(A/A^+)=\W_{\E}(R)\big).$$
A careful perusal of  \cite[Proposition 2.4.1]{rao1991completing} by Rao actually gives the following. 
\begin{proposition}\label{Raodiv}
   Let $R$ be a ring such that $2kR= R$ for $k \in \NN$, then $\NW_{\E}(R[t]) = k\NW_{\E}(R[t])$.  
\end{proposition}

We generalize Rao's result to graded subalgebras of $R[t]$ as follows.

\begin{proposition}\label{div}
	Let $R$ be a ring such that $2kR= R$ for $k \in \NN$ and $A$ be a graded $R$-algebra. Then $\NW_{\E}(A) = k \NW_{\E}(A)$. 
	Moreover, if $\maxSpec R$ is a union of finitely many Noetherian subspaces of dimension at most $1$, then $\W_{\E}(A)$ is $k$-divisible.
\end{proposition}

\begin{proof} The following commutative diagram is a consequence of the discussion in  \S \ref{SW}.

\[
\xymatrix{& \NW_{\E}(A)\ar[d]\ar[r]^{\psi_*}& \NW_{\E}(A[t])\ar[d]\\
  \W_{\E}(R) \ar[rd]_{Id} \ar[r]^{i_{*}} & \W_{\E}(A) \ar[d]_{\eta_{*}} \ar[r]^{\psi_{*}} & \W_{\E}(A[t]) \ar[d]^{\phi_{0*}} \ar[r]^{\phi_{1*}} & \W_{\E}(A)   \\
    & \W_{\E}(R) \ar[r]^{i_{*}} & \W_{\E}(A)  & 
}
\]

The diagram yields $\psi_{*}(\NW_{\E}(A)) \subset \NW_{\E}(A[t])$. We have $\NW_{\E}(A[t]) = k \NW_{\E}(A[t])$  by Proposition \ref{Raodiv}.
Therefore, $\psi_{*}(\NW_{\E}(A)) \subset k \NW_{\E}(A[t])$.
Taking images of both sides under $\phi_{1*}$, we get $\NW_{\E}(A)\subset k\W_{\E}(A)$ since $\phi_{1*} \circ \psi_{*}= id_{W_{\E}(A)}$.

  The short exact sequence $0 \rightarrow \NW_{\E}(A) \rightarrow \W_{\E}(A) \xrightarrow{\eta_{*}} \W_{\E}(R) \rightarrow 0$ of abelian groups splits, so there is a surjective homomorphism $\pi_{*} : \W_{\E}(A) \rightarrow \NW_{\E}(A)$ which restricts to the identity on $\NW_{\E}(A)$. Applying $\pi_{*}$ to both sides of $\NW_{\E}(A)\subset k\W_{\E}(A)$, we get $\NW_{\E}(A)\subset k\NW_{\E}(A)$. The proof follows as the reverse inclusion is clear. 

For the last assertion, we observe that under the hypothesis $\W_{\E}(R) = \frac{\Um_3(R)}{\E_3(R)}$ is trivial, see \S \ref{swg}. Therefore, $\NW_{\E}(A)= \W_{\E}(A)$ and consequently $\W_{\E}(A)$ is $k$-divisible. 
\end{proof}

The following lemma and the subsequent remark provide a framework to simplify the proof of the main results.

\begin{lemma}\label{mainprin}
    Let $R$ be a ring of dimension $d$ $(\geq 2)$  and $I \subset \rad (R)$ be an ideal which contains a nonzero divisor $s$.  Let $A =  \oplus_{i\geq 0} I_i t^i$ be a finitely generated graded $R$-subalgebra of $R[t]$. Then the natural map $\displaystyle \frac{\Um_{d + 1}(A, sA)}{\E_{d + 1}(A, sA)} \longrightarrow \frac{\Um_{d + 1}(A, IA)}{\E_{d + 1}(A, IA)}$ is surjective. 
    \end{lemma}

\begin{proof}
Let $\v \in \Um_{d + 1}(A, IA)$.  We need to find $\v' \in \Um_{d + 1}(A, sA)$ such that $\v \sim_{\E_{d + 1}(A, IA)} \v'$.  Let overline denote the image modulo the ideal $sA$. If $I = (x_1, \ldots, x_r)$, we have 
$$\maxSpec \overline{A}  = V_M(\overline{I}) \cup D_M(\overline{I}) = V_M(\overline{I}) \cup \Big(\cup_{i = 1}^r D_M(\overline{x_i})\Big).$$ 
Here $V_M(\overline{I}) = \maxSpec \frac{A}{sA + I}$ and $D_M(\overline{x_i}) \subset \maxSpec (\frac{A}{sA})_{\overline{x_i}}$. 

We know that $\dim A \leq d + 1$, so $\dim A/ sA \leq d$. It is clear that $\overline{x_i} \in \overline{\rad(R)} \subset \rad(\overline{R})$.
Therefore, by Lemma \ref{maindim}, we deduce  $\dim (\frac{A}{sA})_{\overline{x_i}} \leq d -1$ and consequently $\dim [ D_M(\overline{x_i})] \leq d - 1$ for $i = 1, \ldots, r$. 
It follows that $\maxSpec \overline{A} \setminus V_M(\overline{I})$ is a union of $r$ Noetherian subspaces of dimension at most $d - 1$. Applying \cite[Proposition 2.4]{van1983group}, we get $\overline{\v} \sim_{\E_{d + 1}(\overline{A}, \overline{IA})} e_1$. Lifting the elementary operations, we obtain $\v \sim_{\E_{d + 1}(A, IA)} \v'$ for some $\v' \in \Um_{d + 1}(A, sA)$. Hence, the lemma follows. 
\end{proof}

\begin{remark}\label{mainreduct}
Suppose $R$ is a ring of dimension $d \geq 1$ and $I \subset \rad(R)$ is an ideal. We assume that $A$ is a finitely generated graded $R$-subalgebra of the polynomial ring $R[t]$. The orbit space $\frac{\Um_{d + 1}(A, IA)}{\E_{d +1}(A, IA)}$ has an abelian group structure, see Example \ref{prex}.

 Suppose our purpose is to verify if  $\frac{\Um_{d + 1}(A, IA)}{\E_{d + 1}(A, IA)}$ is $k$-divisible for some $k \in \NN$. By Corollary \ref{nzd}, there is an isomorphism $\displaystyle \frac{\Um_{d+1}(A, IA)}{\E_{d+1}(A, IA)} \longrightarrow \frac{\Um_{d+1}(\overline{A},\overline{IA})}{\E_{d+1}(\overline{A},\overline{IA})}$ where overline denotes the image in $A/ \Gamma_{IA} (A)$. As the property of $k$-divisibility transfers along an isomorphism of orbit spaces, it is enough to show that $\frac{\Um_{d+1}(\overline{A},\overline{IA})}{\E_{d+1}(\overline{A},\overline{IA})}$ is $k$-divisible. 
If $\dim (R/ \Gamma_I(R))< d$, then $\frac{\Um_{d+1}(\overline{A},\overline{I A})}{\E_{d+1}(\overline{A},\overline{I A})}$  is trivial, see \cite[Theorem 3.5]{garggupta2025graded}. If $\overline{I} =0$, then also $\frac{\Um_{d+1}(\overline{A},\overline{I A})}{\E_{d+1}(\overline{A},\overline{I A})}$ is trivial. A trivial orbit space is $k$-divisible, so the only case of interest is when $\dim (R / \Gamma_I(R)) = d$ and $\overline{I} \neq 0$. We have inclusions of rings $R/ \Gamma_I(R) \hookrightarrow A/ \Gamma_{IA} (A) \hookrightarrow R/ \Gamma_I(R) [t]$ and $\overline{I} \subset \rad(\overline{R})$. Therefore, it suffices to assume that $I$ contains a nonzero divisor. 

Due to Lemmas \ref{pkhom} and \ref{mainprin}, it is enough to further assume that $I$ is a proper principal ideal generated by a nonzero divisor. We have inclusions $R_{red} \hookrightarrow A_{red} \hookrightarrow R_{red}[t]$ of rings, where $R_{red} = R/ \Nil R$, $A = A/ \Nil A$; and a bijection $\displaystyle \frac{\Um_{d + 1}(A, IA)}{\E_{d + 1}(A, IA)} \longrightarrow \frac{\Um_{d + 1}(A_{red}, IA_{red})}{\E_{d + 1}(A_{red}, IA_{red})}$ by Lemma \ref{26}. The property of being nonzero divisors is retained in the passage to the quotient ring $R_{red}$. 

Hence, in our quest of the property of $k$-divisibility of $\frac{\Um_{d + 1}(A, IA)}{\E_{d + 1}(A, IA)}$, we may say that it is enough to assume further that $R$ is a reduced ring and $I \subset \rad (R)$ is a proper principal ideal generated by a nonzero divisor. An argument verbatim as above enables us to say the same when our interest is to verify if the orbit space $\frac{\Um_{d + 1}(A, IA)}{\E_{d + 1}(A, IA)}$ is good. 
\end{remark}
The subsequent lemma serves as a further aid in simplifying the proofs of ensuing results.
\begin{lemma} \label{47}
Let $R$ be a ring of dimension $d (\geq 2)$, $A$ be a graded $R$-subalgebra of $R[t]$ and $I =\oplus_{i\geq 0} I_i$ be a homogeneous ideal of $A$ such that  $I_0 \subset \rad (R)$. Then for any $\v \in \Um_{d + 1}(A, I)$ there exists a finitely generated graded $R$-subalgebra $B = \oplus_{i \geq 0}B_i$ of $A$ such that  $B_+ = \oplus_{i \geq 1} B_i \subset I$ and $\v \sim_{\E_{d + 1}(A, I)} \v'$ for some $\v' \in \Um_{d + 1}(B, B_{+})$.
In particular $[\v]$ is contained in the image of $\displaystyle \frac{\Um_{d + 1}(B, B_{+})}{\E_{d + 1}(B, B_{+})} \longrightarrow \frac{\Um_{d + 1}(A, I)}{\E_{d + 1}(A, I)}$. 
\end{lemma}
\begin{proof}
 Let $\v \in  \Um_{d+1}(A, I)$. Suppose overline denotes the image modulo the ideal $I_+ = \oplus_{i\geq 1} I_i$. Then $\overline{\v} \in \Um_{d+1}(R, I_0)$. We have $\overline{\v} \sim_{\E_{d+1}(R, I_0)} e_1$ since $I_0 \subset \rad (R)$. Lifting the elementary operations, we get $\v \sim_{\E_{d+1}(A, I)} \v'$ for some $\v' = (v_0', \dots , v_d') \in \Um_{d+1}(A, I_{+})$.
We choose $(w_0', \ldots, w_d')  \in \Um_{d+1}(A, I_{+})$ such that $\sum_{i\geq 0}^{d}v_i'w_i'=1$. 

Let $B= \oplus_{i \ge 0} B_i$ be the graded $R$-subalgebra of $A$ generated by all homogeneous components of the coordinates $v_i',  w_i'$ for $i = 1, \ldots, d$. It is easily seen that $B_{+} = \oplus_{i >0} B_i \subset I_{+}$, $\v' \in \Um_{d + 1}(B, B_{+})$ and the natural map $\displaystyle \frac{\Um_{d + 1}(B, B_{+})}{\E_{d + 1}(B, B_{+})} \longrightarrow \frac{\Um_{d + 1}(A, I)}{\E_{d + 1}(A, I)}$ sends $[\v']$ to $[\v]$. Hence, the proof follows. 
\end{proof}

 We are now prepared to prove the principal result of this section.
\begin{proposition}\label{42} 
	Let $R$ be a ring of dimension $2$ such that $2kR= R$ for $k \in \NN$, $I \subset \rad(R)$ be an ideal of $R$ and $A$ be a finitely generated graded $R$-subalgebra of $R[t]$. Then the orbit space $\frac{\Um_{3}(A,IA)}{\E_{3}(A, IA)}$ is good and $k$-divisible. 
\end{proposition}

\begin{proof}
As explained in Example \ref{prex}, the orbit space $\frac{\Um_{3}(A, IA)}{\E_3(A, IA)}$ has a group structure. On account of Remark \ref{mainreduct}, it is enough to assume that $R$ is a reduced ring and $I \subset \rad(R)$ is a principal ideal generated by a nonzero divisor $s$. Let $\v \in \Um_3(A, IA)$. According to Lemma \ref{47}, there is a finitely generated graded $R$-subalgebra $B$ of $A$ such that $[\v]$ is contained in the image of $\displaystyle \frac{\Um_{3}(B, B_{+})}{\E_{3}(B, B_{+})} \rightarrow \frac{\Um_{3}(A, I)}{\E_{3}(A, I)}$. Since $\v$ is arbitrary, it suffices to prove that $\frac{\Um_{3}(B,B_+)}{\E_3(B,B_+)}$ is good and $k$-divisible due to Lemma \ref{pkhom}.

In our setup, $\maxSpec(R) = V_M(s) \cup D_M(s)$ is a union of two subspaces of dimension at most $1$. In contrast, $\maxSpec(B) = V_M(sB) \cup D_M(s)$ is a union of two subspaces of dimension at most $2$. It follows that $\frac{\Um_{3}(R)}{\E_{3}(R)}$ is trivial and  $\displaystyle \frac{\Um_{3}(B, B_{+})}{\E_{3}(B, B_{+})} \rightarrow \frac{\Um_{3}(B)}{\E_{3}(B)}$  is an isomorphism by Lemma \ref{retract}. Therefore, the proof is completed once we show that $\frac{\Um_{3}(B)}{\E_3(B)}$ is good and $k$-divisible.


 Let $\u = (u_0, u_1, u_2) \in \Um_{3}(B)$. We have $\frac{\Um_{3}(B)}{\SL_3(B)} \cong \W_{\SL}(B)$ and $\frac{\Um_{3}(B)}{\E_{3}(B)}\cong \W_{\E}(B)$, see \S \ref{swg}.
 Applying Lemma \ref{34}, we conclude that $\displaystyle \frac{\Um_{3}(B)}{\SL_{3}(B)} \cong\W_{\SL}(B) \cong \W_{\SL}(R) \cong \frac{\Um_{3}(R)}{\SL_{3}(R)}$ is trivial, consequently $\Um_{3}(B)=e_1\SL_3(B)$. 
 It follows from \cite[Lemma 1.5.1]{rao1988bass} that $\u \sim_{\E_3(B)} (-u_0, u_1, u_2)$. Therefore, by \cite[Lemma 1.3.1]{rao1988bass}, we have  $[\u]^r =[\u^{(r)}]$ for any $r \in \NN$, i.e. $\frac{\Um_{3}(B)}{\E_{3}(B)}$ is good.  It is $k$-divisible since so is  $\W_{\E}(B) \cong \frac{\Um_{3}(B)}{\E_3(B)}$ by Proposition \ref{div}.  Hence, the proof is completed. 
\end{proof}


