%\label{stresses_fields}
 %   \sigma_{11}(z)+\sigma_{22}(z)=2D_0+4\sum_{k=1}^{\infty}\Rp\Big(D_{k}z^k\Big) ,\\
 %   \sigma_{22}(z)-\sigma_{11}(z)-2i\sigma_{12}(z)=2\left[z\overline{D}_1+\sum_{k=2}^{\infty}k\overline{D}_k\overline{z}^{k-2}(z\overline{z}-1)+\sum_{k=2}^{\infty}\left(\overline{D}_k-D_{-k}\right)\overline{z}^{k-2}\right] ,
%\end{gathered}
%\end{equation}
%while the corresponding strains, satisfying incompressibility $
%    \epsilon_{11}(z)+\epsilon_{22}(z)= 0$, become
%\begin{equation}
%\label{paolagatti}
%        \varepsilon_{22}(z)-\varepsilon_{11}(z)-2i\varepsilon_{12}(z)= \frac{1}{\mu}\left[z\overline{D}_1+\sum_{k=2}^{\infty}k\overline{D}_k\overline{z}^{k-2}(z\overline{z}-1)+\sum_{k=2}^{\infty}\left(\overline{D}_k-D_{-k}\right)\overline{z}^{k-2}\right] .
%\end{equation}

Eqs.~\eqref{paolagatti} and \eqref{stresses_fields} represent the solution of the elastic disc of unit radius made of incompressible material. It can be shown in a straightforward manner that similar expressions for the elastic fields within the disc of radius $R$ are, in addition to the incompressibility constraint $\varepsilon_{11}(z)+\varepsilon_{22}(z)=0$, 

\begin{multline}
\label{u_D_R}
    \frac{2\mu\, u(z)}{R} = 
    i\frac{z}{R}\left\{-\frac{3}{2}\Ip(D_1) - \sum_{k=2}^{\infty} \Ip\left[\frac{(k+1)D_{-k}+(k-1)D_{k}}{k^2-1}\right]\right\} - \frac{z\overline{z}}{R^2}\overline{D}_1 \\[3mm]
    + \sum_{k=2}^{\infty} \overline{D}_{k}\frac{\overline{z}^{k-1}}{R^{k-1}}(1-\frac{z\overline{z}}{R^2}) 
    + \sum_{k=2}^{\infty} \frac{D_{-k}}{k-1}\frac{\overline{z}^{k-1}}{R^{k-1}}+\sum_{k=1}^{\infty}\frac{D_{k}}{k+1}\frac{z^{k+1}}{R^{k+1}}.
\end{multline}

\begin{equation}
\label{uepsR}
    \varepsilon_{22}(z)-\varepsilon_{11}(z)-2i\varepsilon_{12}(z)= \frac{1}{\mu}\left[\frac{z}{R}\overline{D}_1+\sum_{k=2}^{\infty}k\overline{D}_k\frac{\overline{z}^{k-2}}{R^{k-2}}(\frac{z\overline{z}}{R^2}-1)+\sum_{k=2}^{\infty}\left(\overline{D}_k-D_{-k}\right)\frac{\overline{z}^{k-2}}{R^{k-2}}\right],
\end{equation}

\begin{equation}
\label{stresses_fieldsR}
    \begin{gathered}
    p(z)=-\frac{\sigma_{11}(z)+\sigma_{22}(z)}{2}=-D_0-2\sum_{k=1}^{\infty}\Rp\Big(D_{k}\frac{z^k }{R^k}\Big), \\[3mm]
    \sigma_{22}(z)-\sigma_{11}(z)-2i\sigma_{12}(z)=2\left[\frac{z}{R}\overline{D}_1+\sum_{k=2}^{\infty}k\overline{D}_k\frac{\overline{z}^{k-2}}{R^{k-2}}(\frac{z\overline{z}}{R^2}-1)+\sum_{k=2}^{\infty}\left(\overline{D}_k-D_{-k}\right)\frac{\overline{z}^{k-2}}{R^{k-2}}\right],
    \end{gathered}
\end{equation}
%
where the prescribed load at the boundary, $z=\tau$ and $\tau\overline{\tau}=R^2$, can be expanded as
\begin{equation}
\label{expanssigmaR}
    \sigma(\tau) = \sum^{\infty}_{k=1} D_{-k}\frac{R^k}{\tau^{k}} + 
    \sum^{\infty}_{k=0} D_{k}\frac{\tau^{k}}{R^k}.   
\end{equation}

The expressions for the remaining elastic fields at the boundary are 
\begin{equation}
\label{fields_tau}
    \begin{gathered}
    \begin{multlined}
    2\mu\, u(\tau) = i\tau\left\{-\frac{3}{2}\Ip(D_1)-\sum_{k=2}^{\infty}\Ip\left[\frac{(k+1)D_{-k}+(k-1)D_{k}}{k^2-1}\right]\right\}-R\overline{D}_1 \\[3mm] 
    +\sum_{k=2}^{\infty}\frac{{D}_{-k}}{k-1}\frac{R^k}{\tau^{k-1}}+\sum_{k=1}^{\infty}\frac{{D}_{k}}{k+1}\frac{\tau^{k+1}}{R^k}, 
    \end{multlined} \\[3mm]
    \varepsilon_{22}(\tau)-\varepsilon_{11}(\tau)-2i\varepsilon_{12}(\tau)= \frac{1}{\mu}\left[\frac{z}{R}\overline{D}_1+\sum_{k=2}^{\infty}\left(\overline{D}_k-D_{-k}\right)\frac{R^{k-2}}{\tau^{k-2}}\right], \\[3mm]
    p(\tau)=-\frac{\sigma_{11}(\tau)+\sigma_{22}(\tau)}{2}=-D_0-2\sum_{k=1}^{\infty}\Rp\Big(D_{k}\frac{\tau^k }{R^k}\Big), \\[3mm]
    \sigma_{22}(\tau)-\sigma_{11}(\tau)-2i\sigma_{12}(\tau)=2\left[\frac{\tau}{R}\overline{D}_1+\sum_{k=2}^{\infty}\left(\overline{D}_k-D_{-k}\right)\frac{R^{k-2}}{\tau^{k-2}}\right].
    \end{gathered}
\end{equation}


\subsection{\texorpdfstring{Connection with the plane strain compressible case for $\nu \to 1/2$}{}}
\label{mantegazza}

The plane strain case of compressible elasticity treated in \cite{gaibotti2023elastic} is now considered. It is shown below that, in the isochoric limit, the solution of that problem $\nu \to 1/2$, coincides exactly with the solution obtained above directly for an incompressible material. This shows that the linear elastic solution for compressible materials converges smoothly to the incompressible case. 

The disc material is assumed to be isotropic and compressible, characterized by the shear modulus $\mu$ and Poisson's ratio $\nu$. As shown in eq.~(29) of \cite{mogilevskaya2008multiple}, and reproduced as eq.~(27) in \cite{gaibotti2023elastic}, the coefficients of the Fourier series expansions for the displacements and tractions at the boundary of the disc are interrelated (in the present notation) as
\begin{equation}
\label{D}
    \begin{gathered}
    D_{-1} = 0, \quad
    \frac{\kappa-1}{2\mu}D_{0} = 2\Rp\frac{H_{1}}{R}, \\[3mm]
    \frac{1}{2\mu}D_{-k} = \left(k-1\right)\frac{H_{1-k}}{R}, \quad k \geq 2, \\[3mm]
    \frac{\kappa}{2\mu}D_{k} = \left(k+1\right)\frac{H_{k+1}}{R}, \quad k \geq 1,
    \end{gathered}
\end{equation}
in which $\kappa=3-4\nu=1$. Moreover, the tractions at the boundary are given by eq.~\eqref{expanssigmaR} and the displacements there are represented as 
\begin{equation}
\label{albino}
    u(\tau) = u_{1}(\tau) + iu_{2}(\tau) = 
    \sum^{\infty}_{k=1} H_{-k}\frac{R^k}{\tau^k} + \sum^{\infty}_{k=0} H_{k}\frac{\tau^{k}}{R^k}.
\end{equation}
%
Assuming now that the displacements at the boundary satisfy the inextensibility constraint, eq.~\eqref{inexten}, eq.~\eqref{albino} yields (see eqs.~(34)--(36) of \cite{gaibotti2023elastic}),
\begin{equation}
\label{H}
    \Rp H_{1} = 0, \quad
    H_{2} = 0, \quad
    H_{k+1}	= \frac{k-1}{k+1}\overline{H}_{1-k}, \quad k \geq 2.
\end{equation}

An analysis of eqs.~\eqref{D}, \eqref{expanssigmaR}, and \eqref{H} leads to the conclusion that the load must have the form expressed by eq.~\eqref{admis}. The displacements and stresses within the disc can be found from the Kolosov-Muskhelishvili formulae \cite{muskhelishvili2013some} as
\begin{equation}
    \begin{gathered}
    2\mu\, u(z) = \kappa\varphi\left(z\right) - z\overline{\varphi'}\left(z\right) - \overline{\Psi}\left(z\right), \\[3mm]
    \sigma_{11}(z)+\sigma_{22}(z) = 4 \Rp \varphi'\left(z\right), \\[3mm]
    \sigma_{22}(z)-\sigma_{11}(z)-2i\sigma_{12}(z)	=2\left[z\overline{\varphi''}\left(z\right)+\overline{\Psi'}\left(z\right)\right].
    \end{gathered}    
\end{equation}
in which $\Psi$ should not be confused with the stream function used in the previous sections and the potentials were obtained in terms of displacement coefficients in \cite{mogilevskaya2008multiple}, see eq.~(51) of that article. 

Here, assuming $\nu=1/2$, eqs.~\eqref{D} and \eqref{H} can be rewritten in terms of the traction coefficients defined by eq.~\eqref{expanssigmaR} as
\begin{equation}
\label{eq:potentials}
    \varphi(z) = \frac{D_0}{2}z+\sum^{\infty}_{k=2}\frac{D_k}{k+1}\frac{z^{k+1}}{R^k}, 
    \quad
    \Psi(z) = -\sum^{\infty}_{k=2}D_k\frac{k}{k-1}\frac{z^{k-1}}{R^{k-2}}, 
\end{equation}  
so that the fields within the disc are
\begin{equation}
\label{expfields}
    \begin{gathered}
    \frac{2\mu\, u(z)}{R}	= \sum^{\infty}_{k=2}\frac{D_k}{k+1}\frac{z^{k+1}}{R^{k+1}}+\sum^{\infty}_{k=2}\overline{D_k}\frac{{\overline{z}^{k-1}}}{R^{k-1}}\left(\frac{k}{k-1}-\frac{z\overline{z}}{R^2}\right), \\[3mm]
    \sigma_{11}(z)+\sigma_{22}(z) = 2\Rp{D_0} + 4 \Rp \sum^{\infty}_{k=2}D_k\frac{z^{k}}{R^k}, \\[3mm]
    \sigma_{22}(z)-\sigma_{11}(z)-2i\sigma_{12}(z) = 2\sum^{\infty}_{k=2}k\overline{D}_k\frac{{\overline{z}^{k-2}}}{R^{k-2}}\left(\frac{z\overline{z}}{R^2}-1\right).
    \end{gathered}    
\end{equation}

A comparison between eqs.~\eqref{expfields} and eqs.~\eqref{finfieldsR}$_{1,4,5}$ suggests that the expressions for the stresses are the same in both equations, but the expressions for the complex displacement, eq.~\eqref{expfields}, differ in the term corresponding to a rigid-body displacement. The latter term can be added to the first line of eq.~\eqref{expfields} by assuming $u_2(R)=0$. Therefore, it can be concluded that, for the case of a prescribed admissible load at the disc boundary, the plane strain solution with $\nu=1/2$ is identical to that obtained in Section \ref{sec:problemform}.

Finally, the strains inside the disc can be obtained by using the following relations in the limit $\nu=1/2$ 
\begin{equation}
\label{expstrains}
    \begin{gathered}
    \varepsilon_{11}(z)+\varepsilon_{22}(z) = \frac{1-2\nu}{2\mu}[\sigma_{11}(z)+\sigma_{22}(z)]=0, \\[3mm]
    \varepsilon_{22}(z)-\varepsilon_{11}(z)-2i\varepsilon_{12}(z) = \frac{1}{2\mu}[\sigma_{22}(z)-\sigma_{11}(z)-2i\sigma_{12}(z)] = \sum^{\infty}_{k=2}k\frac{\overline{D}_k}{\mu}\frac{{\overline{z}^{k-2}}}{R^{k-2}}(\frac{z\overline{z}}{R^2}-1),
\end{gathered} 
\end{equation}
from which it can be concluded that all components of the strain tensor at the boundary of the disc vanish, as in the case studied in Section \ref{sec:problemform}, see the comment after eq.~\eqref{finfieldsR}.


\section{Examples of solutions for the incompressible elastic disc}
\label{sec:soluzioni}

A circular disc made of incompressible elastic material is considered, subject to a symmetric boundary traction distribution. 

As a first example, the validity of the approach to incompressible elasticity is checked through a trivial example, in which a uniform radial traction $\sigma(\tau)=-\Pi\,\bn$ is prescribed on the entire boundary of the disc ($\Pi$ is positive for compressive tractions). In this case, the only non-vanishing coefficient in eq.~\eqref{expanssigmaR} is $D_0$ and the treatment developed in the previous Section, eqs.~\eqref{stresses_fieldsR}, gives the expected trivial solution in which only $p(z)$ is different from zero and equal to the prescribed radial traction 
\begin{equation}
\label{p_hydro}
    p(z) = -D_0, \quad D_0 = -\Pi,
\end{equation}
while all displacements are null.

In a more elaborate example, a load acting on two symmetric portions of the boundary is applied. The traction is radial and varies along the two arcs spanned by the angle $\alpha$ varying within $[\pm(\pi-\gamma)/2,\pm(\pi+\gamma)/2]$, with the mid-points located at the angles $\alpha = \pm \pi/2$. The load is assumed with the shape of a sinusoidal function of $\alpha$ in the plane ($x,y$), Fig.~\ref{incomp_fields_plot}(a), as 
\begin{equation}
\label{sigma_sin}
    \sigma^{\star}(\alpha) = 
    \left\{
    \begin{array}{ll}
    -S_0\sin\Big[\frac{\pi}{\gamma}\Big(\alpha\mp \frac{\pi-\gamma}{2}\Big)\Big] & 
    \text{if } \alpha \in \big[\pm\frac{\pi-\gamma}{2}, \pm\frac{\pi+\gamma}{2}], \\[3mm]
    0 & 
    \text{elsewhere,}
    \end{array}
    \right.
\end{equation}
where $S_0$ is the traction amplitude.

