\begin{figure}[htb!]
    \centering
    \includegraphics[scale=1.1,keepaspectratio]{u2_Pi2_Smu20.pdf}
    \caption{Dimensionless boundary displacement $|u_2|/R$ evaluated at $\alpha = \pi/2$ for an elastic disc coated with an inextensible elastic rod (height $h = R/10$), as a function of the Poisson's ratio $\nu$ of the disc material. The extrados of the rod is subjected to a sinusoidal traction $\sigma^{\star}(\tau)$, centered at $\alpha_0 = \pm \pi/2$ and symmetrically distributed over an angle $\gamma = 10^{\circ}$. The load magnitude is set to $S_0 = E_d/20$, and two different Young's modulus ratios $E_d/E_c$ (disc to coating) are considered. Nonlinear numerical results are shown as discrete points, together with the linear analytical solution (continuous lines). The nonlinear numerical results show that the displacement tends to vanish as incompressibility is approached ($\nu \to 1/2$), whereas the linear solution predicts a finite displacement in this limit.}
    \label{u2_tau_plot}
\end{figure}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{figure}[htb!]
    \centering
    \includegraphics[scale=1.1,keepaspectratio]{u2_Pi2_Smu2.pdf}
    \caption{As in Fig. 4, except that the applied load magnitude is significantly increased to $S_0 = E_d/2$ to highlight the effects of large strains. The nonlinear analysis shows higher compliance than the linear prediction at small values of $\nu$, while, as $\nu \to 1/2$, the composite structure progressively locks and behaves as a rigid body, causing the displacement to vanish.}
    \label{u2_tau_plot2}
