    \centering
    \includegraphics[width=1\linewidth]{MainArticleFigures/InitData.eps}
    \caption{Data obtained from the experiments with single photon counting. (a) PL intensity time trajectory. (b) Photon distribution function (c) Autocorrelation function estimation and (d) its corresponding power spectral density.}
    \label{fig1}
