%   \mathcal{A}^{\rm s}&=\frac{1}{2} \int_0^t d\tau \Big(\dot{\vec{x}}*\dot{\vec{x}}+\vec{v}_{\rm a}*\vec{v}_{\rm a}+\nabla\FF*\nabla\FF - 2\nabla^2\FF \Big) , \\
%   \mathcal{A}^{\rm a}&=\int_0^t d\tau\left(-\dot{\vec{x}}*\vec{v}_{\rm a}+\dot{\vec{x}}*\nabla\mathcal{F}\right) \;,   \end{split}
