\section{Weak noise expansion and covariant formulation  
of the Fokker-Planck equation}
\subsection{Perturbative solution of the Fokker-Planck equation in additve noise}\label{sec:app_noise}
If we assume a weak noise ansatz for the stationary probability:
\begin{eqnarray}
    P_{\st}\asymp e^{-\FF^{(0)}/\sigma},
\end{eqnarray}
the statioanary condition reads:
\begin{eqnarray}\label{eq:stationary_app1}
\partial_{t}P_{\rm st}&=&
\sigma^{-1}P_{\rm st}\left(F^{i}+D^{ij}\partial_{j}\FF^{(0)}\right)\partial_{i} \FF^{(0)}+\nonumber\\&-&\left(\partial_{i}F^{i}+D^{ij}\partial_{i}\partial_{j}\FF^{(0)}\right)P_{\rm st} =0.
\end{eqnarray}
Following  various approaches\cite{graham1984weak,MFT,Garrido_quasi_pot}, we perturbatively solve Eq.(\ref{eq:stationary_app1}) by equaling to zero each order in $\sigma$.
The first contribution is of order $1/\sigma$ and reads:
\begin{eqnarray}\label{eq:order0_app1}
(F^{i}+D^{ij}\partial_{j}\FF^{(0)})\partial_{i}\FF^{(0)}=0,
\end{eqnarray}
while,  the second (and last) contribution is of order $\sigma^0$:
\begin{eqnarray}\label{eq:order1_app1}
\partial_{i}F^{i}+D^{ij}\partial_{i}\partial_{j}\FF^{(0)}=0.
\end{eqnarray}
By using the definition of gradient, divergence and adiabatic velocity
\begin{eqnarray}
    \vec{v}_{\rm a}=\vec{F}+\nabla\FF^{(0)},
\end{eqnarray}
Eqs.(\ref{eq:order0_app1},\ref{eq:order1_app1}) in vectorial forms read:
\begin{eqnarray}
   \vec{v}_{\rm a}*\nabla\FF^{(0)}=0,\qquad \nabla*\vec{v}_{\rm a}=0.
\end{eqnarray}
If we consider a  further order in the availability expansion:
\begin{eqnarray}\label{eq:noise_ansatz_appendix}
    P_{\st}\approx e^{-\FF^{(0)}/\sigma-\FF^{(1)}},
\end{eqnarray}
it is needed to split the velocity into two parts:
\begin{eqnarray}
    \vec{v}^{(0)}_{\rm a}=\vec{F}+\nabla\FF^{(0)}, \quad    \vec{v}^{(1)}_{\rm a}=\nabla\FF^{(1)}.
\end{eqnarray}
The stationary condition reads:
\begin{eqnarray}\label{eq:stationary_app2}
\partial_{t}P_{\rm st}&=&
\sigma^{-1}P_{\rm st}\left(F^{i}+D^{ij}\partial_{j}\FF^{(0)}\right)\partial_{i} \FF^{(0)}\\
&+&\Big(\partial_{i}\left(F^{i}+D^{ij}\partial_{j}\FF^{(0)}\right)+\nonumber\\
&-&(F^{i}+D^{ij}\partial_{j}\FF^{(0)})\partial_{i}\FF^{(1)}
-D^{ij}\partial_{j}\FF^{(1)}\partial_{i} \FF^{(0)}\Big)P_{\rm st} \nonumber\\
&+&\sigma\left(-D^{ij}\partial_{i}\partial_j\FF^{(1)}+D^{ij}\partial_{i}\FF^{(1)}\partial_{j}\FF^{(1)}\right)P_{\rm st}=0.\nonumber
\end{eqnarray}
The dominant order $\sigma^{-1}$ is not modified with respect to Eq.(\ref{eq:order0_app1}):
\begin{eqnarray}\label{eq:order_zero_perp1}
   \vec{v}^{(0)}_{\rm a}*\nabla\FF^{(0)}=0.
\end{eqnarray}
On the other hand, the order $\sigma^0$ is modified to:
\begin{eqnarray}\label{eq:first_v}
&&-(F^{i}+D^{ij}\partial_{j}\FF^{(0)})\partial_{i}\FF^{(1)}+\partial_{i}\left(F^{i}+D^{ij}\partial_{j}\FF^{(0)}\right)+\nonumber\\&-&D^{ij}\partial_{j}\FF^{(1)}\partial_{i} \FF^{(0)}=0.
\end{eqnarray}
In vectorial forms it reads:
\begin{eqnarray}
    \nabla*\vec{v}^{(0)}_{\rm a}=\vec{v}^{(0)}_{\rm a}*\vec{v}^{(1)}_{\rm a}+\vec{v}^{(1)}_{\rm a}*\nabla\FF^{(0)}
\end{eqnarray}
Finally, the order $\sigma$ reads
\begin{eqnarray}\label{eq:second_v}
&&-D^{ij}\partial_{i}\partial_j\FF^{(1)}+D^{ij}\partial_{i}\FF^{(1)}\partial_{j}\FF^{(1)}=0\\
&&\nabla*\vec{v}^{(1)}_{\rm a }=\vec{v}^{(1)}_{\rm a }*\vec{v}^{(1)}_{\rm a }.
\end{eqnarray}
\subsection{Covariant formulation of the Fokker-Planck equation with multiplicative noise}\label{sec:geom_mult}
We first show consider the covariant formulation of the Fokker-Planck equation in  the Ito scheme, and secondly in the Stratonovich case. Our exposition follows various works by Graham \cite{Graham1977CovariantFO,GRAHAM_itp}. \\
In the Ito case the Fokker-Planck equation reads:
\begin{eqnarray}
    \partial_t P&=&-\partial_i\left(F^iP-\partial_jD^{ij}P\right)\nonumber\\
    &=&-\partial_i\left(\left(F^i-\partial_{j}D^{ij}\right)P-D^{ij}\partial_jP\right).
\end{eqnarray}
As in Sec.\ref{sec:geom_dis} we consider the inverse of the diffusion matrix as a metric $g_{ij}=D_{ij}$ to introduce the covariant derivative:
\begin{eqnarray}
    \nabla_{j} u^{i}=\partial_{j}u^{i}+\Gamma^{i}_{j k}u^{k},
\end{eqnarray}
where $\Gamma$ is the connection. By imposing the parallel transport of the metric:
\begin{eqnarray}
     \nabla_{j} D_{ij}=0 \;,
\end{eqnarray}
the connection is determined to be:
\begin{eqnarray}
    \Gamma^{\alpha}_{\beta \kappa}=\frac{1}{2}D^{\alpha\mu}\left(\partial_{\beta}D_{\mu,\kappa}+\partial_{\kappa}D_{\mu\alpha}-\partial_{\mu}D_{\alpha\beta}\right).
\end{eqnarray}
It follows that the divergence reads:
\begin{eqnarray}\label{eq:div_cov_app}
    \nabla_{i}v^{i}=\sqrt{\vert D\vert}\partial_{i}\left(\frac{v^{i}}{\sqrt{\vert D\vert}}\right),
\end{eqnarray}
where $\vert D\vert$ is the diffusion matrix determinant.
In vectorial notation of the divergence, we indicate  explicitly the diffusive scalar product :
\begin{eqnarray}
\nabla*\vec{v}&=&\nabla^{i}D_{ij}v^{j}=D^{ik}\nabla_{k}D_{ij}v^{j} \nonumber \\
    &=&\nabla_jv^{j}+D^{ik}v^j\nabla_kD_{ij}=\nabla_jv^{j}+{D_{i}}^{k}v_j\nabla_kD^{ij} \nonumber\\
    &=&\nabla_jv^{j}+v_j\nabla_iD^{ij}=\nabla_jv^{j}.
\end{eqnarray}
The Laplace-Beltrami operator is the divergence of a gradient of scalar function:
\begin{eqnarray}\label{eq:laplace_beltrami}
    \nabla*\nabla \phi=\sqrt{\vert D\vert}\partial_{i}\left(\frac{D^{ij}\partial_j\phi}{\sqrt{\vert D\vert}}\right)
\end{eqnarray}
Now, by defining the invariant probability Q and the invariant measure 
\begin{eqnarray}\label{eq:invariant_measure_app}
    Q=P\sqrt{\vert D\vert},\quad d\Omega=\frac{d\vec{x}}{\sqrt{\vert D\vert}},
\end{eqnarray}
one can rewrite the Fokker-Planck  equation in a fully covariant form. First, we need to set the position of the diffusion matrix in a compatible way with the Laplace-Beltrami operator. This will produce a disohomogeneity in the force field. In the ito prescription this reads:
\begin{eqnarray}\label{eq:dis_ito_der}
    &&\sqrt{\vert D\vert}\partial_{i}\partial_jD^{ij}P=\sqrt{\vert D\vert}\partial_{i}\partial_j\left(\frac{D^{ij}Q}{\sqrt{\vert D\vert }}\right)\\
    &=&\sqrt{\vert D\vert}\partial_{i}\left(\frac{D^{ij}\partial_jQ}{\sqrt{\vert D\vert }}\right)+\sqrt{\vert D\vert }\partial_i\left(Q\partial_j\left(\frac{D^{ij}}{\sqrt{\vert D\vert }}\right)\right)\nonumber
\end{eqnarray}

By rewriting now everything using Eqs.(\ref{eq:div_cov_app},\ref{eq:laplace_beltrami},\ref{eq:invariant_measure_app}) we arrive now to:
\begin{eqnarray}
    \partial_t Q&=&-\sqrt{\vert D \vert}\partial_i\left(\frac{\tilde{F}^iQ}{\sqrt{\vert D\vert }}-\frac{D^ji\partial_jQ}{\sqrt{\vert D\vert }}\right)\\
    &=&-\nabla*J,\\
    J^i&=&\tilde{F}^{i}Q-D^{ij}\partial_jQ,
\end{eqnarray}
\begin{eqnarray}
   \tilde{F}^{i}=F^{i}-\sqrt{\vert D\vert}\partial_{j}\left(\frac{D^{ij}}{\sqrt{\vert D\vert }}\right)=F^i-\Gamma^i
\end{eqnarray}
This new term, that we name $\vec{v}_{\rm D}$ can be rewritten as the sum of a first contribution stemming
from the anholonomicity vector $\vec{\omega}$ and a second one from the derivative of the diffusive forces $G$:
\begin{eqnarray}\label{eq:v_d_ito}
    v_{\rm D}^i   &=& D^{ij}\omega_j-\partial_{j}G^{i}_{k}G^{j}_{k}.
\end{eqnarray}

On the other hand, in the case of the Stratonovich prescription, we have first to rewrite the Fokker-Planck to make manifest the presence of the diffusive matrix like in Eq.(\ref{eq:dis_ito_der}): 
\begin{eqnarray}
    \partial_t P&=&-\partial_i\left(FP-G^{i}_{b}\partial_jG^{j}_a\delta^{ab}P\right)\nonumber\\
    &=&-\partial_i\left(\left(F^i+\partial_{j}G^{i}_{k}G^{j}_{k}\right)P-\partial_jD^{ij}P\right).
\end{eqnarray}
Hence, the drift term in the force counterbalance the second term in Eq.(\ref{eq:v_d_ito}), leading to a modification just by anholonomicity:
\begin{eqnarray}
    \tilde{F}^{i}=F^{i}+D^{ij}\omega_j.
\end{eqnarray}
\subsection{Perturbative solution of the  covariant Fokker-Planck equation with multiplicative fluctuations}\label{sec:appendix_exp_mult}
We consider a noise expansion for the invariant probability :
\begin{eqnarray}
 Q_{\st}\approx e^{-\FF^{(0)}/\sigma-\FF^{(1)}},
\end{eqnarray}
and solve order by order in sigma as in Sec.\ref{sec:app_noise}. The results are equivalent to the precedent section, stated in curved geometry, and with the addition of the "phoretic" term in the first order velocity:
\begin{eqnarray}
    \vec{v}^{(1)}_{\rm a}&=&\nabla\FF^{(1)}+\vec{v}_{D}.
\end{eqnarray}
 The dominant order is still given by Eq.(\ref{eq:order_zero_perp1}) but in curved geometry, while the following orders read:
\begin{eqnarray}
    \nabla*\vec{v}^{(0)}_{\rm a}&=&\vec{v}^{(0)}_{\rm a}*\nabla\FF^{(1)}+\vec{\tilde{v}}^{(1)}*\nabla\FF^{(0)}\\
      \nabla*\vec{\tilde{v}}^{(1)}_{\rm a}&=&\vec{\tilde{v}}^{(1)}_{\rm a}*\nabla\FF^{(1)}=\vec{\tilde{v}}^{(1)}_{\rm a}*\left(\vec{\tilde{v}}^{(1)}_{\rm a}-\vec{v}_{D}\right).
\end{eqnarray}
By taking the average, the  last equation leads to the first order entropy production:
\begin{eqnarray}
    \dot{\tilde{S}}^{(1)}&=& \average{ \vec{\tilde{v}}^{(1)}_{\rm a}*\vec{\tilde{v}}^{(1)}_{\rm a}}\nonumber\\
    &=&\average{ \nabla*\vec{\tilde{v}}^{(1)}_{\rm a}}+\average{\vec{v}_{D}*\vec{\tilde{v}}^{(1)}_{\rm a}}\geq 0
\end{eqnarray}
In the case of vanishing "potential" diffusive forces $\vec{\omega}=0$, it shows that the first-order excess dissipation is proportional to the associated velocity divergence in tangent space:
\begin{eqnarray}
       \dot{\tilde{S}}^{(1)}_{\rm ex,\rm a}=\average{ \partial*\vec{\tilde{v}}^{(1)}_{\rm a}}\geq 0
\end{eqnarray}
