\section{Properties of $\alpha$-Strongly Regular and MHR Distributions}
\label{appendix:mhr-properties}

The following lemmas argue that if the value is large, then the virtual value must also be quite large for $\alpha$-strongly regular distributions.

\begin{lemma}[\citealp{HR09}] \label{thm:MHRLightTail}
    Let $D$ be an MHR distribution with a virtual value function $\vv$ and a monopoly reserve $r$. Then, for all values $v \geq r$, $\vv(v) \geq v - r$.
\end{lemma}

\begin{lemma}[\citealp{FW20}] \label{thm:RegLightTail}
    Let $D$ be an $\alpha$-strongly regular distribution with a virtual value function $\vv$ and a monopoly reserve $r$. Then, for all values $v \geq r$, $\frac{1}{\alpha}\vv(v) \geq v - r$.
\end{lemma}

\noindent Note that \Cref{thm:MHRLightTail} is a special case of \Cref{thm:RegLightTail} with $\alpha = 1$.

\Cref{thm:MHRLightTail} is also tight.
The exponential distribution is a distribution that is MHR, but not $\alpha$-strongly regular for any $\alpha < 1$.
For an expected value $\mu$, the exponential distribution has a cumulative distribution function $1 - e^{-(\frac{v}{\mu})}$ and a density $\frac{1}{\mu}e^{-(\frac{v}{\mu})}$ for all $v \geq 0$.
This corresponds to a virtual value $\phi(v) = v - \mu$ and a monopoly reserve $\mu$.

The following lemma shows that the right-tail of $\alpha$-strongly regular distributions have to be light.

\begin{lemma}[\citealp{FW20}] \label{thm:MHRWeirdBound}
    Let $D$ be an $\alpha$-strongly regular distribution with a monopoly reserve $r$.
    Then, for all $f \geq r$,
    \begin{equation}
        \notag
        Pr_{v \sim D}(v \geq f) \leq Pr_{v \sim D}(v \geq r) \times \Bigg(\frac{r}{(1-\alpha) f + \alpha r}\Bigg)^{\frac{1}{1-\alpha}}.
    \end{equation}
\end{lemma}



\section{Omitted Proofs} \label{sec:OmittedProofs}

\subsection{Proof of \Cref{thm:MatroidReg}}
\label{appendix:proof-of-MatroidReg}

We aim to recreate the framework from the MHR scenario.
While \Cref{thm:MatroidBeatCritical} holds seamlessly for all regular distributions, \Cref{thm:MatroidMoreThanCritical} fails to hold beyond MHR value distributions.
We obtain a variant for more general distributions.
We identify two simple conditions for which the auctioneer cannot increase its revenue by concealing bids.
We then prove a variant of \Cref{thm:MatroidMoreThanCritical} for bids that do not satisfy these simple conditions.

The first of the two simple conditions is when the critical bid of a bidder is smaller than $f$ (the second condition is discussed later in the section). Concealing bids will not increase the revenue extracted from the bidder since any additional revenue obtained would be offset through the penalty $f$ paid to the bidder.
Thus, for most parts of the proof, we focus solely on the scenario when $\critical_i \geq f$.
We start by deriving analogs of \Cref{thm:MatroidBeatCritical} and \Cref{thm:MatroidMoreThanCritical}.

\begin{lemma} \label{thm:RegBeatCritical}
    For a matroid feasibility constraint with regular value distributions $D_1, \dots, D_n$,
    $$\E_{v_i \sim D_i}[p_i(v_i, v_{-i}, \vec{b} | \strategy) \times \mathbbm{1}(v_i \geq \critical_i, \critical_i \geq f)] \leq \E_{v_i \sim D_i}[\vv_i(v_i) \, x_i(v_i , v_{-i}, \vec{b} | \strategy) \times \mathbbm{1}(v_i \geq \critical_i, \critical_i \geq f)]$$
    for any strategy $\strategy$ of the auctioneer that fabricates the set of bids $\vec{b}$.
\end{lemma}
For a given set of bids $v_{-i}$ and $\vec{b}$, $\mathbbm{1}(\critical_i \geq f)$ is a non-negative constant that is independent of $v_i$.
Thus, \Cref{thm:RegBeatCritical} follows by multiplying both sides of \Cref{thm:MatroidBeatCritical} by $\mathbbm{1}(\critical_i \geq f)$.

\begin{lemma} \label{thm:MatroidRegIntermediate}
    For a matroid feasibility constraint with $\alpha$-strongly regular bidder value distributions ($0 < \alpha < 1$), bids $v_{-i}$ of bidders apart from $i$ and any strategy $\strategy$ of the auctioneer than fabricates a set of bids $\vec{b}$,
    \begin{equation}
        \notag
        \begin{split}
            \E_{v_i \sim D_i}[p_i(v_i, v_{-i}, \vec{b} | \strategy) \mathbbm{1}(v_i < \beta_i, f \leq \critical_i)] 
            &\leq \frac{1}{\alpha} \cdot \E_{v_i \sim D_i}[\vv_i(v_i) \, x_i(v_i, v_{-i}, \vec{b} | \strategy) \times \mathbbm{1}(f \leq v_i, f \leq \critical_i)] \\
            &\qquad \qquad - \E_{v_i \sim D_i}[\vv_i(v_i) \, x_i(v_i, v_{-i}, \vec{b} | \strategy) \times \mathbbm{1}(\beta_i \leq v_i, f \leq \critical_i)].
        \end{split}
    \end{equation}    
\end{lemma}
\begin{proof}
The following chain of inequalities are similar to \Cref{thm:MatroidMoreThanCritical}.
    \begin{equation}
        \notag
        \begin{split}
            \E_{v_i \sim D_i}[p_i(v_i, v_{-i}, \vec{b} | \strategy) \mathbbm{1}(v_i < \beta_i, f \leq \critical_i)] &\leq \E_{v_i \sim D_i}[(v_i - f) \, x_i(v_i, v_{-i}, \vec{b} | \strategy) \times \mathbbm{1}(v_i < \beta_i, f \leq \critical_i)] \\
            &\leq \E_{v_i \sim D_i}[(\frac{1}{\alpha}\vv_i(v_i) + r_i - f) \, x_i(v_i, v_{-i}, \vec{b} | \strategy) \times \mathbbm{1}(f \leq v_i < \beta_i)]
        \end{split}
    \end{equation}
The first inequality follows since the maximum payment extracted from a bidder is their value.
The second inequality follows by first ignoring all values $v_i < f$, in which case $v_i - f$ is negative, and then applying \Cref{thm:RegLightTail}, which argues $(v_i - r_i) \leq \frac{1}{\alpha} \vv_i(v_i)$ for all $v_i \geq r_i$ for all $\alpha$-strongly regular distributions.
We will be choosing $f \geq r_i$ for all bidders $i$, and thus,
    \begin{equation}
        \notag
        \begin{split}
            \E_{v_i \sim D_i}[p_i(v_i, v_{-i}, \vec{b} | \strategy) \mathbbm{1}(v_i < \beta_i, f \leq \critical_i)]
            &\leq \E_{v_i \sim D_i}[\frac{1}{\alpha}\vv_i(v_i) \, x_i(v_i, v_{-i}, \vec{b} | \strategy) \times \mathbbm{1}(f \leq v_i < \beta_i)] \\
            &= \frac{1}{\alpha} \cdot \E_{v_i \sim D_i}[\vv_i(v_i) \, x_i(v_i, v_{-i}, \vec{b} | \strategy) \times \mathbbm{1}(f \leq v_i, f \leq \critical_i)] \\
            & \qquad - \frac{1}{\alpha} \cdot \E_{v_i \sim D_i}[\vv_i(v_i) \, x_i(v_i, v_{-i}, \vec{b} | \strategy) \times \mathbbm{1}(\beta_i \leq v_i, f \leq \critical_i)] \\
            &\leq \frac{1}{\alpha} \cdot \E_{v_i \sim D_i}[\vv_i(v_i) \, x_i(v_i, v_{-i}, \vec{b} | \strategy) \times \mathbbm{1}(f \leq v_i, f \leq \critical_i)] \\
            & \qquad - \E_{v_i \sim D_i}[\vv_i(v_i) \, x_i(v_i, v_{-i}, \vec{b} | \strategy) \times \mathbbm{1}(\beta_i \leq v_i, f \leq \critical_i)].
        \end{split}
    \end{equation}
The final inequality follows since $\alpha \in (0, 1)$.
\end{proof}

We will now describe the second condition.
Let $\FullRank_i$ be the event that in the virtual-surplus-optimal allocation that does not include bidder $i$, replacing any allocated fabricated bid by bidder $i$ makes the allocation infeasible.
In other words, if bidder $i$ is to be included, it must be by displacing another real bidder.
Note that $\FullRank_i$ is a property of bids $v_{-i}$ and $\vec{b}$, and is independent of $v_i$.
In order to displace a real bidder, bidder $i$ will have to place a bid with a virtual value larger than that of the replaced bidder and thus, its critical bid $\critical_i$ is independent of $\vec{b}$.
Concealing bids will, therefore, not alter the payment made by bidder $i$.
Similar to the scenario $f \geq \critical_i$, $\FullRank_i$ is the easier case to analyze.
Hence, we will focus on $\EmptyRank_i$, the negation of $\FullRank_i$.
We do so by comparing the auctioneer's revenue from being strategic against the revenue in a digital goods environment (where any subset of bidders can be feasibly allocated) with an additional constraint that only bidders with a value larger than $f$ can be allocated.

\begin{lemma} \label{thm:RegEmptyRank}
    Consider the $\alpha$-strongly regular values distributions $D_1, \dots, D_n$ in a matroid environment, with reserves $r_1, \dots, r_n$ respectively.
    Let the collateral $f$ satisfy \Cref{eqn:RegColIneq}.
    Then,
\begin{equation}
    \notag
    \begin{split}
        \sum_{i = 1}^n \E_{\vec{v} \sim \Pi_{j = 1}^n D_j} \Big[\sum_{i=1}^n p_i(v_i, \vec{v}, \vec{b} | \strategy) \times \mathbbm{1}(f \leq \critical_i, \EmptyRank_i) \Big]
        &= \frac{1}{n} \sum_{i = 1}^n \E_{\vec{v} \sim \Pi_{j = 1}^n D_j} \Big[\vv_i(v_i) \times \mathbbm{1}(r_i \leq v_i, f \leq \critical_i, \EmptyRank_i) \Big].
    \end{split}
\end{equation}
\end{lemma}
\begin{proof}
Since the environment is given by a matroid feasibility constraint, an injection can be drawn from the set of allocated bidders with values smaller than their critical value $\critical_i$ and the set of fake bids concealed by the auctioneer.
We can therefore continue assuming that each bidder allocated because of concealed bids are given a discount $f$ each by the auctioneer.

We will combine \Cref{thm:RegBeatCritical} and \Cref{thm:MatroidRegIntermediate}.
However, before taking expectation with respect to 
$v_{-i}$, we will multiply both sides by $\mathbbm{1}(\EmptyRank_i)$.
\begin{equation}
    \notag
    \begin{split}
                    \E_{\vec{v} \sim \Pi_{j = 1}^n D_j} \Big[\sum_{i=1}^n p_i(v_i, \vec{v}, \vec{b} | \strategy) \times \mathbbm{1}(f \leq &\critical_i, \EmptyRank_i)\Big] \\ &\leq \frac{1}{\alpha} \cdot \sum_{i = 1}^n \E_{\vec{v} \sim \Pi_{j = 1}^n D_j}[\vv_i(v_i) \, x_i(v_i, v_{-i}, \vec{b} | \strategy) \times \mathbbm{1}(f \leq v_i, f \leq \critical_i, \EmptyRank_i)]
    \end{split}
\end{equation}
The right hand side can be upper-bounded by the auctioneer's revenue in the digital goods environment, where the bidders are allocated whenever their values are at least the collateral $f$.
By \Cref{thm:MyersonVV}, $\E_{\vec{v} \sim \Pi_{j = 1}^n D_j}[\vv_i(v_i) \times \mathbbm{1}(f \leq v_i, f \leq \critical_i, \EmptyRank_i)] = f \cdot Pr(v_i \geq f) \times \mathbbm{1}(f \leq \critical_i, \EmptyRank_i)$.
We therefore have
\begin{equation}
    \notag
    \begin{split}
        \E&_{\vec{v} \sim \Pi_{j = 1}^n D_j}\Big[\sum_{i=1}^n p_i(v_i, \vec{v}, \vec{b} | \strategy) \times \mathbbm{1}(f \leq \critical_i, \EmptyRank_i) \Big] \leq \frac{1}{\alpha} \cdot \sum_{i = 1}^n \E_{v_{-i} \sim D_{-i}} \Big[f \cdot Pr(v_i \geq f) \times \mathbbm{1}(f \leq \critical_i, \EmptyRank_i)\Big] \\
        &\leq \frac{1}{\alpha} \cdot \sum_{i = 1}^n \Bigg(\frac{r_i}{(1-\alpha) \, f + \alpha r_i}\Bigg)^{\frac{1}{1-\alpha}} \times \Big(\frac{f}{r_i} \Big) \cdot r_i Pr_{v_i \sim D_i}(v_i \geq r_i) \cdot Pr_{v_{-i} \sim D_{-i}}(f \leq \critical_i, \EmptyRank_i) \\
        &\leq \frac{1}{\alpha} \Bigg(\frac{\max_i \{r_i\}}{(1-\alpha) \, f + \alpha \max_i \{r_i\}}\Bigg)^{\frac{1}{1-\alpha}} \times \Big(\frac{f}{\max_i \{r_i\}} \Big) \sum_{i = 1}^n r_i \cdot Pr_{v_i \sim D_i}(v_i \geq r_i) \cdot Pr_{v_{-i} \sim D_{-i}}(f \leq \critical_i, \EmptyRank_i)
    \end{split}
\end{equation}
The second line is a direct consequence of \Cref{thm:MHRWeirdBound} in \Cref{appendix:mhr-properties}.
As for the final inequality, we prove that $\big(\frac{r}{(1-\alpha) \, f + \alpha r}\big)^{\frac{1}{1-\alpha}} \times \big(\frac{f}{r} \big)$ is monotone increasing in $r$ as long as $r \leq f$ in \Cref{thm:Mon}.


\begin{lemma} \label{thm:Mon}
    When $\frac{f}{t} \geq 1$, $\Bigg(\frac{t}{(1-\alpha) \, f + \alpha t}\Bigg)^{\frac{1}{1-\alpha}} \times \Big(\frac{f}{t} \Big)$ is increasing in $t$.
\end{lemma}
\begin{proof}
    Let $x = \frac{f}{t}$. We would want to prove $\Bigg(\frac{1}{(1-\alpha) \, x + \alpha}\Bigg)^{\frac{1}{1-\alpha}} \times x$ is decreasing in $x$ when $x \geq \frac{1}{\alpha}$.
    The above is equivalent to proving
    $$\frac{1}{(1-\alpha)x^\alpha + \alpha x^{-(1-\alpha)}}$$
    is decreasing when $x \geq 1$.
    The derivative of the denominator easily confirms the same.
\end{proof}


Since we choose $f$ such that $\frac{1}{\alpha} \times \big(\frac{\max_i \{r_i\}}{(1-\alpha) \, f + \alpha \max_i \{r_i\}}\big)^{\frac{1}{1-\alpha}} \times \big(\frac{f}{\max_i \{r_i\}} \big) \leq \frac{1}{n}$,
\begin{equation}
    \notag
    \begin{split}
        \E_{\vec{v} \sim \Pi_{i = 1}^n} \Big[\sum_{i=1}^n p_i(v_i, \vec{v}, \vec{b} | \strategy) \times \mathbbm{1}(f \leq \critical_i, \EmptyRank_i) \Big] &\leq \frac{1}{n} \sum_{i = 1}^n r_i \cdot Pr_{v_i \sim D_i}(v_i \geq r_i) \cdot Pr_{v_{-i} \sim D_{-i}}(f \leq \critical_i, \EmptyRank_i) \\
        &= \frac{1}{n} \sum_{i = 1}^n \E_{\vec{v} \sim \Pi_{j = 1}^n} \Big[\vv_i(v_i) \times \mathbbm{1}(r_i \leq v_i, f \leq \critical_i, \EmptyRank_i) \Big]
    \end{split}
\end{equation}
\end{proof}

\begin{proof}[Proof of \Cref{thm:MatroidReg}]
We recall our observations that the auctioneer cannot increase the revenue extracted from bidder $i$ whenever $f > \critical_i$ or the event $\FullRank_i$ happens.
After combining the above observation with \Cref{thm:RegEmptyRank}, we sketch a mechanism with a virtual surplus greater than the auctioneer's expected revenue from being strategic in the DRA.
The optimal mechanism will only obtain a greater virtual surplus and thus, a greater revenue.

Condition on $\critical_i < f$ or the event $\FullRank_i$ getting realized.
Then, the auctioneer cannot increase its revenue from bidder $i$ by concealing any bids.
Thus,
\begin{equation} \label{eqn:Smallf}
    \begin{split}
        \E_{\vec{v} \sim \Pi_{j = 1}^n}\Big[p_i(v_i, \vec{v}, \vec{b} | \strategy) \times \mathbbm{1}(f > \critical_i)\Big] &\leq \E_{\vec{v} \sim \Pi_{j = 1}^n}\Big[p_i(v_i, \vec{v}, \vec{b}) \times \mathbbm{1}(f > \critical_i)\Big] \\
        &= \E_{\vec{v} \sim \Pi_{j = 1}^n}\Big[\vv_i(v_i) \, x_i(v_i, \vec{v}, \vec{b}) \times \mathbbm{1}(f > \critical_i)\Big]
    \end{split}
\end{equation}

\begin{equation} \label{eqn:Largef}
    \begin{split}
        \E_{\vec{v} \sim \Pi_{j = 1}^n}\Big[p_i(v_i, \vec{v}, \vec{b} | \strategy) \times \mathbbm{1}(f \leq \critical_i, \FullRank_i)\Big] &\leq \E_{\vec{v} \sim \Pi_{j = 1}^n}\Big[p_i(v_i, \vec{v}, \vec{b}) \times \mathbbm{1}(f \leq \critical_i, \FullRank_i)\Big] \\
        &= \E_{\vec{v} \sim \Pi_{j = 1}^n}\Big[\vv_i(v_i) \, x_i(v_i, \vec{v}, \vec{b}) \times \mathbbm{1}(f \leq \critical_i, \FullRank_i)\Big]
    \end{split}
\end{equation}
Adding \Cref{eqn:Smallf} and \Cref{eqn:Largef}, summing over all bidders $i$ and adding \Cref{thm:RegEmptyRank}, we get
\begin{equation}
    \notag
    \begin{split}
        \sum_{i=1}^n \E_{\vec{v} \sim \Pi_{j = 1}^n}\Big[p_i(v_i, \vec{v}, \vec{b} | \strategy)\Big] &\leq \frac{1}{n} \sum_{i = 1}^n \E_{\vec{v} \sim \Pi_{j = 1}^n} \Big[\vv_i(v_i) \times \mathbbm{1}(r_i \leq v_i, f \leq \critical_i, \EmptyRank_i) \Big] \\
        &\qquad + \E_{\vec{v} \sim \Pi_{j = 1}^n}\Big[\vv_i(v_i) \, x_i(v_i, \vec{v}, \vec{b}) \times (1-\mathbbm{1}(f \leq \critical_i, \EmptyRank_i))\Big]
    \end{split}
\end{equation}

The following allocation rule achieves a virtual surplus at least the right hand side of the above inequality.
Compute the allocation rule $x(\vec{v}, \vec{b})$ from fabricating a set of bids $\vec{b}$.
\begin{enumerate}
    \item Amongst all bidders $i$ such that $v_{-i}$ satisfy $f \leq \critical_i$ and $\EmptyRank_i$, choose one uniformly at random and allocate to the chosen bidder $i$ if $v_i \geq r_i$.
    \item Allocate all other bidders according to $x(\vec{v}, \vec{b})$.
\end{enumerate}
We still have to verify that the above allocation rule is feasible.
We prove feasibility from allocating bidders according to bullet 1 by considering the following two cases -- whether bidder $i$ is allocated by $x(\vec{v}, \vec{b})$ or not.

When bidder $i$ is excluded by $x(\vec{v}, \vec{b})$, from the definition of $\EmptyRank_i$, there exists an allocated fabricated bid that can be feasibly replaced by bidder $i$ and thus, allocating bidder $i$ alongside the other allocated bidders is feasible.
If $x(\vec{v}, \vec{b})$ allocates bidder $i$, then, by \Cref{thm:MatroidConceal}, the optimal allocation with bidder $i$'s bid concealed allocates the same set of bidders and possibly one additional bidder.
From the definition of $\EmptyRank_i$, at least one of the allocated bids that can be feasibly replaced by $i$ must be fake.
Thus, including bidder $i$ does not break feasibility.
The optimal mechanism $x^{\OPT}$ only has a larger virtual surplus, and thus, a larger revenue that the auctioneer's revenue from being strategic.
\end{proof}

\subsection{Omitted Proofs in \Cref{sec:lowerbound-beyond-matroids}}
\label{appendix:proof-of-CreativeConstraint}

For \Cref{thm:non-matroid-impossibility}, we will recreate the proof of \Cref{thm:CreativeConstraint}.
For some bidder $i$ and a non-matroid feasibility constraint $\Feasibility$, we will find two disjoint sets of bidders $X$ and $Y$ of the same cardinality such that $X \cup \{i\}, Y \in \Feasibility$ and all feasible subsets of $X \cup Y \cup \{i\}$ other than $X \cup i$ have a cardinality at most $|X|$. 
Once such sets $X$ and $Y$ are identified, the remainder of the proof follows closely to \Cref{thm:CreativeConstraint}, replacing the bidders $x$ and $y$ with the sets $X$ and $Y$ respectively.

\begin{proof}[Proof of \Cref{thm:non-matroid-impossibility}]
We will first prove \Cref{thm:non-matroid-impossibility} assuming the existence of a bidder $i$, sets $X$ and $Y$ such that $|X| = |Y|$, $X \cup \{i\}, Y \in \Feasibility$ and all feasible subsets of $X \cup Y \cup \{i\}$ apart from $X \cup \{i\}$ have a cardinality at most $|X|$.
We show that such sets exist later in \Cref{lem:non-matroid}.

When there is only a single bidder $i$ whose value is drawn from the exponential distribution with mean $1$, the miner fabricates the bidders $X \cup Y$ and reports their distributions to be the same exponential distribution as $i$.
Further, it reports a bid $b_x = b_y = f+2$ for all bidders $x \in X$ and $y \in Y$ for any collateral $f$ charged by the DRA.

In the revelation phase, the auctioneer follows a strategy similar to \Cref{thm:CreativeConstraint}.
If bidder $i$'s value $v_i \leq |X| (f+1) + 1$, the auctioneer reveals all its bids.
All feasible subsets contained in $X \cup Y \cup \{i\}$ that does not include $i$ has a cardinality at most $|X|$.
Thus, the virtual-value-optimal allocation allocates the set $X$ and the bidder $i$ as long as it has a positive virtual value.
Thus, bidder $i$'s critical bid equals $1$, the same as when the auctioneer is honest.

Now suppose that $v_i > |X| (f+1) + 1$.
Then, the auctioneer conceals all bidders $x \in X$, and pays a penalty $|X| \times f$.
However, $\{i\}$ is the virtual-value-optimal allocation with a virtual value at least $\vv(|X| (f+1) + 1) = |X| (f+1)$, against the total virtual value equal to $|Y| (f+1) = |X| (f+1)$ of the bidders in $Y$.
Further, bidder $i$'s critical bid equals $|X| (f+1) + 1$.
The auctioneer receives a net revenue equal to $|X| (f+1) + 1 - |X| \times f = |X| + 1 > 1$, the revenue from the honest strategy.
Thus, the strategic deviation generates a strictly larger revenue than the honest strategy, and thus, the DRA is not credible.

It only remains to show the existence of the bidder $i$ and the sets $X$ and $Y$ for an arbitrary non-matroid feasibility constraint. 

\begin{lemma} \label{lem:non-matroid}
    For any downward-closed feasibility constraint $\Feasibility$ that is not a matroid, there exists two feasible sets $\hat{X}, Y \in \Feasibility$ such that $\hat{X} \cap Y = \emptyset$, $|\hat{X}| = |Y| + 1$, and for any feasible subset $S$ of $\Feasibility$ contained in $\hat{X} \cup Y$, $S \neq \hat{X}$, then $|S| < |\hat{X}|$.
\end{lemma}
For any $i \in \hat{X}$, $X = \hat{X} \setminus \{i\}$ and $Y$ satisfy these properties of the sets $X$ and $Y$.
\end{proof}

\begin{proof}[Proof of \Cref{lem:non-matroid}]
    Let the constraint $\Feasibility$ be defined over the set of elements $E$.
    Suppose that $|E| \geq 3$ (all feasibility constraints over $2$ or less elements are matroids).
    It is not hard to verify that the claim holds when $E = 3$.
    We will prove the claim by induction on $e$, the number of items in $E$.

    Let the lemma be true for all non-matroid constraints over $e$ elements for all $e \leq n$.
    We will prove the claim when $|E| = n+1$.

    Since $\Feasibility$ is not a matroid, there exists some sets $A, B$ such that the augmentation property is not satisfied, i.e, $|A| > |B|$ and $B \cup \{i\} \not \in \Feasibility$ for any $i \in A$.
    Let 
    $$\mathcal V = \{(A,B) : A,B\in \Feasibility, |A|>|B|, B \cup \{e\} \notin \Feasibility~\forall e \in A \setminus B\}$$
    be the collection of all such sets $A$ and $B$.

    Choose $(X_0, Y_0) \in \mathcal{V}$ to maximize $|X_0 \cap Y_0|$ amongst all pairs in $\mathcal{V}$.
    We handle the following three cases separately --- either $X_0 \cap Y_0 \neq \emptyset$, or $X_0 \cap Y_0 = \emptyset$ and $|X_0| > |Y_0| + 1$, or $X_0 \cap Y_0 = \emptyset$ and $|X_0| = |Y_0| + 1$.
    \begin{enumerate}
        \item $X_0 \cap Y_0 \neq \emptyset$: Consider the collection $\hat{\Feasibility}$ of all feasible sets contained in $\Feasibility \setminus (X_0 \cap Y_0)$.
        Observe that $\hat{\Feasibility}$ is also not a matroid constraint since $X_0 \setminus (X_0 \cap Y_0)$ and $Y_0 \setminus (X_0 \cap Y_0)$ contained in $\hat{\Feasibility}$ also does not satisfy the augmentation property.
        By the induction hypothesis, there exists $\hat{X}, Y \in \hat{\Feasibility}$ which satisfies all the necessary properties.
        By construction, $\hat{X}$ and $Y$ are also feasible under $\Feasibility$ as required.
        \item $X_0 \cap Y_0 = \emptyset$ and $|X_0| > |Y_0| + 1$: For some element $i \in X_0$, consider the collection $\hat{Feasibility}$ of feasible sets contained in $E \setminus \{i\}$.
        $\hat{\Feasibility}$ is still not a matroid yet, since $X_0 \setminus \{i\}$, $Y$ continue to violate the augmentation property.
        By induction hypothesis, there exists $\hat{X}, Y \in \hat{\Feasibility}$ satisfying all the required properties.
        \item $X_0 \cap Y_0 = \emptyset$ and $|X_0| = |Y_0| + 1$: We will set $\hat{X} = X_0$ and $Y = Y_0$.
        We only have to verify that any feasible subset contained in $X_0 \cup Y_0$ that is not equal to $X_0$ has a cardinality strictly less than $X_0$.
        Assume otherwise and suppose that there exists $S$ such that $S \subseteq X_0 \cup Y_0$ and $|S| \geq X_0$.
        Note that $(S, Y_0) \in \mathcal{V}$.
        Further, $S \cap Y_0 > 0$.
        Otherwise, $S$ is contained in $X_0 \cup Y_0$, has cardinality at least $X_0$ and does not intersect with $Y_0$, and thus, $S$ must be equal to $X_0$.
        However, we choose $(X_0, Y_0) \in \mathcal{V}$ that maximizes the intersection between the two sets.
        Contradiction.
        Thus, any feasible subset contained in $X_0 \cup Y_0$ must either be $X_0$ or have a cardinality strictly smaller than $|X_0|$, as required. \qedhere
    \end{enumerate}
\end{proof}



\subsection{Omitted Proofs in \Cref{sec:LowerMHR}} \label{sec:proofofkkMHR}

\begin{proof}[Proof of \Cref{thm:nnMHR}]
As an immediate corollary to \Cref{thm:11MHR}, we can see that the largest monopoly reserve is also necessary in single-item multi-agent environments.
Consider a bidder with its value drawn from the exponential distribution (called the large bidder) and $(n-1)$ bidders with a deterministic value $\eta$ for a sufficiently small $\eta$ (called small bidders).
The revenue from being honest can be upper bounded by the revenue of an environment with two items --- the first item can solely be allocated to the large bidder and the second item is always allocated to one of the small bidders.
The auctioneer's expected revenue from allocating the item to the large bidder at a price equal to the monopoly reserve $1$ equals $\frac{1}{e}$.
Therefore, the expected honest revenue is at most $\frac{1}{e}+\eta$.
Choose $\eta$ to be sufficiently small such that the auctioneer's revenue while playing the strategy described in \Cref{thm:11MHR} allocating only the large bidder is greater than $\frac{1}{e} + \eta$.
Then, a collateral equal to $1 - \epsilon$ is not sufficient for single-item multi-agent environments.    
\end{proof}

For \Cref{thm:kkMHR} and \Cref{thm:1nMHR}, at a high level, the proofs are similar to \Cref{thm:11MHR} and consist of considering the difference in the auctioneer's revenue from being strategic and being honest when the bidders' values belong to different intervals (albeit requiring a more careful analysis for these environments).

\begin{proof}[Proof of \Cref{thm:kkMHR}]
Consider the auctioneer's strategy where it inserts a fake bid equal to $1+\delta$ and hides the bid when all bidders have values larger than $1$, but there exists a bidder $i$ with value $v_i \in [1, 1+\delta]$.
It reveals the fake bid in all other scenarios.


The auctioneer receives a revenue $k \, (1+\delta)$ when all bidders have a value larger than $1+\delta$, and $1$ per allocated bidder even if a single bidder has a value in the range $[0, 1+\delta]$.
The auctioneer pays a penalty $1-\epsilon$ when (a) there are a positive number of bidders with values between $1$ and $1+\delta$ and (b) all bidders have values that beat the monopoly reserve (this is exactly when the auctioneer hides its fake bid).

Once again, we will evaluate the difference in the auctioneer's revenue when it is strategic and when it is honest.
In  both the strategies, the auctioneer receives a revenue of $1$ per allocated bidder irrespective of the allocated bidders' values.
Further, the strategic auctioneer receives an extra $k\delta$ revenue when all bidders have a value at least $(1+\delta)$, which happens with a probability $e^{-k\, (1+\delta)}$.
The auctioneer pays a penalty precisely when all bidders have value greater than $1$ (probability of which equals $e^{-k}$), but not all of them have a value greater than $1+\delta$ (which happens with a probability $e^{-k(1+\delta)}$).
Thus, the auctioneer's expected marginal revenue from being strategic equals $k \delta e^{-k \, (1+\delta)} - (1-\epsilon) \, (e^{-k} - e^{-k \, (1+\delta)})$
which is positive if and only if
$$\frac{k\delta \, e^{-k \, (1+\delta)}}{(e^{-k} - e^{-k \, (1+\delta)})} \geq (1-\epsilon).$$
Once again, the limit of the left hand side as $\delta \xrightarrow{} 0$ is $1$, and thus, for a small enough $\delta$, the strategic auctioneer receives a larger revenue than being honest.    
\end{proof}

\begin{proof}[Proof of \Cref{thm:1nMHR}]    
    Similar to the single-item single agent environment, the auctioneer inserts a fake bid equal to $1+\delta$, and conceals the fake bid if the highest bid is in the range $[1, 1+\delta]$.

    We break down the proof into five cases depending on the values of the largest and the second largest bids:
    \begin{enumerate}
        \item Both the largest and the second largest bids are greater than $1+\delta$: In this case, the presence of the fake bid is irrelevant, and the auctioneer generates the same revenue irrespective of whether it is honest or strategic.
        \item The largest bid is greater than $1+\delta$, but the second largest bid is in the range $[1, 1+\delta]$:
        The auctioneer receives a payment $1+\delta$ when being strategic, but receives the second highest bid (smaller than $1+\delta$) when being truthful.
        However, as the number of bidders $n \xrightarrow{} \infty$, it is very likely that the second highest bid is quite close to $1+\delta$.
        Thus, we will pretend that the auctioneer receives the same revenue both, when being strategic and when being honest.
        \item The largest bid is greater than $1+\delta$ and the second largest bid is smaller than $1$: The auctioneer makes $1+\delta$ when being strategic, while it makes $1$ by being honest.
        Thus, the auctioneer makes $\delta$ more by being strategic in this case, which happens with a probability $n \, e^{-(1+\delta)}(1-e^{-1})^{(n-1)}$.
        \item The largest bid is in the range $[1, 1+\delta]$ (irrespective of the value of the second largest bid): The auctioneer receives the same payment when being strategic and when being honest.
        However, the auctioneer has to pay a penalty $(1-\epsilon)$ since it has to conceal its fake bid.
        This case happens with a probability $(1-e^{-(1+\delta)})^n - (1-e^{-1})^n$ (i.e, the difference between the probabilities of all bids being smaller than $1+\delta$ and smaller than $1$, respectively).
        \item Both, the largest and the second largest bids are smaller than $1$: No bids beat the reserve and thus, no bidder is allocated the item.
        The auctioneer does not have to conceal its fake bid, since no bidder will get allocated anyways.
    \end{enumerate}

    Thus, the expected difference in revenues equals $$\delta ne^{-(1+\delta)}(1-e^{-1})^{n-1} - (1-\epsilon) \, \Big[(1-e^{-(1 + \delta)})^n - (1-e^{-1})^n \Big]$$
    which is greater than zero if and only if
    $$\frac{\delta n e^{-(1+\delta)}(1-e^{-1})^{n-1}}{\Big[(1-e^{-(1 + \delta)})^n - (1-e^{-1})^n \Big]} > 1-\epsilon.$$
    As was the case in the single-item single-agent environment, the left hand side tends to $1$ as $\delta$ approaches zero.
    Thus, the auctioneer can inject a bid sufficiently close to $1$ to extract larger revenue by being strategic than while playing the honest strategy.
\end{proof}

\subsection{Proof of \Cref{thm:PrivatePublicSep}}
\label{appendix:proof-of-PrivatePublicSep}

Consider the following strategy by the auctioneer.
The auctioneer does not communicate any of the bids placed by the bidders to each other.
The auctioneer sends $(k-1)$ large bids, all greater than $1$ to each of the $k$ bidders and reveals all of them irrespective of the bids submitted by the agents.
Finally, the auctioneer communicates a bid equal to $1+\delta$ to all users, and conceals the bid from any bidder who realizes a value between $1$ and $1+\delta$.

From the perspective of each bidder, $k-1$ items are sold to the $k-1$ large fake bids inserted by the auctioneer and the bidder is competing for the final available item.
Thus, the auctioneer has reduced the auction into $k$ parallel single item auctions, with two bidders in each of them (one real bidder and the other, the fake bid $1+\delta$). However, the total collateral put up by the fake bid is $1$, and not $1$ each for the $k$ parallel auctions.

The auctioneer's revenue from being strategic can be lower bounded as follows.
The auctioneer always pays a penalty $1$, to get a ``license'' to cheat with its fake bid.
With the penalty paid upfront, the auctioneer makes a revenue pointwise larger than the optimal auction --- $\delta$ more whenever a bidder has a value larger than $1+\delta$ (which happens with a probability $e^{-(1+\delta)}$), and exactly the same as the optimal auction at other values.
Thus, the expected additional revenue from inserting a fake bid with value $1+\delta$ equals $k \, \delta e^{-(1+\delta)}$.

For a sufficiently large $k$, the additional revenue is larger than the ``license fee'' $1$ paid by the auctioneer, and thus, it is profitable to deviate from the honest strategy.


\subsection{Proof of \Cref{thm:ADRA}}
\label{appendix:proof-of-ADRA}

% \begin{theorem}\label{thm:ADRA}
%     The ADRA is credible irrespective of the bidders' value distributions $D_1, \dots, D_n$ and the matroid feasibility constraint $\Feasibility$.
% \end{theorem}

To analyze credibility of the ADRA, we will make the following simplifying modification.
When the set of $\mathsf{active}$ bidders have been trimmed down sufficiently so that all bidders in $\activeBid_{\ell}$ can be simultaneously allocated by the ADRA, we break the loop in \Cref{bul:ADRALoop} in \Cref{def:ADRA} (i.e, the original version) to stop the auction (let this happen during level $\ell$).
We then allocate all $\mathsf{active}$ bidders at the final price, and ask them to reveal their bids in level $\ell + 1$.
An alternative could be to continue with the loop in \Cref{bul:ADRALoop}, increasing the virtual price until it exceeds all virtual bids and allocate all $\mathsf{promised}$ bidders in the final simulation of $\hat{\mechanism}$ before all bidders $\mathsf{quit}$.
The alternate design ensures that all bidders reveal their bids only after the virtual price has exceeded the virtual value of their bids.
Note that this is not the case in the original version, since bidders allocated during the final stage (\Cref{bul:ADRAFinal}) might be asked to reveal their bids even though the virtual price is smaller than their virtual bids.

The two variants of the ADRA are strategically equivalent to the auctioneer.
Let $\activeBid_{\ell}$ be the set of active bidders at the start of level $\ell + 1$.
For any set of bids $\mathsf{aborted}$ by the auctioneer during level $\ell + 1$ (or after, in case of the modified version), the payment charged to any bidder is independent of the bids of the bidders in $\activeBid_{\ell}$, as long as they are large enough to remain $\mathsf{active}$ during round $\ell + 1$.
All virtual bids not belonging to $\activeBid_{\ell}$ are strictly smaller than the virtual bids belonging to $\activeBid_{\ell}$.
Since $\hat{\mechanism}$ optimizes virtual-surplus, and the feasibility constraint is a matroid, all bidders in $\activeBid_{\ell}$ are allocated irrespective of the bids $\mathsf{aborted}$ by the auctioneer.
Thus, the critical bids of these bidders are independent of the other bids in $\activeBid_{\ell}$, and is purely a function of the bids $\mathsf{aborted}$ by the auctioneer in levels $\ell + 1$ (or after, in the modified version) and the bids already revealed by the bidders that have $\mathsf{quit}$ in previous levels.
Similarly, conditioned on allocating all bidders in $\activeBid_{\ell}$, the critical bids of all $\mathsf{promised}$ bidders are also purely a function of the bids $\mathsf{aborted}$ by the auctioneer and previously revealed bids.
Therefore, learning the bids in $\activeBid_{\ell}$ during level $\ell + 1$ in the original version does not allow the auctioneer to increase its revenue.
On the other hand, $\mathsf{aborting}$ bids in levels after $\ell + 1$ in the modified game also does not help the auctioneer, since the auctioneer could have extracted a strictly larger revenue by $\mathsf{aborting}$ those bid during level $\ell + 1$.

While the original version achieves a better communication complexity, since it terminates in a lesser number of levels, it is convenient to show that the modified version is credible.
In the following, we show credibility of ADRA for matroids by proving any deviation $G'$ for the auctioneer cannot improve the revenue.

% \Anote{@Qianfan, find a way to transition from the argument above to whatever follows smoothly.}

% \Qianfan{TODO: change all clinched to promised..}

But first, let us define the suggested strategy $S_i^\ADRA(b_i)$ for bidder $i$ as follows:
\begin{itemize}
    \item Commit to bidding $b_i$ (which may differ from her true value $v_i$).
    \item $\mathsf{Quit}$ at the first level $\ell$ where $\overline{\vv_i}(b_i) < p_\ell^\vv$ and reveal the commitment.
\end{itemize}

Observe that bidders should always use some suggested strategy, as other strategies always end up with a negative utility, and it suffices for us to consider suggested strategies only.

\begin{lemma}\label{lemma:use-suggested-strategy}
    It is always a best response for a real bidder $i \in [n]$ to implement the suggested strategy $S_i^\ADRA(b_i)$ for some $b_i$.
\end{lemma}

\begin{proof}
    Whenever bidder $i$ deviates from suggested strategies, they will not be allocated and lose their deposit according to the perfect binding property of the commitment scheme, resulting a negative utility. Therefore, it is dominated by the truthful strategy $S_i^\ADRA(v_i)$ which always yields a non-negative utility.
\end{proof}

Also note that a bidder will always be allocated once $\mathsf{promised}$ with a fixed payment.

\begin{lemma}\label{lem:clinched-implies-allocation}
    A real bidder $i \in [n]$ using a suggested strategy $S_i^\ADRA(b_i)$ for some $b_i$ will always be allocated once $\mathsf{promised}$ with a payment that only depends on auctioneer and bidders' actions before she becomes $\mathsf{promised}$.
\end{lemma}

\begin{proof}
    To see that bidder $i$ will always be allocated once $\mathsf{promised}$ by the end of some level $\ell$ with a payment $p$, note that $\overline{\vv_i}(p)\le p_\ell^\vv$ and every bidder $j$ that does not $\mathsf{quit}$ or $\mathsf{abort}$ by the end of the level must have committed to a bid $\overline{\vv_j}(b_j) > p_\ell^\vv$ or eventually $\mathsf{abort}$, and thus cannot affect bidder $i$'s threshold price.
\end{proof}



Given any auctioneer's deviation $G'$, a strategy profile $\vb{S}$, and bidders' value $\vb{v}$,  denote the final allocation by $A(G',\vb{S}(\vb{v})) \in \hat{\Feasibility}$.  
When it is clear from context, we may abbreviate this as $A(G')$.
In the following, we assume every real bidder $i \in [n]$ implements a suggested strategy $S_i^\ADRA(b_i)$ for some $b_i$, i.e., $\vb{S}=\vb{S}^\ADRA$.

We first show the auctioneer never $\mathsf{abort}$ fabricated bids that is $\mathsf{promised}$ using any undominated deviation $G'$.

\begin{lemma}\label{lem:undominated-deviation}
    When the auctioneer employs any undominated deviation $G'$, a fabricated bid $b_i$ is never $\mathsf{aborted}$ at some level if it is $\mathsf{promised}$ or it would be $\mathsf{promised}$ by the end of the level if not $\mathsf{aborted}$.\footnote{Here we implicitly assume the auctioneer always act last at each level and decide whether to $\mathsf{quit}$ or $\mathsf{abort}$ fabricated bids after receiving all real bidders' actions. \label{footnote:auctioneer-action-last}}
\end{lemma}

\begin{proof}
Consider a deviation $G'$ where the auctioneer $\mathsf{abort}$ a fabricated bid $b_i$ at some information set $I$ of level $\ell$ where $b_i$ is $\mathsf{promised}$ or going to be $\mathsf{promised}$.
Let $\ell'\le\ell$ be the last level where $b_i$ is not $\mathsf{promised}$ at the beginning of the level.
Define $G''$ be another deviation that is identical to $G'$ except that $G''$ does not $\mathsf{abort}$ $b_i$ at information set $I$, and after this point, $G''$ proceeds exactly as if $b_i$ had been $\mathsf{aborted}$ in $G'$.\footnote{This is feasible because the auctioneer's subsequent decisions remain unaffected by whether a fabricated bid is $\mathsf{aborted}$.}



Let $B',B''$ denote sets of bidders who were not $\mathsf{aborted}$ under $G'$ and $G''$, respectively.
By definition, for any strategy profile $\vb{S}$ and bidders' value $\vb{v}$, $G''$ reaches the information set $I$ if and only if $G'$ reaches $I$, and the final set of bidders who did not $\mathsf{abort}$ will be identical expect for $i$, i.e., $B'' = B' \cup \{i\}$.
By the optimality of ADRA, the allocations $A(G'')$ and $A(G'')$ correspond to the virtual-surplus-maximizing feasible subsets of $B'$ and $B''$, respectively, and $i \in A(G'')$ by \Cref{lem:clinched-implies-allocation}.
%\Anote{Can you say a little more why this is true? Feels true, but would be nice to explicitly write the reason down.} \Qianfan{I don't know what's the simplest way to argue this, but one way is to reason about it is through the greedy algorithm running on the matroid} \Anote{I guess we are using the exchange property that we used for the DRA.}
Since $\hat{\Feasibility}$ is a matroid, the size of $G''$ and $G'$ differ by at most $1$, and we consider these two cases separately:
\begin{enumerate}
    \item When $|A(G'')| = |A(G')|+1$, we have $A(G'') = A(G') \cup \{i\}$.
    Then, compared to $G''$, $G'$ loses the collateral $d_{\ell'}$ for aborting $b_i$ without getting anything in return.
    \item When $|A(G'')| = |A(G')|$, there exists some $j \in [\hat{n}]$ such that $\overline{\vv_j}(b_j)\le\overline{\vv_i}(b_i)$ and $(A(G') \setminus \{j\}) \cup \{i\} \in \hat{\Feasibility}$ by \Cref{thm:MatroidBasisExchange} and optimality of $A(G'')$. 
    Then, the difference of revenue between $G'$ and $G''$ will be at most $b_j-d_{\ell'}$ (when $j$ is a real bidder), which must be a negative number since otherwise $b_i$ would not be $\mathsf{promised}$ at the beginning of level $\ell'+1$ (or before aborting if $\ell'=\ell$).
\end{enumerate}
% , we must have $A(G'') \setminus A(G') = \{i\}$, and either $A(G') \cup \{i\} \in \hat{\Feasibility}$ or there exists some $j \in A(G')$ such that $(A(G') \setminus \{j\}) \cup \{i\} \in \hat{\Feasibility}$.
% In the former case, $G'$ loses the collateral $d_{\ell'}$ for aborting $b_i$ without getting anything in return.
% That is also true for the latter case when $j$ is a fabricated bidder.
% In the latter case with $j$ being a real bidder, the difference of revenue between $G'$ and $G''$ will be at most $b_j-d_{\ell'}$, which must be a negative number since otherwise $b_i$ would not be clinched at the beginning of level $\ell'+1$ (or before aborting if $\ell'=\ell$).
In conclusion, $G''$ dominates $G'$. %\Qianfan{requires iid distribution} \Anote{Will collecting a deposit equal to $\max_i \vv^{-1}(p_{\ell+1}^{\vv})$ be sufficient? Or do we really need iid?}
\end{proof}

We further show allocation monotonicity between two suggested strategies $S^\ADRA_i(b_i), S^\ADRA_i(b_i')$ with $b_i < b_i'$ via \Cref{lem:clinched-before-quit} and \Cref{lem:allocation-monotonicity}.

\begin{lemma}\label{lem:clinched-before-quit}
   When the auctioneer employs any undominated deviation $G'$, consider two suggested strategies $S_i^\ADRA(b_i), S_i^\ADRA(b_i')$ for a real bidder $i \in [n]$ with $b_i < b_i'$.
    Whenever bidder $i$ $\mathsf{quit}$ at some level $\ell$ and is eventually allocated using $S_i^\ADRA(b_i)$, she must be $\mathsf{promised}$ by the end of level $\ell$ using $S_i^\ADRA(b_i')$.
\end{lemma}

\begin{proof}
    Assume for some strategy profile $\vb{S}$ and bidders' value $\vb{v}$,  bidder $i$ $\mathsf{quit}$ at level $\ell$ but ends up being allocated (i.e., $i \in A(G')$) using $S_i^\ADRA(b_i)$, while she would not be $\mathsf{promised}$ by the end of level $\ell$ when using $S_i^\ADRA(b_i')$ with $b_i'>b_i$.
    Let $i_1,i_2,...,i_k \in [\hat{n}]$ be the bidders who $\mathsf{abort}$ after bidder $i$ $\mathsf{quit}$, listed in the order in which they abort.
    For every $0 \le j \le k$, further define $A^{(j)} \in \hat{\Feasibility}$ to be the final allocation assuming only a prefix of these bidders $\{i_1,i_2,\ldots,i_j\}$ $\mathsf{abort}$, and we have:
    \begin{itemize}
        \item $i \notin A^{(0)}$ since bidder $i$ would not be $\mathsf{promised}$ by the end of level $\ell$ when using $S_i^\ADRA(b_i')$ with $b_i'>b_i$ (which is  indistinguishable from $S_i^\ADRA(b_i)$ before she $\mathsf{quit}$ at level $\ell_i$ due to the perfectly hiding property of the commitment scheme).
        \item $i \in A^{(k)}$ since $A(G') = A^{(k)}$.
    \end{itemize}

    By a hybrid argument, there exists some $j \in [k]$ such that $i \notin A^{(j-1)}$ while $i \in A^{(j)}$.
    By the optimality of ADRA and the matroid augmentation property, it must be the case that $(A^{(j-1)} \setminus \{i_j\}) \cup \{i\} = A^{(j)}$. However, that further implies the fabricated bidder $i_j$ has already become $\mathsf{promised}$ before being $\mathsf{aborted}$, due to the optimality of $A^{(j)}$ and the fact that $i$ is already $\mathsf{quit}$. By \Cref{lem:undominated-deviation}, this gives us a contradiction to $G'$ being undominated.
\end{proof}


\begin{lemma}\label{lem:allocation-monotonicity}
    When the auctioneer employs any undominated deviation $G'$, consider two suggested strategies $S_i^\ADRA(b_i), S_i^\ADRA(b_i')$ for a real bidder $i \in [n]$ with $b_i < b_i'$.
    Whenever bidder $i$ is allocated using $S_i^\ADRA(b_i)$, she will also be allocated using $S_i^\ADRA(b_i')$ with an identical payment.
\end{lemma}

\begin{proof}
    By \Cref{lem:clinched-before-quit}, bidder $i$ using $S_i^\ADRA(b_i)$ can be allocated only if she is $\mathsf{promised}$ by the end of level $\ell$ (and eventually allocated) when using $S_i^\ADRA(b_i')$. 
    Denote bidder $i$'s payment when using $S_i^\ADRA(b_i)$, $S_i^\ADRA(b_i')$ by $p_i, p_i'$, correspondingly.
    Note that $p_i \le b_i$ and $p_i' \le b_i'$.
    We want to show $p_i=p_i'$.

    % \Qianfan{The following argument is not very rigorous but should be able to refine.}

    Assume $p_i<p_i'$.
    It must be the case that the auctioneer $\mathsf{abort}$ some fabricated bid $b_j$ such that $b_j = p_i'$ after bidder $i$ $\mathsf{quit}$ at level $\ell$ when using $S_i^\ADRA(b_i)$.
    When $b_j < b_i$, not aborting it will save its collateral $d_\ell$ while increasing the payment from bidder $i$;
    when $b_j \ge b_i$, the collateral $d_\ell$ is saved while losing the payment of from bidder $i$, still resulting a positive increment to the total revenue as $p_i \le b_i < d_\ell$.
    In conclusion, aborting $b_j$ is always dominated by not aborting $b_j$, which contradicts to $G'$ being undominated. 

    Now assume $p_i>p_i'$.
    It must be the case that the auctioneer $\mathsf{abort}$ some fabricated bid $b_j$ such that $b_j = p_i$ at level $\ell$ if bidder $i$ does not $\mathsf{quit}$ using $S_i^\ADRA(b_i')$.
    But that implies $b_j\le b_i <b_i'$, and hence not aborting it will save its collateral $d_\ell$ while increase the payment from bidder $i$.
    Therefore, aborting $b_j$ is always dominated by not aborting $b_j$, which contradicts $G'$ being undominated. 
    % \Qianfan{requires iid distribution}\Anote{Same question as before- would collecting the largest deposit that we are currently collection, but from all bidders be sufficient?} \Qianfan{Yeah that sounds good}
\end{proof}

Now we are ready to prove that truth-telling forms an ex-post Nash no matter which undominated deviation $G'$ the auctioneer employs.

\begin{lemma}\label{lem:ADRA-equilbrium}
    When the auctioneer employs any undominated deviation $G'$, the truthful strategy $\vb{S}^\ADRA(\vb{v})=(S_1^\ADRA(v_1),S_2^\ADRA(v_2),\ldots,S_n^\ADRA(v_n))$ forms an ex-post Nash equilibrium.
\end{lemma}

\begin{proof}
    Consider the best response for a real bidder $i \in [n]$ against auctioneer using $G'$ and other bidders using $\vb{S}_{-i}^\ADRA(\vb{v}_{-i})$.
    By \Cref{lemma:use-suggested-strategy}, it suffices for us to consider $S_i^\ADRA(b_i)$ for $b_i \ne v_i$ and show $S_i^\ADRA(v_i)$ weakly dominates all of them.


    When $b_i<v_i$, we immediately have $S_i^\ADRA(v_i)$ weakly dominates $S_i^\ADRA(b_i)$ by \Cref{lem:allocation-monotonicity}.
    On the other hand, when $b_i>v_i$, if bidder $i$ gets allocated using $S_i^\ADRA(v_i)$, then $S_i^\ADRA(b_i)$ will also end up with a same payment by \Cref{lem:allocation-monotonicity}.
    The only case left to analyze is where bidder $i$ only gets allocated by using $S_i^\ADRA(b_i)$ but not when using $S_i^\ADRA(v_i)$.

    Assume the payment $p$ for $S_i^\ADRA(b_i)$ satisfies $p \le v_i$.
    Let $\ell$ be the level that bidder $i$ $\mathsf{quit}$ when using $S_i^\ADRA(v_i)$, and we know bidder $i$ will never be $\mathsf{promised}$ in that case by \Cref{lem:clinched-implies-allocation}.
    Therefore, the auctioneer have to $\mathsf{abort}$ some fabricated bid $b_j$ such that $b_j > v_i$ after observing that bidder $i$ does not $\mathsf{quit}$ at level $\ell$. However, not aborting $b_j$ can save a collateral of at least $b_j$ while losing a revenue of $p \le v_i < b_j$, which contradicts $G'$ begin undominated. Therefore, the payment $p$ for $S_i^\ADRA(b_i)$ satisfies $p > v_i$, which yields a negative utility for bidder $i$.
\end{proof}

\begin{proof}[Proof of \Cref{thm:ADRA}]
    % When the auctioneer follow the protocol of ADRA for matroids exactly, the truth-telling strategy $\vb{S}^\ADRA(\vb{v})$ forms an ex-post Nash equilibrium by \Cref{lem:ADRA-equilbrium}, thus ADRA for matroids is strategyproof.
