\begin{lemma}\label{lemma:impossible-WELandSPA}
    For $n\geq 2$ buyers and $\epsilon>0$, for any valid distribution-reporting mechanism $M$, the following two statements hold:
    \begin{enumerate}
        \item There is an instance $\bm{F}\in\calA^{R}$ such that $\REV(M;\bm{F})<\epsilon\cdot\Myer(\bm{F})\leq\epsilon\cdot\WEL(\bm{F})$.
        \item There is an instance $\bm{F}\in\calA^{R}$ such that $\REV(M;\bm{F})<(1+\epsilon)\cdot\SPA(\bm{F})$.
    \end{enumerate}
    Specifically, the instance $\bm{F}$ can only consist of degenerate distributions, i.e., deterministic values.
\end{lemma}



