\subsection{Upper bound}
To complement our positive result, we prove a matching upper bound, showing that the either-or approximation result is tight up to constant factors.
\begin{theorem}\label{thm:upperbound}
 Assume $\mathcal{F}_1=\cdots=\mathcal{F}_n=\calA$. For any $n\geq 2$ and $K\geq6$, for any valid distribution-reporting mechanism $M$, 
there exists some instance $\bm{F}=(F_1,\cdots,F_n)\in\bm{\calF}$ such that
    $$\mathrm{REV}(M,F_1,\cdots, F_n)\leq \min\left\{\frac{64}{K+\log_2 n}\cdot\mathrm{WEL}(F_1,\cdots, F_n),2^K\cdot\mathrm{SPA}(F_1,\cdots, F_n)\right\}.$$
\end{theorem}
\begin{proofsketch}
We utilize \Cref{lemma:reduce-to-bid-report} to establish the upper bound on the revenue of any distribution-reporting mechanism $M$.

When $K\geq\log_2 n$, we need to prove that $\mathrm{REV}(M,\bm{F})\leq \min\{O(\frac{1}{K})\cdot\mathrm{WEL}(\bm{F}),2^K\cdot\mathrm{SPA}(\bm{F})\}$ for some instance $\bm{F}$. We utilize a result in \citep{GuruganeshMWW24} showing that for any $T\geq3$, no bid-reporting mechanism can guarantee $\min\{\frac{2.5}{\ln T}\WEL,T\cdot\mathrm{SPA}\}$ revenue in degenerate distribution instances. By \Cref{lemma:reduce-to-bid-report}, any distribution mechanism $M$ behaves essentially the same as some bid-reporting mechanism $M'$ on degenerate distribution instances, so the revenue upper bound is still applicable. 

When $K\leq \log_2 n$, we prove the existence of some instance $\bm{F}$ such that $\mathrm{REV}(M,\bm{F})\leq \min\{O(\frac{1}{\log n})\cdot\mathrm{WEL}(\bm{F}),\Theta(1)\cdot\mathrm{SPA}(\bm{F})\}$. We define a distribution $D_I$ of instance $\bm{F}$, where each $F_i$ is independently drawn from a distribution $D_{F}$ over a family of $L\approx\log_2(\sqrt{n})$ distributions $\{F^{1},\cdots,F^{L}\}$. Each $F^j$ is defined by the quantile function $v^j(q)=\frac{1}{2^j\epsilon}\I[q\leq\epsilon]$, and $D_{F}$ assigns $\delta\cdot 2^j$ probability to each $F^j$, where $\delta=\Theta(\frac{1}{\sqrt{n}})$ is the normalizing factor. 

For the left side, the construction of this distribution family allows us to apply \Cref{lemma:reduce-to-bid-report}, showing that the expected revenue of any distribution-reporting mechanism $M$ when $\bm{F}\sim D_I$ is equal to the expected revenue of some bid-reporting mechanism facing a discrete version of equal revenue distribution, which is upper bounded by $\Theta(\sqrt{n})$.

For the right side, note that $\E_{\bm{F}\sim D_I}[\WEL(\bm{F})]=\Theta(\sqrt{n}\log n)$ and $\E_{\bm{F}\sim D_I}[\SPA(\bm{F})]=\Theta(\sqrt{n})$. Through concentration inequalities, we show that $\Pr_{\bm{F}\sim D_I}[\min\{\Theta(\frac{1}{\log n})\cdot\mathrm{WEL}(\bm{F}),\Theta(1)\cdot\mathrm{SPA}(\bm{F})\}\geq \Theta(\sqrt{n})]=\Omega(1)$, which implies $\E_{\bm{F}\sim D_I}[\min\{\Theta(\frac{1}{\log n})\cdot\mathrm{WEL}(\bm{F}),\Theta(1)\cdot\mathrm{SPA}(\bm{F})\}]\geq\Theta(\sqrt{n})$.

In summary, we obtain $\E_{\bm{F}\sim D_I}[\REV(M,\bm{F})]\leq \E_{\bm{F}\sim D_I}[\min\{\Theta(\frac{1}{\log n})\cdot\mathrm{WEL}(\bm{F}),\Theta(1)\cdot\mathrm{SPA}(\bm{F})\}]$, which implies that there is some instance $\bm{F}$ such that
$\REV(M,\bm{F})\leq  \min\{\Theta(\frac{1}{\log n})\cdot\mathrm{WEL}(\bm{F}),\Theta(1)\cdot\mathrm{SPA}(\bm{F})\}$.
\end{proofsketch}

Additionally, this upper bound can be extended to show that our result remain tight up to constant factors even when all distributions are regular.
\begin{theorem}\label{thm:upperbound-regular}
 Assume $\mathcal{F}_1=\cdots=\mathcal{F}_n=\mathcal{A}^{R}$, i.e. the class of regular distributions. For any $n\geq 2$ and any $K\geq8$, for any valid distribution-reporting mechanism $M$, 
there exists some instance $\bm{F}=(F_1,\cdots,F_n)\in\bm{\calF}$ such that
    $$\REV(M,F_1,\cdots, F_n)\leq \min\left\{\frac{1382.4}{K+\log_2 n}\cdot\mathrm{WEL}(F_1,\cdots, F_n),2^K\cdot\mathrm{SPA}(F_1,\cdots, F_n)\right\}.$$
\end{theorem}

\section{Generalization: Multi-Unit Multi-Demand Setting}\label{sec:generalization}
In this section, we extend our main positive result (\Cref{theorem:lowerbound}) from the single-item setting to a more general multi-unit multi-demand setting, achieving an either-or approximation with respect to optimal welfare $\WEL$ and VCG revenue $\VCG$. %To achieve this, we replace SPA by VCG as the bid-reporting mechanism in the construction of Peer-Max mechanism. 

\begin{definition}
    In a multi-unit multi-demand setting, $m$ units of identical items are sold to $n$ buyers, and each buyer $i\in[n]$ has a demand capacity $d_i$ known publicly. For a distribution-reporting mechanism $M=(x,p)$, the allocation rule $x_i(\bm{b};\bm{B})$ now represents the quantity of items allocated to buyer $i$, and the feasibility requires that
\begin{align*}
    \sum_{i\in[n]}x_i(\bm{b};\bm{B})\leq m, \text{\quad and\quad}
    x_i(\bm{b};\bm{B})\in[0,d_i],~\forall i\in[n].
\end{align*}
We denote the space of feasible allocation by $X_{m,\bm{d}}=\{\bm{z}=(z_1,\cdots,z_n):\sum_{i\in[n]}z_i\leq m\land \forall i\in[n],z_i\in[0,d_i]\}$.
\end{definition}

In the multi-unit multi-demand setting, the utility of each buyer remains as given by \Cref{def:ex-ante utility}, i.e.,
\begin{align*}
   U^M_i(\bm{B};F_i)=\E_{\bm{b}_{-i}\sim \bm{B}_{-i},q_i\sim U[0,1]}[x_i(b_i(q_i),\bm{b}_{-i};\bm B)\cdot v_i(q_i)]-\E_{\bm{b}\sim \bm{B}}[p_i(\bm B)],
\end{align*}
where $v_i(\cdot)$ and $b_i(\cdot)$ denote the quantile function of $F_i$ and $B_i$, respectively.

Denote the allocation and payment rules of VCG by $x_i^{\VCG}(\bm{v})=\arg\max_{\bm{z}\in X_{m,\bm{d}}}\sum_{i\in[n]}z_iv_i$ and $p_i^{\VCG}(\bm{v})=\max_{\bm{z}\in X_{m,\bm{d}}}\sum_{i'\in[n]\setminus\{i\}}z_{i'}v_{i'}-\sum_{i'\in[n]\setminus\{i\}}x_{i'}^{\VCG}(\bm{v})v_{i'}$.\footnote{We assume an arbitrary but fixed tie-breaking rule for the allocation rule of VCG.} Given any instance $\bm{F}$, we define the optimal welfare as $\mathrm{WEL}(\bm{F})=\E_{\bm{v}\sim\bm{F}}[\max_{\bm{z}\in X_{m,\bm{d}}}\sum_{i\in[n]}z_iv_i]$ with a slight abuse of notation, and define the VCG revenue as $\mathrm{VCG}(\bm{F})=\E_{\bm{v}\sim\bm{F}}[p_i^{\VCG}(\bm{v})]$.

To extend our main positive result to the multi-unit multi-demand setting, we introduce the Peer-Welfare Mechanism, which generalizes the Peer-Max Mechanism by replacing SPA with VCG as the underlying mechanism. The threshold function for each buyer $i$ is based on the optimal expected welfare of other buyers ignoring the existence of buyer $i$, which is a generalization of the expected maximum value of other buyers adopted in the Peer-Max Mechanism.
% This is motivated by the VCG payment rule, which charges each buyer the welfare loss her participation inflicts upon the remaining buyers.

\begin{definition}\label{def:peer-max-vcg}
A Peer-Welfare mechanism $PW_{D_\alpha}$ specified by a distribution $D_{\alpha}$ for parameter $\alpha\in[0,+\infty)$ is defined as the mechanism that draws $\alpha\sim D_\alpha$, and executes the threshold-augmented mechanism $TAM_{\VCG,\bm{\tau}^{\alpha}}$ with threshold function $\tau_i^{\alpha}(\bm{B}_{-i}):=\alpha\cdot \E_{\bm{v}_{-i}\sim\bm{B}_{-i}}[\max_{(z_1,\cdots,z_n)\in X_{m,\bm{d}}}\sum_{i'\in[n]\setminus\{i\}}z_{i'}v_{i'}]$.

We use $PW_{D_\alpha}(F_1,\cdots,F_n)$ to denote the expected revenue of $PW_{D_\alpha}$ under an instance $(F_1,\cdots,F_n)$.
% Here $X=\{(z_1,\cdots,z_n):\sum_{i\in[n]}z_i\leq m\land \forall i\in[n],~z_i\in[0,d_i]\}$ denotes the set of feasible allocations.
\end{definition}


% We have a weaker result for $n>2$:
\begin{theorem}{\label{theorem:lowerbound-vcg}}
Consider $n\geq 2$ buyers, with distribution classes $\mathcal{F}_1=\cdots=\mathcal{F}_n=\calA$ consisting of all distributions.
Given any integer $K\geq 1$, there exists a distribution $D_{\alpha}$ of parameter $\alpha$, such that for all instances $\bm{F}=(F_1,\cdots,F_n)\in\calA^n$,
    $$PW_{D_\alpha}(F_1,\cdots,F_n)\geq \min\{\frac{1}{24(K+\log_2 n)}\cdot\mathrm{WEL}(F_1,\cdots,F_n),2^K\cdot \mathrm{VCG}(F_1,\cdots,F_n)\}.$$
    % \lny{$PW_{D_\alpha}(F_1,\cdots,F_n)$ denotes revenue with a slight abuse of notation...}
\end{theorem}
\begin{proofsketch}
To generalize \Cref{theorem:lowerbound} to the multi-unit multi-demand setting, we redefine the important quantities $w_i$, $s_i$, and $r_i$ in the proof of \Cref{theorem:lowerbound} as follows:
$$
w_i=\E_{\bm{v}\sim \bm F}[v_i\cdot x_i^{\VCG}(\bm{v})],\ 
s_i=\E_{\bm{v}\sim \bm F}[p_i^{\VCG}(\bm{v})],\ 
r_i=\E_{\bm{v}_{-i}\sim\bm{F}_{-i}}[\max_{\bm{z}\in X_{m,\bm{d}}}\sum_{i'\in[n]\setminus\{i\}}z_{i'}v_{i'}].$$
One can see that the relationship between these quantities and the benchmarks are retained. Specifically,  by the payment rule of VCG, we have $r_i=s_i+\sum_{j\neq i}w_i$. Also, we have $\WEL=\sum_{i\in[n]} w_i$ and $\VCG=\sum_{i\in[n]}s_i$ by definition. This allows us to generalize the analysis in the \Cref{theorem:lowerbound} to this setting.
% The remaining analysis is analogous to \Cref{theorem:lowerbound}.
\end{proofsketch}

We remark that this extension actually holds for any single-parameter environment, as our analysis relies solely on the properties of the VCG mechanism, and does not depend on specific feasibility constraints.

