We conclude this section by presenting a corollary of Theorem \ref{thm:link-complexity-network} which provides simple bounds on $\varphi_{\mathcal{G}}$ not depending on partitions induced by nodal dynamics. 
%This fact is also supported by the following corollary of Theorem \ref{thm:link-complexity-network}.



\begin{corollary}\label{cor:simpleboundsonphiG}{\em (Simple bounds on $\varphi_{\mathcal{G}}$)}
Consider the network system \eqref{eq:sys}. Then, %$\quad\quad \nu(\G)\le \varphi_{\G} \le n- |S(\G)|,$\\
%\vspace{-0.29cm}
%\vspace{-0.5cm}
\begin{align*}
     \quad\quad \nu(\G)\le \varphi_{\G} \le n- |S(\G)|,
\end{align*}
where $\nu(\G)$ and $S(\G)$ denote the matching number and the set of sink nodes of $\mathcal{G}$, respectively.
Moreover, the first inequality is attained when all $\{\gamma_i\}_{i=1}^n$ are identical, while the second inequality when all $\{\gamma_i\}_{i=1}^n$ are distinct.
\end{corollary}
\begin{proof}
Let $C_i$, $i=1,\dots,k$, be defined as in \eqref{eq:Ci} and let $A_j$, $j=1,\dots,n$, be $n\times n$ zero matrices except for their $i$-th column which equals the $i$-th column of $A$. It holds
%\vspace{-0.05cm}
$$
\rank(A) \le \sum\nolimits_{i=1}^k\rank(C_i)\le \sum\nolimits_{j=1}^n\rank(A_j),
$$
since no column of $A$ appears in more than one $C_i$. Note that when all $\{\gamma_i\}_{i=1}^n$ are identical $k=1$ and $C_1=A$ and when all $\{\gamma_i\}_{i=1}^n$ are distinct $k=n$ and $C_i=A_i$, $i=1,\dots,n$.
When $A$ is interpreted as a structured matrix the rank in the previous inequalities can be replaced by the structural rank, and the result follows by noting that $\srank(A)=\nu(\G)$ and $\sum_{j=1}^n\srank(A_j)= n- |S(\G)|$, where the latter identity holds because $A_j=0_{n\times n}$~if~and~only~if~$j\in S(\G)$.~
\end{proof}



\begin{remark}\emph{(Relation with structural controllability)}
	Consider a network system \eqref{eq:sys} with identical nodal dynamics, i.e.,~$\gamma_i = \gamma_j$ for all $i,j$. In this case, the minimum number of inputs $N_{\text{min}}$ needed to guarantee structural controllability~is~given~by \cite{liu2016control}
	\begin{align*}%\label{eq:Nmin}
		N_{\text{min}} = \max\{1, n - \nu(\mathcal{G})\}.
	\end{align*}
	This reveals a complementary relation between $\varphi_{\mathcal{G}}$ and $N_{\text{min}}$: richer internal dynamics facilitate signal propagation, reducing the need for inputs. 
    %The same holds for structural observability. 
\end{remark}



