\begin{document}

\maketitle

\begin{abstract}
	We prove the local classification of K\"ahler metrics with constant holomorphic sectional curvature by exploiting the geometry of the bundle of \(1\)-jets of holomorphic functions.
\end{abstract}

\section{Introduction}

Let \(\varphi\) be a smooth real function on the unit ball \(B \subset \C^n\) such that \(\omega = i \ddb \varphi\) is a K\"ahler metric. Let \(J^1(\mO)\) be the bundle of \(1\)-jets of holomorphic functions on \(B\).
In this paper, we introduce two Hermitian forms \(H\) and \(K\) on \(J^1(\mO)\) naturally associated with \(\varphi\).
The Hermitian form \(H\) is positive definite, while \(K\) has signature \((1,n)\). We show that \(H\) (respectively \(K\)) is flat if and only if \(\omega\) has constant holomorphic sectional curvature \(\kappa = 2\) (respectively \(-2\)).
As an application, we prove the classical local classification of K\"ahler metrics with constant holomorphic sectional curvature (chsc).

\begin{theorem}\label{thm}
	\textup{(i)}
	If \(\omega\) has chsc \(\kappa=2\) then we can find holomorphic coordinates \(z = (z^1, \ldots, z^n)\) such that \(\omega = i \ddb \log (1+|z|^2)\).
	\textup{(ii)} If \(\omega\) has chsc \(\kappa=-2\) then we can find holomorphic coordinates such that \(\omega = -i \ddb \log (1-|z|^2)\).
\end{theorem}

This theorem was first proved by Bochner \cite{bochner} under the assumption that the K\"ahler potential \(\varphi\) is real analytic. For smooth metrics, the result follows from the Cartan-Ambrose-Hicks Theorem \cite{kn, binxu}. 

