\section{Hermitian forms on \(1\)-jets}
We now turn to the construction of Hermitian forms on the bundle of \(1\)-jets.
The construction is somewhat standard and it resembles the Sasaki metric on the tangent bundle of a Riemannian manifold.

\subsection{Setting}
Let \(L \to M\) be a holomorphic line bundle equipped with an Hermitian metric \(h\). Assume that the associated curvature form \(\omega = i \op \p \log h\) is positive, i.e., assume that \(g(u, v) = \omega(u, Iv)\) is a K\"ahler metric on \(M\).

\subsection{Jet bundle}
Let \(E = J^1(L)\) be the bundle of \(1\)-jets of \(L\). The fibre of \(E\) at \(p \in M\) consists of equivalence classes of germs of holomorphic sections of \(L\) around \(p\), where \(s \sim s'\) if \(s(p) = s'(p)\) and \(ds(p) = ds'(p)\). 
Write \(j(s)\) for the equivalence class of the germ \(s\).
The vector bundle \(E\) has rank \(n+1\) and we have an exact sequence:
\begin{equation}\label{eq:jetseq}
	0 \to T^*M \otimes L \to E \xrightarrow{\pi} L \to 0 \,,
\end{equation}
where \(\pi(j(s)) = s\).

\subsection{Hermitian metric \(H\)}
The connection \(\nabla = d + \p \log h\) gives a smooth splitting \(E \cong L \oplus \big(T^*M \otimes L \big)\) of \eqref{eq:jetseq}. Together with the Hermitian metrics \(h\) and \(g \otimes h\) on the summands (where \(g\) is the induced metric on \(T^*M\)) we obtain an Hermitian metric on \(E\).

\begin{definition}\label{def:H}
	Let \(H\) be the Hermitian metric on \(E\) given by
	\begin{equation}\label{eq:metricJ1}
	| j(s) |_H^2 = |s|_h^2 \,+\, |\nabla s|_{g\otimes h}^2 \,\,.
	\end{equation}
	We refer to \(H\) as the Hermitian metric on \(E\) induced by \(h\). 
\end{definition}

%We shall also write \(|\cdot| = |\cdot|_H\) when it is clear from the context.  

\begin{example}
	Let \(M = \CP^1\) and let \(L = \mO(1)\) equipped with its standard Hermitian metric \(h\). Let \(x_1\), \(x_2\) be orthonormal linear coordinates on \(\C^2\), then \(j(x_1)\) and \(j(x_2)\) are pointwise linearly independent sections of \(J^1(\mO(1)) \cong \underline{\C}^2\). We claim that
	\[
	\begin{pmatrix}
	|j(x_1)|_H^2 & H \big(j(x_1), j(x_2)\big) \\
	H \big(j(x_2), j(x_1)\big) & |j(x_2)|_H^2 
	\end{pmatrix}
	\, = \,
	\begin{pmatrix}
	1 & 0 \\
	0 & 1
	\end{pmatrix} \,.
	\]

	To check, let \(U = \{[x_1, x_2] \in \CP^1 \,|\, x_1 \neq 0\}\) and take the local coordinate \(z \mapsto [1,z]\). Trivialize \(\mO(1)\) over \(U\) by the section \(s = x_1\) so \(h = (1+|z|^2)^{-1}\).
	Then \(\omega = h^2 i dz \wedge d\bar{z}\) from which we get \(|dz|^2_{g\otimes h} = h^{-1}\). Using that \(\nabla 1 = \p \log h = -\bz h dz\), we obtain
	\[
	|j(1)|_H^2 = |1|^2_h \,+\, |\nabla 1|^2_{g\otimes h} = h + |z|^2 h = 1 \,.
	\]
	Similarly, \(|j(z)|_H^2 = 1\) and \(H \big(j(x_1), j(x_2)\big)= 0\).
\end{example}

\begin{remark}
	A closely related construction, in the context of K\"ahler-Einstein metrics with positive Ricci curvature is presented in \cite{tian, chili}.
\end{remark}

\subsection{Hermitian form \(K\) of signature \((1,n)\)}
The Hermitian metric \(h\) on \(L\) induces a Hermitian metric \(h^{-1}\) on the dual line bundle \(L^*\). The connection \(\nabla^{\vee} = d + \log h^{-1}\) gives a smooth splitting of the sequence
\begin{equation}\label{eq:jetseq2}
	0 \to T^*M \otimes L^* \to J^1(L^*) \to L^* \to 0 \,.
\end{equation}
Using the Hermitian metrics on the summands, we introduce the following.

\begin{definition}\label{def:K}
	The Hermitian form \(K\) on \(J^1(L^*)\) is given by
	\begin{equation}
		|j(t)|^2_K = |t|^2_{h^{-1}} \,-\, |\nabla^*t|_{g \otimes h^{-1}}^2 \,\,\,.
	\end{equation}
	We write \(E_{1,n} = J^1(L^*)\) and refer to \(K\) as the Hermitian form of signature \((1,n)\) induced by \(h\).
\end{definition}


\begin{example}
	Let \(B\) be the unit disc \(\{[1,z] \in \CP^1 \,|\, |z| < 1\}\) and let \(L = \mO(-1)|_B\) equipped with the Hermitian metric \(h = 1 - |z|^2\) induced from the constant Hermitian form \(|dx_1|^2 - |dx_2|^2\) on \(\C^2\).
	Then \(\omega = -i \ddb \log h\) is the hyperbolic metric of curvature \(-2\). An easy calculation shows that
	\[
	\begin{pmatrix}
	|j(x_1)|_{K}^2 & K \big(j(x_1), j(x_2)\big) \\
	K \big(j(x_2), j(x_1)\big) & |j(x_2)|_{K}^2 
	\end{pmatrix}
	\, = \,
	\begin{pmatrix}
	1 & 0 \\
	0 & -1
	\end{pmatrix} \,.
	\]
\end{example}

\begin{remark}
	A closely related construction, in the context of K\"ahler-Einstein metrics with negative Ricci curvature is presented in \cite{hitchin, simpson}.
\end{remark}

\subsection{Quotient isometry property}
Let \(V\) and \(W\) be finite dimensional complex vector spaces equipped with non-degenerate Hermitian forms \(H\) and \(K\). Let \(f: V \to W\) be a surjective \(\C\)-linear map. We say that \(f\) is a \emph{quotient isometry} if \(V = \ker f \oplus (\ker f)^{\perp}\) and
\[
\forall x, y \in (\ker f)^{\perp}: \,\, K \big(f(x), f(y)\big) = H (x, y) \,\,.
\]
\begin{lemma}\label{lem:quotientisometry}
	Let \(f: V \to W\) be a quotient isometry. Then \(f^*: W^* \to V^*\) is an injective isometry with respect to the induced metrics \(K^{\vee}\) and \(H^{\vee}\).
\end{lemma}

\begin{proof}
	Let \(\varphi\) be the restriction of \(f\) to \((\ker f)^{\perp}\), so \(\varphi: (\ker f)^{\perp} \to W\) is a bijective isometry. Using the Hermitian forms \(H\) and \(K\) to identify \(V^*\) with \(V\) and \(W^*\) with \(W\), we have that \(f^* = (0, \varphi^{-1})\). Since the inverse of an isometry is also an isometry, the lemma follows. 
\end{proof}

\subsection{The line subbundles}
Taking duals in \eqref{eq:jetseq} we obtain an exact sequence
\begin{equation*}
0 \to L^* \xrightarrow{\pi^*} E^* \to TM \otimes L^* \to 0 \,.
\end{equation*}
For simplicity of notation, we omit \(\pi^*\) and think of \(L^*\) as a line subbundle of \(E^*\).
Similarly, taking duals in \eqref{eq:jetseq2} we obtain
\begin{equation*}
0 \to L \to (E_{1,n})^* \to TM \otimes L \to 0 
\end{equation*}
giving us the line subbundle \(L \subset (E_{1,n})^*\).

\begin{corollary}\label{cor:restriction}
	\textup{(i)} The restriction of \(H^{\vee}\) to the line subbundle \(L^* \subset E^*\) is \(h^{-1}\). \textup{(ii)} The restriction of \(K^{\vee}\) to the line subbundle \(L \subset (E_{1,n})^*\) is \(h\) .
\end{corollary}

\begin{proof}
	By definition of the Hermitian forms \(H\) and \(K\), the vector bundle maps \(E \to L\) and \(E_{1,n} \to L^*\) are fibrewise quotient isometries. The corollary then follows from Lemma \ref{lem:quotientisometry}\,.
\end{proof}

\subsection{The sections \(\sigma\) and \(\tau\)}
The line subbundle \(L^* \subset E^*\) defines a holomorphic section
\begin{equation}
	\sigma: M \to \P(E^*) \,.
\end{equation}
Similarly, the line subbundle \(L \subset (E_{1,n})^*\) defines a holomorphic section
\begin{equation}
	\tau: M \to U_{+} \,,
\end{equation}
where \(U_{+}\) is the subset of \(\P\big((E_{1,n})^*\big)\) consisting of lines on which \(K^{\vee} > 0\). The fact that \(K^{\vee}\) restricted to \(L\) is \(>0\) follows from Corollary \ref{cor:restriction}(ii).

\begin{proposition}\label{prop:pullback}
	\textup{(i)} \(\sigma^* \eta_{FS} = \omega\) and \textup{(ii)} \(\tau^* \eta_{CH} = \omega\) \,.
\end{proposition}

\begin{proof}
	(i) By Corollary \ref{cor:restriction}(i) the restriction of \(H^{\vee}\) to \(L^*\) is \(h^{-1}\). By Lemma \ref{lem:pbfs}, \(\sigma^* \eta_{FS} = -\omega_{h^{-1}} = \omega\). (ii) By Corollary \ref{cor:restriction}(ii) the restriction of \(K^{\vee}\) to \(L\) is \(h\). By Lemma \ref{lem:pbch}, \(\tau^* \eta_{CH} = \omega_{h} = \omega\). 
\end{proof}


\section{Curvature} 

With the Hermitian structures on \(1\)-jets in place, we proceed to compute their curvature and relate flatness to constant holomorphic sectional curvature.


\subsection{Background: Chern connection}
Let \(E\) be a holomorphic vector bundle equipped with a non-degenerate Hermitian form \(H\). The Chern connection of \(H\) is the unique connection on \(E\) such that \(\nabla H = 0\) and \(\nabla^{0,1} = \op_E\). 

Let \(s^1, \ldots, s^r\) be a local holomorphic frame of \(E\) and let \(H^{i \bj} = H(s^i, s^j)\). Then we can write \(\nabla s^i = \theta^i_k s^k\) where \(\theta^i_k\) are \((1,0)\)-forms. The equation \(\p H^{i\bj} = \theta^i_k H^{k\bj}\) implies
\[
\theta = (\p H) \cdot H^{-1}
\]
where \(\theta\) is the matrix of \(1\)-forms whose \((i,j)\)-th entry is \(\theta^i_j\) and \(H = (H^{i\bj})\). The curvature of \(\nabla\) is the \((1,1)\)-form with values in \(\End E\) given by \(F = d^{\nabla} \circ \nabla\). In a local holomorphic frame as above, we have \(F s^i = \Omega^i_j s_j \) where \(\Omega^i_j = \op \theta^i_j\). In matrix notation,
\[
\Omega = \op \theta \,.
\]
The Hermitian form \(H\) is said to be flat if \(F \equiv 0\).

\subsection{Main result}
Let \(H\) and \(K\) be as in Definitions \ref{def:H} and \ref{def:K}. 

\begin{proposition}\label{prop:curv}
	\textup{(i)} The Hermitian metric \(H\) is flat if and only if \(g\) has chsc \(\kappa = 2\). \textup{(ii)} The Hermitian form \(K\) is flat if and only if \(g\) has chsc \(\kappa = -2\).
\end{proposition}

The remainder of this section is devoted to the proof of the above proposition, which proceeds by direct calculation. Since the arguments for items (i) and (ii) are essentially identical, we provide full details for item (i) and leave the verification of item (ii) to the reader.


\subsection{Calculation in a local frame}
Let \(\tn\) be the Chern connection of \(H\) on \(E = J^1(L)\). \footnote{We use the tilde to distinguish \(\tn\) from the connection \(\nabla = d + \p \log h\) on \(L\).}   We want to calculate the curvature of \(\tn\) at an arbitrary fixed point \(p \in M\). 

To simplify the calculation, we begin by choosing a suitable holomorphic frame of \(E\) near \(p\).
Let \((z^1, \ldots, z^n)\) be normal coordinates for the K\"ahler metric \(g\) centred at \(p\). With this choice, the metric coefficients of \(g\) satisfy
\begin{equation}
	g_{i\bj} (0) = \delta_{ij} \,\, \text{ and } \,\, \p_k g_{i\bj} (0) = \p_{\bk} g_{i\bj} (0) = 0 \,.
\end{equation}

%We trivialize \(L\) near \(p\) by choosing a holomorphic section \(s\) such that \(h = |s|_h^2\) is as in the following lemma.

\begin{lemma}\label{lem:section}
	There is a holomorphic section \(s\) of \(L\) such that \(|s|_h^2\) satisfies
	\begin{equation}\label{eq:h}
		h(0) = 1 \,,\, dh(0) = 0 \,, \textup{ and } \,\, \p_i \p_j h (0) = \p_{\bi} \p_{\bj} h (0) = 0 \,.
	\end{equation}
\end{lemma}

\begin{proof}
	It is standard and easy to show that we can take \(\ts\) with \(\widetilde{h}(0) =1\) and \(d \widetilde{h}(0) = 0\). 
	Let \(s = f \cdot \ts\), with \(f = 1 + (1/2)c_{ij}z^iz^j\) and \(c_{ij} = - \p_i \p_j \widetilde{h} (0)\). 
\end{proof}

Trivialize \(L \cong \mO\) so that the section \(s\) of Lemma \ref{lem:section} corresponds to the constant function \(1\).  

\begin{definition}\label{def:frame}
	Let \(s^0, \ldots, s^n\) be the holomorphic frame of \(E\) given by
	\begin{equation}
	s^0 = j(1)\,,\, s^1 = j(z^1) \,,\, \ldots \,,\, s^n = j(z^n) \,.
	\end{equation}
\end{definition}




\begin{lemma}\label{lem:metcoeff}
	The entries of the \((n+1) \times (n+1)\) matrix of metric coefficients \(H = (H^{i\bj})\) are given as follows.
	\begin{enumerate}[label=\textup{(\roman*)}]
		\item The coefficient \(H^{0\bar{0}} = H(s^0, s^0)\) is 
		\begin{equation}\label{eq:H00}
		H^{0\bar{0}} = h \,+\, h^{-1} g^{p\bq} (\p_p h) (\p_{\bq} h) \,.
		\end{equation}
		\item For \(1 \leq i  \leq n\), the coefficient \(H^{i\bar{0}} = H(s^i, s^0)\) is 
		\begin{equation}\label{eq:Hi0}
		H^{i\bar{0}} = z^i H^{0\bar{0}} \,+\,  g^{i\bq} (\p_{\bq} h) \,.
		\end{equation}
		\item For \(1 \leq i, j \leq n\),	the coefficient \(H^{i{\bj}} = H(s^i, s^j)\) is 
		\begin{equation}\label{eq:Hij}
		H^{i\bj} = hg^{i\bj} \,+\,  
		h z^i \bz^j  \,+\,
		z^i g^{p\bj} (\p_p h) \,+\,
		\bz^j g^{i\bq} (\p_{\bq}h) \,+\,
		O(|z|^4) \,\,.
		\end{equation}
	\end{enumerate}
\end{lemma}

\begin{proof}
	In our trivialization of \(L\), the Hermitian metric \eqref{eq:metricJ1}
	is given by
	\[
	H(j(u), j(v)) = h \cdot (u \bar{v}) \,+\, h \cdot \langle \nabla u , \nabla v \rangle_{g}
	\]
	where \(u\) and \(v\) are holomorphic functions and \(\nabla u\) is the \(1\)-form 
	\[
	\nabla u = du + u \cdot \p \log h
	\] 
	and similarly for \(v\). On the other hand, the Hermitian product \(\langle \alpha, \beta \rangle_g\) of \(1\)-forms \(\alpha = \alpha_p dz^p\) and \(\beta = \beta_q dz^q\) is given by
	\[
	\langle \alpha, \beta \rangle_g = g^{p\bq} \alpha_p \overline{\beta_q}
	\]
	Applying this to the constant and coordinate functions, we obtain the following.

	\noindent(i) Taking \(u=v=1\), we obtain \(\nabla 1 = h^{-1} \p h\) and
	 \[
	 H^{0\bar{0}} = h \,+\, h^{-1} \cdot |\p h|^2_{g} \,\,.
	 \]
	Since the function \(h\) is real, we have \(\overline{\p_q h} = \p_{\bq} h\) and thus 
	\[
	|\p h|^2_{g} = g^{p\bq} (\p_p h) (\p_{\bq} h)
	\]
	giving us Equation \eqref{eq:H00}. \newpar

	\noindent(ii) Taking \(u=z^i\) and \(v=1\), we obtain \(\nabla z^i = dz^i + z^i \p \log h\) and
	\[
	\begin{aligned}
	H^{i\bar{0}} &= h \cdot z^i \,+\, h \cdot \langle dz^i + z^i \p \log h, \p \log h  \rangle_g \\
	&= z^i H^{0\bar{0}} \,+\, \langle dz^i, \p h \rangle_g
	\end{aligned}
	\]
	giving us Equation \eqref{eq:Hi0}. \newpar

	\noindent(iii) Taking \(u=z^i\) and \(v=z^j\), we obtain
	\[
	H^{i\bj} = h \cdot z^i \bz^j \,+\, h \cdot \langle \nabla z^i, \nabla z^j \rangle_{g} \,\,.
	\]
	Replacing \(\nabla z^i = dz^i + z^i \p \log h\) and similarly for \(\nabla z^j\), we have
	\[
	\begin{aligned}
	h\langle \nabla z^i, \nabla z^j \rangle_{g} &= h \langle dz^i, dz^j \rangle_{g} \,+\,
	\bz^j \langle dz^i, \p h \rangle_{g} \,+\,
	z^i	\langle \p h, d z^j \rangle_{g} \,+\,
	z^i \bz^j h^{-1}|\p h|^2_{g} \\
	&=	 hg^{i\bj} \,+\, \bz^j g^{i\bq} (\p_{\bq} h) \,+\, z^i g^{p\bj} (\p_p h)  \,+\, z^i \bz^j h^{-1}g^{p\bq} (\p_p h) (\p_{\bq} h)
	\end{aligned}
	\]
	and Equation \eqref{eq:Hij} follows from this with \(O(|z|^4) = z^i \bz^j h^{-1}g^{p\bq} (\p_p h) (\p_{\bq} h)\).
\end{proof}

\begin{remark}
	In the above lemma we use the notation \(O(|z|^N)\) to indicate a function \(f\) such that \(|f(z)| \leq C |z|^N\) for all \(|z| \leq 1\) for some constant \(C>0\). The function \(f = z^i \bz^j h^{-1}g^{p\bq} (\p_p h) (\p_{\bq} h)\) is in \(O(|z|^4)\) because \(dh(0) = 0\). 
\end{remark}

\begin{corollary}
	The matrix \(H = (H^{i\bj})\) is equal to the identity at the origin.
\end{corollary}

\begin{proof}
	Since \(h(0)=1\) and \(dh(0) = 0\), Equation \eqref{eq:H00} implies \(H^{0\bar{0}}(0) = 1\). Similarly, Equation \eqref{eq:Hi0} implies \(H^{i\bar{0}}(0) = 0\) for \(i \geq 1\). On the other hand, since \((z^1, \ldots, z^n)\) are normal coordinates, we have \(g^{i\bj}(0) = \delta^{ij}\) and Equation \eqref{eq:Hij} implies \(H^{i\bj} (0) = \delta^{ij}\) for \(i, j \geq 1\).
\end{proof}

\subsection{Derivatives of metric coefficients}
To calculate \(dH\) and \(\ddb H\) at \(0\) we begin with preliminary lemmas on the derivatives of \(g^{i\bj}\) and \(h\).

\begin{lemma}\label{lem:ginvder}
	The following holds:
	\begin{equation}\label{eq:ginv}
		g^{i \bj} (0) = \delta^{ij} \,,\, (\p_k g^{i\bj}) (0) = 0 \,,\, (\p_{\bl} g^{i\bj}) (0) = 0 \,.
	\end{equation}
\end{lemma}

\begin{proof}
	Follows from the fact that \((z^1, \ldots, z^n)\) are normal coordinates.
\end{proof}

\begin{lemma}\label{lem:hder}
	The identity \(\omega = -i \ddb h\) holds at the origin, i.e.,
	\begin{equation}\label{eq:secondorderh}
	(\p_k \p_{\bl} h) (0) = -\delta_{kl} \,.
	\end{equation}
	Moreover, the following third order derivatives of \(h\) vanish
	\begin{equation}\label{eq:thirdorderh}
		(\p_k \p_{\bl} \p_p h) (0) = (\p_k \p_{\bl} \p_{\bq} h) (0) = 0 \,.
	\end{equation}
\end{lemma}

\begin{proof}
	By assumption, \(\omega = - i \ddb \log h\) which implies
	\[
	\begin{aligned}
	g_{k\bl} &= -\p_k \p_{\bl} \log h = -\p_k \big(h^{-1} \p_{\bl} h \big) \\
	&= h^{-2} (\p_k h) (\p_{\bl}h) - \p_k \p_{\bl}  h \,.
	\end{aligned}
	\]
	Evaluating this at \(0\) gives \eqref{eq:secondorderh} and taking exterior derivative gives \eqref{eq:thirdorderh}.
\end{proof}

\begin{lemma}
	The derivative of the matrix \(H = (H^{i\bj})\) vanishes at the origin.
\end{lemma}

\begin{proof}
	This follows from the expression for the metric coefficients given in Lemma \ref{lem:metcoeff} by taking derivatives and using Lemmas \ref{lem:ginvder} and \ref{lem:hder} to evaluate at \(0\). For example, for \(H^{i\bar{0}} = z^i H^{0\bar{0}} \,+\,  g^{i\bq} (\p_{\bq} h) \) we have
	\[
	\begin{aligned}
	\p_k (H^{i\bar{0}}) &= (\p_k z^i) H^{0\bar{0}} \,+\, g^{i\bq} (\p_k\p_{\bq} h) \\
	&= \delta^i_k \,-\, \delta^{iq} \delta_{kq} = 0 \,\, \text{ at } \,\, 0 \,,
	\end{aligned}
	\]
	and \(\p_{\bl} (H^{i\bar{0}}) (0) =  (\p_{\bl}\p_{\bi} h)(0)\) which vanishes by Equation \eqref{eq:h}. The proofs that \(dH^{0\bar{0}}(0) = 0\) and \(dH^{i\bj}(0) = 0\) for \(i, j \geq 1\) are similar and left to the reader.
\end{proof}

\begin{lemma}\label{lem:zero}
	\textup{(i)}
	\((\ddb H^{0\bar{0}})(0) = 0\) and \textup{(ii)} \((\ddb H^{i\bar{0}})(0) = 0\) for \(1 \leq i \leq n\).
\end{lemma}

\begin{proof}
	(i) Taking the derivative \(\p_k \p_{\bl}\) of \(H^{0\bar{0}} = h \,+\, h^{-1} g^{p\bq} (\p_p h) (\p_{\bq} h)\) and evaluating at the origin, we obtain
	\[
	\begin{aligned}
	\p_k \p_{\bl} H^{0\bar{0}} &= \p_k \p_{\bl}h \,+\, g^{p \bq}  (\p_p \p_{\bl} h) (\p_k \p_{\bq} h) \\
	&= -\delta_{k\ell} \,+\, \delta^{pq} (-\delta_{p\ell}) (-\delta_{kq}) \\
	&= -\delta_{k\ell} + \delta_{k\ell} = 0 \,.
	\end{aligned}
	\]
	\noindent (ii) Taking the derivative \(\p_k \p_{\bl}\) of 
	 \(H^{i\bar{0}} = z^i H^{0\bar{0}} \,+\,  g^{i\bq} (\p_{\bq} h)\) and evaluating at the origin, we obtain
	 \[
	 \p_k \p_{\bl} H^{i\bar{0}} = g^{i\bq} (\p_k \p_{\bl} \p_{\bq} h) = \p_k \p_{\bl} \p_{\bi} h
	 \]
	and \((\p_k \p_{\bl} \p_{\bi} h)(0) = 0\) by Equation \eqref{eq:thirdorderh}.
\end{proof}

\begin{lemma}
	We have
	\begin{equation}\label{eq:Hijkl}
	(\p_k \p_{\bl}H^{i\bj}) (0) = (\p_k \p_{\bl}g^{i\bj})(0) - \left(\delta^{ij} \delta_{k\ell} + \delta^i_{k} \delta^j_{\ell} \right) \,.
	\end{equation}
\end{lemma}

\begin{proof}
	Taking the derivative \(\p_k \p_{\bl}\) in Equation \eqref{eq:Hij} and evaluating at \(0\), we have
	\[
	(\p_k \p_{\bl}H^{i\bj}) (0)  = A + B + C
	\]
	with \(A, B, C\) given as follows:
	\begin{itemize}
		\item \(A = \p_k \p_{\bl} (hg^{i\bj})\) which evaluates to
		\[
		\begin{aligned}
		A &= (\p_k \p_{\bl} h) \cdot g^{i\bj} \,+\, h \cdot (\p_k \p_{\bl}g^{i\bj}) \\
		&=\p_k \p_{\bl}g^{i\bj}  - \delta^{ij} \delta_{k\ell} \,;
		\end{aligned}
		\]
		\item \(B = \p_k \p_{\bl} (z^i \bz^j h) = \delta^i_{k} \delta^j_{\ell} \) ;
		\item \(C = \p_k \p_{\bl} \left(\bz^j g^{i\bp} (\p_{\bp}h) \,+\, z^i g^{p\bj} h_{,p} \right)\) which evaluates to
		\[
		\begin{aligned}
		C &= \delta^j_{\ell} g^{i\bp} (\p_k \p_{\bp} h)  \,+\, \delta^i_{k} g^{p\bj} (\p_p \p_{\bl} h)  \\
		&= -\delta^j_{\ell} \delta^i_{k} - \delta^i_{k} \delta^j_{\ell} = -2 \delta^i_{k} \delta^j_{\ell} \,.
		\end{aligned}
		\]	
	\end{itemize}
	Adding the \(A, B, C\) terms gives Equation \eqref{eq:Hijkl}.	
\end{proof}

Finally, we need the next basic result.

\begin{lemma}
	The following holds:
	\begin{equation}\label{eq:ginv2}
	(\p_k \p_{\bl} g^{i\bj}) (0) = -(\p_k \p_{\bl} g_{j \bi}) (0) = R_{j\bi k \bl}(0) 
	\end{equation}
	where \(R\) is the Riemann curvature tensor of \(g\).
\end{lemma}

\begin{proof}
	To calculate \((\p_{\bl}\p_k g^{i\bj}) (0)\) note that
	if \(A\) is a matrix valued function such that \(A(0)\) is the identity and \(dA(0) = 0\) then
	\[
	\ddb A^{-1} = -\p \big( A^{-1} \cdot \op A \cdot A^{-1} \big) = - \ddb A \,\, \text{ at } 0 \,.
	\]
	Equation \eqref{eq:ginv2} follows from this and Equation \eqref{eq:riemann}. The reversal in the order of the \(i, j\) indices is due to the fact that \((g^{i\bj})\) is the inverse transpose of \((g_{i\bj})\).
\end{proof}


\subsection{Proof of Proposition \ref{prop:curv}}
Since \(H(0)\) is the identity and \(dH(0) = 0\) the curvature of \(\tn\) at \(0\) is given by the \((n+1) \times (n+1)\) matrix of \((1,1)\)-forms \(F = \op \p H\). By Lemma \ref{lem:zero} the \((i,j)\)-th entry of \(F\) is zero if either \(i=0\) or \(j=0\).
Therefore, by Equation \eqref{eq:Hijkl}, the curvature \(F  = 0\) if and only if for all \(i, j, k, \ell \in \{1, \ldots, n\}\) we have
\[
(\p_k \p_{\bl}g^{i\bj})(0) = \delta^{ij} \delta_{k\ell} + \delta^i_{k} \delta^j_{\ell}  \,.
\]
By Equation \eqref{eq:ginv2} -and swapping \(i, j\)- the above equation is equivalent to
\[
R_{i \bj k \bl} = g_{i \bj} g_{k\bl} + g_{k\bj} g_{i\bl} \,.
\]
By Equation \eqref{eq:chsc} we see that \(F = 0\) is and only if \(g\) has chsc \(\kappa = 2\).\qed




\section{Proof of Theorem \ref{thm}}
Let \(\omega = i \ddb \varphi\) be a K\"ahler metric on the unit ball \(B \subset \C^n\) that has chsc \(\kappa = 2\). The K\"ahler potential \(\varphi\) defines a Hermitian metric \(h= |1|_h^2 \) on the trivial line bundle \(L = \mO\) with \(h = \exp(-\varphi)\) that has curvature form \(\omega_h = i \op \p \log h = \omega\). 
Let \(H\) be the Hermitian metric on \(E = J^1(\mO)\) induced by \(h\) as in Definition \ref{def:H}. 

By Proposition \ref{prop:curv}(i) the Chern connection \(\tn\) of \(H\) is flat. 
By the Frobenius Theorem, we can find a frame of parallel sections
of \(E\) on \(B\), say
\[
e = (e_0, e_1, \ldots, e_n) \,.
\] 
Since \(\tn^{0,1} = \op_E\) the frame \(e\) is holomorphic. Since \(\tn H = 0\) the products \(H(e_i, e_j)\) are constant. Thus, after composing with a constant linear transformation, we can assume that the frame \(e\) is orthonormal.

Using the dual frame, we identify \(\P(E^*)\) with the trivial bundle \(B \times \CP^n\) and write \(\pi_2 : \P(E^*) \to \CP^n\) for the projection to the fibre factor. The relative Fubini-Study form on \(\P(E^*)\) associated to \(H^{\vee}\) is given by
\[
\eta_{FS} = \pi_2^*(\omega_{FS})
\]
where \(\omega_{FS}\) is the Fubini-Study metric on \(\CP^n\). 

Let \(\sigma: B \to \P(E^*)\) be the holomorphic section defined by \(L^* \subset E^*\) and write
\[
f = \pi_2 \circ \sigma
\]
The function \(f: B \to \CP^n\) is clearly holomorphic and
\[
f^* \omega_{FS} = \sigma^* \big( \pi_2^* \omega_{FS} \big) = \sigma^* \eta_{FS} = \omega
\]
where the last equality follows from Proposition \ref{prop:pullback}(i). This completes the proof of Theorem \ref{thm}(i). The proof of item (ii) is analogous, with the obvious modifications, and is therefore omitted.


