%%%%%%%%%%%%%%%%%%% GAN #########
\subsection{Semi-supervised regression generative adversarial network (SR-GAN)}
\label{sec:GAN_details}
To enable trait prediction from unlabeled hyperspectral spectra, we adopt a semi-supervised GAN framework \citep{olmschenk2019generalizing}. The generator $G$ learns to synthesize spectra that are indistinguishable from real data by optimizing $\mathcal{L}_{\text{gen}}$, while the discriminator $D$ learns both to distinguish real from fake spectra and to regress plant trait values from real labeled data optimizing $\mathcal{L}_{disc}$ . We adopt this notation for $D$ outputs: $f$ is an intermediate feature extractor and $D \circ f$ is final layer trait prediction.
$\text{Dist}(\cdot,\cdot)$ denotes a distance metric (e.g., cosine or Euclidean).

\textbf{Notations}: \( x_{\text{fake}} \): generated fake spectra from the generator; \( x_{\text{unlb}} \): unlabeled sample from GreenHyperSpectra; \( x_{\text{lb}} \): spectra sample from the labeled data;

\paragraph{Generator Matching Loss.} The generator is trained to align the generated spectra with real spectra in the latent feature space:
\begin{equation}
\mathcal{L}_{\text{gen}} = \lambda_{\text{gen}} \cdot \text{Dist}\left(f(x_{\text{fake}}), f(x_{\text{unlabeled}})\right),
\end{equation}
where $\lambda_{\text{gen}}$ controls the influence of the generator loss.

\paragraph{Labeled Supervised Loss.} For labeled spectra $x_{\text{labeled}}$ with corresponding trait references $y$, we define a standard supervised regression loss:
\begin{equation}
\mathcal{L}_{\text{labeled}} = \lambda_{\text{labeled}} \cdot \text{MSE}(D \circ f(x_{\text{labeled}}), y),
\end{equation}
where $\lambda_{\text{labeled}}$ is a weighting coefficient, and $\text{MSE}$ denotes the mean squared error between predicted and true traits.

\paragraph{Unlabeled Matching Loss.} To regularize the feature space, we encourage the feature representations $f(\cdot)$ extracted by $D$ from labeled and unlabeled real spectra to be similar:
\begin{equation}
\mathcal{L}_{\text{unlabeled}} = \lambda_{\text{unlabeled}} \cdot \lambda_{\text{srgan}} \cdot \text{Dist}\left(f(x_{\text{labeled}}), f(x_{\text{unlabeled}})\right),
\end{equation}
where 
%$\text{Dist}(\cdot,\cdot)$ denotes a distance metric (e.g., cosine or Euclidean), 
and $\lambda_{\text{unlabeled}}$ and $\lambda_{\text{srgan}}$ are scaling factors.

\paragraph{Fake Contrastive Loss.} The discriminator is further trained to push away fake spectra $x_{\text{fake}} = G(z)$ from real ones in the feature space:
\begin{equation}
\mathcal{L}_{\text{fake}} = \lambda_{\text{fake}} \cdot \lambda_{\text{srgan}} \cdot \text{Dist}\left(f(x_{\text{unlabeled}}), f(x_{\text{fake}})\right),
\end{equation}
where $\lambda_{\text{fake}}$ weights the contrastive term.

\newpage
\paragraph{Gradient Penalty.} A gradient penalty is used to enforce Lipschitz continuity, stabilizing the training of the discriminator:
\begin{equation}
\mathcal{L}_{\text{GP}} = \lambda_{\text{GP}} \cdot \mathbb{E}_{\hat{x}} \left[max(0, \left(\left\| \nabla_{\hat{x}} f(\hat{x}) \right\|_2 - 1 \right)^2) \right],
\end{equation}
where $\hat{x}$ is an interpolated sample between $x_{\text{fake}}$ and $x_{\text{unlabeled}}$, and $\lambda_{\text{GP}}$ is the penalty coefficient.

\paragraph{Total Losses.} The complete losses for the discriminator are defined as:
\begin{equation}
\mathcal{L}_{disc} = \mathcal{L}_{\text{labeled}} + \mathcal{L}_{\text{unlabeled}} + \mathcal{L}_{\text{fake}} + \mathcal{L}_{\text{GP}},
\end{equation}
