In the proof of \Cref{thm:mainresult} we used \Cref{thm:main} and also the following lemma, which we prove now.
\begin{lemma}
    \label{lma:time_exploit_bit}
    Assume $\LO(x^1_t) < \LO(x^2_t)$ for the current population $P_t=\{x^1_t,x^2_t\}$ of the \dega on \leadingones. Let $T_{\text{Improve}}$ be the number of $\LO$-evaluations until $x^1$ is replaced by a fitter search point. Then
    $
        \E{T_{\text{Improve}}} = O(\lambda).
    $
\end{lemma}
    \begin{proof}
        This follows directly from the construction of exploitation phases. We perform biased crossovers between $x^1_t,x^2_t$ until we find an improvement for $x^1_t$. Let $\mathcal{I}$ be the event of moving the improving bit from $x^2$ to $x^1$ in one such biased crossover. Then
        \begin{align*}
            \Pr[\mathcal I] = 1/\lambda \quad \text{and} \quad T_{\text{Improve}} \sim \geo(\Pr[\mathcal I]),
        \end{align*}
        where $\geo$ denotes a geometric distribution. Hence $\EE[T_{\text{Improve}}] = O(\lambda)$.
    \end{proof}


\subsection{Proof of Theorem \ref{thm:main}}
\label{sub:proof_main}
It remains to prove \Cref{thm:main}, and this whole section is devoted to that. Recall that $\bar H_k$ is the number of bits that align in the non-optimized part of $x^1, x^2$ at the start of phase $k$. We start by proving two lemmas which analyze how the  diversity changes in a diversity and in an exploitation phase, respectively. In the following, we frequently use these inequalities:
\begin{align}
    \label{eq:exp-bounds}
    1-x \leq \exp \lb -x \rb \quad \text{and} \quad 1-x \geq \exp \lb -2x \rb, x \in [0,1/2].
\end{align}
Combining both gives $(1-x)^r \le \exp(-xr) \le 1-xr/2$ if $x\in [0,1/2]$, $r\ge 0$ and $xr \le 1$.
\begin{lemma}
    \label{lma:div-in-div-phase}
    For $k\ge 1$, assume that the $k$-th phase is a diversity phase with $\alpha_k n\ge n^{2/3}$. Then 
    \begin{align*}
        \E{\bar H_{k+1} \cond \bar H_k} \in \big[ \tfrac{1}{2}\bar H_k-1, \big(1 - \tfrac{1}{4e^{2}}\big)\bar H_k\big].
    \end{align*}
    \begin{proof}
        We first prove the lower bound. We may neglect any mutation that flips the optimized part, since the offspring will be rejected. Among the remaining mutations, we compare the critical bit $i$ with any fixed non-optimized bit $j$. By symmetry, both are equally likely to be flipped before the other. Hence, the probability that bit $j$ is flipped strictly before the first improving mutation is at most $1/2$. So before that mutation, $\bar H_k$ decreases by at most a factor of $1/2$ in expectation. Finally, in the improving mutation, in expectation at most one additional bit is flipped. 

        For the upper bound, let $c_2 = 1 - 1/(4e^{2})$. For a fixed generation, let $p_{k,\text{out}}$ be the probability of leaving phase $k$. Then
        \begin{align*}
            p_{k,\text{out}}  = \tfrac{1}{n} \big( 1 - \tfrac 1 n \big)^{n - \alpha n - 1} \le \tfrac{1}{n}.
        \end{align*}
        Let $Y_k$ be the number of $\LO$-evaluations until leaving phase $k$. For $y = n/2$ we calculate
        \begin{align*}
            \Pr\lbr Y_k \geq y \rbr \geq \lb 1 - p_{k,\text{out}}  \rb^y \stackrel{\eqref{eq:exp-bounds}}{\geq} \exp\lb-2p_{k,\text{out}} y \rb \ge 1/e,
        \end{align*}
        where the second step holds for $n \geq 2$. To calculate the reduction in $\bar H_t$, let us consider the event $\mathcal F_i$ of flipping bit $i$ in a one-bit flip in phase $k$; that is, there is a mutation which flips bit $i$ and no other bit. The probability that a fixed mutation is of this type is at least $\tfrac{1}{n}(1-\tfrac{1}{n})^{n-1} \ge \tfrac{1}{en}$. Moreover, by law of total probability, we have
        \begin{align}
        \label{eq:one-bit-flip}
            \Pr \lbr \mathcal F_i \rbr \ge \Pr \lbr \mathcal F_i \cond Y_k \geq y\rbr\cdot \Pr \lbr Y_k \ge y \rbr.
        \end{align}
        Let us analyze $\Pr \lbr \mathcal F_i \cond Y_k \geq y\rbr$. Since more than $y$ trials only increase the chance of $\mathcal F_i$, we get
        \begin{align*}
            \Pr \lbr \mathcal F_i \cond Y_k \ge y\rbr \ge 1- \big( 1- \tfrac{1}{en} \big)^y
            \stackrel{\eqref{eq:exp-bounds}}{\ge} 1-\exp( -\tfrac 1 {2e} ) \stackrel{\eqref{eq:exp-bounds}}{\ge} \tfrac{1}{4e} .
        \end{align*}
%        Applying \Cref{eq:exp-bounds} in the following steps with $n\geq 2$ yields
%        \begin{align*}
%            1 - \exp\lb -\tfrac 1 2 \lb1 - \tfrac 1 n\rb^{\alpha n} \rb \geq \tfrac 1 4 \lb 1 - \tfrac 1 n \rb^{\alpha n} \geq \tfrac{1}{4} \exp \lb-2\alpha\rb.
%        \end{align*}
%        We know  that $0 < \alpha \leq 1$. 
        Plugging our finding back into \Cref{eq:one-bit-flip} gives
        $\Pr [ \mathcal F_i ] \ge  1/(4e^2)$. 
        Thus each one-bit in $\bar H_{k}$ has a chance of at least $1/(4e^2)$ to vanish. We conclude that $\E{\bar H_{k+1}} \leq ( 1 - 1/(4e^2) ) \cdot \bar H_k$, as required.
    \end{proof}
\end{lemma}
\noindent We now analyze how $\bar H_k$ develops during an exploitation phase. We first show in \Cref{lma:length_exploit_whp} that with high probability the progress per exploitation phase is at most $O(\sqrt \lambda \log n)$, where we measure progress as the fitness increase of the fitter of the two individuals. Afterwards, we will derive an upper bound on the increase from $\bar H_k$ to $\bar H_{k+1}$ for an exploitation phase $k$ in \Cref{lma:div-in-exploit}.
\begin{lemma}
    \label{lma:length_exploit_whp}
    Let $\gamma >1$ be constant, $c_{\text{len}} \coloneqq 256\gamma$ and assume $2\leq \lambda = o(n)$. Consider an exploitation phase $k$ with $\alpha_k n \geq n^{2/3}$. Let $L_k$ be the progress made in phase $k$, i.e., the fitness difference between the fitter search point in the first generation of phase $k$ and the fitter search point in the first generation of phase $k+1$. Then with probability $1 - o(n^{-\gamma})$, 
    \begin{align*}
        L_k \leq c_{\text{len}} \cdot \sqrt{\lambda} \log n \eqqcolon L_{\text{max}}.
    \end{align*}
\end{lemma}

    \begin{proof}
    The phase ends as soon as the algorithm reaches a blocking bit as the next critical bit, as defined in \Cref{sec:prelim}. Recall that $B_k$ is the number of blocking bits and $S_k$ is the number of skipping bits in the non-optimized part of the bit-string. Notice that $\bar H_k = B_k + S_k$ and $\EE[S_k \cond \bar H_k] = \EE[B_k\cond \bar H_k] = \frac{1}{2} \bar H_k$, because each bit in $\bar H_k$ independently has a chance of $1/2$ to be either a skipping or a blocking bit. We will distinguish two cases.\\

    \noindent \textbf{Case 1:} $\bar H_k \geq \frac{\alpha_k n}{2}$.\\
    To show an upper bound on the duration of the exploitation phase we will need to show that it is very unlikely to have substantially more $S_k$ than $B_k$ bits. Notice that any bit among $\bar H_k$ comes from $S_k$ or $B_k$ independently with probability $1/2$, so $\EE[B_k] \ge \alpha_k n/4$. Applying a Chernoff bound for $\alpha_k = \Omega(n^{-1/3})$ yields
    \begin{align*}
        \Pr \lbr B_k < \frac{\alpha_k n}{8} \rbr \leq \Pr \lbr B_k \leq \big( 1- \tfrac 1 2 \big)\E{B_k}\rbr
        \leq  \exp{\lb  - \frac{\alpha_k n}{32}\rb} = o(n^{-\gamma}).
    \end{align*}
    In the following let $B_k^\geq$ be the event "$B_k \geq \frac{\alpha_k n}{8}$" and $L_k^>$ be the event "$L_k > L_{\text{max}}$". Then we can bound $\Pr[ L_k^> ]$ by
    \begin{align*}
        \Pr[ L_k^> ] = & \Pr[ L_k^> \cond B_k^\ge ]\cdot \Pr [ B_k^\ge ] + \Pr[ L_k^> \cond \neg B_k^\ge ] \cdot \Pr [ \neg B_k^\ge ]\\
        \le & \ \Pr[ L_k^> \cond B_k^\ge ] + \Pr [ \neg B_k^\ge ] \le \Pr[ L_k^>\cond B_k^\ge ] + o(n^{-\gamma}).
    \end{align*}
    To bound $\Pr[ L_k^>\cond B_k^\ge]$, note that $L_k^>$ implies that there is no blocking bit among the next $L_{\max}$ bits after the critical bit of the beginning of phase $k$. We notice that for each bit we have a blocking-probability of $p_B = B_k/(\alpha_k n) \ge 1/8$. Moreover, blocking bits are negatively associated (for a fixed total number, having a blocking bit in position $i$ decreases the chance of having a blocking bit at position $j\neq i$), hence the bound $\Pr [ L_k^> \mid B_k^{\ge}] \le \lb 1- p_B \rb^{L_{\text{max}}}$  applies~\cite[Property~P2]{joag1983negative}. Not finding a blocking bit in $L_{\text{max}}$ generations is therefore unlikely:
    \begin{align*}
        \Pr [ L_k^> \mid B_k^{\ge} ] \le \lb 1- p_B \rb^{L_{\text{max}}} \le e^{-p_B\cdot   L_{\text{max}}} \stackrel{\lambda \ge 1}{\le} n^{-32\gamma} = o(n^{-\gamma}).
    \end{align*}
    %We used \bound{$\lambda \geq 1$} in the second to last step.\\ 


    \noindent \textbf{Case 2:} $\bar H_k < \frac{\alpha_k n}{2}$.\\
    For this case we know that there are at least $H_k = \alpha_k n - \bar H_k \geq \alpha_k n/2$ diverse bits, i.e. bits that differ between $x^1$ and $x^2$. We will study the development of $B_k$ throughout the first $\tau = \lambda L_{\max}/16$ generations of phase $k$. We will show that after $\tau$ generations enough blocking bits will have been generated to stop the phase w.h.p. in further $\tau$ generations. Note that since this phase only uses crossover, blocking bits can only be generated, not destroyed.

    Let us first show that w.h.p.\! the progress in the first $\tau$ generations is at most $L_{\max}/2$. In each generation, the offspring is accepted if and only if the improving bit is copied from the fitter search point $x^2$ to $x^1$, which happens with probability $1/\lambda$. Let us call $\sigma$ the number of accepted offspring in the first $\tau$ generations of the phase. Then $\EE[\sigma] = L_{\max}/16$, and by the Chernoff bound $\Pr[\sigma > L_{\max}/8] \le \exp(-L_{\max}/48) = o(n^{-\gamma})$. Hence, we may assume $\sigma \le L_{\max}/8$. Those are the only generations in which progress can be made, namely if the offspring $z$ is strictly fitter than both $x^1$ and $x^2$. In this case, each subsequent bit of $z$ after the critical bit has probability $1/2$ to be a one-bit, hence the progress in that generation is dominated by $1+\geo(1/2)$, where $\geo$ denotes a geometric distribution. (Analogously to the argument for diversity phases in Section~\ref{sec:prelim}.) Hence, the expected progress with the first $\sigma \le L_{\max}/8$ accepted offspring is at most $L_{\max}/4$, and the probability that it exceeds $L_{\max}/2$ is at most $\exp(-L_{\max}/16) = o(n^{-\gamma})$ because the sum of geometric random variables is concentrated~\cite[Theorem~1.10.32]{doerr2020probabilistic}. Hence, we may assume that the progress in the first $\tau$ generations is at most $L_{\max}/2$. %\jl{Those calculations are very quick. If you want and have time, you can add details. Otherwise it is also fine like this, especially for the conference version.}

    Let us pessimistically assume that the phase does not end in the first $\tau$ generations, since otherwise we are done. We write $B_{k,\tau}$ for the number of blocking bits after $\tau$ generations.  Then as argued above, the expected number $\EE[\sigma]$ of accepted offspring is $\tau/\lambda = L_{\max}/16$, and again by the Chernoff bound, we have $\sigma \ge L_{\max}/32$ with probability at least $1-\exp(-L_{\max}/256) = 1-o(n^{-\gamma})$. Hence, we may assume that at least $\sigma \ge L_{\max}/32$ offspring are accepted. Let us call this event $\calE_\sigma$.

    We will now study how many new blocking bits are generated under this assumption in the first $\tau$ generations. Let us call this number $B_{\text{new}}$. Consider a diverse pair of bits $(0,1)$ or $(1,0)$. By the condition $\bar H_k < \alpha_k n /2$, there are at least $\alpha_k n/2$ such pairs at the beginning of the phase. In a generation with accepted offspring the crossover operator copies each bit from $x^2$ to $x^1$ with probability $1/\lambda$, thus this is the probability of create equal bits $(0,0)$ or $(1,1)$. Ending up with equal values (either $(0,0)$ or $(1,1)$) in $\tau$ generations therefore happens with probability $1 - ( 1 - 1/\lambda )^{\sigma}$. Moreover, since the two options $(1,0)$ and $(0,1)$ for this position were equally likely to start with, the values $(0,0)$ and $(1,1)$ are also equally likely in the end. This yields an additional factor of $1/2$ that the position yields a stopping bit. Hence, the expected number of new blocking bits is
    %The number of generations $j$ is closely tied to $\tau$. However, it is possible to encounter skipping bits among the first $\tau$ bits. We therefore have $j \le \tau$. 
    \begin{align*}
        \EE[B_{\text{new}} \cond \calE_\sigma] & \ge \frac{\alpha_k n}{2}\cdot \Big( 1 - ( 1 - \tfrac{1}{\lambda} )^{L_{\max}/32} \Big)\cdot \frac{1}{2} \\
        &  
        \begin{cases}
        \stackrel{\eqref{eq:exp-bounds}}\ge \frac{\alpha_k n}{4}\cdot \frac{L_{\max}}{64\lambda} = \frac{\gamma \alpha_k n \log n}{\sqrt{\lambda}} \eqqcolon \psi & \text{if } L_{\max} \le 16\lambda, \\
        \ge \frac{\alpha_k n}{4}\cdot (1-e^{-1/2}) \eqqcolon \psi &  \text{if } L_{\max} > 16\lambda.
        \end{cases}
    \end{align*}
    Moreover, conditioned on $\calE_\sigma$, the random variable $B_{\text{new}}$ dominates the sum of $H_k$ independent indicator random variables, one for each position, where they are independent because their starting values are independent and crossover operates independently on them. Hence, $B_{\text{new}}$ dominates a binomial random variable with expectation $\psi$. By the Chernoff bound, we have $\Pr[B_{\text{new}} < \psi/2] \le \exp(-\Omega(\psi)) \le \exp(-\Omega(n^{1/6})) = o(n^{-\gamma})$, since $\lambda = o(n)$ and $\alpha_k = \Omega(n^{-1/3})$. Therefore, from now on we may assume $B_{\text{new}} \ge \psi/2$. Let us call this event $\calB_{\text{new}}^\geq$.

    Let us call $L_k^2$ the progress in phase $k$ after the first $\tau$ generations. It remains to show that conditional on $\calB_{\text{new}}^\geq$, we have $L_k^2 \le L_{\max}/2$ w.h.p. Note that the converse can only happen if none of the next $L_{\max}/2$ positions after the critical position is a blocking bit. We proceed similarly as in Case~1. 
    %We need to take into account that $\alpha$ may slightly decrease during the phase. But since it suffices to consider a fitness progress of at most $L_{\max}$, we may restrict to the part of the phase when the non-optimized part has size at least $\alpha n-L_{\max} \ge \alpha n/2$. Hence,
    Conditional on $\calB_{\text{new}}^\geq$ each position has a probability of at least $\psi/(\alpha_k n)$ to be a blocking bit. As in Case~1, the blocking bits are negatively associated. Therefore, the probability that none of the next $L_{\max}/2$ bits are blocking bits is at most $(1-\psi/(\alpha_k n))^{L_{\max}/2}$, and hence
    \begin{align}
        \Pr\big[L_k^2 > L_{\max}/2 \cond \calB_{\text{new}}^\geq\big] \le \lb 1-\tfrac{\psi}{\alpha_k n}\rb^{L_{\max}/2}.\label{eq:Lk2}
    \end{align}
    If $L_{\max} \le 16\lambda$ then we have $\psi/(\alpha_k n) = \gamma \log n /\sqrt{\lambda}$, and together with $L_{\max} = 256\gamma\sqrt{\lambda} \log n$  the right hand side of~\eqref{eq:Lk2} is at most $\exp(- 128\gamma^2 \log^2 n) = o(n^{-\gamma})$. If $L_{\max} > 16\lambda$ then $\psi/(\alpha_k n)  = (1-e^{-1/2})/4 \ge 1/12$, and the statement follows from $(1-1/12)^{L_{\max}/2}\le \exp(-10\gamma\sqrt{\lambda} \log n) =o( n^{-\gamma})$. This concludes the proof.
