\noindent Next, we apply \Cref{lma:length_exploit_whp} to derive an upper bound on the expected increase from $\bar H_k$ to $\bar H_{k+1}$.
\begin{lemma}
    \label{lma:div-in-exploit}
    Let $\gamma >1$,  $c_{\text{len}} = 256\gamma$ and $2\leq \lambda = o(n)$. Let phase $k$ be an exploitation phase with $\alpha_k n = \Omega(n^{2/3})$. Then
    \begin{align*}
        \E{\bar H_{k+1} - \bar H_{k}} \leq 5c_{\text{len}} \cdot \alpha_k n \cdot \log n/\sqrt{\lambda} .
    \end{align*}
    \begin{proof}
        As in the proof of \Cref{lma:length_exploit_whp} let $L_k^\leq, L_k^>$ be the events of staying within or exceeding $c_{\text{len}} \cdot \sqrt \lambda \log n$ generations in phase $k$ respectively. Also, let $\Delta \bar H_k \coloneqq \bar H_{k+1} - \bar H_k$. First we notice that a maximum of $\alpha_k n$ bits can contribute to $\Delta \bar H_k$. Therefore,
        \begin{align}
            \EE[\Delta \bar H_k]  & = \EE[\Delta \bar H_k \cond L_k^\leq] \cdot \Pr[ L_k^\leq ] + \EE[\Delta \bar H_k \cond L_k^>] \cdot \Pr[ L_k^> ] \label{eq:negligible_error}\\
            & \leq  \EE[\Delta \bar H_k \cond L_k^\leq]+ \alpha_k n \cdot o(n^{-\gamma}) \leq \EE[\Delta \bar H_k \cond L_k^\leq] + o(n^{1-\gamma}).\nonumber
        \end{align}
        We can choose any $\gamma > 1$, so the latter summand gives us a contribution of only $o(1)$. From now on we will study $\EE[\Delta \bar H_k \cond L_k^\leq]$. 

        Conditioned on $L_k^\leq$, we want to bound the number of improving offspring. Note that every improving offspring increases the fitness of the worse search point by at least one. By slight abuse of notation, let us call $x_k^1$ and $x_k^2$ the two search points at the beginning of the phase. Then $x^1_k$ can improve at most to $\LO(x^2_k)+L_k$, since this is the maximal fitness obtained in this phase. Hence, the number of improving offspring is bounded by $L_k+\LO(x^2_k)-\LO(x^1_k)$. Note that the difference $\LO(x^2_k)-\LO(x^1_k)$ was created by free riders (bits that were 1 by chance) in the generation in which $x^2$ was created as new offspring. Thus it is distributed as $1+\geo(1/2)$ and is bounded by $2\log_2 n$ with probability at least $1-1/n^2$. By the same calculation as in~\eqref{eq:negligible_error}, the error event is so unlikely that it is negligible, and we may thus assume that the number of improving offspring is at most $L_{\max}+2\log_2 n \le 2L_{\max}$ when $n$ is large enough.

        We now use a similar calculation as in the proof of \Cref{lma:length_exploit_whp}, but now we compute an upper bound (instead of a lower bound) for the probability of turning two diverse bits into identical bits. Note that here we do not care whether the result is a blocking bit or skipping bit. We call $p_{\text{id}}$ this probability of turning a fixed diverse pair into an identical one in the $k$-th phase. By using \Cref{eq:exp-bounds} and $\lambda \geq 2$ we find
        \begin{align*}
            p_{\text{id}} \leq 1 - \big( 1- \tfrac 1 \lambda \big)^{2L_{\max}} \leq 1 - \exp( - 4L_{\max}/\lambda ) \leq 4L_{\max}/\lambda.
        \end{align*}
        Therefore, recalling the definition of $L_{\max}$ from \Cref{lma:length_exploit_whp},
        \begin{align*}
            \EE\big[\Delta \bar H_k \cond L_k^\geq\big] \leq \alpha_k n \cdot p_{\text{id}} \leq \alpha_k n \cdot  4 c_{\text{len}}  \sqrt{\lambda} \log n/\lambda .
        \end{align*}
        We conclude $\E{\Delta \bar H_k} \leq 4c_{\text{len}} \cdot  \alpha_k n \log n/\sqrt \lambda + o(1)$ in total. 
    \end{proof}
\end{lemma}


Now that we know how the diversity develops in the two respective phases we can finally prove \Cref{thm:main}.
\begin{proof}[Proof of \Cref{thm:main}]
Fix  arbitrarily $\gamma \coloneqq 2$ (any other $\gamma >1$ would also work). Choose $c>0$ large enough such that $(1-\tfrac{1}{4e^2})(1+5c_{\text{len}}/c) < 0.98$, where $c_{\text{len}}$ is the constant from \Cref{lma:length_exploit_whp}.

We first prove by induction over $k$ that 
\begin{align}\label{eq:induction_hypothesis}
    \E{\bar H_k} \leq c \cdot \alpha_k n \log n/\sqrt{\lambda}
\end{align}
holds at the beginning of every exploitation phase, where we do the inductive step from $k$ to $k+2$, i.e., we consider the combined effect of an exploitation and a diversity phase. Afterwards, we show that it also holds in between and with a index-shifted $\alpha$ if we increase the factor $c$, i.e., we show for some constant $c'>0$
\begin{align}\label{eq:in_between}
    \E{\bar H_t} \leq c' \cdot \alpha_{t-1} n \log n/\sqrt{\lambda}
\end{align}
for all times $t$ for which $\alpha_{t-1} \ge n^{-1/3}$. Note that this is the statement of \Cref{thm:main}.

For the start of the induction, note from \Cref{algo:dega} that the algorithm always starts with two antipodal search points, i.e. at maximum diversity. Moreover, this implies that initially $\LO(x^1) \neq \LO(x^2)$, so the first phase is an exploitation phase and $\bar H_k = 0$ for $k=0$. This establishes the base case of the induction.

For the inductive step, assume that~\eqref{eq:induction_hypothesis} holds for some even $k\ge 0$. Recall $L_{\text{max}}$ from \Cref{lma:length_exploit_whp} and let $\calL= L_{k}^\leq \cap L_{k+1}^\leq$  be the event that $L_k \le L_{\text{max}}$ and $L_{k+1} \le L_{\text{max}}$.  Then $\Pr[L_{k}^\leq] = 1-O(n^{-2})$ by \Cref{lma:length_exploit_whp}, and $\Pr[L_{k+1}^\leq] = 1-O(n^{-2})$ since the progress in a diversity phase is distributed as $1+\geo(1/2)$ and is bounded by $2\log_2 n$ with probability at least $1-1/n^2$. Hence, $\Pr[\calL] = 1-O(n^{-2})$. Since $\bar H_{k+2} \in [0,n]$,
    \begin{align}
        \EE[\bar H_{k+2}] & = \EE[\bar H_{k+2} \cond \calL]\cdot\Pr[\calL] + \EE[\bar H_{k+2} \cond \neg \calL]\cdot\Pr[\neg \calL] \label{eq:negligible_error2}\\
        & = \EE[\bar H_{k+2} \cond \calL] (1-O(n^{-2}))+o(1) 
        = \EE[\bar H_{k+2} \cond \calL] \pm o(1).\nonumber
    \end{align}
In the following we will thus compute $\EE[\bar H_{k+2} \cond \calL]$. Note that by the same calculation as~\eqref{eq:negligible_error} and~\eqref{eq:negligible_error2}, Lemmas \ref{lma:div-in-div-phase} and \ref{lma:div-in-exploit} also hold when conditioning on $\calL$, at the cost of an additive $\pm o(1)$ error term. Hence \Cref{lma:div-in-exploit} yields
    \begin{align} \label{eq:change-with-one-phase}
        \EE[\bar H_{k+1}\cond \calL] 
        & \le \EE[H_{k} \cond \calL]+ 5c_{\text{len}} \cdot \alpha_k n  \log n/\sqrt{\lambda} +o(1)\nonumber \\
        & \stackrel{\eqref{eq:induction_hypothesis}}{\le} (c+5c_{\text{len}})\alpha_k n  \log n/\sqrt{\lambda} + o(1),
    \end{align}
and by \Cref{lma:div-in-div-phase},
    \begin{align}\label{eq:change-with-two-phases}
        \EE[\bar H_{k+2}] &\le  
        \EE[\bar H_{k+2}\cond \calL] +o(1) \le (1-\tfrac{1}{4e^2})\EE[\bar H_{k+1} \cond \calL]+ o(1)\nonumber \\
        %& \le + 5c_{\text{len}} \cdot \frac{\alpha_k n \cdot \log n}{\sqrt{\lambda}} +o(1)\\
        & \le (1-\tfrac{1}{4e^2})(c+5c_{\text{len}})\alpha_k n  \log n/\sqrt{\lambda} + o(1)\nonumber\\
        & \le 0.99c \cdot \alpha_k n \log n/\sqrt{\lambda},
    \end{align}
where we absorbed the $o(1)$ term into the constant in the last term. This is almost the desired inductive bound, except that we need $\alpha_{k+2}$ instead of $\alpha_k$. However, conditional on $\calL$ and for large enough~$n$,
\begin{align*}
\alpha_{k+2}n = \alpha_kn -L_k-L_{k+1} \ge \alpha_k n - 2L_{\max} \ge 0.99\alpha_k n,
\end{align*}
because $L_{\max} = O(\sqrt{n}\log n)$ and $\alpha n = \Omega(n^{2/3})$. This implies that $0.99\alpha_k \le \alpha_{k+2}$. Hence we may continue \eqref{eq:change-with-two-phases} as 
    \begin{align*}
        \EE[\bar H_{k+2}] &\le \EE[\bar H_{k+2}\cond \calL] +o(1)\le c \cdot\alpha_{k+2} n  \log n/\sqrt{\lambda},
    \end{align*}
which yields \eqref{eq:induction_hypothesis} for $k+2$. By induction, this shows the statement for all even $k$. For the remaining points in time, which are not the start of an exploitation phase, we use very similar arguments. Equation~\eqref{eq:change-with-one-phase} tells us that after the $k$-th phase, $k$ even, we have $\EE[\bar H_{k+1}] = O(\alpha_k n\log n /\sqrt{n})$. The same argument also shows that $\EE[\bar H_{t}] = O(\alpha_k n\log n /\sqrt{n})$ for all times $t$ during the $k$-th phase. For the $(k+1)$-th phase, since it is a diversity phase $\bar H$ can only decrease during this phase, so we also have $\EE[\bar H_{t}] \le \EE[\bar H_{k+1}] = O(\alpha_k n\log n /\sqrt{n})$ for all times $t$ during the $(k+1)$-th phase. As before $\alpha$ only changes by a $(1-o(1))$ factor during one phase, hence we also obtain $\EE[\bar H_{t}] = O(\alpha_t n\log n /\sqrt{n})$ for all $t$ in either phase $k$ or phase $k+1$, at the expense of a slightly larger hidden constant $c'$. Therefore, the statement~\eqref{eq:in_between} for all times $t$ follows.
