\title{Higher path groupoids and the holonomy of formal power series connections}
\author{Matthew Cellot}

\begin{document}

\begin{abstract}
\noindent Building on ideas of Kohno, we develop a framework for the construction of higher holonomy functors via the transport of formal power series connections.  Using these techniques, we obtain functors from the path groupoid, the path 2-groupoid, and the path 3-groupoid of a manifold. As an application, we construct a Gray functor from the path 3-groupoid of the configuration space of $m$ points in $\mathbb{R}^n$ for~$n\geqslant 4$.
\end{abstract}

\maketitle

\section*{Introduction}

\noindent The purpose of this article is to construct a higher categorical analogue of holonomy functors. Let's first recall the construction of holonomy functors using the notion of parallel transport for a connection. Let~$M$ denote a smooth manifold and consider a connection $\nabla$ on a vector bundle $E\to M$.  Given a smooth curve $\gamma\colon [0,1] \to M$, a section $X$ of $E$ along $\gamma$ is \emph{flat} if $\nabla_{\gamma'(t)}X = 0$. Suppose given an element~$e\in E$ above $\gamma(0)$.  Then the \emph{parallel transport} of $e$ along $\gamma$ is the unique flat section $X$ of $E$ above $\gamma$ such that ~$X_{\gamma(0)} = e$. Therefore, $\nabla$ defines a way of moving elements of the fibers along curves, that is, a linear map $\Theta(\gamma) \colon E_{\gamma(0)}\, \tilde{\to}\, E_{\gamma(1)}$ that sends $e \in E_{\gamma(0)}$ to $X_{\gamma(1)}\in E_{\gamma(1)}$.  In fact,  the points and the smooth paths of~$M$ assemble to form a category $\mathcal{P}_1(M)$ called the \emph{path groupoid} of $M$ (see Section \ref{higherpathgroupoids}), and the parallel transport for $\nabla$ defines a \emph{holonomy functor}
$$
\mathrm{Hol}^1_\nabla \colon \mathcal{P}_1(M) \to \mathrm{Vect}
$$
that sends a point $x\in M$ to the vector space $E_x$, and a smooth path $\gamma$ from $x$ to $y$ to the linear map~$\Theta(\gamma) \colon E_x\, \tilde{\to}\,  E_y$. 

Note that in the particular case of a trivial vector bundle  $E = M\times V$, a connection on $E$ is the same as an $\mathrm{End}(V)$-valued differential 1-form $\omega\in C^1_{dR}(M)\otimes \mathrm{End}(V)$, and the parallel transport along a smooth curve $\gamma\colon [0,1]\to M$ induces the linear map 
$$
\Theta(\gamma) = \mathrm{Id}_V + \int_\gamma \omega + \int_\gamma \omega\omega + \int_\gamma \omega\omega\omega + \cdots \colon V\, \tilde{\to}\, V,
$$
where $\displaystyle \int \omega\ldots\omega$ denotes the iterated integral of $\omega, \ldots, \omega$, as defined by Chen \cite{chen1973} (see Section \ref{iteratedintegrals}). This then defines a holonomy functor
$$
\mathrm{Hol}^1_\omega\colon \mathcal{P}_1(M)\to \GL(V),
$$ 
where $\GL(V)$ is the category with only one object and with morphisms given by the automorphisms of~$V$.

Several very interesting functors arise in this setting. If we denote by $\mathrm{Conf}(m, \mathbb{C})$ the configuration space of $m$ pairwise distinct points in $\mathbb{C}$, then a loop $\gamma\colon [0,1] \to \mathrm{Conf}(m,\mathbb{C})$ can be seen as a pure braid with $m$ strands.  Moreover, the homotopy class of a loop in $\mathrm{Conf}(m,\mathbb{C})$ corresponds to the isotopy class of a pure braid, and we get an isomorphism between the fundamental group of $\mathrm{Conf}(m, \mathbb{C})$ and the pure braid group $P_m$. The Knizhnik-Zamolodchikov connection $\omega_{KZ}$ is a flat connection on a trivial vector bundle~$\mathrm{Conf}(m,\mathbb{C}) \times V \to  \mathrm{Conf}(m,\mathbb{C})$, where the vector space $V$ is obtained by taking the tensor product of~$m$ representations of a simple Lie algebra. The parallel transport of $\omega_{KZ}$ induces representations of $P_m$ and of the braid group $B_m = P_m/\mathfrak{S}_m$, where we take the quotient by the symmetric group~$\mathfrak{S}_m$.  The Drinfeld-Kohno theorem then states that the representations of braid groups induced by the Knizhnik-Zamolodchikov connection correspond to the representations of braid groups resulting from the corresponding quantum group (see details in  \cite[Chapter 5]{ohtsuki2002quantum}). Moreover, these representations induce the Kontsevich integral, a powerful invariant of knots that is universal among Vassiliev invariants (see details in~\cite[Chapter~6]{ohtsuki2002quantum}).

In order to construct higher categorical analogues of holonomy functors, we build on a method due to Kohno \cite{kohno2016higher, kohno2021higher, Koh2022}. We first introduce higher categorical versions of the path groupoid of a smooth manifold $M$: the path 2-groupoid $\mathcal{P}_2(M)$ and the path 3-groupoid $\mathcal{P}_3(M)$.  These structures allow us to consider higher homotopical data of $M$.  Moreover, we associate to a coaugmented differential graded coalgebra $C$ a strict 2-category $\mathcal{C}_2(C)$ and a Gray 3-category $\mathcal{C}_3(C)$ via the cobar complex of~$C$.  Then we show that the transport of a formal power series connection with values in the cobar complex of~$C$ yields functors from the path 2-groupoid and the path 3-groupoid of $M$ to the 2-category $\mathcal{C}_2(C)$ and the Gray 3-category~$\mathcal{C}_3(C)$, respectively:

\begin{theorem}\label{maintheorem}
Let $\omega$ be a formal power series connection on a smooth manifold $M$. The transport of $\omega$ induces higher holonomy functors
\begin{align*}
\mathrm{Hol}_\omega^2 \colon \mathcal{P}_2(M) \to \mathcal{C}_2(C)&& \text{and} &&
\mathrm{Hol}_\omega^3 \colon \mathcal{P}_3(M) \to \mathcal{C}_3(C).
\end{align*}
\end{theorem}
\noindent Theorem \ref{maintheorem} corresponds to Theorems \ref{thm2holonomy} and \ref{thm3holonomy} in Section \ref{higherholonomyfunctors}.

Next we apply our construction to a formal power series connection introduced by Komendarczyk, Koytcheff and Voli\'c \cite{KKV} that generalizes the Knizhnik-Zamolodchikov connection.  This yields a functor from the path 3-groupoid of the configuration space of $m$ points in $\R^n$ for $n\geqslant 4$ (see remark in Section \ref{application}).

For $k\geqslant 4$, we conjecture the existence  of holonomy $k$-functors $\mathrm{Hol}_\omega^k $ from the path $k$-groupoid $\mathcal{P}_k(M)$ of a manifold $M$ to some target $k$-category  $\mathcal{C}_k(C)$.  Nevertheless, a precise definition of $\mathcal{P}_k(M)$ remains to be written.

This work is motivated by the study of higher order versions of the Knizhnik-Kamolod\-chikov equation and the derived representations of braid groups.  Generalizations of these types of techniques can be seen in the work of Cohen and Gitler \cite{cohen2002loop} who give detailed descriptions of the homology of loop spaces of configuration spaces.  Moreover,  many related results help to better understand higher path groupoids.  We refer for instance to work by Baez and Schreiber \cite{baez2004higher} on higher gauge theory and~2-connections, as well as work by Faria Martins and Picken \cite{martins2010two, faria_martins_fundamental_2011} on higher dimensional holonomy. For further work on higher holonomy functors, see Kohno \cite{kohno2016higher, kohno2020higher, kohno2021higher}, Schreiber and Waldorf~\cite{schreiber_parallel_2007, schreiber_smooth_2008}. Moreover, we expect that higher holonomy functors may be useful in the study of braided surfaces in~4-space, as studied by Kamada \cite{kamada_braid_2002}, Carter and Saito \cite{carter_knotted_1998}, as well as the study of loop braid groups, as presented by Damiani \cite{damiani_journey_2017}.

The paper is organized as follows. In Section \ref{higherpathgroupoids}, we recall the definition of the path groupoid, the path~2-groupoid, and the path 3-groupoid of a smooth manifold.  In Section \ref{iteratedintegrals}, we recall the notion of iterated integral due to Chen \cite{chen1973}.  In Section \ref{formalpowerseriesconnections}, we define the notion of formal power series connection (compare to~\cite{chen1973, chen1977}). In Section \ref{higherholonomyfunctors}, we construct the holonomy functor, the holonomy~2-functor, and the holonomy~3-functor of a formal power series connection, and we prove Theorem \ref{maintheorem}. In Section~\ref{application}, we describe the holonomy 3-functor of a formal power series connection defined by Komendarczyk, Koytcheff and Voli\'c \cite{KKV} on the configuration space of $m$ points in $\R^n$ for $n\geqslant 4$.

Throughout this work, all vector spaces, algebras and coalgebras will be over the field $\R$. 

\section*{Acknowledgements}

\noindent I am extremely grateful to Toshitake Kohno for his guidance during my stay at the University of Tokyo, and for helping me discover the world of higher holonomy functors.

\section{Higher path groupoids}\label{higherpathgroupoids}

\noindent In this section, we follow the presentation given by Faria Martins and Picken \cite{faria_martins_fundamental_2011} of the path groupoid, the path 2-groupoid, and the path 3-groupoid of a smooth manifold. Similar definitions can be found in \cite{schreiber_parallel_2007, schreiber_smooth_2008, kohno2016higher,kohno2020higher,kohno2021higher, martins2010two}.

Throughout this section, we suppose $M$ is a smooth manifold (possibly with boundary).  

\subsection{Higher order paths}\label{n-paths}
An \emph{$n$-path}, for an integer $n\geqslant 0$, is a smooth map $\alpha\colon [0,1]^n\to M$ for which there exists an $\varepsilon > 0$ such that for all $i\in \{1, \ldots n\}$,
\begin{align*}
0\leqslant t_i \leqslant \varepsilon & \Rightarrow \alpha(t_1, \ldots , t_i, \ldots , t_n) = \alpha(t_1, \ldots,  0, \ldots , t_n),\\
1-\varepsilon \leqslant t_i \leqslant 1 &\Rightarrow \alpha(t_1, \ldots , t_i, \ldots, t_n) = \alpha(t_1, \ldots , 1, \ldots t_n), 
\end{align*}
and $\alpha([0,1]^{n-1}\times \{0\})$ and $\alpha([0,1]^{n-1}\times \{1\})$ both consist of a single point. In particular, a $0$-path is just a point.

An \emph{$n$-path from $f$ to $g$}, where $f$ and $g$ are $(n-1)$-paths, is an $n$-path $\alpha\colon [0,1]^{n}\to M$ such that
\begin{align*}
\alpha(0,-,\cdots, -) = f && \text{ and } &&
\alpha(1, -, \cdots , -) = g,
\end{align*}
where $\alpha(x,-,\cdots,-)$, for $x\in [0,1]$, denotes the $(n-1)$-path defined by
$$
\alpha(x,-,\cdots,-)(t_1, \ldots, t_{n-1}) = \alpha(x, t_1, \ldots, t_{n-1}),
$$
for all $(t_1, \ldots, t_{n-1})\in [0,1]^{n-1}$.

The \emph{composition of two 1-paths} $\gamma_1$ and $\gamma_2$ such that $\gamma_1(1) = \gamma_2(0)$ is the 1-path $\gamma_1 \circ \gamma_2$ defined by:
\begin{equation*}
\gamma_1\circ  \gamma_2(t) = 
\begin{cases}
\gamma_1(2t) & \text{if} \ 0 \leqslant t \leqslant \frac{1}{2},\\
\gamma_2(2t-1) & \text{if}\  \frac{1}{2}\leqslant t \leqslant 1.
\end{cases}
\end{equation*}

\subsection{Rank-1 homotopies}
A \emph{rank-1 homotopy} is a 2-path $h\colon [0,1]^2\to M$ such that for all $(s,t) \in [0,1]^2$,  the rank of its differential $d_{(s, t)}h$ is less than 2.  Two 1-paths $\gamma$ and $\gamma'$ are \emph{rank-1 homotopic} if there exists a rank-1 homotopy from $\gamma$ to $\gamma'$.

A \emph{$1$-track} $[\gamma]$ is the rank-1 homotopy class of a 1-path $\gamma$.  The \emph{composition $[\gamma_1]\circ [\gamma_2]$ of two 1-tracks}~$[\gamma_1]$ and $[\gamma_2]$ such that $\gamma_1(1) = \gamma_2(0)$ is the 1-track $[\gamma_1\circ \gamma_2]$.  Notice that the composition of two 1-tracks doesn't depend on the choice of representative 1-paths and that it is associative. Moreover, if we denote by $c_{x}$ the constant~1-path at a point $x\in M$, then for any 1-path $\gamma$,
\begin{align*}
[\gamma] \circ [c_{\gamma(1)}] = [\gamma] && \text{and} && [c_{\gamma(0)}] \circ [\gamma] = [\gamma].
\end{align*}

\subsection{Path groupoids}
The \emph{path groupoid} of $M$ is the category $\mathcal{P}_1(M)$ whose objects are given by the points of $M$ and whose morphisms are 1-tracks, with composition induced by the composition of 1-tracks.  Notice that every 1-track is invertible. 

\subsection{Vertical composition of 2-paths}\label{vertical composition}Let $g$ and $h$ be 2-paths such that $g(1, -) = h(0,-)$. The \emph{vertical composition} of $g$ and $h$ is the 2-path $g\cdot h$ defined by:
\begin{equation*}
(g\cdot h)(s,t) = 
\begin{cases}
g(2s,t) &\text{if}\ 0\leqslant s \leqslant \frac{1}{2} \ \text{and} \ 0\leqslant t \leqslant 1,\\
h(2s-1,t) &\text{if}\ \frac{1}{2}\leqslant s \leqslant 1 \ \text{and} \ 0\leqslant t \leqslant 1.
\end{cases}
\end{equation*}

\subsection{Horizontal composition of 2-paths}

Let $h_1$ and $h_2$ be 2-paths such that $$h_1([0,1]\times \{1\}) = h_2([0,1]\times \{0\}).$$ The \emph{horizontal composition} of $h_1$ and $h_2$ is the 2-path $h_1\circ h_2$ defined by:
\begin{equation*}
(h_1\circ h_2) (s,t) = 
\begin{cases}
h_1(s,2t) &\text{if}\ 0\leqslant s \leqslant 1 \ \text{and} \ 0\leqslant t \leqslant \frac{1}{2},\\
h_2(s,2t-1) &\text{if}\ 0\leqslant s \leqslant 1 \ \text{and} \ \frac{1}{2}\leqslant t \leqslant 1.
\end{cases}
\end{equation*}


\subsection{Rank-2 homotopies} A \emph{rank-2 homotopy} is a 3-path $\alpha\colon [0,1]^3\to M$ such that:
\begin{itemize}
\item for all $(r,s,t) \in [0,1]^3$, the rank of its differential $d_{(r,s,t)}\alpha$ is less than 3,
\item $\alpha(-,0,-)$ and $\alpha(-,1,-)$ are rank-1 homotopies.
\end{itemize}
Two 2-paths $g$ and $h$ are \emph{rank-2 homotopic} if there exists a rank-2 homotopy from $g$ to $h$.

A \emph{2-track} $[g]$ is the rank-2 homotopy class of a 2-path $g$. The \emph{vertical composition of~2-tracks} is induced by the vertical composition of 2-paths, and the \emph{horizontal composition of 2-tracks} is induced by the horizontal composition of 2-paths. Notice that these compositions are associative and satisfy the interchange law. 

\subsection{Path 2-groupoids} The \emph{path 2-groupoid of $M$} is the strict 2-category $\mathcal{P}_2 (M)$ defined as follows.  The objects of $\mathcal{P}_2 (M)$ are the points of $M$. The 1-morphisms of $\mathcal{P}_2 (M)$ are given by 1-tracks, with composition induced by the composition of 1-tracks.  A 2-morphism in $\mathcal{P}_2 (M)$ from $[\gamma]$ to $[\gamma']$ is given by a 2-track $[g]$ such that $[g(0, -,-)] = [\gamma]$ and $[g(1, -,-)] = [\gamma']$.  The identity of a 1-morphism $[\gamma]$ is given by the rank-2 homotopy class of the constant 2-path at $\gamma$.  The vertical and the horizontal composition of 2-morphisms are induced by the vertical and the horizontal composition of~2-paths, respectively. We refer the reader to \cite{martins2010two} for the details on the vertical and the horizontal composition of 2-morphisms. Notice that all 2-tracks are invertible.

\subsection{Laminated rank-2 homotopies}
We recall a stronger notion of rank-2 homotopy due to Faria Martins and Picken \cite{faria_martins_fundamental_2011}. A \emph{laminated rank-2 homotopy} is a rank-2 homotopy $\alpha$ such that for all~$(r,s) \in [0,1]^2$ at least one of the following conditions holds:
\begin{itemize}
\item for all $t\in [0,1]$, there exist constants $(a_t,b_t)\neq (0,0)$ such that 
$$
a_t\frac{\partial}{\partial r}\alpha(r,s,t) + b_t\frac{\partial}{\partial t}\alpha(r,s,t) = 0,
$$
\item for all $t\in [0,1]$, there exist constants $(a_t,b_t)\neq (0,0)$ such that 
$$
a_t\frac{\partial}{\partial s}\alpha(r,s,t) + b_t\frac{\partial}{\partial t}\alpha(r,s,t) = 0,
$$
\item there exist constants $(a,b) \neq (0,0)$ such that, for all $t\in [0,1]$,
\begin{equation*}
a\frac{\partial}{\partial r}\alpha(r,s,t) + b\frac{\partial}{\partial s}\alpha(r,s,t) = 0.
\end{equation*}
\end{itemize}
A \emph{laminated 2-track} $[g]$ is the laminated rank-2 homotopy class of a 2-path $g$. 

\subsection{Whiskering of 2-paths by 1-paths}
Let $\gamma$ be a 1-path and $g$ be a 2-path such that $$\gamma(1) = g([0,1]\times \{0\}).$$
The \emph{left whiskering of $g$ with $\gamma$} is the 2-path $\gamma\circ g$ given by:
\begin{equation*}
\gamma\circ g (s,t) = 
\begin{cases}
\gamma(2t) & \text{if } 0\leqslant t \leqslant \frac{1}{2} \text{ and } 0\leqslant s \leqslant 1,\\
g(2t-1, s) & \text{if } \frac{1}{2}\leqslant t \leqslant 1 \text{ and } 0\leqslant s \leqslant 1.
\end{cases}
\end{equation*}

Let $\gamma$ be a 1-path and $g$ be a 2-path such that $$g([0,1]\times \{1\}) = \gamma(0).$$
The \emph{right whiskering of $g$ with $\gamma$} is the 2-path $g\circ \gamma$ given by:
\begin{equation*}
g\circ \gamma (s,t) = 
\begin{cases}
g(2t, s) & \text{if } 0\leqslant t \leqslant \frac{1}{2} \text{ and } 0\leqslant s \leqslant 1,\\
\gamma(2t-1) & \text{if } \frac{1}{2}\leqslant t \leqslant 1 \text{ and } 0\leqslant s \leqslant 1.
\end{cases}
\end{equation*}
The \emph{left (respectively right) whiskering of a laminated 2-track with a 1-track} is the laminated rank-2 homotopy class of the left (respectively right) whiskering of a representative 2-path with a representative~1-path. Notice that this operation doesn't depend on the choice of representatives.

\subsection{Horizontal compositions of laminated 2-tracks}

The horizontal composition of 2-paths does not descend to the quotient by laminated rank-2 homotopy.  Therefore, we use whiskering to define two more notions of horizontal composition. 

Let $h_1$ and $h_2$ be 2-paths such that $$h_1([0,1]\times \{1\}) = h_2([0,1]\times \{0\}).$$ 
We denote by 
$\begin{pmatrix}
& h_2\\
h_1 & 
\end{pmatrix}$ the 2-path defined by $\begin{pmatrix}
& h_2\\
h_1 & 
\end{pmatrix} = (h_1\circ h_2(0,-))\cdot (h_1(1,-) \circ h_2)$. More explicitly:
\begin{equation*}
\begin{pmatrix}
& h_2\\
h_1 & 
\end{pmatrix} (s,t) = 
\begin{cases}
h_1(2s, 2t) & \text{if } 0\leqslant s \leqslant \frac{1}{2} \text{ and } 0\leqslant t \leqslant \frac{1}{2},\\
h_1(1, 2t) & \text{if } \frac{1}{2}\leqslant s \leqslant 1 \text{ and } 0\leqslant t \leqslant \frac{1}{2},\\
h_2(0, 2t-1) & \text{if } 0 \leqslant s \leqslant \frac{1}{2} \text{ and } \frac{1}{2}\leqslant t \leqslant 1,\\
h_2(2s-1, 2t-1) & \text{if } \frac{1}{2} \leqslant s \leqslant 1 \text{ and } \frac{1}{2}\leqslant t \leqslant 1.\\
\end{cases}
\end{equation*}
We denote by $\begin{pmatrix}
h_1 & \\
& h_2
\end{pmatrix}$ the 2-path defined by $\begin{pmatrix}
h_1 & \\
& h_2
\end{pmatrix} = (h_1(0,-)\circ h_2)\cdot (h_1\circ h_2(1,-))$. More explicitly:
\begin{equation*}
\begin{pmatrix}
h_1& \\
 & h_2
\end{pmatrix} (s,t) = 
\begin{cases}
h_1(0, 2t) & \text{if } 0\leqslant s \leqslant \frac{1}{2} \text{ and } 0\leqslant t \leqslant \frac{1}{2},\\
h_1(2s-1, 2t) & \text{if } \frac{1}{2}\leqslant s \leqslant 1 \text{ and } 0\leqslant t \leqslant \frac{1}{2},\\
h_2(2s, 2t-1) & \text{if } 0 \leqslant s \leqslant \frac{1}{2} \text{ and } \frac{1}{2}\leqslant t \leqslant 1,\\
h_2(1, 2t-1) & \text{if } \frac{1}{2} \leqslant s \leqslant 1 \text{ and } \frac{1}{2}\leqslant t \leqslant 1.\\
\end{cases}
\end{equation*}
These compositions induce compositions of laminated 2-tracks denoted by $\begin{pmatrix}
& [h_2]\\
[h_1] & 
\end{pmatrix}$ and
$\begin{pmatrix}
[h_1] & \\
& [h_2]
\end{pmatrix}$, respectively. 

\subsection{Upward composition of 3-paths}
Let $J$ and $K$ be 3-paths such that 
$$J(1,-,-) = K(0,-,-).$$  The \emph{upward composition} of $J$ and $K$ is the 3-path defined by:
\begin{equation*}
J*K (r,s,t) = 
\begin{cases}
J(2r,s,t) &\text{if } 0\leqslant r \leqslant \frac{1}{2}, \ 0\leqslant s \leqslant 1 \text{ and }0\leqslant t \leqslant 1,\\
K(2r-1, s,t) & \text{if }\frac{1}{2}\leqslant r \leqslant 1, \ 0\leqslant s \leqslant 1 \text{ and }0\leqslant t \leqslant 1.
\end{cases}
\end{equation*}

\subsection{Vertical composition of 3-paths}
Let $J$ and $K$ be 3-paths such that 
$$J(-,1,-) = K(-,0,-).$$ 
The \emph{vertical composition} of $J$ and $K$ is the 3-path defined by:
\begin{equation*}
J\cdot K (r,s,t) = 
\begin{cases}
J(r,2s,t) &\text{if } 0\leqslant r \leqslant 1, \ 0\leqslant s \leqslant \frac{1}{2} \text{ and }0\leqslant t \leqslant 1,\\
K(r, 2s-1,t) & \text{if }0\leqslant r \leqslant 1, \ \frac{1}{2}\leqslant s \leqslant 1 \text{ and }0\leqslant t \leqslant 1.
\end{cases}
\end{equation*}

\subsection{Rank-3 homotopies}
A \emph{good 3-path} is a 3-path $J\colon [0,1]^3 \to M$ such that 
\begin{itemize}
\item  for all $r, r'\in [0,1]$ and $t\in [0,1]$, $J(r,0,t) = J(r', 0,t)$,
\item for all $r, r'\in [0,1]$ and $t\in [0,1]$, $J(r,1,t) = J(r', 1,t)$.
\end{itemize} 
A \emph{rank-3 homotopy} is a 4-path $W \colon [0,1]^4\to M$ such that
\begin{itemize}
\item for all $(q,r,s,t) \in [0,1]^n$, the rank of $d_{(q,r,s,t)}W$ is less than 4,
\item the restrictions $W(-,0,-,-)$ and $W(-,1,-,-)$ are laminated rank-2 homotopies,
\item the restrictions $W(-,r,0,-)$ and $W(-,r,1,-)$ are independent of $r\in [0,1]$ and define rank-1 homotopies.
\end{itemize}
Two good 3-paths $J$ and $J'$ are \emph{rank-3 homotopic} if there exists a rank-3 homotopy from $J$ to $J'$.
A~\emph{3-track}~$[J]$ is the rank-3 homotopy class of a good 3-path $J$.

\subsection{Whiskering of 3-tracks by 1-tracks} Let $\gamma$ be a 1-path and let $J$ be a 3-path such that $$\gamma(1) = J([0,1]^2\times \{0\}).$$ The \emph{left whiskering of $J$ with $\gamma$} is the 3-path $\gamma\circ J$ defined by:
\begin{equation*}
\gamma\circ J (r,s,t) = 
\begin{cases}
\gamma(2t) & \text{if } 0\leqslant r \leqslant 1, \ 0\leqslant s\leqslant 1 \text{ and } 0\leqslant t \leqslant \frac{1}{2},\\
J(r,s,2t-1) & \text{if }0\leqslant r \leqslant 1, \ 0\leqslant s\leqslant 1 \text{ and } \frac{1}{2}\leqslant t \leqslant 1.
\end{cases}
\end{equation*}

Let $\gamma$ be a 1-path and let $J$ be a 3-path such that $$J([0,1]^2\times \{1\}) = \gamma(0).$$
The \emph{right whiskering of $J$ with $\gamma$} is the 3-path $J\circ \gamma$ defined by:
\begin{equation*}
J\circ \gamma (r,s,t) = 
\begin{cases}
J(r,s,2t) & \text{if } 0\leqslant r \leqslant 1, \ 0\leqslant s\leqslant 1 \text{ and } 0\leqslant t \leqslant \frac{1}{2},\\
\gamma(2t-1) & \text{if }0\leqslant r \leqslant 1, \ 0\leqslant s\leqslant 1 \text{ and } \frac{1}{2}\leqslant t \leqslant 1.
\end{cases}
\end{equation*}

The \emph{left (respectively right) whiskering of a 3-track with a 1-track} is the rank-3 homotopy class of the left (respectively right) whiskering of a representative good 3-path with a representative 1-path. Notice that this operation doesn't depend on the choice of representatives.

\subsection{Path 3-groupoids}

The \emph{path 3-groupoid of $M$} (or the \emph{fundamental Gray 3-groupoid of $M$}) is the Gray 3-groupoid $\mathcal{P}_3(M)$ defined as follows. The objects of $\mathcal{P}_3(M)$ are the points of $M$.  The 1-morphisms of $\mathcal{P}_3(M)$ are given by 1-tracks, with composition induced by the composition of 1-tracks.  A~2-morphism in $\mathcal{P}_3(M)$ from $[\gamma]$ to $[\gamma']$ is given by a laminated 2-track $[g]$ such that $[g(0,-,-)] = [\gamma]$ \break and $[g(1,-,-)] = [\gamma']$. The vertical composition and the horizontal compositions of 2-morphisms are induced by the vertical composition and the horizontal compositions of 2-paths, respectively. A~3-mor\-phism in $\mathcal{P}_3(M)$ from $[g]$ to $[h]$ is given by a 3-track $[J]$ such that $[J(0,-,-)] = [g]$ and $[J(1,-,-)] = [h]$. The upward composition, the vertical composition and the horizontal compositions of 3-morphisms are induced by the upward composition, the vertical composition and the horizontal compositions of 3-paths, respectively.  We refer the reader to \cite{faria_martins_fundamental_2011} for more details on $\mathcal{P}_3(M)$ and for the proof that it is a Gray 3-groupoid. 

\section{Iterated integrals}\label{iteratedintegrals}
\noindent In this section, we recall the notion of differential form on a differentiable space,  and we describe a certain class of differential forms on path spaces called iterated integrals.  We refer the reader to \cite{chen1973, chen1977} for more details.

\subsection{Differentiable spaces and differentiable maps}
A \emph{convex $n$-region} (or simply a \emph{convex region}) is a closed convex subset of~$\R^n$, for some $n \geqslant 0$.  A map $f$ from a convex $n$-region $U$ to a convex region~$V$ is \emph{smooth} if there exists a smooth extension of $f$ to an open subset of $\mathbb{R}^n$.  A \emph{differentiable space} is a Hausdorff space $X$ equipped with a family of maps, called \emph{plots}, satisfying the following conditions:
\begin{itemize}
\item every plot is a continuous map $\phi : U \to X$, where $U$ is a convex region,
\item if $\phi : U \to X$ is a plot,  $U'$ is a convex region, and $f : U' \to U$ is a smooth map, then $\phi \circ f$ is a plot,
\item every map $\{0\} \to X$ is a plot.
\end{itemize}
We say that a plot $\psi$ with domain $V$ \emph{goes through} another plot $\phi$ with domain $U$ via $f$ if there exists a smooth map $f : V \to U$ such that $\psi = \phi\circ f$. Let $X$ and $X'$ be differentiable spaces. A \emph{differentiable map} from $X$ to $X'$ is a continuous map $f : X \to X'$ such that, for every plot $\phi$ of $X$, $f\circ \phi$ is a plot of $X'$.


The notion of differentiable space is weaker than that of smooth manifold and will help us avoid certain limitations associated to smooth manifolds.  In particular, smooth manifolds are differentiable spaces with plots given by smooth maps $\phi : U \to M$ where $U$ is a convex region. 


\subsection{Differential forms on differentiable spaces}
For any $p\geqslant 0$, a \emph{differential $p$-form} on a differentiable space $X$ is a rule that assigns to each plot $\phi : U \to X $ a differential $p$-form $\omega_\phi \in C_{dR}^p(U)$ such that, if $\psi$ is a plot that goes through $\phi$ via $f$, then:
\begin{equation*}
f^*\omega_\psi = \omega_\phi.
\end{equation*}
A \emph{differential form} on $X$ is a differential $p$-form for some $p$ called its \emph{degree}. The set of differential $p$-forms on a differentiable space $X$ is denoted by $C_{dR}^p(X)$. The differential forms on a differentiable space $X$ define a commutative differential graded algebra $C_{dR}^*(X) = \bigoplus_{p\geqslant 0}C_{dR}^p(X)$ whose sum, exterior product and exterior derivative are given by:
\begin{align*}
(\omega + \omega')_\phi &= \omega_\phi + \omega'_\phi,\\
(\omega \wedge \omega')_\phi &= \omega_\phi \wedge \omega_\phi,\\
(d\omega)_\phi &= d\omega_\phi,
\end{align*}
for any plot $\phi\colon U \to X$. 

\subsection{Pointed path spaces}
The \emph{pointed path space} of a smooth manifold $M$ is the set $P(M;x_0,x_1)$ of~1-paths in $M$ from~$x_0$ to $x_1$ (see Section \ref{n-paths}) with the compact-open topology, where $x_0$ and $x_1$ are points of~$M$.  The pointed path space of $M$ is a differentiable space when equipped with the following plots. A plot of~$P(M;x_0,x_1)$ is a continuous map $\phi : U \to P(M;x_0,x_1)$, such that the adjoint map~$\widetilde{\phi} : U \times [0,1] \to M$ is smooth.

\subsection{Iterated integrals on paths spaces}

Let $\omega_1, \ldots, \omega_k$ be differential forms of positive degree on a smooth manifold $M$.  Let $\phi : U \to P(M;x_0,x_1)$ be a plot of $P(M;x_0,x_1)$,  where $x_0$ and $x_1$ are points of~$M$,  and let $\Delta^k$ denote the $k$-simplex given by:
\begin{equation*}
\Delta^k = \{(t_1, \ldots, t_k)\in \mathbb{R}^k \mid 0\leqslant t_1\leqslant \cdots \leqslant t_k\leqslant 1\}.
\end{equation*}
The plot $\phi$ induces a smooth map $\widetilde{\phi} :  \Delta^k\times U \to M^k$ defined by:
\begin{equation*}
\widetilde{\phi}(t_1, \ldots, t_k, x) = \left(\phi(x)(t_1), \ldots,\phi(x)(t_k)\right),
\end{equation*}
for all $((t_1, \ldots, t_k),x)\in \Delta^k\times U$.

We denote by $\pi_i : M^k \to M$ the projection onto the $i$-th factor for any smooth manifold $M$. The \emph{iterated integral} of differential forms $\omega_1, \ldots, \omega_k$ of positive degree on $M$ is the diffe\-rential form~$\displaystyle \int \omega_1 \ldots \omega_k$ on the differen\-tiable space $P(M;x_0,x_1)$ defined by:
\begin{equation*}
\left(\int \omega_1 \ldots \omega_k\right)_{\!\phi} = \int_{\Delta^k}\widetilde{\phi}^*(\pi_1^*\omega_1\wedge \cdots \wedge \pi_k^*\omega_k),
\end{equation*}
for any plot $\phi : U \to P(M;x_0,x_1)$, where $\displaystyle \int_{\Delta^k}$ denotes integration along the fiber of $\Delta^k\times U \to U$. Linear combinations of iterated integrals will also be called iterated integrals.  The iterated integral $$\int \omega_1 \ldots \omega_k$$ is a differential form of degree $\deg(\omega_1) + \cdots + \deg(\omega_k) - k$, where $\mathrm{deg}(\omega_i)$ denotes the degree of $\omega_i$ for \break all $i \in \{1,\ldots , k\}$.

We recall a useful formula:
\begin{lem}[see \cite{kohno2016higher}]\label{lem21}
Let $\omega_1, \ldots \omega_k$ be differential forms of positive degree on a smooth mani\-fold~$M$. On the pointed path space~$P(M; x_0, x_1)$, we have:
\begin{align*}
d \int \omega_1\ldots \omega_k = &\sum\limits_{i=1}^k (-1)^{\nu_{i-1} +1}\int \omega_1\ldots \omega_{i-1}\, d\omega_i\, \omega_{i+1} \ldots \omega_k \\
&+ \sum\limits_{i=1}^{k-1}(-1)^{\nu_i +1}\int \omega_1\ldots \omega_{i-1}(\omega_i\wedge \omega_{i+1}) \omega_{i+2}\ldots \omega_k ,
\end{align*}
where $\nu_i = \deg(\omega_1) +\cdots + \deg(\omega_i) - i$.
\end{lem}

\subsection{The bar complex}\label{barcomplex}

Let $M$ be a smooth manifold and let $x_0$ and $x_1$ be points of $M$.  The \emph{bar complex of ite\-rated integrals on $M$} (or simply the \emph{bar complex on $M$}) is the sub\-complex~$B^*(M)$ of the complex~$C^*_{dR}(P(M; x_0,x_1))$ of differential forms on the pointed path space of $M$ such that for all $q\geqslant 0$, the vector space $B^q(M)$ is the sum of the images of the multilinear maps 
$$
\int \colon C_{dR}^{p_1}(M)\otimes \cdots \otimes C_{dR}^{p_k}(M) \to C_{dR}^q(P(M; x_0,x_1)) 
$$
defined by the iterated integrals, where the sum is taken over all positive integers $k, p_1, \ldots, p_k$ such that~$p_1+ \cdots + p_k - k = q$.  As a consequence of Lemma \ref{lem21}, we have that $d \left(B^q(M)\right) \subset B^{q+1}(M)$. 

A nonzero element of $B^*(M)$ is \emph{homogeneous of length $k$}, for some $k\geqslant 0$,  if it is the sum of iterated integrals of the form:
$$ \int \omega_1 \cdots \omega_k. $$


%For $k\geqslant 0$, we denote by $F_k\left(B^*(M)\right)$ the subspace of $B^*(M)$ generated by the iterated integrals of the form
%$$ \int \omega_1 \cdots \omega_l,\ \text{ for some } l\geqslant k, $$
%where $\omega_1, \ldots , \omega_l$ are differential forms of positive degree on $M$.  Notice that $d\left( F_k\left(B^*(M)\right)\right) \subset F_k\left(B^*(M)\right)$. There is a descending filtration of complexes:
%$$ B^*(M) = F_0\left(B^*(M)\right)\supset F_1\left(B^*(M)\right) \supset F_2\left(B^*(M)\right) \supset \cdots$$ 
%Denote by $\widehat{B^*(M)}$ the completion of the bar complex $B^*(M)$ with respect to this filtration, \emph{i.e.}
%$$
%\widehat{B^*(M)} = \Bigl\{ (a_k)_{k\geqslant 0} \in \prod\limits_{k\geqslant 0}\left(B^*(M)/F_k\left(B^*(M)\right)\right) \Bigm| a_i = a_j \left(\mathrm{mod}\  F_k\left(B^*(M)\right)\right) \text{ for all }i\leqslant j \Bigr\} .
%$$

\subsection{The integration of iterated integrals over bounded plots}\label{integrationiteratedintegrals}

A \emph{bounded} plot of a differentiable space is a plot with bounded domain.  Let $\omega_1, \ldots , \omega_k$ be differential forms of positive degree on a smooth manifold $M$, and let $\phi$ be a bounded plot of $P(M; x_0, x_1)$ with domain $U$. Then the \emph{integration of~$\displaystyle \int \omega_1\ldots \omega_k$ over $\phi$}, denoted by~$\displaystyle \langle \int \omega_1\ldots \omega_k, \phi \rangle$, is defined by the following equation:
\begin{equation*}
\langle \int \omega_1\ldots \omega_k, \phi \rangle =
\begin{cases}\displaystyle
 \int_U \left(\int \omega_1\ldots \omega_k\right)_{\! \phi} & \text{if $\mathrm{deg}(\omega_1) + \cdots + \mathrm{deg}(\omega_k) - k = \dim U$,}\\
 0 & \text{otherwise.}
\end{cases}
\end{equation*}
Note that for $k = 1$, we get the integral:
\begin{equation*}
\langle \int \omega_1, \phi \rangle = \int_{[0,1]\times U}\widetilde{\phi}^*\omega_1,
\end{equation*}
where $\widetilde{\phi}$ is the adjoint map to the plot $\phi$.  In particular, if $U = *$, then the above is simply the integration of a differential form on $M$ along a path. 

For $k = 0$,  we set:
\begin{equation*}
\langle \int \omega_1\ldots \omega_k, \phi \rangle = \delta_0^{\dim U}.
\end{equation*}

For any bounded plot $\phi \colon U \to P(M; x_0,x_1)$, taking the integration over $\phi$ defines a linear map 
$$
\langle\,  \cdot\, , \phi\rangle \colon B^*(M) \to \R.
$$

\section{Formal power series connections}\label{formalpowerseriesconnections}

\noindent In this section, we build on Chen's theory of formal power series connections \cite{chen1973, chen1977} and its formulation by Kohno~\cite{kohno2016higher, kohno2020higher, Koh2022}.  We recall the definition of the cobar complex of a coaugmented differential graded coalgebra, the definition of a formal power series connection, and the definition of its transport.  We then recall a result of Chen that relates the transport of a formal power series connection to the homology of the loop space of a simply connection manifold.

Throughout this section, $C$ denotes a coaugmented differential graded coalgebra. 


\subsection{The cobar complex}
The \emph{free augmented algebra} on a graded vector space $V$ is the algebra $TV$ given by
\begin{equation*}
TV = \R \oplus V \oplus \left(V\otimes V\right) \oplus \left(V\otimes V \otimes V\right) \oplus \cdots
\end{equation*}
with multiplication given by concatenation.  The \emph{desuspension} of a graded vector space $V = \bigoplus_{n\geqslant 1} V_n$ is the graded vector space $s^{-1}V$ given by $(s^{-1}V)_n = V_{n+1}$. The element of $s^{-1}V$ corresponding to $v\in V$ is denoted by $s^{-1}v$.  

Let $\eta\colon \R \to C$ denote the coaugmentation of the coalgebra $C$, and let $\partial$ denote its differential. We suppose $\partial$ is of degree $-1$.  The \emph{coaugmentation coideal of $C$} is $\bar{C} = \mathrm{coker}(\eta)$.  The \emph{reduced coproduct $\bar{\Delta}$ of $C$} is the composite $\bar{\Delta} = (q\otimes q )\circ \Delta\colon C \to \bar{C}\otimes \bar{C}$, where $\Delta$ denotes the coproduct of $C$ and $q\colon C\to \bar{C}$ denotes the quotient map. The \emph{cobar complex} of a coaugmented differential graded coalgebra $C$ is the differential graded algebra $\Omega (C) = (T(s^{-1}C), d_\Omega)$ with differential $d_\Omega$ defined by
\begin{equation*}
d_\Omega (s^{-1}c) = -s^{-1}\partial c + \sum(-1)^{\mathrm{deg}(c_{(1)})}s^{-1}c_{(1)}\otimes s^{-1}c_{(2)},
\end{equation*}
where $\bar{\Delta}(c) = \sum c_{(1)}\otimes c_{(2)}$.  We denote by $\Omega^n(C)$, for some $n\geqslant 0$, the subspace of $\Omega(C)$ generated by homogeneous elements of degree $n$.  Notice that the differential $d_\Omega$ lowers the degree by 1. 

An element $x \in \Omega(C)$ is \emph{homogeneous of length $k$}, for some integer $k\geqslant 1$,  if there exist elements~$c_1, \ldots c_k \in C$ such that 
$$
x = s^{-1}c_1\otimes \cdots \otimes s^{-1}c_k.
$$
In that case, we write 
$$
x = [c_1\vert \cdots \vert c_k].
$$
By convention, an element $x\in \Omega(C)$ is \emph{homogenenous of length $0$} if $x\in \R$. 
For any $k\geqslant 0$, we denote by~$F_k(\Omega(C))$ the subspace of $\Omega(C)$ generated by homogeneous elements of length at least ~$k$. Notice that~$d\left(F_k(\Omega(C))\right) \subset F_k(\Omega(C))$.  There is a descending filtration of complexes:
\begin{equation*}
\Omega(C) = F_0(\Omega(C)) \supset F_1(\Omega(C)) \supset F_2(\Omega(C)) \supset \cdots
\end{equation*}
Denote by $\widehat{\Omega(C)}$ the completion of the cobar complex $\Omega(C)$ with respect to this filtration, \emph{i.e.}
$$
\widehat{\Omega(C)} = \Bigl\{ (c_k)_{k\geqslant 0} \in \prod\limits_{k\geqslant 0}\left(\Omega(C)/F_k\left(\Omega(C)\right)\right) \Bigm| c_i = c_j \left(\mathrm{mod}\  F_k\left(\Omega(C)\right)\right) \text{ for all }i\leqslant j \Bigr\} .
$$

For any $n\geqslant 0$, we denote by $\widehat{\Omega^n(C)}$ the subspace of $\widehat{\Omega(C)}$ generated by homogeneous elements of degree $n$.  $\widehat{\Omega(C)}$ is a differential graded algebra. In particular, for any nonnegative integers $i$ and $j$, the product induces an inclusion of subspaces: $$\widehat{\Omega^i(C)} \otimes \widehat{\Omega^j(C)} \subset \widehat{\Omega^{i+j}(C)}.$$
Notice that $\widehat{\Omega^0(C)}$ is a subalgebra of $\widehat{\Omega(C)}$.

\subsection{Formal power series connections}

Let $(C_{dR}^*(M), d)$ denote the differential graded algebra of differential forms on a smooth manifold $M$. The \emph{completed tensor product of $C_{dR}^*(M)$ and $\Omega(C)$}, where~$\Omega(C)$ is the cobar complex of $C$, is the algebra $C_{dR}^*(M)\, \widehat{\otimes}\, \Omega(C)$ whose elements are formal sums $\sum_{i\geqslant 0}\omega_i \otimes c_i$ with homogeneous $\omega_i \in C_{dR}^*(M)$ and $c_i \in \Omega(C)$, such that for each $n\geqslant 0$, there is only a finite number of terms $\omega_i \otimes c_i$ verifying $\mathrm{deg}(\omega_i) + \mathrm{deg}(c_i) = n$. The product of two elements $\sum_{i\geqslant 0}\omega_i \otimes c_i$ and $\sum_{j\geqslant 0}\psi_j\otimes d_j$ of $C_{dR}^*(M)\,  \widehat{\otimes}\,  \Omega(C)$ is defined by:
\begin{equation*}
(\sum_{i\geqslant 0}\omega_i \otimes c_i) \wedge (\sum_{j\geqslant 0}\psi_j\otimes d_j) = \sum_{i,j \geqslant 0}\omega_i\wedge \psi_j \otimes c_i d_j,
\end{equation*}
which gives $C_{dR}^*(M)\, \widehat{\otimes}\, \Omega(C)$ the structure of an algebra with unit $1 = 1\otimes 1$.
We extend $d$ and $d_\Omega$ to~$C_{dR}^*(M)\, \widehat{\otimes}\, \Omega(C)$ via:
\begin{align*}
d\left(\sum_{i\geqslant 0}\omega_i \otimes c_i \right) &= \sum_{i\geqslant 0}d\omega_i \otimes c_i,\\
d_\Omega\left(\sum_{i\geqslant 0}\omega_i \otimes c_i\right) &= \sum_{i\geqslant 0}\omega_i \otimes d_\Omega c_i.
\end{align*}
Let $\varepsilon : C_{dR}^*(M) \to C_{dR}^*(M)$ denote the automorphism given by $\varepsilon (\omega) = (-1)^{\mathrm{deg}(\omega)}\omega$ for any homogeneous element $\omega \in C_{dR}^*(M)$. We extend $\varepsilon$ to $C_{dR}^*(M)\,  \widehat{\otimes}\, \Omega(C)$ via:
\begin{equation*}
\varepsilon\left(\sum_{i\geqslant 0}\omega_i \otimes c_i\right) = \sum_{i\geqslant 0}\varepsilon(\omega_i) \otimes c_i.
\end{equation*}
A \emph{formal power series connection} on $M$ is an element $\displaystyle \omega = \sum_{i\geqslant 0}\omega_i \otimes c_i \in C_{dR}^*(M)\, \widehat{\otimes}\, \Omega(C)$ such that:
\begin{itemize}
\item for all $i \geqslant 0$,  $\mathrm{deg}(\omega_i) = \mathrm{deg}(c_i),$
\item the \emph{twisted cochain condition} is verified: $d_\Omega \omega + d \omega = \varepsilon(\omega) \wedge \omega$.
\end{itemize}

\subsection{The transport of a formal power series connection}\label{transport} Let $\Omega(C)$ denote the cobar complex of~$C$, and let $B^*(M)$ denote the bar complex of iterated integrals on a smooth manifold $M$.  A nonzero element $\sum_{i\geqslant 0}b_i\otimes c_i \in B^*(M)\, \widehat{\otimes}\, \Omega(C)$ is \emph{homogeneous of length~$k$}, for some $k\geqslant 1$, if for all $i\geqslant 0$ the element $b_i$ is homogeneous of length~$k$ (see Section~\ref{barcomplex}).  For all $k\geqslant 1$, let~$F_k$ denote the vector subspace of $B^*(M)\, \widehat{\otimes}\, \Omega(C)$ generated by homogeneous elements of length at least $k$. This defines a descending filtration of vector subspaces:
$$ 
B^*(M)\, \widehat{\otimes}\, \Omega(C) = F_1 \supset F_2 \supset F_3 \supset \cdots
$$
Denote by $\widehat{B^*(M)\, \widehat{\otimes}\, \Omega(C)}$ the completion of $B^*(M)\, \widehat{\otimes}\, \Omega(C)$ with respect to this filtration. 


The \emph{transport} $T_\omega$ of a formal power series connection $\omega = \sum_{i\geqslant 0}\omega_i \otimes c_i \in C^*_{dR}(M)\, \widehat{\otimes}\, \Omega(C)$ is the element:
$$T_\omega =  1 + \sum_{k\geqslant 1} \sum_{i_1, \ldots i_k \geqslant 0}\int \omega_{i_1}\ldots \omega_{i_k} \otimes c_{i_1}\cdots c_{i_k} \in \widehat{B^*(M)\, \widehat{\otimes}\, \Omega(C)}.
$$
Notice that if $\mathrm{deg}(\omega_i) \geqslant 2$ for all $i\geqslant 0$, then $T_\omega \in B^*(M)\, \widehat{\otimes}\, \Omega(C)$.  For any bounded plot $\phi$ of the pointed path space of $M$,  the integration of iterated integrals (see Section \ref{integrationiteratedintegrals}) extends to define an element
$$
\langle T_\omega, \phi\rangle = \sum_{k\geqslant 0} \sum_{i_1, \ldots i_k \geqslant 0}\langle \int \omega_{i_1}\ldots \omega_{i_k}, \phi \rangle\,  c_{i_1}\cdots c_{i_k} \in \widehat{\Omega(C)}.
$$

\subsection{The homology of loop spaces}
In \cite{chen1977}, Chen uses the transport of a formal power series connection to study the homology of the loop space of a simply connected manifold $M$.  He sets 
$$ \omega = \sum\limits_{i\geqslant 0}\omega_i \otimes c_i \in C^*_{dR}(M)\otimes \Omega(H_{\geqslant 1}(M; \R)),
$$
where $H_{\geqslant 1}(M; \R) = \bigoplus_{k\geqslant 1} H_k(M;\R)$ is the graded vector space defined by the positive degree part of the singular homology of $M$ with real coefficients, $(c_i)_i$ is a basis of $H_{\geqslant 1}(M;\R)$, and $(\omega_i)_i$ are closed forms representing cohomology classes dual to $(c_i)_i$. He shows the existence of a derivation $\partial$ on $\Omega(H_*(M;\R))$ such that:
\begin{thm}[\cite{chen1977}]
There is an isomorphism $H_{*}(\Omega M; \R) \cong H_{*}(\Omega(H_{\geqslant 1}(M; \R)), \partial)$ induced by the map
$$ 
\begin{array}{ccl}
C_*(\Omega M; \R) & \to & \Omega(H_{\geqslant 1}(M; \R))\\
 c & \mapsto & \langle T_\omega, c\rangle,
\end{array}
$$
where $\langle T_\omega, c\rangle$ denotes the integration of the transport $T_\omega$ over $c$. 
\end{thm}

\section{Higher holonomy functors}\label{higherholonomyfunctors}

\noindent In this section, we show how the transport of a formal power series connection induces functors from the path groupoid, the path 2-groupoid, and the path 3-groupoid of a manifold.  

Throughout this section, we fix $\omega \in C_{dR}^*(M) \, \widehat{\otimes }\, \Omega(C)$ a formal power series connection on a manifold~$M$, with $\Omega(C)$ the cobar complex of a coaugmented differential graded coalgebra $C$ (see Section \ref{formalpowerseriesconnections}).  We denote by~$T_\omega$ the transport of $\omega$.

\subsection{Holonomy functors}

Let $\omega_1, \ldots , \omega_k$ be differential forms on $M$.  Kohno shows \cite{kohno2016higher} that if $\gamma$ and $\gamma'$ are rank-1 homotopic 1-paths, then:
\begin{equation*}
\langle \int \omega_1 \ldots  \omega_k, \gamma\rangle  = \langle \int  \omega_1 \ldots \omega_k, \gamma' \rangle,
\end{equation*}
where $\langle \cdot, \cdot\rangle$ denotes the integration of iterated integrals over bounded plots (see Section \ref{iteratedintegrals}).
Moreover, the composition of 1-tracks is compatible with integration: if $\gamma$ and $\delta$ are 1-tracks such that $\gamma(1) = \delta(0)$, then
$$
\langle T_\omega, \gamma\circ \delta \rangle = \langle T_\omega, \gamma\rangle \langle T_\omega, \delta\rangle.
$$

Recall the algebra $\widehat{\Omega^0(C)}$ generated by the homogeneous elements of degree 0 in the completion of the cobar complex of $C$ (see Section \ref{formalpowerseriesconnections}). We define the category $\mathcal{C}_1(C)$ by the following data:
\begin{itemize}
\item the category $\mathcal{C}_1(C)$ has a single object $*$,
\item an endomorphism of $*$ in $\mathcal{C}_1(C)$ is an element of $\widehat{\Omega^0(C)}$ with composition given by the product in $\widehat{\Omega^0(C)}$.
\end{itemize}

The \emph{holonomy functor of $\omega$} is the functor
$$
\mathrm{Hol}^1_\omega \colon \mathcal{P}_1(M) \to \mathcal{C}_1(C)
$$
defined by
$$ \mathrm{Hol}^1_\omega ([\gamma]) = \langle T_\omega, \gamma\rangle,$$
for any 1-track $[\gamma]$.

\subsection{Integration over 2-tracks}

In this section, we extend the notion of integration over 2-paths to that of integration over 2-tracks.  Moreover, we show that the integration of the transport $T_\omega$ of a formal power series connection $\omega$ over a 2-track is compatible with the vertical and the horizontal composition.

\begin{lem}\label{lem2tracks}
If $g$ and $h$ are rank-2 homotopic 2-paths in $M$, then
$$ \langle T_\omega, g\rangle - \langle T_\omega, h\rangle \in d_\Omega\left( \widehat{\Omega^1(C)} \otimes \widehat{\Omega^1(C)}\right). $$
\end{lem}
\begin{proof}
Let $g-h = \partial H$ with $H$ a rank-2 homotopy.
\begin{align*}
\langle T_\omega, g\rangle - \langle T_\omega, h\rangle 
= \langle T_\omega, \partial H\rangle 
= \langle  dT_\omega, H\rangle
= d_\Omega \langle T_\omega, H\rangle,
\end{align*}
where the second equality is a consequence of Stokes' theorem, and the third equality is a consequence of the twisted cochain condition. Since $H$ is rank-2, $\langle T_\omega, H\rangle \in \widehat{\Omega^1(C)} \otimes \widehat{\Omega^1(C)}$.
\end{proof}


\begin{rem*}Contrary to \cite[Proposition 3.4]{Koh2022}, we find that if $g$ and $h$ are rank-2 homotopic 2-paths and~$\omega_1, \ldots, \omega_k$ are differential forms of degree $\deg(\omega_1), \ldots, \deg(\omega_k)$, respectively, then we don't necessarily have
$$
\langle \int \omega_1\ldots\omega_k , g\rangle = \langle \int \omega_1\ldots\omega_k , h\rangle.
$$
Indeed, we need a stronger condition: that $g$ and $h$ are laminated rank-2 homotopic (see Lemma \ref{lemlam2tracks}). 
\end{rem*}

The vertical composition of 2-paths is compatible with integration:
\begin{lem}\label{lemvert2tracks}
If $g$ and $h$ are 2-paths such that $g(1,-) = h(0,-)$, then
$$ 
\langle T_\omega,  g \cdot h\rangle = \langle T_\omega, g\rangle + \langle T_\omega, h\rangle.
$$
\end{lem}
\begin{proof}
For any differential forms $\omega_1, \ldots \omega_k$ of positive degree such that $\deg(\omega_1) + \cdots +\deg(\omega_k) -k = 1$, we have: 
\begin{align*}
\langle \int \omega_1 \ldots \omega_k ,  g\cdot h\rangle 
&= \int_{[0,\frac{1}{2}]}\int_{\Delta^k}\widetilde{g\cdot h}^*(\omega_1\times \cdots \times \omega_k) + \int_{[\frac{1}{2},1]}\int_{\Delta^k}\widetilde{g\cdot h}^*(\omega_1\times \cdots \times \omega_k),\\
&= \int_{[0,1]}\int_{\Delta^k}\widetilde{g}^*(\omega_1\times \cdots \times \omega_k) + \int_{[0,1]}\int_{\Delta^k}\widetilde{h}^*(\omega_1\times \cdots \times \omega_k),\\
&= \langle \int \omega_1 \ldots \omega_k ,  g\rangle + \langle \int \omega_1 \ldots \omega_k ,  g\rangle. \qedhere
\end{align*}
\end{proof}
We have the following formulas for the horizontal composition of 2-paths.
\begin{lem}\label{lemhoriz2tracks}
If $g$ and $h$ are 2-paths such that $g(-, 1) = h(-,0)$, then the following equations hold in the quotient space $ \widehat{\Omega^1(C)}/ d_\Omega\left( \widehat{\Omega^1(C)} \otimes \widehat{\Omega^1(C)}\right)$:
\begin{align*}
\langle T_\omega, g\circ h\rangle &= \langle T_\omega, g\rangle \langle T_\omega,  h(0,-) \rangle + \langle T_\omega, g(1,-) \rangle \langle T_\omega, h\rangle,\\
&= \langle T_\omega, g(0,-)\rangle \langle T_\omega, h\rangle + \langle T_\omega, g\rangle \langle T_\omega, h(1,-)\rangle. 
\end{align*}
\end{lem}
\begin{proof}
Note that $g\circ h$ is rank-2 homotopic to $(g\circ c_{h(0,-)}) \cdot (c_{g(1,-)}\circ h)$ and to $(c_{g(0,-)}\circ h) \cdot (g \circ c_{h(1,-)})$.  Therefore, the equations result from Lemma \ref{lem2tracks}, Lemma \ref{lemvert2tracks} and  \cite[Proposition 2.1.1]{chen1973}.
\end{proof}

\subsection{The target 2-category}

Recall that $\widehat{\Omega(C)}$ denotes the completion of the cobar complex of~$C$, and that~$\widehat{\Omega^i(C)}$ is the vector subspace generated by homogeneous elements of degree $i$ (see Section \ref{formalpowerseriesconnections}). We define the strict 2-category $\mathcal{C}_2(C)$ by the following data:
\begin{itemize}
\item the 2-category $\mathcal{C}_2(C)$ has a single object $*$,
\item an endomorphism of $*$ in $\mathcal{C}_2(C)$ is an element of $\widehat{\Omega^0(C)}$, with composition given by the product in $\widehat{\Omega^0(C)}$,
\item for 1-morphisms $m$ and $n$ of $\mathcal{C}_2(C)$,  a 2-morphism from $m$ to $n$ is an element of the set
$$\mathcal{C}_2(C)(m,n) = \left\lbrace M \in \widehat{\Omega^1(C)}/d_\Omega\left( \widehat{\Omega^1(C)}\otimes \widehat{\Omega^1(C)} \right) \mid d_\Omega M = m - n \right\rbrace,$$
\item the vertical composition of 2-morphisms is given by
\[
\begin{array}{ccl}
\mathcal{C}_2(C)(m,n)\times \mathcal{C}_2(C)(n,p) & \to & \mathcal{C}_2(C)(m,p)\\
(M, N) & \mapsto & M+ N,
\end{array}
\]
\item the horizontal composition of 2-morphisms is given by
\[
\begin{array}{ccl}
\mathcal{C}_2(C)(m,n)\times \mathcal{C}_2(C)(p,q) & \to & \mathcal{C}_2(C)(m p,n q)\\
(M,N) & \mapsto & Mp + nN = mN + Mq.
\end{array}
\]
\end{itemize}
It is a straightforward verification that $\mathcal{C}_2(C)$ is a strict 2-category. 

\subsection{Holonomy 2-functors}

Recall from Section \ref{formalpowerseriesconnections} the transport $T_\omega$ of the formal power series connection $\omega$, and from Section \ref{iteratedintegrals} the integration $\langle \cdot, \cdot\rangle$ of iterated integrals over bounded plots.  

Let's define the association $\mathrm{Hol}^2_\omega$. For any 1-track $[\gamma]$,  we set
$$ \mathrm{Hol}^2_\omega ([\gamma]) = \langle T_\omega , \gamma\rangle.$$
For any 2-track $[g]$, we set
$$ \mathrm{Hol}^2_\omega ([g]) = [\langle T_\omega, g\rangle ],$$
where $[\langle T_\omega, g\rangle ]$ denotes the class of $\langle T_\omega, g\rangle$ in $ \widehat{\Omega^1(C)}/ d_\Omega\left( \widehat{\Omega^1(C)} \otimes \widehat{\Omega^1(C)}\right)$.
We deduce from Lemma \ref{lem2tracks} that the above association is well defined. 

From Lemmas \ref{lemvert2tracks} and \ref{lemhoriz2tracks}, we deduce  that the association~$\mathrm{Hol}^2_\omega$ is compatible the vertical and horizontal composition of 2-tracks:
\begin{thm}\label{thm2holonomy}
The transport of the formal power series connection $\omega$ induces a 2-functor:
$$ \mathrm{Hol}^2_\omega \colon \mathcal{P}_2(M) \to \mathcal{C}_2(C)$$ 
called the \emph{holonomy 2-functor of $\omega$}.
\end{thm}




\subsection{Integration over laminated 2-tracks}
In this section, we extend the notion of integration over~2-paths to that of integration over laminated 2-tracks. Moreover, we show that the integration of the transport $T_\omega$ of a formal power series connection $\omega$ over laminated 2-tracks is compatible with the vertical composition and the horizontal compositions of laminated 2-tracks. 

\begin{lem}\label{lemlam2tracks}
If $g$ and $h$ are laminated rank-2 homotopic 2-paths, then 
\begin{equation*}
\langle T_\omega, g\rangle = \langle T_\omega, h\rangle. 
\end{equation*}
\end{lem}
\begin{proof}
Let $H$ denote a laminated rank-2 homotopy from $g$ to $h$.  We have
\begin{align*}
\langle T_\omega, h\rangle - \langle T_\omega, g\rangle 
&= \langle T_\omega, \partial H\rangle, \\
&= \langle dT_\omega, H\rangle,
\end{align*}
where the second equality is consequence of Stokes' theorem.  Therefore, it suffices to show that for any positive integer $k$ and for any differential forms $\omega_1, \ldots, \omega_k$ of positive degree on $M$ such that $$\deg(\omega_1) + \cdots + \deg(\omega_k) = k + 2,$$ we have $\displaystyle \langle \int \omega_1\ldots \omega_k , H\rangle = 0$.  Recall that 
\begin{align*}
\langle \int \omega_1\ldots\omega_k , H\rangle 
&= \int_{[0,1]^2}\int_{\Delta^k}\widetilde{H}^*(\omega_1\times \cdots \times \omega_k),
\end{align*}
where $\widetilde{H}(r,s,t_1, \ldots, t_k) = (H(r,s,t_1), \ldots, H(r,s,t_k))$ for all $(r,s)\in [0,1]^2$ and $(t_1, \ldots, t_k) \in \Delta^k$. The condition that $H$ is laminated ensures that the rank of $d\widetilde{H}$ is at most $k+1$, and therefore 
\begin{equation*}
\widetilde{H}^*(\omega_1\times \cdots\times \omega_k) = 0.\qedhere
\end{equation*}

\end{proof}



The left and right whiskering of 2-paths with 1-paths is compatible with integration:
\begin{lem}\label{lemw2tracks}
Let $M$ be a smooth manifold and let $\omega_1, \ldots \omega_k$ be differential forms on $M$. If $\gamma$ is a 1-path and $g$ is a 2-path such that $\gamma(1) = g([0,1]\times \{0\})$, then
\begin{equation*}
\langle T_\omega, \gamma\circ g \rangle = \langle T_\omega, \gamma\rangle \langle T_\omega, g\rangle.
\end{equation*}
If $\gamma$ is a 1-path and $g$ is a 2-path such that $g([0,1]\times \{1\}) = \gamma(0)$, then
\begin{equation*}
\langle T_\omega, g \circ \gamma\rangle = \langle T_\omega, g\rangle\langle T_\omega, \gamma\rangle.
\end{equation*}
\end{lem}
\begin{proof}
This is a direction consequence of \cite[Proposition 2.1.2]{chen1973}.
\end{proof}

As a consequence of Lemmas \ref{lemvert2tracks} and \ref{lemw2tracks}, we get:
\begin{lem}\label{lemhoriz2paths}
If $h_1$ and $h_2$ are 2-paths such that $h_1([0,1]\times \{1\}) = h_2([0,1]\times \{0\})$, then
\begin{align*}
\left\langle T_\omega, \begin{pmatrix}
& h_2\\
h_1 & 
\end{pmatrix}\right\rangle &= \langle T_\omega, h_1\rangle \langle T_\omega, h_2(0,-)\rangle + \langle T_\omega h_1(1,-)\rangle \langle T_\omega, h_2\rangle, \\
\left\langle T_\omega, \begin{pmatrix}
h_1& \\
& h_2
\end{pmatrix}\right\rangle & = \langle T_\omega, h_1(0,-)\rangle \langle T_\omega, h_2\rangle + \langle T_\omega, h_1\rangle \langle T_\omega, h_2(1,-)\rangle.
\end{align*}
\end{lem}

\subsection{Integration over 3-tracks}
In this section, we extend the notion of integration over good 3-paths to that of integration over 3-tracks. Moreover, we show that the integration of the transport $T_\omega$ of a formal power series connection $\omega$ is compatible with the upward composition, the vertical composition and the horizontal compositions of 3-tracks. 

We denote by $\widehat{\Omega^{1,2}(C)}$ the subspace of $\widehat{\Omega^3(C)}$ defined by
$$\widehat{\Omega^{1,2}(C)}=  \left(\widehat{\Omega^1(A^*)}\otimes \widehat{\Omega^2(C)}\right) +  \left(\widehat{\Omega^2(C)}\otimes \widehat{\Omega^1(C)} \right)$$ 
\begin{lem}\label{lem3tracks}
If $J$ and $J'$ are rank-3 homotopic good 3-paths, then
\begin{equation*}
\langle T_\omega, J'\rangle - \langle T_\omega, J\rangle \in d_\Omega \widehat{\Omega^{1,2}(C)}.
\end{equation*}
\end{lem}
\begin{proof}
Let $W$ be a rank-3 homotopy from $J$ to $J'$.  We have
\begin{align*}
\langle T_\omega, J'\rangle - \langle T_\omega, J\rangle = \langle T_\omega, \partial W\rangle = \langle dT_\omega, W\rangle = d_\Omega\langle T_\omega, W\rangle,
\end{align*}
where the second equality is a consequence of Stokes' theorem, and the third equality is a consequence of the twisted cochain condition. Since $W$ is rank-3, $\langle T_\omega, W\rangle \in \widehat{\Omega^{1,2}(C)}$.
\end{proof}

\begin{lem}\label{lemup3paths}
If $J$ and $J'$ are 3-paths such that $J(1, -,-) = J(0,-,-)$, then 
\begin{equation*}
\langle T_\omega,  J* J'\rangle = \langle T_\omega, J\rangle + \langle T_\omega, J'\rangle.
\end{equation*}
\end{lem}
\begin{proof}
For any differential forms $\omega_1, \ldots, \omega_k$ of positive degree such that $\deg(\omega_1)+\cdots +\deg(\omega_k) - k = 1$,  we have:

\begin{align*}
\langle\int \omega_1\ldots\omega_k, J*J'\rangle 
&= \int_{[0, \frac{1}{2}]\times [0,1]}\int_{\Delta^k}\widetilde{J*J'}^*(\omega_1\times\cdots\times \omega_k) + \int_{[\frac{1}{2}, 1]\times [0,1]}\int_{\Delta^k}\widetilde{J*J'}^*(\omega_1\times\cdots\times \omega_k),\\
&= \int_{[0, 1]\times [0,1]}\int_{\Delta^k}\widetilde{J}^*(\omega_1\times\cdots\times \omega_k) +  \int_{[0, 1]\times [0,1]}\int_{\Delta^k}\widetilde{J'}^*(\omega_1\times\cdots\times \omega_k),\\
&= \langle\int \omega_1\ldots\omega_k, J\rangle  + \langle\int \omega_1\ldots\omega_k, J'\rangle .\qedhere
\end{align*}
\end{proof}
By exchanging the first two coordinates in the previous proof, we get:
\begin{lem}\label{lemvert3paths}
If $J$ and $J'$ are 3-paths such that $J(-,1,-) = J'(-,0,-)$, then
$$\langle T_\omega,  J\cdot J'\rangle = \langle T_\omega, J\rangle + \langle T_\omega, J'\rangle. $$
\end{lem}

As a consequence of Lemma \ref{lemvert3paths} and \cite[Proposition 2.1.2]{chen1973}, we get:
\begin{lem}\label{lemhoriz3paths}
If $J$ and $J'$ are good 3-paths such that $J([0,1]^2\times \{1\}) = J'([0,1]^2\times \{0\})$, then
\begin{align*}
\left\langle T_\omega, \begin{pmatrix}
& J'\\
J & 
\end{pmatrix}\right\rangle &= \langle T_\omega, J\rangle \langle T_\omega, J'(0,0,-)\rangle + \langle T_\omega J(0,1,-)\rangle \langle T_\omega, J'\rangle,\\
\left\langle T_\omega, \begin{pmatrix}
J& \\
& J'
\end{pmatrix}\right\rangle &= \langle T_\omega, J(0,1,-)\rangle \langle T_\omega, J'\rangle + \langle T_\omega J\rangle \langle T_\omega, J'(0,0,-)\rangle.\\
\end{align*}
\end{lem}


\subsection{The target Gray 3-category}

Recall that $\widehat{\Omega(C)}$ denotes the completion of the cobar complex of~$C$, and that $\widehat{\Omega^i(C)}$ is the vector subspace generated by homogeneous elements of degree $i$ (see Section~\ref{formalpowerseriesconnections}). We define the Gray 3-category $\mathcal{C}_3(C)$ by the following data:
\begin{itemize}
\item the Gray 3-category $\mathcal{C}_3(C)$ has a single object $*$,
\item an endomorphism of $*$ is an element of $\widehat{\Omega^0(C)} $ with composition given by the product,
\item for 1-morphisms $m$ and $n$ of $\mathcal{C}_3(C)$,  a 2-morphism from $m$ to $n$ is an element of the set
$$\mathcal{C}_3(C)(m,n) = \left\lbrace M\in \widehat{\Omega^1(C)}\mid d_\Omega M = m-n \right\rbrace, $$
\item the vertical composition of 2-morphisms is given by
\[
\begin{array}{ccl}
\mathcal{C}_3(C)(m,n) \times \mathcal{C}_3(C)(n,p) & \to & \mathcal{C}_3(C)(m,p)\\
(M,N) & \mapsto & M + N,
\end{array}
\]
\item the left whiskering of a 2-morphism $M$ with a 1-morphism $m$ is given by $mM$,
\item the right whiskering of a 2-morphism $M$ with a 1-morphism $m$ is given by $Mm$,
\item for 2-morphisms $M,N \in \mathcal{C}_3(C)(m,n)$, a 3-morphism from $M$ to $N$ is an element of the set
$$
\mathcal{C}_3(C)(m,n)(M,N) = \left\lbrace \alpha \in  \widehat{\Omega^2(C)}/d_\Omega\widehat{\Omega^{1,2}(C)} \mid d_\Omega \alpha = M-N \right\rbrace,
$$
\item the upward composition of 3-morphisms is given by
\[
\begin{array}{ccl}
\mathcal{C}_3(C)(m,n)(M,N) \times \mathcal{C}_3(C)(m,n)(N,P) & \to & \mathcal{C}_3(C)(m,n)(M,P)\\
(\alpha, \beta) & \mapsto & \alpha + \beta,
\end{array}
\]
\item the vertical composition of 3-morphisms is given by
\[
\begin{array}{ccl}
\mathcal{C}_3(C)(m,n)(M,N) \times \mathcal{C}_3(C)(n,p)(P,Q) & \to & \mathcal{C}_3(C)(m,p)(M\cdot P,N\cdot Q)\\
(\alpha, \beta) & \mapsto & \alpha + \beta,
\end{array}
\]
\item the left whiskering of a 3-morphism $\alpha$ with a 1-morphism $m$ is given by $m\alpha$,
\item the right whiskering of a 3-morphism $\alpha$ with a 1-morphism $m$ is given by $\alpha m$.
\end{itemize}
It is a straightforward verification that $\mathcal{C}_3(C)$ is a Gray 3-category.

\subsection{Holonomy 3-functors}

Recall from Section \ref{formalpowerseriesconnections} the transport $T_\omega$ of the formal power series connection $\omega$, and from Section \ref{iteratedintegrals} the integration $\langle \cdot, \cdot \rangle$ of iterated integrals over bounded plots.

Let's define the association $\mathrm{Hol}^3_\omega$. For any 1-track $[\gamma]$, we set
$$\mathrm{Hol}^3_\omega([\gamma]) = \langle T_\omega, \gamma\rangle.$$
For any laminated 2-track $[g]$, we set 
$$\mathrm{Hol}^3_\omega([g]) = \langle T_\omega, g\rangle.$$
We deduce from Lemma \ref{lemlam2tracks} that the element $\langle T_\omega, g\rangle \in \widehat{\Omega^1(C)}$ doesn't depend on the choice of representative 2-path $g$.
For any 3-track $[J]$, we set 
$$\mathrm{Hol}^3_\omega([J]) = [\langle T_\omega, J\rangle],$$
where $[\langle T_\omega, J\rangle]$ denotes the class of $\langle T_\omega, J\rangle$ in $\widehat{\Omega^2(C)}/d_\Omega\widehat{\Omega^{1,2}(C)}$. We deduce from Lemma \ref{lem3tracks} that the class $[\langle T_\omega, J\rangle]$ doesn't depend on the choice of representative good 3-path $J$. 

From Lemmas \ref{lemvert2tracks} and \ref{lemhoriz2paths},  we deduce that the association $\mathrm{Hol}^2_\omega$ is compatible with the vertical composition and the horizontal compositions of laminated 2-tracks. From Lemmas \ref{lemup3paths}, \ref{lemvert3paths} and  \ref{lemhoriz3paths}, we deduce 
that the association $\mathrm{Hol}^3_\omega$ is compatible with the upward composition, the vertical composition, and the horizontal compositions of 3-tracks:

\begin{thm}\label{thm3holonomy}
The transport of the formal power series $\omega$ induces a Gray functor:
$$
 \mathrm{Hol}^3_\omega \colon \mathcal{P}_3(M) \to \mathcal{C}_3(C)
$$
called the \emph{holonomy 3-functor of $\omega$}.
\end{thm}


\section{Application: a higher holonomy functor for configuration spaces}\label{application}

\noindent In this section, we apply the construction of Section \ref{higherholonomyfunctors} to a formal power series connection defined by Komendarczyk, Koytcheff and Voli\'c \cite{KKV} on the configuration space of $m$ points in $\R^n$ for $n\geqslant 4$.  We describe the resulting holonomy 3-functor.


\subsection{The formal power series connection}

Let $\bar{\mathcal{D}}(m)$ denote Kontsevich's differential graded algebra of oriented diagrams for some integers $n\geqslant 4$ and $m\geqslant 1$ as defined in \cite{lambrechtsvolic, KKV}.  Let $I$ denote the formality integration map, and let $\mathcal{B}(m)$ denote a basis of $\bar{\mathcal{D}}(m)$ (as a vector space) given by choosing a diagram in each orientation class.  Since $n\geqslant 4$, each grading vector space of $\bar{\mathcal{D}}(m)$ is finite dimensional, therefore the graded dual $\bar{\mathcal{D}}(m)^*$ is a differential graded coalgebra.  We recall the formal power series connection introduced in \cite{KKV}:
\begin{equation*}
\omega = \sum_{\Gamma \in \mathcal{B}(m)}I(\Gamma)\otimes \frac{[\Gamma^*]}{\lvert \mathrm{Aut}(\Gamma)\rvert} \in C_{dR}^*(\mathrm{Conf}(m,\R^n)) \otimes \Omega(\bar{\mathcal{D}}(m)^*).
\end{equation*}
\begin{rem*} Notice that if we allowed $n = 3$,  then the above sum would contain infinitely many differential~1-forms and therefore would not define a formal power series connection.  Requiring that $n\geqslant 4$ ensures that~$\omega$ only contains finitely many terms in each degree and no terms of degree 1.  Moreover, since~$\mathrm{Conf}(m,\R^n)$ is finite dimensional,  the above sum is finite. 
\end{rem*}

The transport of $\omega$ is given by:
$$
T_\omega = \sum\limits_{k\geqslant 0} \sum\limits_{\Gamma_1, \,\ldots \Gamma_k \in \mathcal{B}(m)}\int I(\Gamma_1)\ldots I(\Gamma_k) \otimes \frac{[\Gamma_1^*\vert \cdots \vert \Gamma_k^*]}{\lvert \mathrm{Aut}(\Gamma_1)\rvert \cdots \lvert \mathrm{Aut}(\Gamma_k)\rvert} \in B^*(\mathrm{Conf}(m,\R^n))\otimes \Omega(\bar{\mathcal{D}}(m)^*).
$$

\subsection{The holonomy 3-functor}
Since $\bar{\mathcal{D}}(m)^*$ is 1-connected, the Gray 3-category $\mathcal{C}_3(\bar{\mathcal{D}}(m)^*)$ admits a simpler description:
\begin{itemize}
\item the 1-morphisms of $\mathcal{C}_3(\bar{\mathcal{D}}(m)^*)$ are given by the set $\R$, with composition given by multiplication,
\item the 2-morphisms of $\mathcal{C}_3(\bar{\mathcal{D}}(m)^*)$ are given by linear combinations of diagrams of degree 2, with the vertical composition and the horizontal compositions all given by addition,
\item for any 2-morphisms $X$ and $Y$ from $x$ to $y$, the set of 3-morphisms from $X$ to $Y$ is given by
\begin{equation*}
\mathcal{C}_3(\bar{\mathcal{D}}(m)^*)(X,Y) = \{\alpha \in \Omega^2(\mathcal{D}(m)^*)/d_\Omega \Omega^{1,2}(\bar{\mathcal{D}}(m)^*) \mid d_\Omega(\alpha) = Y - X\},
\end{equation*}
with the upward composition, the vertical composition and the horizontal compositions of 3-morphisms all given by addition. 
\end{itemize}

Theorem \ref{thm3holonomy} induces:
\begin{cor}
Let $n\geqslant 4$ and $m\geqslant 1$. The transport of $\omega$ induces a holonomy 3-functor:
\begin{equation*}
\mathrm{Hol}^3_\omega\colon \mathcal{P}_3(\mathrm{Conf}(m,\R^n)) \to \mathcal{C}_3(\bar{\mathcal{D}}(m)^*).
\end{equation*}
\end{cor}

