\subsection{Hitting and Meeting Times in the Precise Setting}\label{sec:hitandmeetime}
\subsubsection{Hitting Times.}
Let $(Z_n)$ be a homogeneous Markov chain on $\ZZ$ with transition matrix $T=(T(z,z'))_{z,z'\in\ZZ}$.  For any target set $A\subset\ZZ$, define the \emph{hitting time}
\[
  \tau_A =\inf\{\,n\ge0: Z_n\in A\}\,\in\N_0\cup\{+\infty\}.
\]
This random variable represents the number of steps the process needs to first reach $A$. 
Conditioned on the chain starting at $z\in\ZZ$, the \emph{expected hitting time} is
\[
  h_A^T(z)=\EE_{\PP_Z}\bigl[\tau_A \mid Z_0=z\bigr].
\]
The quantity $h^{T}_A(z)$ represents the expected number of steps that the process $(Z_n)$, starting in $z\in \ZZ$, will take before reaching the set $A$.
\begin{comment}
Let $A$ be a subset of $\ZZ$. The hitting time $\tau_A:\Omega\to \N_0\cup \{+\infty\}$ is a random variable defined as
\[
\tau_A(\omega)\coloneqq\inf \{t\in \N_0 \mid \omega(t)\in A\}.
\]

%We note that $\tau_A(\omega)=+\infty$ if the path $\omega$ never reaches $A$. 

Given a Markov chain $\PP$ and a starting position $X_0$, we define the vector of expected hitting times $h^{\PP}_A\in \R^{N}$ as
\begin{equation}
    h^{\PP}_A(x):=\EE_\PP [\tau_A\mid X_0=x].
\end{equation}
\end{comment}

\begin{theorem}[\cite{norrisbook1997markov}]
    Let $A\subset \ZZ$ and let $(Z_n)$ be a homogeneous Markov chain with transition matrix $T$. The vector of expected hitting times $h^T_A=(h_A^T(z))_{z\in\ZZ}$ is the minimal non-negative solution to the following system of equations:
    \begin{equation}
        \begin{cases}
            h^T_A(z)=0 & \text{ for all $z\in A$,}\\
            h^T_A(z)=1+\sum_{z'\in \ZZ}T(z,z')h^T_A(z') & \text{ for all $z\notin A$,} 
        \end{cases}
    \end{equation}
    which can be rewritten as 
    \begin{equation}\label{eq:hittingtime_comp}
        h^T_A=\one_{A^c}+\one_{A^c}\cdot Th^T_A,
    \end{equation}
    where $\one$ is the indicator function and $\cdot$ represents the element-wise multiplication.
\end{theorem}

\subsubsection{Meeting Times.} 
Consider a joint stochastic process $(X_n,Y_n)_{n\in \N_0}$ on \(\ZZ^2:=\ZZ \times \ZZ\).  Define the \emph{meeting time} for $X_n$ and $Y_n$ as
\[
  \mu =\inf\{\,n\ge0: X_n = Y_n\}\,\in\N_0\cup\{+\infty\}.
\]
If the joint process starts at $(X_0,Y_0)=(x,y)$ then the \emph{expected meeting time} is
%Conditioned on initial states $x,y\in\ZZ$, the \emph{expected meeting time} is
\begin{equation} \label{eq:defexpectedmeetingtime}
      m{(x,y)}\coloneqq\EE_{\PP_{(X,Y)}}\bigl[\mu \mid X_0=x,\;Y_0=y\bigr].
\end{equation}
The quantity $m{(x,y)}$ represents the expected number of steps that the two processes, when starting in $x$ and $y$ respectively, will take before meeting. 
In the case where the joint process $(X_n, Y_n)$ is obtained as the independent product of two homogenous Markov chains $(X_n)$ and $(Y_n)$ with transition matrices $T$ and $S$, respectively, the expected meeting time has a particularly nice characterisation.
\begin{theorem}[{\cite{bullo2018meeting,Griffeath1975}}]
\label{thm:meeting}
Let $(X_n)$ and $(Y_n)$ be two homogenous Markov chains with transition matrices $T$ and $S$ respectively. The matrix of expected meeting times $m=(m{(x,y)})_{x,y\in\ZZ}$ is the minimal non-negative solution to the following system of equations:
    \begin{equation}\label{eq:meetingsys}
    \begin{cases}
        m{(x,x)}=0 & \text{for all $x\in \ZZ$,}\\
        m{(x,y)}=1+\sum_{x',y'\in \ZZ}T{(x,x')}S{(y, y')} m{(x',y')} & \text{for all $x\ne y$,}
    \end{cases}
    \end{equation}
which can be rewritten as 
    \begin{equation}\label{eq:meetime_matrix}
        m=J+TmS^\top,
    \end{equation}
    where $J$ is a $N\times N$ matrix that has zeros on the main diagonal and ones everywhere else, and $S^\top$ is the transpose of $S$.
\end{theorem}
