			\section{Transient behavior of the NBF-SIR model}\label{sec:transient}
			In the previous section we have discussed the stability properties of the NBF-SIR model and the implications of network effects and behavioral feedbacks for the design of control strategies. This section focuses on the transient behavior of the dynamics. The main result of the section is that, under some assumptions on the feedback mechanism, the NBF-SIR model with rank-1 interaction matrix considered in Example \ref{ex1} admits an aggregate infection curve that exhibits a unimodal behavior. 
			%Our result generalizes the unimodality behavior of the aggregate infection curve established in \cite{Alutto2024tcns} for the network SIR model with rank-1 interaction matrix with no behavioral feedback. A unimodality result of the infection curve was previously established also for the scalar BF-SIR model in \cite{Alutto2021OnSE}, which, however, is not implied by this result. 
			Note that the class of NBF-SIR models considered in Example \ref{ex1} can be rewritten as
			\begin{equation}\label{eq:example1}
				\!\begin{cases}
					\displaystyle	\dot{x}_i = -x_i g_i(x_i) \sum_{j =1}^n f_j(y_j)y_j\\[12pt]
					\displaystyle	\dot{y}_i =   x_i g_i(x_i) \sum_{j =1}^n f_j(y_j) y_j - \gamma y_i
				\end{cases} \ \forall i=1,\ldots,n.
			\end{equation}
			%for all $i=1,\ldots,n$.
			%Note that the class of models introduced in Example \ref{ex1} satisfies conditions \eqref{eq:ip1}, \eqref{eq:ip2}, and \eqref{eq:ip3}. 
			%In particular, the interaction matrix reads $A(x,y) = g(x) f(y)^T > \0$, with $g_i(x_i),f_j(y_j)>0$ for every $i,j = 1,\cdots,n$ and $x_i,y_j>0$. This formulation highlights that $A(x,y)$ is a rank-1 matrix for every $(x,y)$ with local feedback, which are the keys of our result. As a consequence, the dominant eigenvalue of $A(x,y)$ is $g(x)^T f(y)$, corresponding to the trace of $A(x,y)$, with unique left dominant eigenvector
			%$$ (v_{\max}^T g(x)) \,f(y)^T  = (f(y)^T g(x) ) \,v_{\max}^T$$
			%and this implies dominant left-eigenvector is given by 
			For this model, the dominant eigenvalue of $A(x,y)$ is $g(x)^T f(y)$, corresponding to the trace of $A(x,y)$, with unique left dominant eigenvector
			$v_{\max}(A(x,y)) = f(y)$. 
			Now, let
			\be \label{bary} \bar{y}(t) = \sum_{j=1}^n f_j(y_j(t))y_j(t) \,.\ee
			The next result states that, under reasonable assumptions, $t\mapsto\bar y(t)$ is unimodal, namely, it exhibits a single peak. 


			\begin{thm}\label{theo:bary}
				Consider model \eqref{eq:example1} with initial condition $(x(0),y(0))$ in $\mc S$ such that \be\label{initial-cond}\0\lneq x(0)\le\1-y(0)\lneq\1\,.\ee
				Assume that $g(x),f(y)>\0$, that $x_i g_i(x_i)$ is increasing and $f_j(y_j) y_j$ is increasing and concave for every $i,j = 1,\dots,n$ and $(x,y)$ in $\mc S$.
				Then:
				\begin{enumerate} 
					\item[(i)] if $\dot{\bar y}(0) \le 0$, then $\ov y(t)$ is strictly decreasing for $t\ge0$; 
					\item[(ii)] if $\dot{\bar y}(0)>0$, then there exists $\hat t>0$ such that $\ov y(t)$ is strictly increasing on $[0,\hat t]$ and strictly decreasing on $[\hat t,+\infty)$.
				\end{enumerate}
			\end{thm}
			\begin{pf}
				(i)	We prove the result by contradiction. If (i) does not hold true, there must exist $\tau \ge 0$ such that $\dot{\bar y}(\tau)=0$ and $\ddot{\bar y}(\tau) \ge 0$. Direct computation yields
				\be \label{dot-bary} 
				\ba{rcl}\dot{\bar y} & = &  \ds \sum_{j=1}^n \dot y_j [f_j' y_j + f_j]\,,\\[12pt]
				\ddot{\bar y}& = & \ds \sum_{j=1}^n [f_j''y_j + 2 f_j']\dot y_j^2 + \sum_{j=1}^n [f_j'y_j + f_j]\ddot{y}_j
				\ea 
				\ee 
				where, from \eqref{eq:example1},
				\begin{equation}\label{eq:ddoty}
					\ddot y_j = \dot x_j g_j \bar y + x_j g_j' \dot x_j \bar y  +x_j g_j \dot{ \bar y  }- \gamma \dot y_j
				\end{equation}
				for every $j=1,\ldots,n$.
				For simplicity of notation, we omit the dependence on $\tau$ on the right-hand side of the following equation. Note that
				\be\label{eq:ddoty2}
				\ba{rcl}
				\ddot{\bar y}(\tau) & \leq & \ds\sum_{j=1}^n (f_j'y_j + f_j)\ddot{y}_j \\[6pt]
				& \leq & \bar y \ds \sum_{j =1}^n (f_j'y_j + f_j)(g_j' x_j + g_j) \dot x_j - \gamma \dot{\bar y} \\[6pt]
				& = & \bar y \ds \sum_{j =1}^n (f_j'y_j + f_j)(g_j' x_j + g_j) \dot x_j\,,
				\ea
				\ee
				where the first inequality follows from the second equation of \eqref{dot-bary} and from concavity of $f_j(y_j) y_j$, while the second one follows from 
				\eqref{eq:ddoty}, from the first equation of \eqref{dot-bary} and from $\dot{\bar y}(\tau)=0$. Now, note that $x_jg_j(x_j)$ and $f_j(y_j) y_j$ are both increasing for every $j = 1,\dots,n$, hence
				\be\label{eq1}
				\ba{rcl}
				f_j'(y_j(\tau))y_j(\tau) + f_j(y_j(\tau)) & > & 0\,, \\[5pt] 
				g_j'(x_j(\tau)) x_j(\tau) + g_j(x_j(\tau)) & > & 0\,.
				\ea
				\ee 
				Moreover, since $y(0) \gneq \mb 0$ and $f(y)>\0$, Proposition \ref{prop:basic}(iii) implies that 
				\be\label{eq2}
				\bar y(\tau)>0\,.
				\ee 
				Furthermore, 
				\be\label{eq3}
				\dot x_j(\tau) <0 \ \text{for a } j \in \{1,\cdots,n\}\,.
				\ee
				This follows from $x(0) \gneq \mb 0$ and from Proposition \ref{prop:basic}(ii), which implies that $x_j(\tau)>0$ for at least a $j = 1,\cdots,n$. Hence, $\dot x_j(\tau)<0$ is implied by $\bar y(\tau)>0$, $g(x)>\0$ and \eqref{eq:example1}. Plugging \eqref{eq1}-\eqref{eq3} into \eqref{eq:ddoty2} we get a contradiction and prove the statement. 

				(ii) Assume by contradiction that $\dot{\bar y}(t)>0$ for every $t \ge 0$. This would imply the existence of a node $j$ such that $\dot{y}_j(t) > 0$ for all $t \ge 0$, contradicting Proposition \ref{prop:basic}(v). Hence, $\hat t = \min \{ t\geq0 :\dot{\bar y}(t)=0 \}$ is well defined and $\bar y(t)$ is increasing in $[0,\hat t]$. The fact that $\bar y$ is decreasing for $t >\hat t$ follows from point (i).
			\qed\end{pf}
			\begin{rem}  
				Let
				$h_{ij}(x_i, y_j) = x_i g_i(x_i) f_j(y_j) y_j$
				denote the \emph{force of infection} from node $j$ to node $i$, which represents the rate of new infections in subpopulation $i$ due to interactions with infected agents of subpopulation $j$.
				The assumptions of Theorem \ref{theo:bary} have a clear epidemiological motivation as they can be equivalently expressed in terms of $h_{ij}(x_i,y_j)$ by saying that $h_{ij}(x_i,y_j)$ is increasing in $x_i$ and $y_j$ and concave in $y_j$. The monotonicity of $h_{ij}(x_i,y_j)$ with respect to $y_j$ reflects the idea that more infected agents lead to a higher transmission rate, even though the per capita interactions of single infected agents may decrease due to behavioral adaptions. The concavity captures saturation effects, namely, when more agents are already infected, the impact of an additional one on the rate of new infections decreases. The monotonicity with respect to $x_i$ reflects the idea that a larger susceptible population increases the potential for new infections. Note that interaction matrix \eqref{eq:feedback} satisfies all assumptions of Theorem \ref{theo:bary}. 
				%	One example that satisfies all assumptions is the case
				%	\be\label{eq:feedback}A_{ij} = \frac{g_i(x_i)}{1+ay_j} \quad \forall i,j = 1,\ldots, n,\ee
				%	for every non-decreasing function $g_i: [0,1] \to [0, \infty)$ and $a \ge 0$. 
				%	
				%		Hence, Theorem \ref{theo:bary} generalizes \tcr{\cite[Proposition 2]{Alutto25}}, which proved the unimodality of the infection curve for the scalar SIR model with feedback \eqref{eq:feedback}.
			\end{rem}
			\begin{rem}
				The unimodality of $\bar y = \sum b_j y_j$ was established in \cite[Theorem 1]{Alutto2024tcns} for the network SIR model with constant rank-1 interaction matrix $$A = ab^T$$
				with vectors $a,b > \mb 0$.
				Since for this constant interaction matrix the force of infection $h_{ij}(x_i,y_j) = a_ix_ib_jy_j$ is increasing in $x_i$ and $y_j$ and concave in $y_j$, and since in this case $f(y) = b$, Theorem \ref{theo:bary} generalizes such a result.
			\end{rem}
			\begin{rem}
				The aggregate variable $\bar{y} = \sum_j f_j(y_j) y_j$ is increasing in every component $y_j$ and may be interpreted as an indicator of the overall infection level in the network. In some special cases, e.g., with interaction matrix \eqref{eq:feedback} with $\alpha = 0$ and when the subpopulations have equal size, $\bar{y} = \sum y_j $ is proportional to the fraction of infected agents in the entire population.
			\end{rem}
