$\boldsymbol{\Xi}_l = \bigl[\Thetab_{l,1}^\transp, \Thetab_{l,2}^\transp \cdots, \Thetab^{\transp}_{l,\Nbs}\bigr]^\transp \in \Gamma$,
%\end{equation}
