%%%%%%%%%%
\begin{equation}
    \label{eq:log-likelihood}
    l(\underline{\mathbf{y}};\boldsymbol{\Xi},\tilde{\mathbf{x}}) \approx -\frac{1}{\sigma^2_\mathrm{N}} \sum_{i=1}^{\Nbs} \bigl\| \tilde{\mathbf{y}}_i - h_i \mathbf{G}\Bigl(f_{\mathrm{D},i},\tau_i(\mathbf{p}),\theta_i(\mathbf{p})\Bigr) \tilde{\mathbf{x}}_i  \bigr\|^2
