\end{figure}
\begin{figure}[t]
  	\includegraphics[width=1.\linewidth]{h22N_and_rOmega_a0.70.pdf}
  	\caption{In the top panel of this figure we show the amplitude of the $h_{22}^{\rm N}$ mode defined in Eq.~\eqref{eq.:h22N expr}, which corresponds to the Newtonian order of the $h_{22}$ mode. We compute the quantity $|h_{22}^{\rm N}|$ on critical plunge geodesics with spin $a = 0.7$ and values of critical eccentricity $e_c \le 1$, and we plot it as a function of the radial coordinate $r$. The bottom panel shows the quantity $r \Omega$ of the considered critical plunge geodesics as a function of $r$. The different curves start at different radii because of the fact that the critical plunge geodesics asymptotically start at the critical radius $r_c$, which is a function of the quantities $a$ and $e_c$, as mentioned in Sec.~\ref{Sec.:critical plunge geodesics}.
  	}
