Let  $$\alpha'': 0=a_0<a_1<\ldots<a_{n+1}$$ be a sequence of non-negative integers such that $\gcd(a_1, \dots, a_{n+1}) = 1.$ Suppose $d=a_{n+1}$ and  let $$\alpha': d - a_0, d - a_1 \dots, d - a_{n+1}.$$ 
 Define a $\mathcal{K}$-algebra homomorphism
\[
\varphi: \mathcal{K}[x_0, x_1, \ldots, x_{n+1}] \to \mathcal{K}[s, t] \text{ by } \varphi(x_i) = s^{d - a_i} t^{a_i}, \quad 0 \le i \le n+1.
\]
and let $I(\alpha)$ denote the kernel of $\varphi$ . Then \[
R = \mathcal{K}[x_0, \ldots, x_{n+1}]/I(\alpha) \cong \mathcal{K}[s^d, s^{d - a_1}t^{a_1}, \ldots, s^{d - a_n}t^{a_n}, t^d].
\] Further, let $\varphi^{''}$ and $\varphi'$ denote the maps $\mathcal{K}[x_1, \ldots, x_{n+1}] \to \mathcal{K}[t] \text{ defined as } \varphi^{''}(x_i) =  t^{a_i},~ 1 \le i \le n+1$ and  $\mathcal{K}[x_0, \ldots, x_{n}] \to \mathcal{K}[s] \text{ defined as } \varphi^{'}(x_i) =  s^{d-a_i}, \quad 0 \le i \le n$ respectively. We write 
$I(\alpha'')$ and $I(\alpha')$ for $\ker (\varphi^{''})$ and $\ker (\varphi^{'})$ respectively. Then, we have 
\begin{equation}\label{1}
\begin{aligned}
R'' = \mathcal{K}[x_1, \ldots, x_{n+1}]/I(\alpha'') \cong \mathcal{K}[t^{a_1}, t^{a_2}, \ldots, t^{a_n}, t^d],
\\R' = \mathcal{K}[x_0, \ldots, x_n]/I(\alpha') \cong \mathcal{K}[s^d, s^{d - a_1}, \ldots, s^{d - a_n}].
\end{aligned}
\end{equation}
Note that $I(\alpha'')$ is the vanishing ideal of the affine monomial curve $\mathcal{C}(\alpha'')$ given parametrically by $t \mapsto (t^{a_1}, \ldots, t^d)$,
and $I(\alpha')$ is the vanishing ideal of the affine curve $\mathcal{C}(\alpha')$ given parametrically by
$s \mapsto (s^d, s^{d - a_1}, \ldots, s^{d - a_n})$. Moreover,
\begin{equation}\label{2}
\begin{aligned}
I(\alpha) &= I(\alpha'')^h \quad \text{(homogenized with respect to } x_0), \\
         &= I(\alpha')^h \quad \text{(homogenized with respect to } x_{n+1}),
\end{aligned}
\end{equation}
is the vanishing ideal of the projective monomial curve $\mathcal{C}(\alpha)$ defined parametrically by $[s : t] \mapsto [s^d : s^{d - a_1}t^{a_1} : \ldots : s^{d - a_n}t^{a_n} : t^d]$. We have that $R = \mathcal{K}[M]$ is the subring of $\mathcal{K}[s, t]$ generated by the set of monomials
$M = \{ s_0=s^d,s_1= s^{d-a_1}t^{a_1}, \ldots, s_n= s^{d-a_n}t^{a_n} ,s_{n+1}=t^d \}.
$
Any product $s_0^{m_0}s_1^{m_1}\cdots s_{n+1}^{m_{n+1}}$ with $m_i \in \mathbb{Z}_+$ is called a monomial in $\mathcal{K}[M]$. If $u = s_0^{m_0}s_1^{m_1} \cdots s_{n+1}^{m_{n+1}}$, we write $u = S^m$ with $m = (m_0, m_1, \dots, m_{n+1}) \in \mathbb{Z}_+^{n+2}$.
Suppose $f \in \mathcal{K}[M]$. Then $f =\mathop \sum\limits_{u \in \mathrm{Mon}(\mathcal{K}[M])} m_u u$, where $m_u \in \mathcal{K}$ and $\mathrm{Mon}(\mathcal{K}[M])$ denotes the set of monomials in $\mathcal{K}[M]$. Define the set of terms of $f$ as
\[
\mathrm{term}(f) = \{ u \in \mathrm{Mon}(\mathcal{K}[M]) : m_u \neq 0 \}.
\]
Next, we state some facts about monomial ideals in the subalgebra $\mathcal{K}[M]$ of $\mathcal{K}[s,t]$ which will be used in the consequent sections. 
\begin{remark}\label{R} 
    \begin{enumerate}[(i)]  
        \item\label{i} Let $I = \langle S^m : m \in A \rangle$ be a monomial ideal in $\mathcal{K}[M]$ where $A \subseteq \mathbb{Z}_+^{n+2}$ and let $f \in \mathcal{K}[M]$. 
        Then $f\in I$ if and only if every term of $f$ lies in $I$.    
              \item  Suppose $f$ and $g$ are monomials in $\mathcal{K}[M]$  such that $fg \in I $ implies that either $f \in I$ or $g^k \in I$ for some positive integer $k$. Then $I$ is a primary ideal.
        \item In the ring $\mathcal{K}[M]$, the ideal $((s^d)^m : (t^d)^\infty)=\mathop\cup\limits_{n\geq 0} ((s^d)^m : (t^d)^n)$ is a monomial ideal for all $m \in \mathbb{N}$. 
    \end{enumerate}
\end{remark}


\begin{proof}
    \begin{enumerate}[(i)]
        \item It is easy to see that $f \in I$ if and only if $f$ is a $\mathcal{K}$-linear combination of monomials in $I$ which gives the result immediately. 

        \item Let $f', g' \in \mathcal{K}[M]$ such that $f'g' \in I$ and $f' \notin I$. Write
\[
f' = b_1f_1 + \cdots + b_nf_n, \quad g' = b_1'g_1 + \cdots + b_m'g_m,
\]
where $f_i$ and $g_j$ are monomials for $1\leq i\leq n,$  
 $1\leq j\leq m$ and  $b_i,b_j' \in \mathcal{K}$. Since $f' \notin I$, we have $f_r \notin I$ for at least one $f_r$ by part \eqref{i}. Again from part \eqref{i}, we get that for each $j$, $f_r g_j \in I$ implies $g_j \in \sqrt{I}$. Hence $g' \in \sqrt{I}$ which gives that $I$ is primary.
 \item Since $\mathcal{K}[M]$ is a Noetherian domain, there exists some large $N \in \mathbb{N}$ such that
$
((s^d)^m : (t^d)^\infty) = ((s^d)^m : (t^d)^N).
$ Let $f \in ((s^d)^m : (t^d)^N)$. Then $(t^d)^N f \in ((s^d)^m)$ which gives that every term of $(t^d)^N f$ lies in $((s^d)^m)$ and thus every term of $f$ lies in $((s^d)^m : (t^d)^N)$. From part \eqref{i}, we get that the ideal  $((s^d)^m : (t^d)^N)$ is monomial.
    \end{enumerate}
\end{proof}
