We end this section with the following crucial observation. 
\begin{theorem}\label{saturation}
The ideal $I = ((s^d)^m : (t^d)^\infty)$  is a primary ideal in the ring $\mathcal{K}[M]$ for all $m\geq 1.$
\end{theorem}
\begin{proof}
By Remark \ref{R}, $I$ is a monomial ideal. Let $X, Y \in \mathcal{K}[M]$ be monomials such that $XY \in I$. If $X \notin I$, then $Y = s^n t^m$ for some $n \ne 0$ . Then $Y^{md} \in I$ and by Remark \ref{R}, $I$ is primary.
\end{proof}
For any module $R$ we denote by $H^i_\mathfrak{M}(R)$ the $i-$th local cohomology module of $R$ with respect to $\mathfrak{M}.$
\section{Buchsbaum monomial curves }\label{AE}
In this section, we will give a large class of curves which are non-smooth,non Cohen-Macaulay Buchsbaum. For a fixed positive integer $n$, we consider the set of monomials
\[
M_r^n = \{s^{a_n}, s^{a_n - b_1}t^{b_1}, s^{a_n - b_2}t^{b_2}, s^{a_n - a_0}t^{a_0}, s^{a_n - a_1}t^{a_1}, \dots, t^{a_n}\}.
\]
where $r \geq 5$ is a positive integer and \begin{equation}\label{AS}b_1 = r,~b_2 = 2r - 2 \text{ and }
a_i = 2r + 2i - 1\end{equation}for all $1\leq i\leq n$  
For convenience, we will denote $M_r^n$ simply by $\mathcal{M}$ when $r$ and $n$ are fixed and  $\mathcal{R} = \mathcal{K}[\mathcal{M}]$.
Our objective is to investigate whether $\mathcal{R}$ is a Buchsbaum ring. Note that $\mathcal{R}$ defines a non-smooth monomial curve. As discussed in \eqref{1},we have the ideals $\mathcal{I}\subset \mathcal{K}[x_0, \ldots, x_{n+3}],~\mathcal{I}'\subset \mathcal{K}[x_0, \ldots, x_{n+2}]$ and $\mathcal{I}''\subset \mathcal{K}[x_1, \ldots, x_{n+3}]$ with the following identifications:
\[
\mathcal{R} = \mathcal{K}[x_0, \ldots, x_{n+3}]/\mathcal{I} \cong \mathcal{K}[\mathcal{M}],
\]
\[
\mathcal{R}'' = \mathcal{K}[x_1, \ldots, x_{n+3}]/ \mathcal{I}'' \cong \mathcal{K}[t^{b_1}, t^{b_2}, t^{a_0}, \ldots, t^{a_n}],
\]
\[
\mathcal{R}' = \mathcal{K}[x_0, \ldots, x_{n+2}]/\mathcal{I}' \cong \mathcal{K}[s^{a_n}, s^{a_n - b_1}, s^{a_n - b_2}, s^{a_n - a_0}, \ldots, s^{a_n - a_{n-1}}].
\]
As in \eqref{2}, we have
\begin{equation*}
\begin{aligned}
\mathcal{I} &= (\mathcal{I}'')^h \quad \text{(homogenization with respect to } x_0), \\ 
           &= (\mathcal{I}')^h \quad \text{(homogenization with respect to } x_{n+3}).
\end{aligned}
\end{equation*}
\begin{theorem}\label{thm-pre5}
 In the ring $\mathcal{R}$, the ideal $I=(s^{a_n},s^{3a_n-3b_1}t^{3b_1})$ is a primary ideal.    
\end{theorem}
\begin{proof}
In view of Theorem \ref{saturation}, it is enough to prove that $I=((s^{a_n}):(t^{a_n})^\infty)$. Let $X$ be a monomial in $\mathcal{R}$ and $X.(t^{a_n})^m\in (s^{a_n})$ for some $m\in \mathbb{Z}^+$. Without loss of generality, we may assume that
\begin{equation*}
    X=(s^{a_n})^{m_1}(s^{a_n-b_1}t^{b_1})^{m_2}(s^{a_n-b_2}t^{b_2})^{m_3}(s^{a_n-a_0}t^{a_0})^{n_0}\cdots(s^{a_{n}-a_{n-1}}t^{a_{n-1}})^{n_{n-1}}  
\end{equation*} 
where $m_1,m_2,m_3,n_i \in \mathbb{Z}^+$ for $i=0,1,\dots n-1$ and we may assume that $m_1=0$ and $m_2<3$. In this case, we want to prove that $X\in (s^{a_n}).$ We write $X^\prime$ for the monomial $X$  after the substitution $t=1.$ Thus $X' \in \mathcal{R}'$,  i.e.,   \begin{equation}\label{prime}
X^\prime =(s^{a_n-b_1})^{m_2}(s^{a_n-b_2})^{m_3}(s^{a_n-a_0})^{n_0}(s^{a_n-a_1})^{n_1}\ldots(s^{a_n-a_{n-1}})^{n_{n-1}}
\end{equation}
Since $X.(t^{a_n})^m\in (s^{a_n})$ in $\mathcal{R}$ we get that $ X^\prime \in (s^{a_n})$ in $\mathcal{R}'$. 
\begin{claim}
    There exist non negative integers $m_1',m_2',m_3',n_i',$ $i=1,...,n-1$ and $m_1'\neq 0$ such that 
\begin{eqnarray}\label{eq}
    X'=(s^{a_n})^{m_1'}(s^{a_n-b_1})^{m_2'}(s^{a_n-b_2})^{m_3'}\cdots(s^{a_n-a_{n-1}})^{n_{n-1}'}\\ 
    \mbox{ with }\label{ineq} 
     m_2+m_3+\sum_{i=0}^{n-1}n_i \geq m_1'+m_2'+m_3'+\sum_{i=0}^{n-1}n_i'.
\end{eqnarray} 
\end{claim}
\begin{proof}[Proof of Claim]
Observe that $a_n = 2r + 2n + 1,a_n-{b_1} = r + 2n - 1,a_{n} - xb_{2} = 2n + 1,a_n - a_i = 2n - 2i, \; i = 0, \ldots, n - 1$
and 
$a_n > a_{n}-b_1 > a_{n}-b_2 > \cdots > a_n - a_{n-1}.$   Let $$P = m_2(a_n - b_1) + m_3(a_n - b_2) + \sum_{i=0}^{n-1} n_i(a_n - a_i).$$
Then $X' = s^P$ in $\mathcal{K}[s]$. Now $X' \in (s^{a_n})\mathcal{R}' \Rightarrow X' = s^{a_n} s^{P-a_n}$ where $s^{P-a_n} \in \mathcal{R}'$. On comparing the degree of $s$ in $\mathcal{K}[s]$ we get,
 $P - a_n \geq 0.$ 

 Suppose $P - a_n < a_n - b_2$. Then $P-a_n$ is a non-negative integer combination of $a_n-a_i$ for $0\leq i\leq n-1$ . Notice that $a_n - a_i$, $i = 0, \ldots, n$ are the all even numbers from $0$ to $a_n - b_2$ . Thus, $P - a_n$ is an even number and $P - a_n = a_n - a_j \text{ for some } j \in \{0, 1, \ldots, n\}.$
In this case, we get that $X' = s^{a_n} s^{(a_n - a_j)} \text{ and } m_1' + m_2' + m_3' + \sum_{i=0}^{n-1} n_i' = 2 \leq m_2 + m_3 + \sum_{i=0}^{n-1} n_i.$
%%since $a_n > a_n - a_j$.

Now suppose $P-a_n \geq a_n - b_2$.  Let $m \geq 2$ be a positive integer such that 
$(m - 1) \leq \frac{P-a_n}{a_n - b_2} < m.$ Then $ (a_n - b_2) \leq (P - a_n) - (m - 2)(a_n - b_2) < 2(a_n - b_2).$ For conveniece, let
\[
L = (P - a_n) - (m - 2)(a_n - b_2)
\]
Suppose $L$ is an odd number. Then
\[
0 \leq L - (a_n - b_2) < a_n - b_2
\]
and $L - (a_n - b_2)$ is an even number which means $L - (a_n - b_2) = a_n - a_j \text{ for some } j \in \{0, \ldots, n\}.$ This gives
% We get:
% \[
% P - a_n - (m - 2)(a_n - b_2) = (a_n - b_2) + (a_n - a_j)
% \]
\[
s^P = s^{a_n + (m - 2)(a_n - b_2) + (a_n - b_2) + (a_n - a_j)}
\]
So we take $m_1' = 1$, $m_2' = 0$, $m_3' = (m - 1)$ and $n_j' = 1$ for $j \in \{0, \ldots, n-1\}$.
Now we show the inequality \eqref{ineq} in three cases when $m_2 = 0,1$ and $2$ respectively. First let $m_2=0$. Then 
\begin{eqnarray*}
\left( m_3 + \sum_{i=0}^{n-1} n_i \right)(a_n - b_2) \geq P& =& a_n + (m - 1)(a_n - b_2) + (a_n - a_j)
\text{ and }\\
P &>& (1 + (m - 1))(a_n - b_2) 
\end{eqnarray*}
where the last inequality follows since $ a_n > a_n - b_2 \text{ and } a_n - a_j \geq 0.$ This implies $
m_3 + \sum_{i=0}^{n-1} n_i > m
\Rightarrow m_3 + \sum_{i=0}^{n-1} n_i \geq m + 1
\Rightarrow m_3 + \sum_{i=0}^{n-1} n_i \geq m_1' + m_2' + m_3' + \sum n_i'
.$

Suppose $m_2 = 1$. Then
\begin{eqnarray*}
(a_n - b_1) + \left( m_3 + \sum_{i=0}^{n-1} n_i \right)(a_n - b_2) &\geq& P 
= a_n + (m - 1)(a_n - b_2) + (a_n - a_j) \text{ and }
\\ P &>& (a_n - b_1) + (m - 1)(a_n - b_2) 
\end{eqnarray*}
where the last inequality follows since $a_n > a_n - b_1.$ This implies $m_3 + \sum_{i=0}^{n-1} n_i > m - 1
\Rightarrow m_3 + \sum_{i=0}^{n-1} n_i \geq m
\Rightarrow m_2 + m_3 + \sum_{i=0}^{n-1} n_i \geq m_1' + m_2' + m_3' + \sum_{i=0}^{n-1} n_i'.$

Now suppose $m_2 = 2$. Then
\begin{eqnarray*}
 2(a_n - b_1) + \left( m_3 + \sum_{i=0}^{n-1} n_i \right)(a_n - b_2) &\geq& P 
= a_n + (m - 1)(a_n - b_2) + (a_n - a_j)
\\ \text{ and }  P &>& 2(a_n - b_1) + (m - 2)(a_n - b_2)
\end{eqnarray*}
where the last inequality follows since  $a_n + (a_n - b_2) > 2(a_n - b_1)$. This implies  \\$\left( m_3 + \sum_{i=0}^{n-1} n_i \right) > m - 2
\Rightarrow m_3 + \sum_{i=0}^{n-1} n_i \geq m - 1
\Rightarrow m_2 + m_3 + \sum_{i=0}^{n-1} n_i \geq m_1' + m_2' + m_3' + \sum_{i=0}^{n-1} n_i'.$

\vspace{0.5cm}
Now assume that $L$ is an even number. We have that $(a_n - b_2) - (a_n - a_0) \leq L - (a_n - a_0) < 2(a_n - b_2)-(a_n-a_0) \Rightarrow 1 \leq L - (a_n - a_0) < (a_n - b_2) + 1.$ Since $L - (a_n - a_0)$ is an even number and is less than $(a_n-b_2)$, 
we get that $
L - (a_n - a_0) = a_n - a_j
$
 for some $j \in \{0, 1, \ldots, n-1\}$. Therefore, $P - a_n - (m - 2)(a_n - b_2) - (a_n - a_0) = a_n - a_j$ which implies 
\[
s^P = s^{a_n + (m - 2)(a_n - b_2) + (a_n - a_j) + (a_n - a_0)}.
\]
So we take $m_1' = 1,~m_2' = 0,~ m_3' = (m - 2)$ . Further, if $j=0$, we choose $n_0'=2$ and if $j\neq 0$, we choose  $n_0' = 1$ and $n_j'=1$. Now we show the inequality \eqref{ineq}.  First, suppose \( m_2 = 0 \). Then,
\begin{eqnarray*}
    \left( m_3 + \sum_{i=0}^{n-1} n_i \right)(a_n - b_2) \geq P &=& a_n + (m - 2)(a_n - b_2) + (a_n - a_0) + (a_n - a_j) \text{ and }
\\P &>& 2(a_n - b_2) + (m - 2)(a_n - b_2) 
\end{eqnarray*}
where the last inequality follows since $a_n+ (a_n - a_0 )> 2(a_n - b_2) \text{ and } a_n - a_j > 0$. This implies $\left( m_3 + \sum_{i=0}^{n-1} n_i \right) > m
\Rightarrow m_3 + \sum_{i=0}^{n-1} n_i \geq m + 1=m_1' + m_2' + m_3' + \sum_{i=0}^{n-1} n_i'.$

Now suppose  \( m_2 = 1 \). Then,
\begin{eqnarray*}
    (a_n - b_1) + \left( m_3 + \sum_{i=0}^{n-1} n_i \right)(a_n - b_2)&\geq&P= a_n + (m - 2)(a_n - b_2) + (a_n - a_0) + (a_n - a_j) \\ \text{ and }
P &>& (a_n - b_1) + (a_n - b_2) + (m - 2)(a_n - b_2) 
\end{eqnarray*}
where the last inequality follows since  $a_n + (a_n - a_0) > (a_n-b_1)+(a_n - b_2)$. This implies $m_3 + \sum_{i=0}^{n-1} n_i > m - 1
\Rightarrow m_3 + \sum_{i=0}^{n-1} n_i \geq m
\Rightarrow m_2 + m_3 + \sum_{i=0}^{n-1} n_i \geq m_1' + m_2' + m_3' + \sum_{i=0}^{n-1} n_i'.$
Finally let \( m_2 = 2 \). Then
\begin{eqnarray*}
    2(a_n - b_1)+ \left(m_3 + \sum_{i=0}^{n-1} n_i\right)(a_n - b_2) &\geq& P= a_n + (m - 2)(a_n - b_2) + (a_n - a_0) + (a_n - a_j) 
\\ \text{ and } P &>& (m - 2)(a_n - b_2) + 2(a_n - b_1) 
\end{eqnarray*}
where the last inequality follows since $a_n + (a_n - a_0) > 2(a_n - b_1)$. This implies \\$\left( m_3 + \sum_{i=0}^{n-1} n_i \right) \geq m - 1
\Rightarrow m_2 + m_3 + \sum_{i=0}^{n-1} n_i \geq m_1' + m_2' + m_3' + \sum_{i=0}^{n-1} n_i'.$ This completes the proof of the claim. 

%%\\From all cases we get %%\begin{equation*}
 %   X'=(s^{a_n})^{m_1'}(s^{a_n-b_1})^{m_2'}(s^{a_n-b_2})^{m_3'}(s^{a_n-a_0})^{n_0'}(s^{a_n-a_1})^{n_1'}...(s^{a_n-a_{n-1}})^{n_{n-1}'}\end{equation*} and  $m_2+m_3+\sum_{i=0}^{n-1}n_i \geq m_1'+m_2'+m_3'+\sum_{i=0}^{n-1}n_i'$
\end{proof}
Now from \eqref{eq}, we get that $X'-(s^{a_n})^{m_1'}(s^{a_n-b_1})^{m_2'}(s^{a_n-b_2})^{m_3'}(s^{a_n-a_0})^{n_0'}...(s^{a_n-a_{n-1}})^{n_{n-1}'}\\=0\implies x_1^{m_2}x_2^{m_3}\cdots x_{n+2}^{n_{n-1}}-x_0^{m_1'}x_1^{m_2'}\cdots x_{n+2}^{n_{n-1}'} \in \mathcal{I}'$. So on homogenizeing this element with respect to $x_{n+3}$, we  get that $X \in (s^{a_n})$ in $\mathcal{R}$. Thus  $((s^{a_n}):(t^{a_n})^\infty) \subseteq I$. Now for the other side containment, we have that $s^{a_n} \in ((s^{a_n}):(t^{a_n})^\infty)$ and $3(a_n-b_1)-a_n > a_n-b_2.$ Suppose $3(a_n-b_1)-a_n$ is an even number, say $2q$ for some positive integer $q \geq 2$. Then $s^{3(a_n-b_1)}=s^{a_n}s^{(a_n-a_{n-1})q}$. So, after homogenization, we get $s^{3(a_n-b_1)}t^{3b_1}\in ((s^{a_n}):(t^{a_n})^\infty)$ .  Suppose $3(a_n-b_1)-a_n$ is an odd number. Equivalently $3(a_n-b_1)-a_n -(a_n-b_2)$ is an even number, say $2q$ for some $q\in \mathbb{Z}^+$ then, by similar arguments, we get that $s^{3(a_n-b_1)}t^{3b_1}\in ((s^{a_n}):(t^{a_n})^\infty)$. Therefore, $((s^{a_n}):(t^{a_n})^\infty) = I$
\end{proof}
\begin{corollary}\label{cor-pre1}
 In the ring $\mathcal{R}$, the ideal $J=(s^{ka_n},s^{(k-1)a_n}s^{3a_n-3b_1}t^{3b_1}),~k\in \mathbb{N}$  is a primary ideal. Moreover $J= ((s^{a_n})^k:(t^{a_n})^\infty).$
\end{corollary}
\begin{proof}
    Let $X\in ((s^{a_n})^k:(t^{a_n})^\infty) $ be a monomial. Then $X(t^{a_n})^m=s^{ka_n}.L$ for some $m\in \mathbb{Z}^+$ and $L\in \mathcal{R}$. Put $t=1$, then $X=s^{ka_n}.L'$ where $L'\in \mathcal{R}'$ is obtained by substituting $t=1$ in $L$. This gives $\frac{X}{s^{(k-1)a_n}}\in (s^{a_n})\mathcal{R}'\implies \frac{X}{s^{(k-1)a_n}}(t^{a_n})^z\in (s^{a_n})\mathcal{R}$ for some $z \in \mathbb{Z}^+ \implies X\in (s^{a_n})^k$ or $X\in s^{(k-1)a_n}s^{3a_n-3b_1}t^{3b_1}$ from Theorem \ref{thm-pre5}. Thus $((s^{a_n})^k:(t^{a_n})^\infty) \subseteq J$ and $s^{3a_n-3b_1}t^{3b_1}\in ((s^{a_n}):(t^{a_n})^\infty) \implies s^{(k-1)a_n}s^{3a_n-3b_1}t^{3b_1} \in ((s^{a_n})^k:(t^{a_n})^\infty) $. Hence 
   $(s^{ka_n},s^{(k-1)a_n}s^{3a_n-3b_1}t^{3b_1})=((s^{a_n})^k:(t^{a_n})^\infty).$
   \end{proof}
Let $\mathfrak{m}=(s^{a_n},s^{{a_n}-b_1}t^{b_1},s^{a_n-b_2}t^{b_2},s^{a_n-a_0}t^{a_0},\dots,t^{a_n})$ be the homogeneous maximal ideal of $\mathcal{R}$. Radical of  $J$ is the ideal $(s^{a_n},s^{{a_n}-b_1}t^{b_1},s^{a_n-b_2}t^{b_2},s^{a_n-a_0}t^{a_0}, \dots,s^{a_n-a_{n-1}}t^{a_{n-1}})\subseteq \mathcal{R}$ and radical of the ideal $L=(s^{2a_n},t^{a_n})$ is $\mathfrak{m}$, i.e.,  $L$ is a primary ideal. We obtain the following theorem which will be needed later.
\begin{theorem}\label{thm-pre6}
Suppose $r\leq 5+2n$. Then $(s^{2a_n})=(s^{2a_n},s^{a_n}s^{3a_n-3b_1}t^{3b_1}) \cap L $ is  primary decomposition of the ideal $(s^{2a_n})\subseteq \mathcal{R}.$ 
\end{theorem}
 It immediately follows from   Corollary \ref{cor-pre1} and the next proposition. 

\begin{proposition}\label{lemma-pre1}
    If $r\leq 5+2n$ then $s^{3a_n-3b_1}t^{3b_1}t^{a_n} \in (s^{a_n}).$
\end{proposition}
\begin{proof}
Suppose $r=2r'$ is an even number  where $r'$ is a positive integer. Then %when $n=1;$$s^{3a_n-3b_1}t^{3b_1}t^{a_n}=s^{a_n}s^{2(a_n-b_2)}t^{2b_2}s^{a_n-x_3}t^{x_3}$ when 
\begin{equation*}s^{3a_n-3b_1}t^{3b_1}t^{a_n}=s^{a_n}s^{2(a_n-b_2)}t^{2b_2}s^{a_n-a_{n-(r'-2)}}t^{a_{n-(r'-2)}}\in (s^{a_n}). \end{equation*}
Now suppose $r$ is an odd number, say $r=2r'+1,~r'$ is a positive integer. If $n\geq r'+1$ then $s^{3a_n-3b_1}t^{3b_1}t^{a_n}=
        s^{2a_n}s^{a_n-a_{r'+1}}t^{a_{r'+1}}t^{a_n}\in (s^{a_n})$. Now suppose $n<r'+1$. On the other hand, we have $n\geq \frac{r-5}{2}=\frac{2r'-5}{2}\implies n\geq r'-2$, i.e., $r'+1>n\geq r'-2$.  Then 
       \begin{equation*} 
            s^{3a_n-3b_1}t^{3b_1}t^{a_n}=
            \begin{cases}
        s^{a_n}s^{3(a_n-b_2)}t^{3b_2}\in (s^{a_n}) \text{ when } r'-2 = n  \\
        s^{a_n}s^{a_n-b_2}t^{b_2}s^{2(a_n-a_0)}t^{2a_0}\in (s^{a_n}) \text{ when } r'-1 = n \\
        s^{a_n}s^{a_n-b_2}t^{b_2}s^{a_n-a_0}t^{a_0}s^{a_n-a_1}t^{a_1}\in (s^{a_n}) \text{ when } r'= n 
        \end{cases}
        \end{equation*}
\end{proof}
Now we obtain a class of Buchbaum rings through the next theorem.    
    \begin{theorem}\label{thm-pre7}
         Suppose $r\leq 5+2n$. Then  $\mathcal{R}=\mathcal{K}[\mathcal{M}]\subseteq \mathcal{K}[s,t]$ is a  Buchsbaum ring of $\dim=2$. 
    \end{theorem}
    \begin{proof}
      Clearly $\mathcal{R}$ is an integral domain and  $\dim \mathcal{R}=2$. Consider the domain $A=\mathcal{R}/(s^{2a_n})$. We have $\dim A=1$ and $(0)=(s^{2a_n},s^{a_n}s^{3a_n-3b_1}t^{3b_1})/(s^{2a_n}) \cap L/(s^{2a_n})$ is a primary decomposition of the ideal $(0)$ in $A$ by theorem \ref{thm-pre6} . Now from \cite[Proposition 3.13]{4},  $H_\mathfrak{m}^0(A)=(s^{2a_n},s^{a_n}s^{3a_n-3b_1}t^{3b_1})/(s^{2a_n}).$
 Now we observe the follwing relations which implies that $\mathfrak{m}$ annihilates $H_\mathfrak{m}^0(A)$.
    \begin{equation}\label{q_1}
s^{a_n}s^{3a_n-3b_1}t^{3b_1}s^{a_n-b_1}t^{b_1}=s^{3a_n}s^{a_n-a_0}t^{a_0}s^{a_n-a_1}t^{a_1};
       \end{equation}
       \begin{equation}\label{q_2}
        s^{a_n}s^{3a_n-3b_1}t^{3b_1}s^{a_n-b_2}t^{b_2}=s^{2a_n}s^{a_n-b_1}t^{b_1}s^{2(a_n-a_0)}t^{2a_0};
       \end{equation}
       \begin{equation}\label{q_3}
           s^{a_n}s^{3a_n-3b_1}t^{3b_1}s^{a_n-a_0}t^{a_0}=s^{2a_n}s^{a_n-b_1}t^{b_1}s^{a_n-b_2}t^{b_2}s^{(a_n-a_1)}t^{a_1};
       \end{equation}
       \begin{equation}\label{q_4}
       s^{a_n}s^{3a_n-3b_1}t^{3b_1}s^{a_n-a_i}t^{a_i}=s^{2a_n}s^{a_n-b_1}t^{b_1}s^{a_n-b_2}t^{b_2}s^{a_n-a_{i+1}}t^{a_{i+1}} \text{ for } i=1,2,.,n-1,~~
    \end{equation}
        and $s^{a_n}s^{3a_n-3b_1}t^{3b_1}t^{a_n} \in (s^{2a_n})$ from Proposition \ref{lemma-pre1}.
 Since $\mathfrak{m}$ annihilates $H_\mathfrak{m}^0(A)$, we have  that  $A$ is a Buchsbaum ring, see \cite[Lemma 2.1]{5} which implies that   $\mathcal{R}$ is a Buchsbaum ring by \cite[Theorem 3]{3}.  
    \end{proof}
  Now we find class of non Cohen-Macaulay Buchbaum rings which is the main result of this section. 
    \begin{theorem}\label{XY}
        Suppose $r\geq 5$ and $2n\geq r-5.$ Then we have the following.
        \begin{enumerate}[(i)]
            \item $\mathcal{R}$ is Cohen-Macaulay if $r$ is odd and $2n\geq r+1$.
            \item $\mathcal{R}$   is   non Cohen-Macaulay Buchbaum if $r$ is an odd and $2n <r+1$. 
             \item  $\mathcal{R}$ is non Cohen-Macaulay Buchbaum if $r$ is an even number.
            \end{enumerate}
    \end{theorem}
    % \begin{theorem}\label{thm-pre8}
    %      If $r\leq 5+2n$ and $r$ is a odd integer such that $r=2r'+1;r'$ is positive integer then $\mathcal{R}$ is cohen macaulay ring if $n\geq r'+1$ and not cohen macaulay but Buchsbaum if $n < r'+1$ also if $r$ is an even integer then $\mathcal{R}$ is not cohen macaulay but Buchsbaum.
    % \end{theorem}
    \begin{proof}
    By Theorem \ref{thm-pre7}, $\mathcal{R}$ is Buchbaum in all cases. 
    \begin{enumerate}[(i)]
        \item Let $r$ be odd, say $r=2r'+1$ with $r'$ a positive integer and $2n\geq r+1 \implies n \geq r'+1$. Then $s^{3a_n-3b_1}t^{3b_1} \in (s^{a_n})$ from Proposition \ref{lemma-pre1} which implies that the ideal $(s^{a_n})$ is a primary ideal by Theorem \ref{thm-pre5}. Therefore, every zero divisor of $\mathcal{R}/(s^{a_n})$ is in the radical of $(s^{a_n})$. So, $t^{a_n}$ is not a zero divisor of $\mathcal{R}/(s^{a_n})$. Therefore,   $\mathcal{R}/(s^{a_n})$ is Cohen Macaulay which implies that $\mathcal{R}$ is Cohen Macaulay.
       \item \label{AC} Let $r=2r'+1$. Now suppose $2n <r+1 \implies n < r'+1$. We  prove that $s^{3a_n-3b_1}t^{3b_1} \notin(s^{a_n})$. Suppose, if possible, $s^{3a_n-3b_1}t^{3b_1} \in(s^{a_n})$ then \begin{equation}\label{AB}
           s^{3a_n-3b_1}t^{3b_1}=(s^{a_n})^{m_1}(s^{a_n-b_1}t^{b_1})^{m_2}(s^{a_n-b_2}t^{b_2})^{m_3}(s^{a_n-a_0}t^{a_0})^{n_0}\cdots (t^{a_{n}})^{n_{n}} 
       \end{equation}
       where $m_1,m_2,m_3,n_i \in \mathbb{Z}^+$ for $i=0,1,\dots n$ and $m_1\neq 0$. This gives that  $(x_1)^3-(x_0)^{m_1}(x_1)^{m_2}(x_2)^{m_3}(x_3)^{n_0}(x_4)^{n_1}\cdots (x_{n+3})^{n_{n}} \in \mathcal{I}.$ Since $(x_1)^3\notin \mathcal{I}$, we get  
$m_1+m_2+m_3+\sum_{i=0}^{n}n_i=3$. 

Since $a_n>a_n-{b_1}>a_{n} - b_{2} >a_n - a_0>\cdots>a_n-a_{n-1}$, on comparing the degrees of $s$ in $\mathcal{K}[s,t]$ in equation (\ref{AB}),    we get that $3(a_n-b_1)\neq a_n+(a_n-b_1)+c$ for $c\in\{a_n,a_n-{b_1} ,a_{n} - b_{2} ,a_n - a_i, i = 0, \ldots, n \}$. Moreover, we have $3(a_n-b_1)>a_n+2(a_n-b_2).$ So  the equality $3(a_n-b_1)=2a_n+c$ with $c\in \{a_n,a_n-{b_1} ,a_{n} - b_{2} ,a_n - a_i, i = 0, \ldots, n \} \implies 3(a_n-b_1)-2a_n \geq 0 \implies n \geq r'+1$ which gives a contradiction. Therefore, $s^{3a_n-3b_1}t^{3b_1} \notin(s^{a_n})$ but $s^{3a_n-3b_1}t^{3b_1}.t^{a_n} \in (s^{a_n})$ by Proposition \ref{lemma-pre1}. Hence  $(s^{a_n})$ is not a primary ideal. Now $H_\mathfrak{m}^0(\mathcal{R}/(s^{a_n}))=(s^{3a_n-3b_1}t^{3b_1}) \neq 0$ by \cite[Proposition $3.13$]{4} which implies that $\mathcal{R}/(s^{a_n})$ is not a Cohen Macaulay ring. Consequently, $\mathcal{R}$ is not a Cohen Macaulay ring.
      \item Let $r$ be an even number and suppose $s^{3a_n-3b_1}t^{3b_1} \in(s^{a_n})$. Then by similar arguments as  in part (\ref{AC}), we get the equation (\ref{AB}) with $m_1+m_2+m_3+\sum_{i=0}^{n}n_i=3$ and $m_1\neq 0$. Now again using the fact that  $a_n>a_n-{b_1}>a_{n} - b_{2} >a_n - a_0>\cdots>a_n-a_{n-1}$ and  comparing the degrees of $s$ in $\mathcal{K}[s,t]$,   we get  that $(3a_n-3b_1)-a_n$ is an even number but $2a_n-3b_1 \neq 2(a_n-b_1) $ or $2(a_n-b_2)$ or $(a_n-b_1)+(a_n-b_2)$ and also $2a_n-3b_1 > 2(a_n-a_0) $ which gives a contradiction. Thus $s^{3a_n-3b_1}t^{3b_1} \notin(s^{a_n})$ but $s^{3a_n-3b_1}t^{3b_1}.t^{a_n} \in (s^{a_n})$ by Proposition \ref{lemma-pre1} which gives that $(s^{a_n})$ is not a primary ideal. Now $H_\mathfrak{m}^0(\mathcal{R}/(s^{a_n}))=(s^{3a_n-3b_1}t^{3b_1}) \neq 0$ by \cite[Proposition $3.13$]{4} which implies $\mathcal{R}/(s^{a_n})$ is not a Cohen Macaulay ring and so $\mathcal{R}$ is not a Cohen Macaulay ring.
      \end{enumerate}
    \end{proof}
