In this section, we present a method to find the Cohen–Macaulayfication of a projective monomial curve. In  \cite{1}, S. Goto defined the Cohen–Macaulayfication of a Buchsbaum ring under certain conditions. We adopt similar techniques here to obtain the Cohen–Macaulayfication of a projective monomial curve. Let $R$ be a projective monomial curve and let $\mathfrak{M}$ denote its unique homogeneous maximal ideal. By \cite[Theorem 1.1]{6}, we have that $R$ is a $k$-Buchsbaum domain of dimension $2$ for some $k \in \mathbb{Z}^+$ and it admits a Macaulayfication, denoted by $\widetilde{R}$. This implies that $R$ is a generalized Cohen--Macaulay ring. Consequently, there exists a positive integer $n$ such that for every system of parameters $a_1, a_2$ of $R$, we have $(a_{i-1}) : a_i \subseteq (a_{i-1}) : \mathfrak{M}^n \quad \text{for } i = 1, 2; \text{ see \cite{7}.}$
Now, let $a \in \mathfrak{M}^k$ and let the primary decomposition of $(a)$ be given by $(a) = \bigcap Q_i(P_i),$
where each $Q_i(P_i)$ is $P_i$-primary. We Define
$$C(a) = \bigcap_{P_i \neq m} Q_i(P_i).$$

% \\Let $R$ is a Projective monomial curve and $m$ is the unique homogeneous maximal ideal.In the view of \cite[Theorem 1.1]{6} we get $R$ is a $k$-Buchsbaum Domain of $\dim=2$ for some $k\in \mathbb{Z}^+$ and it has a macaulayfication say $\Tilde{R}.$ This gives $R$ is a Generalized Cohen-Macaulay thus there exist a Positive integer $n$ such that for every system of parameters $a_1,a_2$ of $R$, $(a_{i-1}):a_i\subset(a_{i-1}):m^n$ for $i=1,2$ see \cite{7}.
% \\Let $a\in m^k $ and Primary Decomposition of $(a)=\bigcap Q_i(P_i)$ where $Q_i(P_i)$ is $P_i$ Primary. Now define $C(a)=\bigcap_{P_i \neq m} Q_i(P_i)$.
\begin{lemma}\label{4.1}
    If $R$ is $k$-Buchsbaum and $a\in R$  then $R/(a)$ is also $k$-Buchsbaum.
\end{lemma}
\begin{proof}
    Since $R$ is domain, $0 \to R \xrightarrow{a}R\to R/(a)\to 0$ is an exact sequence which induces the exact sequence $0\to H^0_{\mathfrak{M}}(R/(a))\to H^1_{\mathfrak{M}}(R)\to ...$ of local cohomlogy modules and    $\mathfrak{M}^kH^1_{\mathfrak{M}}(R)=0$ hence $\mathfrak{M}^kH^0_{\mathfrak{M}}(R/(a))=0$. Thus $R/(a)$ is $k$-Buchsbaum.
\end{proof}
\begin{lemma}\label{4.2}
 Let $R$ be $k$-Buchsbaum domain and $n\in \mathbb{Z}^+$ be an integer such that for every system of parameters    $a_1,a_2$ of $R$,\begin{equation}\label{trungs-result}
   (a_{i-1}):a_i\subseteq(a_{i-1}):m^n.
 \end{equation}
\begin{enumerate}[(i)]
    \item 
    Let $a,b$ be a system of parameters of $R$ with $b\in \mathfrak{M}^n$ then $C(a)=a:b^t=a:\mathfrak{M}^n$ where $t\geq 1.$ 
   \item $C(a)^2=aC(a).$
\end{enumerate}
\end{lemma}
\begin{proof}
    \begin{enumerate}[(i)]
        \item \label{AD} Let $a,b$ be a system of parameters of $R$ and $b\in \mathfrak{M}^n$. Then $a,b^t$ is a system of parameters for $t\geq 1$. Now using 
        \eqref{trungs-result},
    we have 
        $$(a:b^t)\subseteq (a:\mathfrak{M}^n)\subseteq (a:b)\subseteq (a:b^t) $$
    which gives $(a:b^t)=(a:\mathfrak{M}^n)=(a:b)$  for $t\geq 1.$  
   Then we get $(0:b')=(0:(b')^t)=(0:(\mathfrak{M}')^n)$ in $R/(a)$ where $b'=b/(a)$ and $\mathfrak{M}'=\mathfrak{M}/(a)$ . On the other hand, as $C(a)/(a) = C_{R/(a)}(0)$ and by \cite[Proposition 3.13]{4} we get that  $C_{R/(a)}(0) = H^0_{\mathfrak{M}'}(R/(a))=\bigcup_{r>0}(0:\mathfrak{M}^r)=(0:(\mathfrak{M}')^{n_1})$ for large $n_1\in \mathbb{Z}^+$. Now $(0:(\mathfrak{M}')^{n_1}) \subset (0:(b')^{n_1})=(0:(\mathfrak{M}')^n) \implies  H^0_{\mathfrak{M}'}(R/(a))=(0:(\mathfrak{M}')^n) $. Thus we get $C(a)=a:b=a:\mathfrak{M}^n$ for some $n\in \mathbb{Z}^+.$

\item  It suffices to show that $C(a)^2 \subseteq aC(a)$. Let $f, g \in C(a)$ Then we may express $bf = ax$ and $bg = ay$ for some $x, y \in R$. On the other hand, we have $fg = az$ for some $z \in R$. Hence $a(b^2z) = b^2(fg) = a^2(xy)\implies b^2z = a(xy)$ as $a$ is $R$-regular. Thus $z \in a : b^2$ and consequently $z \in C(a)$ as $C(a) = a : b^2$ from part (\ref{AD}). Therefore $fg \in aC(a)$ and so we have $C(a)^2 \subset aC(a)$ as required.
\end{enumerate}
\end{proof}
Let $Q(R)$ be the total quotinet ring of $R$. It is easy to see that $R\subseteq \tilde{R}\subseteq Q(R)$ where $$\tilde{R}=\{\frac{x}{a};x\in C(a)\}=a^{-1}C(a).$$ 
\begin{lemma}
    Let $R$ be a $k$-Buchsbaum domain and $\Tilde{R}$ as above then
    \begin{enumerate}[(i)]
        \item $\Tilde{R}$ is a subring of $Q(R);$
        \item $\Tilde{R} \cong C(a)$ as $R$ modules.
    \end{enumerate}
\end{lemma}
\begin{proof}
    \begin{enumerate}[(i)]
        \item This follows from Lemma \ref{4.2}.
        \item Let $f:C(a)\to \Tilde{R}$ be the map defined by $f(x)=\frac{x}{a}.$ Then $f$ is the required isomorphism.
    \end{enumerate}
\end{proof}
