\begin{theorem}\label{H}
Let $R$ be a $k$-Buchsbaum domain and let $\tilde{R}$ be as above. Then $$H^1_\mathfrak{M}(R) \cong \Tilde{R}/R.$$ Moreover,  $\Tilde{R}$ is the Macaulayfication of $R.$
\end{theorem}
\begin{proof}
Consider the short exact sequence
\begin{equation}\label{d'}
0 \to R \to \Tilde{R} \to \Tilde{R}/R \to 0.
\end{equation}
Applying the local cohomology functor $H^i_\mathfrak{M}(-)$, we observe that $H^0_\mathfrak{M}(\Tilde{R}/R) = \Tilde{R}/R$,
since $H^0_\mathfrak{M}(\tilde{R}/R) = \mathop\bigcup\limits_{r > 0} (0 : \mathfrak{M}^r)$ and from Lemma \ref{4.2} (\ref{AD}), we have $(0 : \mathfrak{M}^n) = \Tilde{R}/R$ for some $n \in \mathbb{Z}^+$. Now consider the short exact sequence
\begin{equation}\label{a'}
0 \to (a) \to C(a) \to C(a)/(a) \to 0
\end{equation}
where $a$ is a non-zerodivisor in $R$. Since $R \cong (a)$ as $R$-modules, it follows that
\begin{equation}\label{b'}
H^i_\mathfrak{M}(R) \cong H^i_\mathfrak{M}((a)) = H^i_\mathfrak{M}(a) \quad \text{for all } i > 0.
\end{equation}

It is known that $C(a)/(a) = H^0_\mathfrak{M}(R/(a))$ which is an Artinian module of finite length as $R/(a)$ is a $k$-Buchsbaum ring (by Lemma \ref{4.1}). Thus $\dim H^0_\mathfrak{M}(R/(a)) = 0$. Applying $H^i_\mathfrak{M}(-)$ to the exact sequence \eqref{a'} yields
\[
0 \to H^0_\mathfrak{M}(a) \to H^0_\mathfrak{M}(C(a)) \to H^0_m(C(a)/(a)) \to H^1_\mathfrak{M}(a) \to H^1_\mathfrak{M}(C(a)) \to H^1_\mathfrak{M}(C(a)/(a)) = 0.
\]
This implies $H^i_\mathfrak{M}(a) \cong H^i_\mathfrak{M}(C(a))\text{ for } i \geq 2.$
Since $a$ is a non-zerodivisor of both $R$ and $C(a)$, we have  $H^0_\mathfrak{M}(C(a)) = 0$. Now consider the short exact sequence
\begin{equation}\label{a}
0 \to (a) \xrightarrow{f} R \to R/(a) \to 0,
\end{equation}
and the map $R \xrightarrow{g} (a)$ such that $fg(x) = ax$ for $x \in R$. From \eqref{a}, applying $H^i_\mathfrak{M}(-)$ gives
\begin{equation}\label{b}
0 \to H^0_\mathfrak{M}(R/(a)) \to H^1_\mathfrak{M}(a) \xrightarrow{f} H^1_\mathfrak{M}(R) \to H^1_\mathfrak{M}(R/(a)) \to \cdots.
\end{equation}
Since \( g \) is an isomorphism,  we have the following commutative diagram:
 \[
 \begin{tikzcd}
 & H^1_\mathfrak{M}(R) \arrow[dl, "g"'] \arrow[dr, "a"] & \\
 H^1_\mathfrak{M}(a) \arrow[rr, "f"] & & H^1_\mathfrak{M}(R)
 \end{tikzcd}
 \]
 We know that $a \cdot H^1_\mathfrak{M}(R) = 0$ as $a \in \mathfrak{M}^k$. Thus the map $f$ is the zero map. Therefore, from \eqref{b}, we get the exact sequence 
\[
0 \to H^0_\mathfrak{M}(R/(a)) \to H^1_\mathfrak{M}(a) \to 0,
\]
and hence
\begin{equation}\label{c'}
H^0_\mathfrak{M}(R/(a)) \cong H^1_\mathfrak{M}(a) \cong H^1_\mathfrak{M}(R).
\end{equation}

From \eqref{a'}, we have:
\begin{eqnarray*} 0 \to H^0_\mathfrak{M} \left(C(a)/(a)\right) \to H^1_\mathfrak{M}(a) \to H^1_\mathfrak{M}(C(a)) \to 0\\
 \implies 0 \to C(a)/(a) \to H^1_\mathfrak{M}(a) \to H^1_\mathfrak{M}(C(a)) \to 0\\
 \implies 0 \to H^0_\mathfrak{M}(R/(a)) \to H^1_\mathfrak{M}(a) \to H^1_\mathfrak{M}(C(a)) \to 0.
 \end{eqnarray*}
 From \eqref{c'}, we get that   $l(H^0_\mathfrak{M}(R/(a))) = l(H^1_\mathfrak{M}(a))$ and we know that an injective homomorphism between  two  Artinian modules of the same length is an isomorphism.  
Therefore $H^1_\mathfrak{M}(C(a)) = 0.$ Hence, we obtain
\[
H^0_\mathfrak{M}(C(a)) = 0, \quad H^1_\mathfrak{M}(C(a)) = 0, \quad H^i_\mathfrak{M}(C(a)) = H^i_\mathfrak{M}(R) \text{ for } i \geq 2.
\]
Since $\dim C(a) = \operatorname{depth} C(a) = 2$, it follows that $C(a)$ is a Cohen--Macaulay $R$-module. Thus, $\tilde{R}$ is a Cohen--Macaulay $R$-module. Now, applying $H^i_\mathfrak{M}(-)$ to the sequence \eqref{d'}, we get the exact sequence 
\[
0 \to \tilde{R}/R \to H^1_\mathfrak{M}(R) \to 0
\]
which gives the desired isomorphism $H^1_\mathfrak{M}(R) \cong \Tilde{R}/R.$
Now from \cite[Theorem 1.1]{6} we get that $\Tilde{R}$ is the Macaulayfication of $R$.
\end{proof}
