\author{Giacomo Bascape}
\title[Toroidal graph manifolds with small homology are not SU(2)-abelian]{Toroidal graph manifolds with small homology are not SU(2)-abelian}
%\title[]{Small Homology and SU(2)-abelian Graph Manifolds}
%\title[]{Toroidal SU(2)-abelian graph manifold cannot have small homology}

\begin{document}

\begin{abstract}
 We show that if $Y$ is a toroidal closed graph manifold rational homology $3$-sphere with $|H_1(Y;\mathbb{Z})| \le 5$, then there exists an irreducible representation $\fund{Y} \to SU(2)$. 
This answers positively to a conjecture by Baldwin and Sivek \cite[Conjecture 1.5]{InstantoLSpaceAndSplicing} in the case of graph manifolds.
\end{abstract}

\maketitle

\section{Introduction}

In this work we will consider only compact and oriented $3$-manifolds, with or without boundary. A $3$-manifold $Y$ is called \emph{$SU(2)$-abelian} if every representation $\fund{Y}\to SU(2)$ has abelian image. This work is mainly motivated by the following conjecture:
\begin{conj}[\cite{zhang2019remarks}]\label{conj: SU(2)-ab implies HF L-space}
    Let $Y$ be a rational homology $3$-sphere. If $Y$ is $SU(2)$-abelian, then it is an Heegaard Floer L-space.
\end{conj}

Recall that a rational homology $3$-sphere $Y$ is said to be an \emph{Heegaard Floer L-space} if its (hat) Heegaard Floer group is the simplest possible, namely if $\rank \widehat{HF}(Y)=|H_1(Y;\mathbb{Z})|$. Details can be found in \cite{HFdef2} and \cite{HFdef1}.

The prototypical examples of L-spaces are lens spaces. As a lens space has abelian fundamental group, it is $SU(2)$-abelian. Therefore, lens spaces are $3$-manifolds for which Conjecture \ref{conj: SU(2)-ab implies HF L-space} holds. Note that the converse statement does not hold: suppose that $K\subset S^3$ is the alternating pretzel knot of type $P(2,3,7)$. The double cover $\Sigma_2(K)$ of $S^3$ branced along $K$ is an L-space \cite[Proposition 3.3]{alternatingimpliesLpsace}. It is known that $\Sigma_2(K)$ is a Seifert fibred space and by \cite[Theorem 1.2]{Menangerie} it is not $SU(2)$-abelian. Therefore $\Sigma_2(K)$ is an example of an L-space that is not $SU(2)$-abelian. In general, Conjecture \ref{conj: SU(2)-ab implies HF L-space} provides a criterion to decide the $SU(2)$-abelian status of a $3$-manifolds: if $Y$ is not an Heegaard Floer L-space, then we expect $Y$ to be not $SU(2)$-abelian. 

Hanselman, Rasmussen, and Watson proved in \cite[Theorem 7.20]{BorderedHeegaardHomology} that if $Y$ is a prime toroidal rational homology $3$-sphere such that $|H_1(Y;\mathbb{Z})| \le 4$, then $Y$ is not an Heegaard Floer L-space. According to Conjecture \ref{conj: SU(2)-ab implies HF L-space}, such a manifold is expected to be not $SU(2)$-abelian. We prove in Theorem \ref{teo: sigma small then not SU(2)-abelian} that this intuition is correct in the case of graph manifolds. (We remind the reader that lens spaces and $\mathbb{RP}^3 \# \mathbb{RP}^3$ are not toroidal $3$-manifolds, however they are $SU(2)$-abelian graph manifolds.) 
\begin{teo}\label{teo: sigma small then not SU(2)-abelian}
    Let $Y$ be a toroidal graph manifold rational homology $3$-sphere. If $|H_1(Y;\mathbb{Z})| \le 5$, then $Y$ is not $SU(2)$-abelian.
\end{teo}

A similar result to Theorem \ref{teo: sigma small then not SU(2)-abelian} can be found in \cite[Theorem 1.1]{baldwin2024smallheegaardgenussu2} in which it is shown that if $Y$ is a rational homology $3$-sphere with Heegaard genus $2$ and $|H_1(Y;\mathbb{Z})| \in \{1,3,5\}$, then $Y$ is not $SU(2)$-abelian. 

Let us assume that $Y$ is an $SU(2)$-abelian toroidal rational homology $3$-sphere. If $|H_1(Y;\mathbb{Z})|=5$, then, as a consequence of \cite[Corollary 4.10]{SivekBalwinSteinFilling} and \cite{CohenPrimePowerHomology}, the manifold $Y$ is an instanton L-space. According to \cite[Conjecture 7.24]{kronheimer2010knots}, we expect $Y$ to be an Heegaard Floer L-space. As an application of \cite[Theorem 7.20]{BorderedHeegaardHomology}, if $Y$ is a prime toroidal Heegaard Floer L-space with $|H_1(Y;\mathbb{Z})|=5$, then $Y$ is a graph manifold obtained by gluing trefoil exteriors. Therefore, by Theorem \ref{teo: sigma small then not SU(2)-abelian} the manifold $Y$ is not $SU(2)$-abelian.
We conclude that, if $Y$ is any toroidal $3$-manifold with $|H_1(Y;\mathbb{Z})|=5$, then we expect $Y$ to be not $SU(2)$-abelian.
Similarly, if $Y$ is a toroidal manifold with $|H_1(Y;\mathbb{Z})|=6$, then $Y$ is not a Heegaard Floer L-space by \cite[Theorem 7.20]{BorderedHeegaardHomology}. According to Conjecture \ref{conj: SU(2)-ab implies HF L-space}, we expect $Y$ to not be $SU(2)$-abelian. We summarise this by proposing the following as a refinement of \cite[Conjecture 1.5]{InstantoLSpaceAndSplicing}:
\begin{conj}
    Let $Y$ be a toroidal rational homology $3$-sphere. If $|H_1(Y;\mathbb{Z})| \le 6$, then $Y$ is not $SU(2)$-abelian.
\end{conj}

We now give an outline of the technique we will use in this work. Let $Y_1$ and $Y_2$ be two $3$-manifolds with torus boundary. Let $\Sigma$ be a separating torus in a closed $3$-manifold $Y$. If the torus $\Sigma \subset Y$ is such that 
\[
    \overline{Y \setminus \Sigma} = Y_1 \cup Y_2,
\]
then we say that $Y=Y_1 \cup_{\Sigma} Y_2$.
Let us assume that $Y=Y_1\cup_{\Sigma}Y_2$. We define $\R{\Sigma}$ as $\text{Hom}(\fund{\Sigma},\Ui)$, where $\Sigma$ is the torus in $Y$ corresponding to $\partial Y_1=\partial Y_2$. Furthermore, we define $T(Y_i,\partial Y_i) \subset \R{\Sigma}$ as the set of representations $\fund{\Sigma}\to \Ui$ that extend to a representation $\fund{Y_i} \to SU(2)$, we call $T(Y_i,\partial Y_i)$ the \emph{$\Ui$-representation space of $ Y_i$ relative to $\partial Y_i$}.
As a consequence of \cite[Theorem 3.7]{Mino}, the $SU(2)$-abelian status of $Y=Y_1 \cup_{\Sigma} Y_2$ is completely determined by the intersection
\begin{align}\label{eq: una volta intersezione}
    T(Y_1,\partial Y_1)\cap T(Y_2,\partial Y_2) \subset \R{\Sigma}.
\end{align}
Details can be found in Section \ref{sec: review of T(Y,Y)}. Therefore, we prove Theorem \ref{teo: sigma small then not SU(2)-abelian} by assuming that $Y=Y_1\cup_{\Sigma}Y_2$ and by studying $T(Y_1,\partial Y_1)$, $T(Y_2,\partial Y_2)$, and the intersection in \eqref{eq: una volta intersezione}.

Let $Y$ be a graph manifold rational homology $3$-sphere. We shall prove in 
Corollary \ref{cor: the usefull decomposition}
that there exists a system $\tau \subset Y$ of disjoint embedded tori that cuts $Y$ in simple pieces. Namely,
\[
    \overline{Y \setminus \tau} = \left( \cup C_3 \right) \cup \left( \cup C_2 \right) \cup \left( \cup D_\ast, \right)
\]
where $C_3$ is a 3D pair of pants (i.e. the exterior of the link in Figure \ref{fig:Link}), $C_2$ is the twisted I-bundle over a punctured Mo\"ebius band, and $D_\ast$ is a Seifert fibred space which admits a Seifert fibration with disk base space. The notation for Seifert fibred spaces can be found in Subsection \ref{subsection: SFS}.
We shall describe in details the pieces $C_2$ and $C_3$ in Section \ref{sec: two important pieces}.
The space $C_3$ has three torus boundary components, we call them $\Sigma_1$, $\Sigma_2$, and $\Sigma_3$. Similarly, $C_2$ has two of these and we call them $\Sigma_1'$ and $\Sigma_2'$. Two crucial results of this work are Theorem \ref{teo: alg for C3} and Theorem \ref{teo: alg for C2}. In the first one we describe the space $T(Y,\partial Y) \subset \R{\Sigma_3}$, where $Y=Y_1 \cup_{\Sigma_1} C_3 \cup_{\Sigma_2} Y_2$ is the $3$-manifold with torus boundary as in Figure \ref{Figure: the manifold Y1 C3 Y2}, from the data
\[
    T(Y_1,\partial Y_1) \subset \R{\Sigma_1} \quad \text{and} \quad  T(Y_2,\partial Y_2) \subset \R{\Sigma_2}.
\]
Similarly, Theorem \ref{teo: alg for C2} describes the space $T(Y,\partial Y) \subset \R{\Sigma_2'}$, where $Y=Y_1 \cup_{\Sigma_1'} C_2$ is the $3$-manifold with torus boundary as in Figure \ref{Figure: the manifold Y1 C2}, from the description of $T(Y_1,\partial Y_1) \subset \R{\Sigma_1'}$.

Here are a couple of results that the author finds interesting.
Let $Y_1 \neq S^1 \times \mathbb{D}^2$ and $Y_2\neq S^1 \times \mathbb{D}^2$ be two $3$-manifolds with torus boundary, we denote by
$\lambda_i \subset \partial Y_i$ the rational longitude of $Y_i$. We call $o_i \in \mathbb{N}$ the order of $\lambda_i$ in $H_1(Y_i;\mathbb{Z})$.
Let $o_1 =1$, $o_2 \in \{1,3\}$, and $Y$ be the result of gluing $Y_1$ and $Y_2$ in a such way that $\geo{\lambda_1}{\lambda_2}=1$.
According to \cite[Theorem 1.1]{boyer2023slopedetectiontoroidal3manifolds} and \cite[Theorem 1.3]{boyer2023slopedetectiontoroidal3manifolds}, the manifold $Y$ is not an $L$-space.
The proof of the Theorem \ref{teo: sigma small then not SU(2)-abelian} naturally leads us to the following propositions, which state that such a $Y$ is not $SU(2)$-abelian, as suggested by Conjecture \ref{conj: SU(2)-ab implies HF L-space}.

\begin{prop}\label{prop: sigma =1 ish}
     Let $Y_1$ and $Y_2$ be two graph rational with torus boundary and null-homologous rational longitudes. If neither $Y_1$ nor $Y_2$ is a solid torus and $Y=Y_1 \cup_{\Sigma} Y_2$ is a rational homology sphere such that $\Delta(\lambda_1,\lambda_2)= 1$, then $Y$ is not $SU(2)$-abelian.
\end{prop}

\begin{cor}\label{cor: o1=1 and o2=3 and delta=1}
    Let $Y_1$ and $Y_2$ be two graph manifolds with torus boundary. If neither $Y_1$ nor $Y_2$ is a solid torus, $o_1=1$, $o_2=3$, and $Y=Y_1 \cup_{\Sigma} Y_2$ is a rational homology sphere such that $\Delta(\lambda_1,\lambda_2)= 1$, then $Y$ is not $SU(2)$-abelian.
\end{cor}

