\section{Notation}
\label{sec: notation}
Recall that for any irreducible orientable $3$-manifold $Y$, there is minimal collection $\mathscr{T}$ of properly embedded disjoint essential tori such that each component of $Y \setminus \mathscr{T}$ is either a hyperbolic or a Seifert fibred manifold, and such a collection is unique up to isotopy (see \cite{Jaco1979SeifertFS}). The \emph{JSJ decomposition} of $Y$ is given by
\[
Y= Y_0 \sqcup \cdots \sqcup Y_n
\]
where each $Y_i$ is the closure of a component of $Y \setminus \mathscr{T}$. A manifold $Y_i$ is called a \emph{JSJ piece} of $Y$ and a torus in the collection $\mathscr{T}$ is called a \emph{JSJ torus} of $Y$.

\begin{defn}
    Let $Y$ be a compact, irreducible, and orientable $3$-manifold. We said that $Y$ is a graph manifold if every of its JSJ piece if a Seifert fibred manifold.
\end{defn}

Let $M$ be a manifold with torus boundary. A (rational) slope on the boundary $M$ is an element $[\alpha]$ of the projective space of $H_1(\partial M;\mathbb{Q})$, where $\alpha \in H_1(\partial M;\mathbb{Q}) \setminus \{ 0 \} $. Slopes can be identified as either
 \begin{itemize}
     \item a $\pm$-pair of primitive elements of $H_1(\partial M; \mathbb{Z})\equiv \fund{\partial M}$;
    \item a $\partial M$-isotopy class of essential simple closed curves on $\partial M$. 
 \end{itemize}
For further details, see \cite[Subsection 4.2]{boyer2022orderdetection}.

Let $\Sigma$ be a torus, and $\{\mu,\lambda\}$ a basis of $H_1(\Sigma;\mathbb{Z})$. We use the convention, depending on the choice of the basis $\{\mu,\lambda\}$, such that an element $\nicefrac{p}{q} \in \mathbb{Q}\cup \{\nicefrac{1}{0}\}$ corresponds to the slope $p \mu + q \lambda \in H_1(\Sigma;\mathbb{Z})$. The \emph{distance} between two slopes $\nicefrac{p}{q}$ and $\nicefrac{r}{s}$ is $\Delta(\nicefrac{p}{q},\nicefrac{r}{s})=|ps-rq|$ and it corresponds to the absolute value of the algebraic intersection number between curves representing $\nicefrac{p}{q}$ and $\nicefrac{r}{s}$.

If $Y$ is a compact $3$-manifold with toroidal boundary components $\Sigma_1, \cdots, \Sigma_n$ with fixed bases $\{\mu_i,\lambda_i\}$ for each $H_1(\Sigma_i;\mathbb{Z})$, then
\[
    Y\left(\Sigma_1, \cdots, \Sigma_n;\nicefrac{r_1}{s_n},\cdots \nicefrac{r_n}{s_n}\right)
\]
denotes the closed $3$-manifold obtained by performing Dehn fillings along a simple closed curve representing $\nicefrac{r_i}{s_i}$ on $\Sigma_i$ for each $i=1,\cdots, n$. Moreover, if $Y$ has torus boundary and $\alpha \subset \partial Y$ is a slope, we make the notation lighter by defining
\[
    Y\left(\alpha\right) \coloneq Y(\partial Y;\alpha).
\]

Let $Y$ be a $3$-manifold with torus boundary, we define the \emph{rational longitude} of $Y$ as the unique slope $\lambda_{Y} \subset Y$ such that $[\lambda_{Y}]$ is a torsion element of $H_1(Y; \mathbb{Z})$.
In order to make the notation lighter, if $Y_i$ is a $3$-manifold with torus boundary, then, when it is not confusing, we denote by $\lambda_i \subset \partial Y_i$ the rational longitude of $Y_i$ and by $o_i$ the order of $\lambda_i$ in $H_1(Y_i;\mathbb{Z})$.

The subgroup of $SU(2)$ made of the diagonal matrices is called $\Ui$. In order to make the notation a little lighter, when not confusing, we use the following notation:
\[
e^{i\theta} \coloneqq
\begin{bmatrix}
    e^{i\theta} & 0 \\ 0 & e^{-i\theta}
\end{bmatrix} \in \Ui \le SU(2).
\]

Let $z$ be a non-central element of $SU(2)$. We denote by $\Lambda_z \subset SU(2)$ the centralizer subgroup of the element $z$. The subgroups $\Lambda_z$ and $\Ui$ are known to be conjugate in $SU(2)$, details can be found in \cite[Lecture 13]{saveliev}. The following is well known.
\begin{fact}\label{Fact: centralizers}
Let $x,y$ be two non-central elements of $SU(2)$. The elements $x$ and $y$ commute if and only if the two centralizer subgroups $\Lambda_x$ and $\Lambda_y$ coincide.
\end{fact}

\subsection{Seifert fibred spaces}\label{subsection: SFS}
A compact space $Y$ is said to be a \emph{Seifert fibred space}, or
\emph{Seifert fibred manifold},
if there exists a collection of pairwise disjoint circles $f_\alpha \subset Y$, which are called \emph{fibers}, such that
\[
    Y = \bigcup_{\alpha} f_\alpha,
\]
and every fiber $f_\alpha$ admits a tubular neighbourhood in $Y$ that is union of fibers. We call such a tubular neighbourhood a \emph{fibred neighbourhood}.

Every fiber $f_\alpha$ is associated with an invariant called \emph{order} that counts how many times any other close by fiber wraps around $f_\alpha$.
A fiber of order one is called \emph{regular fiber} and the ones with order $2$ or greater are called \emph{singular fibers}.
A compact Seifert fibred space admits finite many singular fibers.

\begin{defn}
    Let $Y$ be a Seifert fibred space and let $S \subset Y$ be an embedded or immersed surface. We say that $S$ is \emph{vertical} if it is union of fibers of $Y$.
\end{defn}

Let $Y$ be a Seifert fibred space. It can be proven that 
\[
    Y/\sim \quad \text{with} \quad x\sim y \text{ if and only if }x,y \in f_\alpha,
\]
is a $2$-dimensional \emph{orbifold} $\mathcal{B}$ with a number of cone points equal to the number of the singular fibers, each of order equal to the order of the corresponding singular fiber.
We give \cite{ScottGoemtries} and \cite{orbifold} as references for the concept of orbifold.
Let $B$ be underlying surface of the orbifold $\mathcal{B}$ and $\{p_1,\cdots, p_n\}$ the orders of its cone points. The orbifold $\mathcal{B}$ is sometimes denoted by
\[
    B(p_1,\cdots,p_n).
\]
We say that $Y$ is \emph{Seifert fibred} over the orbifold $\mathcal{B}=B(p_1,\cdots,p_n)$ and, when the Seifert fibration of $Y$ is fixed, that $B$ is the \emph{base space} of $Y$. To be even more accurate, when we say that $Y$ has base space $B$ we mean that there exists a Seifert fibration of $Y$ whose base space is $B$.

Let $n\ge 1$. A Seifert fibred manifold with $n$ singular fibers can be described from the surface $B$ and a set of fraction $\{\nicefrac{p_1}{q_n}, \cdots, \nicefrac{p_n}{q_n}\}$, where $p_i$ is the order of the $i^th$ singular fiber. We call the fraction $\nicefrac{p_i}{q_i}$ a \emph{Seifert coefficient} of $Y$. We can therefore write
\[
    Y= B\left(\frac{p_1}{q_1},\cdots, \frac{p_n}{q_n}\right).
\]
In this case, $Y$ is Seifert fibred over the orbifold $B(p_1,\cdots,p_n)$ and has base space $B$.
Details, can be found in \cite[Section 10.3.2]{martelli}.

\section{A taste of \texorpdfstring{$T(Y,\partial Y)$}{T(Y,Y)}}
\label{sec: review of T(Y,Y)}

We recall various definitions from \cite{Mino}.
Let $\Sigma$ be a torus, we define the space $\R{\Sigma}$ as $\text{Hom}(\fund{\Sigma},\Ui)$. The space $\R{\Sigma}$ it is diffeomorphic to $S^1 \times S^1$.
Let $\{x,y\} $ be an ordered basis of $\fund{\Sigma}$. We give the space $\R{\Sigma}$ coordinates $(\theta,\psi)$ according to this basis in the following way:
the point $(\theta,\psi) \in \R{\Sigma}$ corresponds to the unique representation $\fund{\Sigma} \to \Ui$ such that
\begin{equation}\label{eq: general coordinates}
    x \mapsto e^{i\theta} \quad \text{and} \quad y\mapsto e^{i \psi}.
\end{equation}

Let $Y$ be a $3$-manifold with boundary, define $R(Y)$ as $\text{Hom}(\fund{Y},SU(2))$. The \emph{representation space of $Y$ relative to $\partial Y$}, by $T(Y,\partial Y)$ denoted, is defined as the set of representations $\fund{\partial Y} \to \Ui$ that extend to an $SU(2)$-representation of $\fund{Y}$.
By definition, there in an inclusion $T(Y,\partial Y) \subset \R{\partial Y}$.

\begin{defn} \label{defn: A1 H1 e P1}
    Let $Y$ be a $3$-manifold with torus boundary, let $\iota \colon \partial Y \to Y$ be the topological natural inclusion. We define the sets $A(Y), H(Y)$, and $P(Y)$ as:
    \begin{alignat*}{2}
        A(Y)& \coloneqq \left\{ \eta \in \R {\partial Y} \,\middle|\, \exists \rho \in R(Y) \text{ such that } \restr{\rho}{\iota_\ast \fund{\partial Y}}\equiv \eta\text{ and $\rho$ is abelian} \right\}, \\
        H(Y)& \coloneqq \left\{ \eta \in \R{\partial Y} \,\middle|\, \exists \rho \in R(Y) \text{ such that } \restr{\rho}{\iota_\ast \fund{\partial Y}}\equiv \eta\text{ and $\rho$ is irreducible} \right\}, \\
        P(Y)& \coloneqq \Big\{ \eta \in \R{\partial Y} \,\Big|
            \begin{aligned}[t]
            &\exists \rho \in R(Y) \text{ such that } \restr{\rho}{\iota_\ast \fund{\partial Y}}\equiv \eta,\\
            &\text{$\eta$ is central, and $\rho$ is abelian and noncentral} \Big\}.
    \end{aligned}
    \end{alignat*}
\end{defn}
Equivalently, a representation $\fund{\partial Y} \to \Ui$ is in $A(Y$ (resp. $H(Y)$) if and only if it extends to an abelian (resp. an irreducible) representation $\fund{Y} \to SU(2)$. Similarly, a representation $\fund{\partial Y} \to \ZSU$ is in $P(Y)$ if and only if it extends to an abelian representation $\fund{Y} \to SU(2)$ whose image is not in $\ZSU$. 
Notice that $P(Y) \subset A(Y)$ and $A(Y)\cup H(Y)=T(Y,\partial Y) \subseteq \R{\partial Y}$.

\begin{cor}[{\cite[Corollary 3.9]{Mino}}]\label{cor: A(Y) with rational longitude}
    Let $Y$ be a $3$-manifold with torus boundary. Then
    \[
    A(Y)= \left\{\eta \in \R{\partial Y} \middle| \eta(\lambda_Y)^{o_Y}=1\right\} \subset \R{\partial Y}.
\]
\end{cor}

If $Y=Y_1 \cup_{\Sigma} Y_2$, then in $Y$ the tori $\partial Y_1$  and $\partial Y_2$ are both equal to $\Sigma$. Therefore, $T(Y_1,\partial Y_1)$ and $T(Y_2,\partial Y_2)$ are both subsets of the variety $\R{\Sigma}$. This implies that the intersection $T(Y_1,\partial Y_1) \cap T(Y_2,\partial Y_2)$ is well defined in $\R{\Sigma}$. Hence we have the following result:

\begin{teo}[{\cite[Theorem 3.7]{Mino}}]\label{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}
    Let $Y_1$ and $Y_2$ be two $3$-manifolds with torus boundary. The manifold $Y=Y_1 \cup_{\Sigma} Y_2$ is $SU(2)$-abelian if and only if $H(Y_1)\cap H(Y_2)$, $H(Y_1) \cap A(Y_2)$, $A(Y_1) \cap H(Y_2)$, and $P(Y_1) \cap P(Y_2)$ are empty.
\end{teo}

\begin{cor}[{\cite[Corollary 3.11]{Mino}}]\label{cor: Y SU(2) allora i due pezzi sono SU(2)-abelian}
    If the manifold $Y = Y_1 \cup_{\Sigma} Y_2$ is $SU(2)$-abelian, then the manifold $Y_1(\lambda_2)$
    is $SU(2)$-abelian.
\end{cor}

Next Lemma was previously proven in \cite{LinHolonomyPerturbation} with a different notation, we report the proof for the sake of completeness.

\begin{lemma}\label{lemma: translation}
    Let $Y$ be a rational homology solid torus with torus boundary such that the rational longitude $\lambda_Y$ has odd order $o_Y$. Let $\xi$ be a slope such that $\{\xi,\lambda_Y \}$ is a basis for $\fund{\partial Y}$. Let $\R{\partial Y}$ be given with coordinates $(\theta,\psi)$ according to this ordered basis as in \eqref{eq: general coordinates}.
    The sets $A(Y)$ and $H(Y)$ are invariant, as subsets of $\R{\partial Y}$, by translation of vector $(\pi,0)$ with respect to the $(\theta,\psi)$-coordinates.
    \begin{proof}
        Since $Y$ is a rational homology solid torus, we have that
        \[
            H_1(Y;\mathbb{Z}) = \mathbb{Z} \oplus \text{Torsion}\quad \text{and} \quad \frac{H_1(Y;\mathbb{Z})}{\text{Torsion}}= \mathbb{Z}.
        \]
        Let $p \colon \fund{Y} \to \mathbb{Z}$ be the composition of the abelianitation map $\fund{Y} \twoheadrightarrow H_1(Y;\mathbb{Z})$ and the quotient map $H_1(Y;\mathbb{Z}) \twoheadrightarrow H_1(Y;\mathbb{Z})/\text{Torsion}$. The homeomorphism $p$ is surjective.

        Let $z \in \mathbb{Z}$ be a generator of $\ima p$.
        A standard homology computation shows that $p(\xi)=o_Y \cdot z \in \ima p$ and that $p(\lambda_Y)=0$.
        \iffalse
        Since $p(\lambda_Y)=0$, $p$ is surjective, and $o_Y=1$,
        the image of $p$ is generated by $p(\xi)$. Thus, $H_1(Y;\mathbb{Z})/\text{Torsion}= p(\xi)\cdot \mathbb{Z}$.
        \fi
        We define the homomorphism
        \[
            \omega \colon \frac{H_1(Y;\mathbb{Z})}{\text{Torsion}}=\ima{p} \to \{\pm 1\} \quad \text{by} \quad n \cdot z \mapsto (-1)^n.
        \]
        Let $\chi \colon \fund{Y} \to \{\pm 1\} = \ZSU$ be the composition $\omega \circ p$. We notice that $\chi(\xi)=\chi(z)^{o_Y}=-1$ and that $\chi(\lambda_Y)=1$.

        Let $\eta$ be a representation in $A(Y)$ (resp. $H(Y)$), then there exists an abelian (resp. irreducible) representation $\rho \in R(Y)$ such that $\restr{\rho}{\fund{\partial Y}} \equiv \eta$. Let us assume that $\eta \in \R{\partial Y}$ has coordinates $(\theta_0,\psi_0) \in [0,2\pi]^2$.
        We define $\rho' \colon \fund{Y} \to SU(2)$ by the multiplication
        \[
            x \mapsto \chi(x) \rho(x).
        \]
        Clearly, $\rho' \in R(Y)$ and it is abelian (resp. irreducible) if and only if $\rho$ is abelian (resp. irreducible). Thus, $\restr{\rho'}{\fund{\partial Y}}$ is a point of $A(Y)$ (resp. $H(Y)$). We notice that
        \[
        \rho'(\lambda_Y)=\rho(\lambda_Y)=e^{i\psi_0} \quad \text{and} \quad\rho'(\xi)=-\rho(\xi) = e^{i \pi} e^{i\theta_0}=e^{i (\pi + \theta_0)}.
        \]
        Thus, if $(\theta_0,\psi_0)$ is a point of $A(Y)$ (resp. $H(Y)$), then $(\theta_0 + \pi,\psi_0)$ is a point of $A(Y)$ (resp. $H(Y)$).
    \end{proof}
\end{lemma}

\begin{defn}\label{defn: jewelled representation}
    Let $G$ be a group and $H$ a linear group \footnote{A linear group is a group of invertible matrices over a given field and with the operation of matrix multiplication.}. For a given matrix $M$, we denote by $M^\top$ the transpose of a $M$. Let $\rho \colon G \to H$ be a representation. We define the \emph{jewelled representation} $\rho^\dagger : G \to H$ as
    \[\rho^\dagger(x)=\left(\rho(x)^{-1}\right)^\top = \left(\rho(x)^{\top}\right)^{-1}.
    \]
\end{defn}

In the following we assume that $Y$ is a $3$-manifold with torus boundary and that an ordered basis $\{x_1,x_2\}$ for $\fund{\partial Y}$ is given. Therefore, we parameterize $\R{\partial Y}$ with coordinates $(\theta,\psi)$ as in \eqref{eq: general coordinates} according to this ordered basis.

\begin{cor}\label{cor: jewelled repr}
    Let $Y$ be a $3$-manifold with torus boundary. If $(\theta_0,\psi_0) \in T(Y,\partial Y) \subset \R{\partial Y}$, then $(2\pi - \theta_0,2\pi-\psi_0) \in T(Y,\partial Y) \subset \R{\partial Y}$. In particular, if $(\theta_0,\psi_0)$ is in either $H(Y)$, $A(Y)$, or $P(Y)$, then $(2\pi - \theta_0,2\pi-\psi_0)$ is in either $H(Y)$, $A(Y)$, or $P(Y)$ respectively.
    \begin{proof}
        Let $\eta \colon \fund{\partial Y} \to \Ui$ be the representation corresponding to $(\theta_0,\psi_0)$. Let $\rho\colon \fund{Y} \to SU(2)$ the extension of $\eta$.
        The jewelled representation $\rho^\dagger$ is such that
        \[
        \restr{\rho^\dagger}{\fund{\partial Y}} = \eta^\dagger.
        \]
        In particular, $\eta^\dagger \in T(Y,\partial Y)$. Moreover, since $\eta(x_1)$ and $\eta(x_2)$ are diagonal matrices,
        \[
            \eta^\dagger(x_1)=\left(e^{i \theta_0}\right)^{-1}=e^{i (2\pi - \theta_0)} \quad \text{and} \quad  \eta^\dagger(x_2)=\left(e^{i \psi_0}\right)^{-1}=e^{i (2\pi - \psi_0)}.
        \]
        Therefore, $(2\pi-\theta_0,2\pi -\psi_0) \in T(Y,\partial Y) \subset \R{\partial Y}$. It is easy to see that $\rho^\dagger$ is abelian (resp. irreducible, resp. abelian and non central) if and only if $\rho$ is abelian, (resp. irreducible, resp. abelian and non central).
    \end{proof}
\end{cor}

\section{Two important ingredients}
\label{sec: two important pieces}

Let $L \subset S^3$ be the $3$-components link obtained as the connected sum of two Hopf links. The link $L$ is represented in Figure \ref{fig:Link}.
\begin{figure}
    \centering
    \includegraphics[width=0.3\linewidth]{Link.pdf}
    \caption{The connected sum of two Hopf links.}
    \label{fig:Link}
\end{figure}
We define $C_3$ as the closed manifold $S^3 \setminus \nu(L)$, where $\nu(L)$ is an open tubular neighborhood of the link $L$. The manifold $C_3$ is some times called \emph{3D pair of pants}.

Another way to see $C_3$ is what follow. Let $\mathbb{D}^2$ be a closed disk of radius $1$. Let $D_1$ and $D_2$ be two open disks of $\mathbb{D}^2$, each of radius $\nicefrac{1}{4}$ and centered in $(0,\nicefrac{1}{2})$ and $(0,-\nicefrac{1}{2})$ respectively. The manifold $C_3$ is
\[
    C_3 = \left(\mathbb{D}^2 \times S^1\right) \setminus (D_1 \cup D_2) \times S^1 = \left(\mathbb{D}^2 \setminus (D_1 \cup D_2) \right) \times S^1.
\]

The manifold $C_3$ is a Seifert fibred manifold with fundamental group equal to
\begin{equation}\label{eq: fundamental group C3}
    \fund{C_3} = \left\langle x_1,x_2,x_3,h \middle| [x_j,h], x_1x_2=x_3\right\rangle,
\end{equation}
where $h$ is a regular fiber of the fibration and $[x,y]$ denotes the commutator element.

The manifold $C_3$ has three toridal boundary components, namely $\Sigma_1$, $\Sigma_2$, and $\Sigma_3$. For $j \in \{1,2,3\}$, the ordered basis $\{x_j,h\}$ generates the fundamental group $\fund{\Sigma_j}$. We give coordinates $(\theta_j,\psi_j)$ to the variety $\R{\Sigma_j}$ as in \eqref{eq: general coordinates}:
the point $(\theta_j,\psi_j) \in \R{\Sigma_j}$ corresponds to the unique representation $\fund{\Sigma_j} \to \Ui$ such that
\begin{equation}\label{eq: coordinates for C3}
    x_j \mapsto e^{i\theta_j} \quad \text{and} \quad h\mapsto e^{i \psi_j}.
\end{equation}

\begin{notation}
    When using $C_3$, we call $h$ the regular fiber of $C_3$. When $h$ is considered in $\Sigma_j$, we call it $h_j$ for $j \in \{1,2,3\}$.
\end{notation}

We define $C_2$ as the twisted I-bundle over the M\"obius band.
The manifold $C_2$ is a Seifert fibred manifold with fundamental group equal to
\begin{equation}\label{eq: fundamental group C2}
    \fund{C_2} = \left\langle x_1,x_2,z,h \middle| [x_j,h], x_1x_2z^2, zhz^{-1}h\right\rangle,
\end{equation}
where $h$ is the regular fiber of the fibration.

The manifold $C_2$ has two toridal boundary components, namely $\Sigma_1'$, $\Sigma_2'$. For $j \in \{1,2\}$, the ordered basis $\{x_j,h\}$ generates the fundamental group $\fund{\Sigma_j'}$. As before, we give coordinates $(\theta_j,\psi_j)$ to the variety $\R{\Sigma_j'}$ as in \eqref{eq: general coordinates}:
the point $(\theta_j,\psi_j) \in \R{\Sigma_j'}$ corresponds to the unique representation $\fund{\Sigma_j'} \to \Ui$ such that
\begin{equation}\label{eq: coordinates for C2}
    x_j \mapsto e^{i\theta_j} \quad \text{and} \quad h\mapsto e^{i \psi_j}.
\end{equation}

\begin{notation}
    When using $C_2$ we call $h$ the regular fiber of $C_2$. When $h$ is considered in $\Sigma_j'$, we call it $h_j$ for $j \in \{1,2\}$.
\end{notation}

Let $Y_1$ and $Y_2$ be two manifolds with torus boundary. When we write $Y=Y_1 \cup_{\Sigma_1} C_3 \cup_{\Sigma_2} Y_2$, we mean that $Y$ is a manifold with torus boundary admitting two embedded tori $\Sigma_1$ and $\Sigma_2$ such that
\[
    \overline{Y \setminus (\Sigma_1 \cup \Sigma_2)}= Y_1 \cup C_3 \cup Y_2.
\]
In particular $\partial Y = \Sigma_3 \subset \partial C_3$. Figure \ref{Figure: the manifold Y1 C3 Y2} shows the manifold $Y=Y_1 \cup_{\Sigma_1} C_3 \cup_{\Sigma_2} Y_2$.

Similarly, when we write $Y=Y_1 \cup_{\Sigma_1'} C_2$, we mean that $Y$ is a manifold with torus boundary admitting an embedded torus $\Sigma_1$ such that
\[
    \overline{Y \setminus \Sigma_1'}= Y_1 \cup C_2.
\]
Figure \ref{Figure: the manifold Y1 C2} shows the manifold $Y=Y_1 \cup_{\Sigma_1'} C_2$.
In particular $\partial Y = \Sigma_2' \subset \partial C_2$.

\begin{rmk}[{\cite[Lemma 7.1]{LSpaceTautFoliationsAndGraphManifolds}}]\label{rmk: order of toroidal}
    Let $Y=Y_1 \cup_{\Sigma} Y_2$ be a rational homology $3$-sphere.
    We obtain that
        \begin{align*}
        \left|H_1(Y;\mathbb{Z})\right|=o_1o_2t_1t_2 \geo{\lambda_1}{\lambda_2},
        \end{align*}
    where $o_i$ is the order of $\lambda_i$ in $H_1(Y_i,\mathbb{Z})$ and $t_i$ is the order of the torsion subgroup of $H_1(Y_i,\mathbb{Z})$. In particular $o_i$ divides $t_i$.
\end{rmk}

\begin{lemma}\label{lemma orders and torsion of C3}
    Let $Y_1$, $Y_2$, and $Y=Y_1 \cup_{\Sigma_1} C_3 \cup_{\Sigma_2} Y_2$ be rational homology solid tori with torus boundary. If $H_1(Y;\mathbb{Z})$ has the torsion subgroup of order one, then both $H_1(Y_1;\mathbb{Z})$ and $H_1(Y_2;\mathbb{Z})$ have torsion subgroup of order one. In particular, $\lambda_1$ and $\lambda_2$ are both null-homologous.
        \begin{proof}
            We denote by $\lambda_Y \subset \Sigma_3 = \partial Y$ the rational longitude of $Y$, by $o_Y$ its order in $H_1(Y;\mathbb{Z})$ and by $t_Y$ the order of the torsion subgroup of $H_1(Y;\mathbb{Z})$. 
            By hypothesis $t_Y=1$. Remark \ref{rmk: order of toroidal} states that $o_Y$ divides $t_Y$. Therefore $o_Y=1$.
            Similarly, for $i \in \{1,2\}$, we denote by $\lambda_i$, $o_i$, and $t_i$ the rational longitude of $Y_i$, its order in $H_1(Y_i;\mathbb{Z})$ and the order of the torsion subgroup of $H_1(Y_i;\mathbb{Z})$ respectively.

            The product $\geo{\lambda_1}{h_1}\geo{\lambda_2}{h_2}$ is either zero or non zero. We split the proof is these two cases.

            Let us assume that $\geo{\lambda_1}{h_1}\geo{\lambda_2}{h_2}=0$. Without loss of generality, we assume that $\geo{\lambda_1}{h_1}=0$.
            A standard homology computation shows that the regular fiber $h_3 \subset \Sigma_3$ is the rational longitude of $Y$.
            With an abuse of notation, we call $x_3 \subset \Sigma_3$ be the slope whose homotopy class is
            \[
                x_3 \in \fund{C_3}.
            \]
            Therefore $\geo{h_3}{x_3}=1$.
            This implies that $Y(x_3)$ is a rational homology $3$-sphere.
            Remark \ref{rmk: order of toroidal} states that
            \[
            \left|H_1(Y(x_3);\mathbb{Z})\right| =o_Yt_Y\geo{\lambda_Y}{x_3}=1.
            \]

            It is straightforward to see that $C_3(\Sigma_3;x_3)$ is homeomorphic to $S^1 \times S^1 \times [0,1]$. Thefore,
             there exists a diffeomorphism $\varphi \colon \partial Y_1 \to \partial Y_2$ such that
            \[
            Y(x_3) = Y_1 \cup_{\varphi} Y_2.
            \]
            Again, Remark \ref{rmk: order of toroidal} implies that
            \[
            1 = \left|H_1(Y(x_3);\mathbb{Z})\right| = \left|H_1(Y_1 \cup_{\varphi} Y_2;\mathbb{Z})\right| = o_1t_1o_2t_2 \geo{\lambda_1}{\lambda_2}.
            \]
            This latter implies that $t_1=t_2=1$ and, since $o_i$ divides $t_i$, that $o_1=o_2=1$.

            Let us assume that $\geo{\lambda_1}{h_1}\geo{\lambda_2}{h_2} \neq 0$. For $i \in \{1,2\}$, let  $n_i,m_i$ be integers such that
            \[
                \lambda_1=n_1 x_1 + m_1 h_1 \subset \Sigma_1 \quad \text{and} \quad \lambda_2=n_2 x_2 + m_2 h_2 \subset \Sigma_2.
            \]
            Since $\geo{\lambda_1}{h_1}\geo{\lambda_2}{h_2} \neq 0$, the integers $n_1$ and $n_2$ are not null.
            Let us set $g=\gcd(n_1,n_2)$. Let $\sigma \subset \Sigma_3$ be the slope
            \[
                \sigma\coloneqq \frac{n_1 n_2}{gk} x_3 + \frac{n_1 m_2+n_2 m_1}{gk} h_3 \subset \Sigma_3 \quad \text{with} \quad k = \gcd \left( \frac{n_1n_2}{g}, \frac{n_1 m_2+n_2 m_1}{g}\right).
            \]
            It is easy to see that in $H_1(Y;\mathbb{Z})$, the element  $(o_1o_2k) \cdot \sigma$ is trivial. This implies that $\sigma=\lambda_Y$. We point out that $\geo{\lambda_1}{h_1}=n_1$, $\geo{\lambda_2}{h_2}=n_2$, and $\geo{\lambda_Y}{h_3}=\nicefrac{n_1n_2}{gk}$.

            Since $n_1n_2 \neq 0$, the longitude $\lambda_Y \subset \partial \Sigma_3 = \partial Y$ is not the regular fiber $h_3 \subset \partial \Sigma_3 = \partial Y$. This implies that $Y(h_3)$ is a rational homology $3$-sphere. In particular
            \[
                Y(h_3)=Y_1(h_1) \# Y_2(h_2).
            \]
            This implies that $ H_1(Y(h_3);\mathbb{Z}) = H_1(Y_1(h_1);\mathbb{Z}) \oplus H_1(Y_2(h_2);\mathbb{Z})$. 
            Therefore, by Remark \ref{rmk: order of toroidal}, we obtain that
            \begin{align*}
            \left| H_1(Y(h_3);\mathbb{Z}) \right| & = \left| H_1(Y_1(h_1);\mathbb{Z}) \right| \cdot \left| H_1(Y_2(h_2);\mathbb{Z}) \right| \\
                o_Yt_Y\geo{\lambda_Y}{h_3} &= o_1t_1 \geo{\lambda_1}{h_1} o_2t_2 \geo{\lambda_2}{h_2} \\
                 \frac{n_1n_2}{gk} &= o_1t_1 n_1 o_2t_2 n_2 \\
                1 & = o_1t_1 o_2t_2 gk.
            \end{align*}
     Therefore, $t_1=t_2=o_1=o_2=1$.
        \end{proof}
\end{lemma}

\begin{lemma}\label{lemma: rational longitude of C2}
    Let $Y_1$ be a $3$-manifold with torus boundary and $Y=Y_1 \cup_{\Sigma_1'} C_2$. The regular fiber $h_2 \subset \Sigma_2$ is the rational longitude $\lambda_Y$ and it has order $1$ if $\geo{\lambda_1}{h_1} = 0$ and $o_1=1$ and $2$ otherwise. 
    \begin{proof}
        The presentation \eqref{eq: fundamental group C2} implies that $2[h]=2[h_2]$ is trivial in $H_1(C_2;\mathbb{Z})$. Therefore, $2[h_2]$ is trivial in $H_1(Y;\mathbb{Z})$. This implies that $h_2$ is the rational longitude of $Y$ and it has order either $1$ or $2$.

        If $\geo{\lambda_1}{h_1} = 0$ and $o_1=1$, then $[h_2]=[h_1]=[\lambda_1]$ in $H_1(Y;\mathbb{Z})$ and this latter in nullhomologous in $H_1(Y_1;\mathbb{Z})$. This implies that $[h_2]$ is nullhomologus in $H_1(Y;\mathbb{Z})$ and that the order of the rational longitude is one.

        If either $\geo{\lambda_1}{h_1} \neq 0$ or $o_1 \neq 1$, then $[h_2]=[h_1]=[h]$ is not trivial in both $H_1(Y_1;\mathbb{Z})$ and $H_1(C_2;\mathbb{Z})$. Therefore the order of the order of the rational longitude is two.
    \end{proof}
\end{lemma}

\begin{rmk}\label{rmk: bases for C3}
    Let us consider $C_3$.
    If $\xi_1 \subset \Sigma_1$ and $\xi_2 \subset \Sigma_2$ are two slopes such that $\geo{\xi_1}{h}=\geo{\xi_2}{h}=1$, then $\{\xi_1,h\}$ and $\{\xi_2,h\}$ are bases for $\fund{\Sigma_1}$ and $\fund{\Sigma_2}$. In particular we can assume that $\fund{C_3}$ is presented as in \eqref{eq: fundamental group C3} and that
    \[
        [\xi_1]=x_1 \in \fund{\Sigma_1} \quad \text{and} \quad [\xi_2]=x_2 \in \fund{\Sigma_2}.
    \]
\end{rmk}

A similar consideration can be done for $C_2$ as well:
\begin{rmk}\label{rmk: bases for C2}
    Let us consider $C_2$.
    If $\xi_1 \subset \Sigma_1'$ is a slope such that $\geo{\xi_1}{h}=1$, then $\{\xi_1,h\}$ is a basis for $\fund{\Sigma_1'}$. Furthermore, we can assume that $\fund{C_2}$ is presented as in \eqref{eq: fundamental group C2} and that $[\xi_1]=x_1 \in \fund{\Sigma_1'}$.
\end{rmk}


\section{The topological set up}
\label{section: the topology set up}

We recall that in Subsection \ref{subsection: SFS} we made the notation for Seifert fibred spaces explicit.

We shall now prove the existence of a decomposition into ‘simple’ pieces of graph manifolds rational homology $3$-spheres. That is, we will show that a graph manifold rational homology $3$-sphere admits a system of tori that decomposes it into a collection of $C_3's$, $C_2's$ and $\mathbb{D}^2(\nicefrac{p_\ast}{q_\ast})$,
where $\mathbb{D}^2(\nicefrac{p_\ast}{q_\ast})$ indicates a Seifert fibred with disk base space. We remind the reader that a solid torus $S^1 \times \mathbb{D}^2$ has disk base space, therefore the class $\mathbb{D}^2(\nicefrac{p_\ast}{q_\ast})$ contains solid tori.

Let $Y$ be a graph manifold rational homology sphere and let $Y_i$ be a JSJ piece. Through the calculation of the fist Betti number, we conclude that $Y_i$ admits has base space a planar surface, i.e. either a punctured sphere $S^2$ or a punctured projective plane $\mathbb{RP}^2$. For details see \cite[Section 2.2]{boyer2017foliations}.

\begin{lemma}\label{lemma: system for S2}
    Let $Y$ a Seifert space with boundary and base space a punctured $S^2$.
    There exists a system of embedded disjoint tori $\tau \subset Y$ such that
        \[
            \overline{Y \setminus \tau} = \left(\bigcup C_3\right) \cup  \mathbb{D}^2(\nicefrac{p_{\ast,i}}{q_{\ast,i}}).
        \]
        \begin{proof}
        If $Y$ has one boundary component then $\tau = \emptyset$.
         If $Y$ has two boundary components, then there exists a vertical torus $\Sigma \subset Y$ such that
    \[
        \overline{Y \setminus \tau} = C_3 \cup M,
    \]
        where $M$ is a Seifert fibred space with disk base space. In particular, $M=S^1\times \mathbb{D}^2$ if $Y$ has at most one singular fiber.
        Let us assume that $Y$ has $n \ge 3$ boundary components and $m \ge 0$ singular fibers.
        Let $\text{sgm} \colon \mathbb{N} \to \{1,0\}$ be the signum function.
        It is easy to see that there exists a system $\tau\subset Y$ of $n-2+ \text{sgm}(m)$ vertical tori such that
        \[
            \overline{Y \setminus \tau} = 
            \begin{dcases}
                \bigcup_{n-2} C_3 & \text{if $m=0$} \\
                \left(\bigcup_{n-1} C_3\right) \cup \mathbb{D}^2(\nicefrac{p_{\ast}}{q_{\ast}}) & \text{if $m \ge 1$}.
            \end{dcases}
        \]
        For example, Figure \ref{Figure: vertical tori for C3} shows the system $5$ tori in the case $n=6$ and $m \ge 1$.
        \end{proof}
\end{lemma}

\begin{lemma}\label{lemma: system for RP2}
     Let $Y$ a Seifert space with boundary and base space a punctured $\mathbb{RP}^2$. There exists a system of embedded disjoint tori $\tau \subset Y$ such that
        \[
            \overline{Y \setminus \tau} = C_2 \cup \left(\bigcup C_3\right) \cup  \mathbb{D}^2(\nicefrac{p_{\ast,i}}{q_{\ast,i}}).
        \]
        \begin{proof}
            If $Y$ has one boundary component and no singular fiber, then
            according to \cite[Theorem 10.4.19]{martelli} $Y$ admits a Seifert fibration over a disk with two singular fibers, both of order $2$. In this case, $Y= \mathbb{D}^2(\nicefrac{p_\ast}{q_\ast})$ and $\tau = \emptyset$.
            If $Y$ has one boundary component and $m \ge 1$ singular fibers, then there exists a vertical torus $\Sigma \subset Y$ such that
            \[
                \overline{Y \setminus \Sigma} = C_2 \cup M,
            \]
            where $M= \mathbb{D}^2 (\nicefrac{p_\ast}{q_\ast})$. If $Y$ has two boundary components and no singular fibers, then
            $Y = C_2$ and $\tau = \emptyset$.

            Similarly to Lemma \ref{lemma: system for S2}, if $Y$ has $n \ge 2$ boundary component and $m \ge 0$ singular fibers, then there exists a system $\tau \subset Y$ of $n-1+\text{sgm}(m)$ tori such that
        \[
            \overline{Y \setminus \tau} = C_2 \cup
            \begin{dcases}
                \bigcup_{n-1} C_3 & \text{if $m=0$} \\
                \left(\bigcup_{n} C_3\right) \cup\mathbb{D}^2(\nicefrac{p_{\ast}}{q_{\ast}}). & \text{if $m \ge 1$}.
            \end{dcases}
        \]
        For example, Figure \ref{Figure: vertical tori for C2} shows a system of disjoint vertical tori $\tau \subset Y$ in the case that $Y$ has four boundary components and a positive number of singular fibers.
        \end{proof}
\end{lemma}
\begin{cor}\label{cor: the usefull decomposition}
        Let $Y$ be a graph manifold rational homology $3$-sphere, there exists a system of embedded disjoint tori $\tau \subset Y$ and three finite (potentially empty) sets $I,J,K$ such that
        \[
            \overline{Y \setminus \tau} = \left(\bigcup_{k \in K} C_3\right) \cup \left(\bigcup_{j \in J} C_2\right) \cup \left(\bigcup_{i \in I} \mathbb{D}^2(\nicefrac{p_{\ast,i}}{q_{\ast,i}})\right),
        \]
        where $\mathbb{D}^2(\nicefrac{p_{\ast,i}}{q_{\ast,i}})$ is a Seifert fibred space with disk base.
        \begin{proof}
            The conclusion holds by Lemma \ref{lemma: system for S2} and Lemma \ref{lemma: system for RP2}.
        \end{proof}
\end{cor}

