Clearly, if $Y$ is a graph rational homology $3$-sphere $\Sigma \subset Y$ an embedded torus, then every component of $\overline{Y \setminus \Sigma}$ is a rational homology solid torus.

\begin{cor}\label{cor: C3 obstruction longitudes}
    Let $Y_1$ and $Y_2$ two rational homology solid tori.
    Let $Y=Y_1\cup_{\Sigma_1}C_3 \cup_{\Sigma_2}Y_2$ be such that $\Delta(\lambda_{1},h_1)=\Delta(\lambda_{2},h_2)=0$. The manifold $Y$ is not a rational homology solid torus.
    \begin{proof}
    By Mayer Vietoris, we obtain that the following sequence is exact:
    \[
        \cdots \to H_1(\Sigma_1;\mathbb{Q})\oplus H_1(\Sigma_2;\mathbb{Q}) \overset{\iota}{\to} H_1(Y_1;\mathbb{Q}) \oplus H_1(Y_2;\mathbb{Q}) \oplus H_1(C_3;\mathbb{Q}) \overset{j}{\to} H_1(Y;\mathbb{Q})\to 0.
    \]
    The conditions $\Delta(\lambda_{1},h_1)=0 $ and $\Delta(\lambda_{2},h_2)=0$ imply that $\rank \iota =3$. This implies that $\rank j =2$ and $\dim H_1(Y;\mathbb{Q}) =2$. This implies that $Y$ is not a rational homology solid torus.
    \end{proof}
\end{cor}

\begin{cor}\label{cor: C2 obstruction longitudes}
    Let $Y_1$ be a rational homology solid torus.
    If $Y=Y_1\cup_{\Sigma_1'}C_2 $ is such that $\Delta(\lambda_{1},h_1)=0$, then $Y$ is not rational homology solid torus. 
    \begin{proof}
    By Mayer Vietoris, we obtain that the following sequence is exact:
    \[
        \cdots \to H_1(\Sigma_1';\mathbb{Q}) \overset{\iota}{\to} H_1(Y_1;\mathbb{Q})  \oplus H_1(C_2;\mathbb{Q}) \overset{j}{\to} H_1(Y;\mathbb{Q})\to 0.
    \]
    The conditions $\Delta(\lambda_{1},h_1)=0 $ implies that $\rank \iota =1$. This implies that $\rank j =2$ and $\dim H_1(Y;\mathbb{Q}) =2$. This implies that $Y$ is not a rational homology solid torus.
    \end{proof}
\end{cor}

\section{The recipe for \texorpdfstring{$C_3$}{C3}}

Let $Y=Y_1 \cup_{\Sigma_1}C_3 \cup_{\Sigma_2} Y_2$. In this section we describe $T(Y,\partial Y) \subset \R{\Sigma_3}$ taking as inputs the spaces $T(Y_1,\partial Y_1) \subset \R{\partial Y_1}$ and $T(Y_2,\partial Y_2) \subset \R{\partial Y_2}$. We recall that, if $M$ is a manifold, then
\[
    R(M) \coloneqq \text{Hom} \left( \fund{M};SU(2)\right).
\]
We recall that $\partial C_3 = \Sigma_1 \cup \Sigma_2 \cup \Sigma_3$ and, in particular, the space $\R{\Sigma_j}$ comes with coordinates with coordinates $(\theta_j,\psi_j)$ as in \eqref{eq: coordinates for C3}. 

\begin{lemma}\label{lemma: C3 abelian extension}
      For $j \in \{1,2,3\}$, let $\eta_j \colon \fund{\Sigma_j} \to \Ui$ be the representation with coordinates $(\theta_j,\psi_j)$ in $\R{\Sigma_j}$. There exists an abelian representation $\rho \in R(C_3)$ such that
    \[
        \restr{\rho}{\fund{\Sigma_1}} \equiv \eta_1, \quad \restr{\rho}{\fund{\Sigma_2}} \equiv \eta_2, \quad \text{and} \quad \restr{\rho}{\fund{\Sigma_3}} \equiv \eta_3
    \]
    if and only if $\psi_1=\psi_2=\psi_3$ and $\theta_1+\theta_2=\theta_3$.
    \begin{proof}
        If such an abelian representation $\rho \colon \fund{C_3} \to SU(2)$ exists, then $\rho(h)=\eta_j(h)$ for $j \in \{1,2,3\}$. Hence, $\psi_1=\psi_2=\psi_3$. Moreover, the presentation of $\fund{C_3}$ as in \eqref{eq: fundamental group C3} implies that
        \[
        \eta_1(x_1)\eta_2(x_2)=\rho(x_1)\rho(x_2)=\rho(x_1x_2)=\rho(x_3)=\eta_3(x_3).
        \]
        Hence, $e^{i\theta_1}e^{i\theta_2}=e^{i\theta_3}$ and then $\theta_1+\theta_2=\theta_3$.

        Conversely, let $\rho \in R(C_3)$ be defined as
        \[
        \rho(x_1)=e^{i\theta_1}, \quad \rho(x_2)=e^{i\theta_2}, \quad \rho(x_3)=e^{i\theta_3}, \quad \text{and,} \quad \rho(h)=e^{i\psi_1}.
        \]
        The representation $\rho$ is abelian and $\restr{\rho}{\fund{\Sigma_j}} \equiv \eta_j$ for every $j \in \{1,2,3\}$.
    \end{proof}
\end{lemma}

\begin{defn}

For two reals $a,b \in [-2,2]$ we define the interval $I(a,b)$ as
\begin{align}\label{eq: interval I}
I(a,b) \coloneqq \left(ab- \frac{1}{2}\left(\sqrt{(4-a^2)(4-b^2)} \right),ab+ \frac{1}{2}\left(\sqrt{(4-a^2)(4-b^2)} \right) \right) \subseteq (-2,2).
\end{align}
\end{defn}
In \cite[Proposition 7.2]{Mino} the author proved that, for given $a,b,c \in [-2,2]$, there exist two matrices $A,B \in SU(2)$ with $\Tr A =a$, $\Tr B =b$, $\Tr AB =c$ and $AB \neq BA$ if and only if $c \in I(a,b)$. 

\begin{lemma}\label{lemma: C3 extension irreducible}
    If there exists an irreducible representation $\rho \in R(C_3)$, then $\rho(h) \in \ZSU$ and $\Tr \rho(x_3) \in I \left( \Tr\rho(x_1),\Tr \rho(x_2)\right)$.

    Conversely, let $\varepsilon \in \{0,\pi\}$ and $\theta_1,\theta_2,\theta_3 \in [0,2\pi]$. If
    \[
    \psi_1=\psi_2=\psi_3=\varepsilon \quad \text{and}  \quad 
    2\cos \theta_3 \in I(2\cos\theta_1,2\cos \theta_2),
    \]
    then there exists an irreducible representation $\rho \in R(C_3)$ such that $\restr{\rho}{\fund{\Sigma_j}}$ is conjugate to the representation $\eta_j\in \R{\Sigma_j}$ with coordinates $(\theta_j,\psi_j)$ for $j \in \{1,2,3\}$. 
    \begin{proof}
        If such an irreducible representation $\rho \in R(C_3)$ exists, then, since $h$ is central in $\fund{C_3}$, we obtain that $\rho(h) \in \ZSU=\{\pm 1\}$ by Fact \ref{Fact: centralizers}.
        Since $\rho$ is irreducible, $\rho(x_1)\rho(x_2) \neq \rho(x_2)\rho(x_1)$, because $\rho$ would be abelian instead.
        Thus, by \cite[Proposition 7.2]{Mino}, $\Tr \rho(x_3) \in I(\Tr \rho(x_1),\Tr \rho(x_2))$.

        We prove now the converse. For $j \in \{1,2,3\}$, let $\eta_j\in \R{\Sigma_j}$ be a representation with coordinates $(\theta_j,\psi_j)$. We recall that $\Tr \eta(x_j) = 2\cos \theta_j$. By \cite[Proposition 7.2]{Mino}, since $2\cos \theta_3 \in I(2\cos\theta_1,2\cos \theta_2)$, there exist three matrices $X_1,X_2,X_3 \in SU(2)$ such that $X_3 = X_1X_2$, $\Tr X_j=2\cos \theta_j$, and $X_1X_2 \neq X_2X_1$. We define the irreducible representation $\rho \colon \fund{C_3} \to SU(2)$ by
        \[
            \rho(x_j)=X_j, \quad \text{and} \quad \rho(h)=e^{i\varepsilon}.
        \]
        Since $\Tr \eta_j(x_j)=\Tr X_j$ and $\Tr \eta_j(h)=\pm 1$, we get that $\restr{\rho}{\fund{\Sigma_j}} \equiv \eta_j$ up to conjugation.
    \end{proof}
\end{lemma}

\begin{defn}\label{defn: A+B}
    Let $\Sigma_1$, $\Sigma_2$, and $\Sigma_3$ be the boundary components of $C_3$. Let $\R{\Sigma_j}$ comes with coordinates $(\theta_j,\psi_j)$ as in \eqref{eq: coordinates for C3}. Let $A \subset \R{\Sigma_1}$ and $B \subset \R{\Sigma_2}$ be two subsets. We define $A+B$ as the subset of $\R{\Sigma_3}$ defined by
    \[
    A+B \coloneqq \left\{ (\theta_1+\theta_2,\psi) \in \R{\Sigma_3} \middle| (\theta_1,\psi) \in \R{\Sigma_1} \text{ and } (\theta_2,\psi) \in \R{\Sigma_2}\right\}.
    \]
\end{defn}
