From the rest of the section, $Y_1$ and $Y_2$ will be two manifolds with torus boundary and $Y$ the manifold $Y_1 \cup_{\Sigma_1} C_3 \cup_{\Sigma_2} Y_2$ represented in Figure \ref{Figure: the manifold Y1 C3 Y2}.

\begin{defn}\label{defn H3,0 e H3,pi}
    Let $Y=Y_1 \cup_{\Sigma_1} C_3 \cup_{\Sigma_2} Y_2$ be as before. For $j \in \{1,2\}$, we consider $T(Y_j,\partial Y_j)$ as a subset of $\R{\Sigma_j}$.
    Let $\varepsilon \in \{0,\pi\}$. We define $S_j^\varepsilon $ as $ T(Y_j,\partial Y_j) \cap \{\psi_j = \varepsilon\} \subset \R{\Sigma_j}$. We define the interval $J^\varepsilon \subset (-2,2)$ as
    \[
        J^\varepsilon= \bigcup_{\substack{(\theta_1,\varepsilon) \in S_1^\varepsilon \\ (\theta_2,\varepsilon) \in S_2^\varepsilon}} I(2\cos \theta_1,2\cos\theta_2).
    \]
    Finally, we define $H_{3,\varepsilon} \subseteq \R{\Sigma_3}$ as $H_{3,\varepsilon} \coloneqq \left\{ (\theta_3,\varepsilon) \in \R{\Sigma_3} \middle| 2\cos \theta_3 \in J^\varepsilon \right\}$.
\end{defn}

\begin{rmk}
    \label{rmk: When theta1 theta2 is in piZ}
    According to Definition \ref{defn H3,0 e H3,pi}, the interval $J^\varepsilon$ is an open subinterval of $(-2,2)$. Therefore, it does not contain $\pm 2$. Hence, the sets $H_{3,0}$ and $H_{3,\pi}$ do not contain central representations $\fund{\Sigma_3}\to \ZSU$. Moreover if $2\cos \theta_3 \in I(2\cos \theta_1,2 \cos \theta_2)$, then $\theta_1,\theta_2 \notin \pi \mathbb{Z}$.
\end{rmk}

We recall the $T(Y_1,\partial Y_1)=A(Y_1) \cup H(Y_1)$, where the representations $\fund{\partial Y_1} \to SU(2)$ in $A(Y_1)$ (resp. $H(Y_1)$) extend to $\fund{Y_1}$ in an abelian (resp. irreducible) way.
Moreover, $P(Y_1) \subset A(Y_1)$ is the set of central representations $\fund{\partial Y_1} \to \ZSU$ that extend to $\fund{Y_1}$ in an abelian and noncentral way. In the following we consider $\Sigma_1$, $\Sigma_2$, and $\Sigma_3$ as the boundary components of $C_3$ and we give to $\R{\Sigma_j}$ coordinates $(\theta_j,\psi_j)$ as in \eqref{eq: coordinates for C3}.

\begin{teo}\label{teo: alg for C3}
    Let $Y=Y_1 \cup_{\Sigma_1} C_3 \cup_{\Sigma_2} Y_2$. Let $A(Y_j),H(Y_j)$, and $P(Y_j)$ be considered as subsets of $\R{\Sigma_j}$. The space $T(Y,\partial Y)\subset \R{\Sigma_3}$ is equal to $A(Y)\cup H(Y)$, where \[A(Y)=A(Y_1) + A(Y_2)\] and
    \begin{gather*}
        H(Y)= \left(A(Y_1) + H(Y_2)\right) \cup \left(H(Y_1) + A(Y_2)\right) \cup \left(H(Y_1) + H(Y_2)\right)\\ \cup (P(Y_1) + P(Y_2)) \cup H_{3,0} \cup H_{3,\pi}.
     \end{gather*}
    \begin{proof}
        We first prove the statement $A(Y)=A(Y_1)+A(Y_2)$. Let $\eta_3 \in A(Y) \subseteq T(Y,\partial Y)$. Hence, there exists an abelian representation $\rho \in R(Y)$ such that $\restr{\rho}{\fund{\Sigma_3}}\equiv \eta_3$. We define $\eta_1$ (resp. $\eta_2$) as the restriction $ \restr{\rho}{\fund{\Sigma_1}}$ (resp. $ \restr{\rho}{\fund{\Sigma_2}}$). Since $\rho$ is abelian, $\ima \rho \subseteq \Ui$ and therefore $\ima \eta_j \subseteq \Ui$. Thus, $\eta_j \in \R{\Sigma_j}$. Let $(\theta_j,\psi_j)$ be the coordinates of $\eta_j$ in $\R{\Sigma_j}$, Lemma \ref{lemma: C3 abelian extension} implies that $\psi_1=\psi_2=\psi_3$ and $\theta_3 = \theta_1 + \theta_2$. Thus, $(\theta_3,\psi_3) \in A_1+A_2$. This implies that $A(Y) \subseteq A_1+A_2$.

        Conversely, let $\eta_3 \in A(Y_1)+A(Y_2)$ be of coordinates $(\theta_3,\psi_3)$. By the definition of the set $A(Y_1) + A(Y_2)$, we obtain that $\theta_3=\theta_1+\theta_2$ with $(\theta_1,\psi_3) \in A(Y_1) \subset \R{\Sigma_1}$ and $(\theta_2,\psi_3) \in A(Y_2) \subset \R{\Sigma_2}$. Let $\eta_1$ and $\eta_2$ be the representations corresponding to these two points.
        Lemma \ref{lemma: C3 abelian extension} implies that there exists an abelian representation $\rho_c \in R(C_3)$ such that $\restr{\rho_c}{\fund{\Sigma_j}} \equiv \eta_j$.
        Let $\rho_1 \in R(Y_1)$ (resp. $\rho_2 \in R(Y_2)$) be an abelian representation such that $\restr{\rho_1}{\fund{\Sigma_1}} \equiv \eta_1$ (resp. $\restr{\rho_2}{\fund{\Sigma_2}} \equiv \eta_2$). Thus, there exists an abelian representation $\rho \in R(Y)$ such that
        \[
            \restr{\rho}{\fund{Y_1}} \equiv \rho_1, \quad \restr{\rho}{\fund{Y_2}} \equiv \rho_2 \quad \text{and} \quad \restr{\rho}{\fund{C_3}}\equiv \rho_c,
        \]
        In particular, $\restr{\rho}{\fund{\Sigma_3}}\equiv\restr{\rho_c}{\fund{\Sigma_3}}\equiv\eta_3$. Thus, $\eta_3 \in A(Y)$ and $A(Y_1)+A(Y_2) \subseteq A(Y)$.

        We focus on $H(Y)$.
        If $\eta_3 \in P(Y_1) + P(Y_2)$, then, by Lemma \ref{lemma: C3 abelian extension}, there exists an abelian representation $\rho_c \in R(C_3)$ such that $\restr{\rho_c}{\fund{\Sigma_1}}$ and $\restr{\rho_c}{\fund{\Sigma_2}}$ are central and they extend to two abelian noncentral representations $\rho_1 \colon\fund{Y_1} \to SU(2)$ and $\rho_2 \colon \fund{Y_2} \to SU(2)$, respectively. Hence, there exists a representation $\rho \in R(Y)$ such that
        \[
            \restr{\rho}{\fund{Y_1}} \equiv \rho_1, \quad \restr{\rho}{\fund{Y_2}} \equiv \rho_2 \quad \text{and} \quad \restr{\rho}{\fund{C_3}}\equiv \rho_c,
        \]
        If $\rho$ is irreducible, then $\eta_3 \in H(Y)$ and $P(Y_1) + P(Y_2) \subseteq H(Y)$. Let us assume that $\rho$ is abelian, this implies that $\ima \rho$, $\ima \rho_1$, $\ima \rho_2$, and $\ima \rho_c$ are all in $\Ui$.
        We define
        \[
            M \coloneq \begin{bmatrix}
                i & i \\ 0 & -i
            \end{bmatrix} \in SU(2).
        \]
        Notice that if $e^{i x} \in SU(2)$ is noncentral, i.e. $x \notin \{0,\pi\}$, then
        \[
            Me^{i x}M^{-1} = \begin{bmatrix}
                i & i \\ 0 & -i
            \end{bmatrix}
            \begin{bmatrix}
                e^{ix} & 0 \\ 0 & e^{-ix}
            \end{bmatrix}
            \begin{bmatrix}
                -i & -i \\ 0 & i
            \end{bmatrix}=
            \begin{bmatrix}
                e^{i x} & e^{ix} -e^{-ix}\\ 0 & e^{-ix}
            \end{bmatrix}.
        \]
        Therefore, the product $Me^{i x}M^{-1}$ does not commute with $e^{i x}$. 
        We define the representation $\rho' \in R(Y)$ as
        \[
            \rho'(x)= \begin{dcases}
                M \rho(x)M^{-1} \quad \text{if } x \in \fund{Y_1} \\
                \rho(x) \quad \text{otherwise}.
            \end{dcases}
        \]
        We notice that, since $\rho(\fund{\Sigma_1})\subset \ZSU$, the representation $\rho'$ is well-defined.
        Since neither $\rho_1$ nor $\rho_2$ is central, $\rho'$ is irreducible. Hence $\eta_3 \in H(Y)$ and $P(Y_1) + P(Y_2) \subseteq H(Y)$.

        If $\eta_3 \in \left(A(Y_1) + H(Y_2)\right) \cup \left(H(Y_1) + A(Y_2)\right) \cup \left(H(Y_1) + H(Y_2)\right)$, then by Lemma \ref{lemma: C3 abelian extension}, there exists an abelian representation $\rho_c \in R(Y)$ such that $\restr{\rho_c}{\fund{\Sigma_3}}=\eta_3$ and either $\restr{\rho}{\fund{\Sigma_1}} \in H_1$ or $\restr{\rho}{\fund{\Sigma_2}} \in H_2$. This implies that there exists a $\rho \in R(Y)$ such that $\restr{\rho}{\fund{\Sigma_3}}=\eta_3$ and either $\restr{\rho}{\fund{Y_1}}$ or $\restr{\rho}{\fund{Y_2}}$ is irreducible. Thus, $\rho$ is irreducible and $\eta_3 \in H(Y)$. This implies that $\left(A(Y_1) + H(Y_2)\right) \cup \left(H(Y_1) + A(Y_2)\right) \cup \left(H(Y_1) + H(Y_2)\right) \subseteq H(Y)$.

        Let $\varepsilon \in \{0,\pi\}$. If $\eta_3 \in H_{3,\varepsilon}$, then, by definition of the set $H_{3,\varepsilon}$, there exist $\theta_1$ and $\theta_2$ such that 
        \begin{align}
            \label{eq: la uso una volta coseni}
            2\cos \theta_3 \in I(2\cos \theta_1,2\cos \theta_2), \quad (\theta_1,\varepsilon) \in T(Y_1,\partial Y_1), \quad \text{and,} \quad (\theta_2,\varepsilon) \in T(Y_2,\partial Y_2),
        \end{align}
        where $(\theta_3,\varepsilon)$ are the coordinates of the representation $\eta_3$.
        Let $\eta_1 \in \R{\Sigma_1}$ and $\eta_2 \in \R{\Sigma_2}$ be the representations corresponding to the coordinates $(\theta_1,\varepsilon)$ and $(\theta_2,\varepsilon)$ respectively.
        The identity \eqref{eq: la uso una volta coseni} states that $\eta_1$ and $\eta_2$ extend to $\rho_1 \colon \fund{Y_1} \to SU(2)$ and $\rho_2 \colon \fund{Y_2} \to SU(2)$. In particular, for $j \in \{1,2\}$ we have that $\restr{\rho_j}{\fund{\Sigma_j}} \equiv \eta_j$.

        Lemma \ref{lemma: C3 extension irreducible} implies that there exists an irreducible representation $\rho_c \in R(C_3)$ and three matrices $X_1,X_2,X_3 \in SU(2)$ such that
        \[
            \restr{\rho_c}{\fund{\Sigma_j}}=X_j \eta_j X_j^{-1}.
        \]
        Up to conjugation, we can assume that $\restr{\rho_c}{\fund{\Sigma_3}}\equiv \eta_3$. We define the representation $\rho \colon \fund{Y} \to SU(2)$ as
        \[
        \rho(x)= 
        \begin{dcases}
            X_1 \rho_1(x) X_1^{-1} \quad \text{if $x \in \fund{Y_1}$} \\
            X_2 \rho_2(x) X_2^{-1} \quad \text{if $x \in \fund{Y_2}$} \\
            \rho_c(x) \quad \text{if $x \in \fund{C_3}$}.
        \end{dcases}
        \]
        We notice that, for $j \in \{1,2\}$, we have that $\restr{\rho_c}{\fund{\Sigma_j}} \equiv X_j \eta_jX_j^{-1}$ and
        \[
            \restr{\left(X_j\rho_j X_j^{-1}\right)}{\fund{\Sigma_j}} \equiv X_j \restr{\rho_j}{\fund{\Sigma_j}}X_j^{-1} \equiv X_j \eta_j X_j^{-1} \equiv \restr{\rho_c}{\fund{\Sigma_j}}.
        \]
        The representation $\rho$ is irreducible and $\restr{\rho}{\fund{\Sigma_3}}\equiv \eta_3$. Thus, $\eta_3 \in H(Y)$ and hence $H_{3,0} \cup H_{3,\pi} \subset H(Y)$. This concludes the proof that
        \begin{multline*}
            \left(A(Y_1) + H(Y_2)\right) \cup \left(H(Y_1) + A(Y_2)\right) \cup \left(H(Y_1) + H(Y_2)\right) \cup (P(Y_1) + P(Y_2)) \cup \\ \cup H_{3,0} \cup H_{3,\pi} \subseteq H(Y).
        \end{multline*}

        Conversely, let $\eta_3 \in H(Y)$. Thus, there exists an irreducible extension $\rho \in R(Y)$ of $\eta_3$.
        Let us focus on $\rho_c \coloneq \restr{\rho}{\fund{C_3}}$.
        If $\rho_c$ is irreducible, then Lemma \ref{lemma: C3 extension irreducible} implies that $\eta_3 \in H_{3,0}\cup H_{3,\pi}$.
        We conclude that
        \[
            H_{3,0} \cup H_{3,\pi} \subseteq H(Y).
        \]

        Let us assume that $\rho_c$ is abelian. If $\restr{\rho}{\fund{Y_1}}$ is irreducible, then Lemma \ref{lemma: C3 abelian extension} implies that $\eta_3 \in (H(Y_1)) + A(Y_2)) \cup (H(Y_1) + H(Y_2))$. If $\restr{\rho}{\fund{Y_1}}$ is abelian and $\restr{\rho}{\fund{Y_2}}$ is irreducible, then Lemma \ref{lemma: C3 abelian extension} implies that $\eta_3 \in (A(Y_1) + H(Y_2))$. Finally, if both $\restr{\rho}{\fund{Y_1}}$ and $\restr{\rho}{\fund{Y_2}}$ are both abelian, then, as we saw before, since $\rho$ is irreducible, $\eta_3 \in P(Y_1) + P(Y_2)$. This concludes that
        \begin{multline*}
       H(Y) \subseteq\\ \left(A(Y_1) + H(Y_2)\right) \cup \left(H(Y_1) + A(Y_2)\right) \cup \left(H(Y_1) + H(Y_2)\right) \cup (P(Y_1) + P(Y_2)) \cup H_{3,0} \cup H_{3,\pi}.
        \end{multline*}
    \end{proof}
\end{teo}

