\begin{lemma}{\label{lemma: extension abelian C2}}
    The representation $\eta_1 \colon \fund{\Sigma_1'}\to SU(2)$ extends to an abelian representation of $\fund{C_2}$ if and only if $\eta_1(h_1)^2=1$.
    \begin{proof}
        Let us assume that there exists an abelian representation $\rho \in R(C_2)$ such that $\restr{\rho}{\fund{\Sigma_1'}}\equiv\eta_1$. Since $\rho$ is abelian, it factors through the first homology $H_1(C_2;\mathbb{Z})$. Notice that the presentation \eqref{eq: fundamental group C2} implies that the homologous class of the regular fiber $h$ has order $2$ in $H_1(C_2;\mathbb{Z})$. Hence, $\rho(h)^2=\eta_1(h_1)^2=1$.

        Conversely, up to conjugation, we assume that $\ima \eta_1 \subseteq \Ui$. Let $(\theta_1,\psi_1)$ be the coordinates of $\eta_1$ in $\R{\Sigma_1}$. Since $\eta_1(h)^2=1$, we obtain that $\psi_1 \in \pi \mathbb{Z}$. We define the representation $\rho \in R(C_2)$ as
        \[
        \rho(x_1)=e^{i \theta_1}, \quad \rho(x_2)=e^{i (\pi -\theta_1)}, \quad \rho(h)=e^{i\psi_1}, \quad \text{and} \quad \rho(z)=e^{i \frac{\pi}{2}}.
        \]
        The representation $\rho$ is abelian and it is an extension of $\eta_1$.
    \end{proof}
\end{lemma}
