\begin{lemma}\label{lemma: irr extension C2, translazione}
    Let $\eta_1 \in \R{\Sigma_1'}$ be the representation of coordinates $(\theta_1,\psi_1)$ with $\psi_1 \notin \pi \mathbb{Z}$. There exists an irreducible representation $\rho \colon \fund{C_2} \to SU(2)$ such that $\restr{\rho}{\fund{\Sigma_1'}} \equiv \eta_1$, $\ima \restr{\rho}{\fund{\Sigma_2'}} \subseteq \Ui$, and this latter has coordinates $(\pi -\theta_1,\psi_1) \in \R{\Sigma_2}$.
    \begin{proof}
        Let $Z \in SU(2)$ be as in Remark \ref{rmk: the matrices H and K for C2}. We define the representation $\rho \in R(C_2)$ as
        \[
        \rho(x_1)=e^{i\theta_1} \quad \rho(x_2)=e^{i(\pi-\theta_1)} \quad \rho(h)=e^{i\psi_1}, \quad \text{and} \quad \rho(z)=Z.
        \]
        Since $\psi_1 \notin \pi \mathbb{Z}$, the element $\rho(h)$ is noncentral and Remark \ref{rmk: the matrices H and K for C2} implies that $\rho(z)\rho(h)\rho(z)^{-1} \rho(h)=1$ and $\rho(z)\rho(h) \neq \rho(h)\rho(z)$. Therefore, $\rho$ is a well defined representation of $\fund{C_2}$ and is irreducible,
        The representation $\rho$ is an extenstion of $\eta_1$. Moreover, $\restr{\rho}{\fund{\Sigma_2'}}$ has image in $\Ui$ and it has coordinates $(\pi - \theta_1,\psi_1)$ in $\R{\Sigma_2}$.
    \end{proof}
\end{lemma}

\begin{lemma}\label{lemma: irr extension C2, central h}
     Let $\eta_1 \in \R{\Sigma_1'}$ be of coordinates $(\theta_1,\psi_1)$. Let us assume that $\psi_1 \in \pi \mathbb{Z}$ and $\theta_1 \notin \pi \mathbb{Z}$. For every $\theta_2 \in (0,\pi)\cup (\pi,2\pi)$ there exists an irreducible representation $\rho \colon \fund{C_2} \to SU(2)$ such that $\restr{\rho}{\fund{\Sigma_1'}}\equiv \eta_1$ and $\Tr \rho(x_2) = 2\cos \theta_2$.
     \begin{proof}
        We define the representation $\rho \colon \fund{C_2} \to SU(2)$ as
        \[
        \rho(x_1)=e^{i\theta_1} \quad \rho(x_2)=\begin{bmatrix}
            \cos \theta_2 & i\sin\theta_2 \\ i\sin\theta_2 & \cos \theta_2
        \end{bmatrix} \quad \rho(h)=e^{i\psi_1}, \quad \text{and} \quad \rho(z)=Z',
        \]
        where $Z'\in SU(2)$ is such that $Z'^2 =\rho(x_2)^{-1}\rho(x_1)^{-1}$. Such a matrix $Z'$ exists as the product $\rho(x_2)^{-1}\rho(x_1)^{-1}$ is contained in its centralizer which is a divisible subgroup of $SU(2)$. Details can be found in \cite[Proposition 3.19]{Lam_1999}.
        Since $\psi_1 \in \pi \mathbb{Z}$, the image $\rho(h)$ is central in $SU(2)$. This implies that $[\rho(x_j),\rho(h)]=1$ for $j \in \{1,2\}$.
        Since $\theta_2 \notin \pi \mathbb{Z}$, the matrix $\rho(x_2)$ is not diagonal. This implies that $\rho(x_1)\rho(x_2)\neq \rho(x_2)\rho(x_1)$, and hence $\rho$ is irreducible. We conclude that $\restr{\rho}{\fund{\Sigma_1'}}\equiv \eta_1$ and $\Tr \rho(x_2) = 2\cos \theta_2$.
     \end{proof}
\end{lemma}

\begin{lemma}\label{lemma: almost the receipt for C2}
     Let $Y=Y_1 \cup_{\Sigma_1'} C_2$. Let the set $T(Y_1,\partial Y_1) =A(Y_1) \cup H(Y_1)$ be considered as a subset of $\R{\Sigma_1'}$. Let $(\theta_1,\psi_1) \in T(Y_1,\partial Y_1)$ and $\varepsilon \in \{0,\pi\}$, then
     \begin{enumerate}
         \item If $\psi_1 \notin \pi \mathbb{Z}$, then $(-\theta_1+\pi,\psi_1) \in H(Y) \subset \R{\Sigma_2'}$
          \item If $\psi_1 = \varepsilon$ and $(\theta_1,\psi_1) \in A(Y_1)$, then $\{\psi_2 = \varepsilon\} \subset A(Y) \subset \R{\Sigma_2'}$,
          \item If $\psi_1 = \varepsilon$ and $(\theta_1,\psi_1) \in H(Y_1)$, then $\{\psi_2 = \varepsilon\} \subset H(Y) \subset \R{\Sigma_2'}$,
          \item If $\psi_1 = \varepsilon$ and $\theta_1 \notin \pi \mathbb{Z}$, then $\{\psi_2 = \varepsilon\}\setminus \{0,\pi\}^2 \subset H(Y) \subset \R{\Sigma_2'}$.
     \end{enumerate}
     \begin{proof}
     Let $\eta_1 \colon \fund{\Sigma_1'}\to SU(2)$ be the representation corresponding to $(\theta_1,\psi_1)\in \R{\Sigma_1'}$.
     As $(\theta_1,\psi_1) \in T(Y_1,\partial Y_1)$, there exists a representation $\rho_1 \colon \fund{Y_1} \to SU(2)$ such that $\restr{\rho_1}{ \fund{\Sigma_1'}}$ has these coordinates.

     Let us assume that $\psi_1 \notin \pi \mathbb{Z}$. Lemma \ref{lemma: irr extension C2, translazione} implies that there exists an irreducible representation $\rho_c \colon\fund{C_2} \to SU(2)$ such that
     $\restr{\rho_c}{\fund{\Sigma_1'}} \in \R{\Sigma_1'}$ has coordinates $(\theta_1,\psi_1)$ and $\restr{\rho_c}{\fund{\Sigma_2'}}$ has coordinates $(-\theta_1+\pi,\psi_1)$.
     Therefore, there exists an irreducible representation $\rho \colon \fund{Y} \to SU(2)$ such that
     \[
        \restr{\rho}{\fund{Y_1}}\equiv \rho_1 \quad \text{and} \quad \restr{\rho}{\fund{C_2}}\equiv \rho_c.
     \]
     This proves the first statement. Similarly,
     the second and the third are consequences of Lemma \ref{lemma: extension abelian C2}.
    Let us focus on the forth one. Let $\theta_2 \in (0,\pi) \cup (\pi,2\pi)$ and $\psi_1=\varepsilon$. 
    As a consequence of Lemma \ref{lemma: irr extension C2, central h}, there exists an irreducible representation representation $\rho_c \colon \fund{C_2} \to SU(2)$ such that $\restr{\rho_c}{\fund{\Sigma_1}'}$ has coordinates $(\theta_1,\varepsilon)$ and $\Tr \rho_c(x_2) = 2\cos \theta_2$. Therefore, there exists an irreducible representation $\rho \colon \fund{Y} \to SU(2)$ such that
    \[
        \restr{\rho}{\fund{Y_1}} \equiv \rho_1, \quad \restr{\rho}{\fund{C_2}}\equiv \rho_c, \quad \text{and}\quad \Tr \rho(x_2) = 2\cos \theta_2.
    \]
    Up to conjugation, we can assume that $\restr{\rho}{\fund{\Sigma_2'}}$ has image in $\Ui$. In particular, $\rho(x_2)=e^{i \theta_2}$ up to conjugation. This implies that $(\theta_2,\varepsilon) \in H(Y) \subset \R{\Sigma_2'}$. We conclude that, for every $\theta_2 \in (0,\pi) \cup (\pi,2\pi)$, the point $(\theta_2,\varepsilon)$ is in $ H(Y) \subset \R{\Sigma_2'}$. This concludes the forth statement.
     \end{proof}
\end{lemma}

Here is an observation on the next theorem: let $Y=Y_1 \cup_{\Sigma_1'} C_2$, the trivial representation $t\colon \fund{Y_1} \to SU(2)$ is abelian and $\restr{t}{\fund{\Sigma_1}}$ has coordinates $(0,0)\in \R{\Sigma_1'}$, hence $\restr{t}{\Sigma_1} \in A(Y_1)$. This implies that $A(Y_1) \cap \{\psi_1=0\} \subset \R{\Sigma_1'}$ is never empty. We give Figure \ref{Figure example C2} as an example how Theorem \ref{teo: alg for C2} works.

\begin{teo}\label{teo: alg for C2}
    Let $Y=Y_1 \cup_{\Sigma_1} C_2$. Let the set $T(Y_1,\partial Y_1) =A(Y_1) \cup H(Y_1)$ be considered as a subset of $\R{\Sigma_1'}$. As a subset of $\R{\Sigma_2'}$, the set $T(Y,\partial Y)$ is equal to $A(Y) \cup H(Y)$. Furthermore,
        \begin{align}\label{eq: la uso una volta. A(Y) in C2 alg}
        A(Y) = \begin{dcases}
            \{\psi_2 = 0\} & \text{if } A(Y_1) \cap \{\psi_1=\pi\} = \emptyset \\
            \{\psi_2 = 0\} \cup \{\psi_2=\pi\} & \text{otherwise}.
        \end{dcases}
         \end{align}
        and
        $H_{Y,t}  \cup H_{Y,0} \cup H_{Y,\pi} \subseteq H(Y)$, where
        \begin{align*}
             H_{Y,t} \coloneq \left\{(- \theta_1+\pi,\psi_1) \in \R{\Sigma_2'} \middle| (\theta_1,\psi_1) \in T(Y_1,\partial Y_1), \psi_1 \notin \pi \mathbb{Z}\right\},
            \end{align*}
and, for $\varepsilon \in \{0,\pi\}$,
            \begin{align*}
             H_{Y,\varepsilon} \coloneq \begin{dcases}
                    \{\psi_2 = \varepsilon\} \subset \R{\Sigma_2'}& \text{if } H(Y_1) \cap \{\psi_1=\varepsilon\} \neq \emptyset \\
                    \{\psi_2 = \varepsilon \}\setminus \{0,\pi\}^2 \subset \R{\Sigma_2'} & \text{if } T(Y_1,\partial Y_1) \cap \left( \{\psi_1=\varepsilon\} \setminus \{0,\pi\}^2\right) \neq \emptyset \\
           \emptyset & \text{otherwise}.
            \end{dcases}
        \end{align*}
        \begin{proof}
            Let us start by showing the conclusion for $A(Y)$. Let $S$ be the right handed side of \eqref{eq: la uso una volta. A(Y) in C2 alg}. The second statement of Lemma \ref{lemma: almost the receipt for C2} implies that $S \subseteq A(Y)$. Conversely, let $\eta \in A(Y) \subset \R{\Sigma_2'}$. Thus, there exists a representation $\rho \colon \fund{Y} \to SU(2)$ such that
            $\restr{\rho}{\fund{C_2}}$ and $\restr{\rho}{\fund{Y_1}}$ are abelian and $\restr{\rho}{\fund{\Sigma_2}}=\eta$. Lemma \ref{lemma: extension abelian C2} implies that
            \[
            \restr{\rho}{\fund{Y_1}}(h) = \restr{\rho}{\fund{\Sigma_1'}}(h_1)= \pm 1.
            \]
            Thus, since the representation $\restr{\rho}{\fund{\Sigma_1'}}$ extends to an abelian representation of $\fund{Y_1}$, the set $A(Y_1)$ intersect either the line $\{\psi_1 =0\} \subset\R{\Sigma_1'}$ or the line $\{\psi_1 =\pi\} \subset\R{\Sigma_1'}$. Therefore, $A(Y) \subseteq S$. We conclude that $A(Y)=S$.

            Let us focus on $H(Y)$. If $\eta =(-\theta_1+\pi,\psi_1)$ is a point of $H_{Y,t} \subset \R{\Sigma_2'}$, then according to Lemma \ref{lemma: irr extension C2, translazione} there exist an irreducible representation $\rho_c \colon \fund{C_2} \to SU(2)$ such $\restr{\rho_c}{\fund{\Sigma_2'}}=\eta$ and $\restr{\rho_c}{\fund{\Sigma_1'}}$ is the point with coordinates $(\theta_1,\psi_1) \in \R{\Sigma_1'}$. Since $(\theta_1,\psi_1) \in T(Y_1,\partial Y_1)$, the restriction $\restr{\rho_c}{\fund{\Sigma_1'}}$ extends to $\fund{Y_1}$. This implies that $\eta$ extends to an irreducible representation $\fund{Y}\to SU(2)$. Therefore, $H_{Y,t} \subseteq H(Y)$.

            Similarly, if $\eta \in H_{Y,\varepsilon}$, then by Lemma \ref{lemma: irr extension C2, central h} there exists a representation $\rho \in R(Y)$ such that either $\restr{\rho}{\fund{C_2}}$ or $\restr{\rho}{\fund{Y_1}}$ is irreducible. Hence, $\rho$ is irreducible and $\restr{\rho}{\fund{\Sigma_2'}}\equiv \eta$. Therefore, $\eta \in H(Y)$ and $H_{Y,\varepsilon} \subseteq H(Y)$. We conclude that
            \[
                H_{Y,t} \cup H_{Y,0}\cup H_{Y,\pi} \subseteq H(Y) \subseteq \R{\Sigma_2'}.
            \]
        \end{proof}
\end{teo}

