\section{A crunchy property}

\begin{defn}\label{defn: the line}
Let $Y$ be a $3$-manifold with torus boundary.
Let $\R{\partial Y}$ comes with coordinates $(\theta,\psi)$.
We say that $L \subset \R{\partial Y}$ is a \emph{line} of the torus $\R{\partial Y}$ if $L$ is of the form
\[
    L_{\nicefrac{r}{s}}+c \coloneq \left\{(\theta,\psi)\in \R{\partial Y} \middle| r \theta + s \psi_1 \equiv_{2\pi} c \right\},
\]
where $\nicefrac{r}{s}\in \mathbb{Q} \cup \{\nicefrac{1}{0}\}$ and $c \in [0,2\pi]$. In particular, we say that $L$ has slope $\nicefrac{r}{s}$.
\end{defn}

Let $\Sigma$ be a torus. We say that a path $\gamma \colon (-1,1)\to \R{\Sigma}$ is \emph{trivial} if it is homotopic relative to the set
\[
    \left\{\lim_{x \mapsto \pm 1} \gamma(x)\right\} \subset \R{\Sigma}
\]
to a constant path.
For instance, a path that starts from a point, travels for a finite amount of time, and returns back to the starting point on its track is a trivial path.

\begin{defn}\label{defn: property P strong}
    Let $Y$ be a $3$-manifold with torus boundary. We say that $Y$ is \emph{LIPA} if there exists a nontrivial path $\gamma \colon (-1,1)\to H(Y)$ such that $\gamma \not \subset A(Y)$,
    \[
        \lim_{x \mapsto \pm 1} \gamma(x) \in A(Y)
    \]
    and there exists a line of $\R{\partial Y}$ containing $\gamma$. Such a path is called a \emph{LIPA-path} of $Y$.
\end{defn}

Notice that if a manifold $Y$ with torus boundary is LIPA, then $H(Y) \subset \R{\partial Y}$ is nonempty and in particular $Y \neq S^1 \times \mathbb{D}^2$. In this section we are going to prove that if $Y$ graph manifold rational homology solid torus and $Y \neq S^1 \times \mathbb{D}^2$, then $Y$ is LIPA.

Let $n \ge 3$, it is easy to see that for every $1\le i \le n-1$ there exists a pair of vertical tori $\Sigma_1,\Sigma_2 \subset \mathbb{D}^2(\nicefrac{p_1}{q_1},\cdots, \nicefrac{p_n}{q_n})$ such that
\begin{equation}
\label{eq: una volta, dec con m fibers}
    \overline{\mathbb{D}^2(\nicefrac{p_1}{q_1},\cdots, \nicefrac{p_n}{q_n}) \setminus \left(\Sigma_1\cup \Sigma_2\right)} = \mathbb{D}^2(\nicefrac{p_1}{q_1},\cdots, \nicefrac{p_i}{q_i}) \cup C_3 \cup \mathbb{D}^2(\nicefrac{p_{i+1}}{q_{i+1}},\cdots \nicefrac{p_n}{q_n}).
\end{equation}
This implies that if $Y$ is a graph manifold rational homology solid torus, then we can choose a system of disjoint tori $\tau \subset Y$ as in Corollary \ref{cor: the usefull decomposition} such that
\[
\overline{Y\setminus \tau} = \left(\bigcup_{k\in K} C_3\right) \cup \left(\bigcup_{j \in J} C_2\right) \cup \left(\bigcup_{i \in I}  D_i\right),
\]
where $D_i$ indicates a Seifert fibred space with disk base space and at most two singular fibers.

\begin{lemma}\label{lemma: the manifold D(p1,p2) has the property P}
    Let $Y = \mathbb{D}^2(\nicefrac{p_1}{q_1},\nicefrac{p_2}{q_2})$ be such that $2 \le p_1 \le p_2$. The manifold $Y$ is LIPA.
    \begin{proof}
        Without loss of generality, we can assume that $q_1$ and $q_2$ are odd. We consider $\fund{Y}$ presented as follows:
        \[
            \fund{Y} = \langle x_1,x_2,h \,|\, x_1^{p_1}h^{q_1},x_2^{p_2}h^{q_2}, \text{$h$ central} \rangle.
        \]
        Let $\mu$ be the slope $\partial Y$ such that $[\mu]=x_1x_2 \in \fund{Y}$. We call such a slope \emph{fibration meridian}. For details see \cite[Definition 2.1.1]{Mino} or \cite[Section 2.2]{LspaceIntervalGraphManifold}.

        By Fact \ref{Fact: centralizers}, if $\rho \in R(Y)$ is irreducible, then $\rho(h) \in \ZSU$. We define $H(Y)_\pi \subset H(Y)$ as
        \[
            H(Y)_\pi = \left\{\eta \in H(Y) \middle| \eta(h)=e^{i\pi}=-1\right\}.
        \]
        According to \cite[Lemma 7.8]{Mino} there the following map is surjective and two-to-one:
        \[
    f \colon H(Y)_\pi \to  J_\pi(p_1,p_2) \quad \text{with} \quad
       \eta \mapsto \Tr\eta(\mu),
   \]
   where
   \[
    J_\pi(p_1,p_2) = \bigcup_{\substack{k_1,k_2 \in \mathbb{Z} \\ k_i \text{ odd} }} I \left(2 \cos\left( \frac{\pi k_1}{p_1}\right), 2 \cos\left( \frac{\pi k_2}{p_2}\right) \right),
   \]
   where the interval $I \subseteq (-2,2)$ is as in \eqref{eq: interval I}.
   According to \cite[Lemma 7.6]{Mino}, the interval $J_\pi(p_1,p_2)$ is nonempty.
   For $k_1,k_2$ odd, we write $I_{k_1,k_2}$ for the interval $I\left(2\cos (\nicefrac{\pi k_1}{p_1}),2\cos (\nicefrac{\pi k_2}{p_2})\right)$. Since $J_\pi(p_1,p_2)$ is nonempty, at least one interval $I_{k_1,k_2}$ is nonempty. Let us assume that the interval $I_{k_1,k_2}$ is nonempty. This latter is connected and the preimage $f^{-1}I_{k_1,k_2}$ has two connected components in $H_{Y,\pi}$. Thus, $f^{-1}I_{k_1,k_2}$ defines two paths
   \[
   \gamma_{k_1,k_2}^{1},\gamma_{k_1,k_2}^{2} \colon (-1,1) \to H_{Y,\pi}.
   \]
   We are going to prove that these two paths are LIPA-paths for $Y$ by proving the conditions of Definition \ref{defn: property P strong}.

    Let $\alpha\in \{1,2\}$, the path $\gamma_{k_1,k_2}^{\alpha}$ is contained in the line
    \[
        L_{\pi} \coloneq \left\{ \eta \in \R{\partial Y} \middle| \eta(h)=e^{i\pi}\right\}.
    \]
    As the rational longitude of $Y$ is not the regular fiber $h$, the path $\gamma_{k_1,k_2}^{\alpha}$ is not contained $\subset A(Y)$.

    We observe that, according to the function $f$ above,
   \[
    \lim_{x \mapsto \pm 1} \Tr\left(\left.\gamma_{k_1,k_2}^{\alpha}\middle(x\right)(\mu)\right) \in \partial I_{k_1,k_2} \quad \text{with} \quad \alpha \in \{1,2\}.  
    \]
    We recall that
    the endpoints of the interval $I_{k_1,k_2}$ are
    \begin{equation*}
    \left\{ 2 \cos \left( \pi \left( \frac{k_1}{p_1} + \frac{k_2}{p_2}\right) \right), 2 \cos \left( \pi \left( \frac{k_1}{p_1} - \frac{k_2}{p_2}\right)\right) \right\}.
\end{equation*}
This implies that if $\eta \in \R{\partial Y}$ is a representation such that
\[
    \eta \in \left\{ \lim_{x \mapsto \pm 1} \gamma_{k_1,k_2}^{\alpha}(x) \right\}_{\alpha=1,2},
\]
then $\eta(h)=-1$ and $\eta(\mu)=e^{i\theta}$, where
\[
    \theta \in \left\{\pi \left( \frac{k_1}{p_1} + \frac{k_2}{p_2}\right),\pi \left( \frac{k_1}{p_1} - \frac{k_2}{p_2}\right),2\pi -\pi \left( \frac{k_1}{p_1} + \frac{k_2}{p_2}\right),2\pi-\pi \left( \frac{k_1}{p_1} - \frac{k_2}{p_2}\right)\right\}.
\]
Let $g \coloneq \gcd(p_1,p_2)$. As a consequence of \cite[Lemma 5.1]{Mino}, we obtain that
\[
    \lambda_Y= \mu \frac{p_1p_2}{o_Yg} + h \frac{q_1p_2 +q_2p_1}{o_Yg}.
\]
It is straightforward to prove that if $\eta$ is as above, then $\eta(\lambda_Y)^{o_Y}=1$. This implies that $\eta \in A(Y)$ by Corollary \ref{cor: A(Y) with rational longitude}. Hence, for $\alpha \in \{1,2\}$
\[
    \lim_{x \mapsto \pm 1} \gamma_{k_1,k_2}^{\alpha} \in A(Y).  
\]
    \end{proof}
\end{lemma}

\begin{lemma}\label{lemma: the sum is empty then}
    Let $Y=Y_1 \cup_{\Sigma_1}C_3 \cup_{\Sigma_2} Y_2$. If $H(Y_2) \neq \emptyset$ and the sum $A(Y_1)+H(Y_2) \subset \R{\Sigma_3}$ is empty, then $\Delta(h_1,\lambda_{1})=0$. 
    \begin{proof}
        Let $n,m \in \mathbb{Z}$ be integers such that $\lambda_{1}=nx_1+mh_1$ in $\fund{\Sigma_1}$. Thus, $|n| = \Delta(\lambda_{1},h_1)$. By Corollary \ref{cor: A(Y) with rational longitude},
        \[
            A(Y_1)= \left\{ (\theta_1,\psi_1) \in \R{\Sigma_1} \middle| o_1 \left( n\theta_1+m\psi_1\right)=0\right\}.
        \]
        Let $(\theta_0,\psi_0) \in H(Y_2)$, such a point exists since $H(Y_2) \neq \emptyset$ by hypothesis. If $A(Y_1) \cap \{\psi_1= \psi_0\} \neq \emptyset$, then $A(Y_1) + H(Y_2) \neq \emptyset$ by Definition \ref{defn: A+B}. Therefore, since $A(Y_1) + H(Y_2)$ is empty by hypothesis, then
        $
            A(Y_1) \cap \{\psi_1= \psi_0\} = \emptyset.
        $
        This implies that $|n|=\Delta(\lambda_{1},h_1)=0$.
    \end{proof}
\end{lemma}

\begin{lemma}\label{C3 has the property P}
    Let $Y=Y_1 \cup_{\Sigma_1} C_3 \cup_{\Sigma_2} Y_2$ graph manifold rational homology solid torus. Let us assume that $Y$ is not a solid torus. For $j \in \{1,2\}$, if $Y_j$ is either LIPA or a solid torus, then the manifold $Y$ is LIPA.
    \begin{proof}
        If $Y_j$ is a solid torus, then, since $Y$ is a graph manifold, $\Delta(\lambda_{j},h_j) \neq 0$. Hence, if $Y_1$ and $Y_2$ are two solid tori, the manifold $Y$ is a Seifert fibred space with disk base space. Since $Y$ is not a solid torus by assumption, the conclusion holds by Lemma \ref{lemma: the manifold D(p1,p2) has the property P}. Therefore, we assume that either $Y_1$ or $Y_2$ is not a solid torus. Without loss of generality, we assume that $Y_2$ is not a solid torus and, by hypothesis, this implies that $Y_2$ is LIPA.

        Since $Y_2$ is LIPA, the set $H(Y_2)$ is nonempty. If $\geo{\lambda_1}{h_1} =0$, then, since $Y$ is a graph manifold, $Y_1$ is not a solid torus and, by hypothesis, it is LIPA. Thus, $H(Y_1) \neq \emptyset$ and, according to Corollary \ref{cor: C3 obstruction longitudes}, we obtain that $\geo{\lambda_2}{h_2}\neq 0$. Therefore, up to swapping $Y_1$ and $Y_2$, we can assume that $\geo{\lambda_1}{h_1}\neq 0$. According to Lemma \ref{lemma: the sum is empty then} the sum $A(Y_1)+H(Y_2) \subset\R{\Sigma_3}$ is not empty.
        Let $\gamma : (-1,1)\to H(Y_2)$ be an LIPA-path of $Y_2$ in $\R{\Sigma_2}$. Thus,
        \[
            \lim_{x \to \pm 1} \gamma(x) \in A(Y_2).
        \]
        As shown in the proof of Lemma \ref{lemma: the sum is empty then}, since $\geo{\lambda_1}{h_1}\neq 0$, for every $x \in (-1,1)$
        \[
            A(Y_1) + \gamma(x) \neq \emptyset \quad \text{and therefore} \quad  A(Y_1) + \gamma(x) \in A(Y_1)+H(Y_2) \subseteq H(Y) \subseteq \R{\Sigma_3}.
        \]
        Thus, the sum $A(Y_1) + \ima{\gamma}$ defines a path $\delta \colon (-1,1)\to H(Y)$. 
        Furthermore, we obtain that
        \[
            \left\{\lim_{x \to \pm 1} \delta(x)\right\}\in \lim_{x \to \pm 1} \left(A(Y_1) + \gamma(x)\right) \subseteq A(Y_1)+A(Y_2) = A(Y).
        \]
        Since $\gamma \not \subset A(Y_1) $, we obtain that $\delta \not \subset A(Y)$. This implies that $Y$ is LIPA.
        \end{proof}
\end{lemma}

\begin{lemma}\label{C2 has the property P}
    Let $Y=Y_1 \cup_{\Sigma_1'} C_2$ be an graph rational homology solid torus. If $Y_1$ either is LIPA or it is a solid torus, then the manifold $Y$ is  LIPA.
    \begin{proof}
        We assume $\R{\Sigma_1'}$ and $\R{\Sigma_2'}$ to be parameterized as in \eqref{eq: coordinates for C2}.
        Let $n,m \in \mathbb{Z}$ be integers such that
        \[
            \lambda_1 = n x_1 + m h_1 \in \fund{\Sigma_1}.
        \]
        Thus, $|n|=\Delta(\lambda_1,h_1)$. This implies that
        \[
            A(Y_1)= \left\{(\theta_1,\psi_1)\in \R{\Sigma_1'} \middle| o_1 (n \theta_1+m\psi_1)=0\right\}
        \]
        According to Corollary \ref{cor: C2 obstruction longitudes}, $n=\Delta(\lambda_1,h_1)\neq 0$. By Theorem \ref{teo: alg for C2}, the set $A(Y)\subset \R{\Sigma_2}$ is equal to $\{\psi_2=0\}\cup\{\psi_2=\pi\}$. We define $H'$ as
        \begin{align*}
            H'&= \left\{(\pi -\theta_1,\psi_1)\in \R{\Sigma_2'} \middle| (\theta_1,\psi_1) \in A(Y_1)\right\} \\
            &= \left\{(\pi -\theta_1,\psi_1)\in \R{\Sigma_2'} \middle| o_1 (n\theta_1+m\psi_1)=0\right\} \\
            &=\left\{(\theta_2,\psi_2) \in \R{\Sigma_2'} \middle| o_1\left( n\theta_2 -m\psi_2 - \pi n \right)=0\right\} .
         \end{align*}
        According to Theorem \ref{teo: alg for C2}, $H' \subseteq H(Y)$.
        In fact $H'$ is the subset of $ H_{Y,t}$ of Theorem \ref{teo: alg for C2}. The set $H'$ is made of $o_1$-many parallel lines each of slope $\nicefrac{-n}{m}$.
        Since $n \neq 0$, Theorem \ref{teo: alg for C2} implies that
        \[
            H' \not\subset A(Y)= \left\{ (\theta_2,\psi_2) \in \R{\Sigma_2'} \middle| \psi_2=0,\pi \right\}
        \]
        Moreover, each line of $H'$ intersects both lines of $A(Y)$. Hence, $H'\subset H_{Y,t}$ contains a LIPA path. Therefore, $Y$ is LIPA.
    \end{proof}
\end{lemma}

\begin{teo}\label{teo: admissible pieces have the property P}
    Let $Y$ be a graph manifold rational homology solid torus. If $Y$ is not a solid torus, then $Y$ has the LIPA.
    \begin{proof}
    As we explained before, Corollary \ref{cor: the usefull decomposition} implies the existence of a system of disjoint tori $\tau$ such that $\overline{Y \setminus \tau}$ is union of $C_3$'s, $C_2$'s, solid tori, and Seifert fibred spaces with two singular fibers and disk base space. Lemma \ref{lemma: the manifold D(p1,p2) has the property P}, Lemma \ref{C3 has the property P}, and Lemma \ref{C2 has the property P} imply the conclusion. 
    \end{proof}
\end{teo}

As a consequence of Theorem \ref{teo: admissible pieces have the property P}, we show Proposition \ref{prop: sigma =1 ish} and Corollary \ref{cor: o1=1 and o2=3 and delta=1}.

\begin{repprop}{prop: sigma =1 ish}
     Let $Y_1$ and $Y_2$ be two graph manifold with torus boundary and null-homologous longitudes. If neither $Y_1$ nor $Y_2$ is a solid torus and $Y=Y_1 \cup_{\Sigma} Y_2$ is a rational homology sphere such that $\Delta(\lambda_1,\lambda_2)= 1$, then $Y$ is not $SU(2)$-abelian.
     \begin{proof}
    According to Theorem \ref{teo: admissible pieces have the property P}, the manifolds $Y_1$ and $Y_2$ are both LIPA.
    Since $\geo{\lambda_1}{\lambda_2}=1$, the ordered set $\{\lambda_1,\lambda_2\}$ is a basis for $\fund{\Sigma}$. We give the space $\R{\Sigma}$ coordinates $(\theta,\psi)$ according to this ordered basis as in \eqref{eq: general coordinates}. According to Corollary \ref{cor: A(Y) with rational longitude}, the set $\{\theta=0\}$ (resp. $\{\psi=0\}$) is equal to $A(Y_1)$ (resp. $A(Y_2)$) as a subset of $\R{\Sigma}$.
         For $i \in \{1,2\}$, let $\gamma_i \colon (-1,1)\to \R{\Sigma}$ be a LIPA-path of $Y_i$. Let $\gamma_1^t$ (rel. $\gamma_2^t$) the translation of $\gamma_1$ (rel. $\gamma_2$) by $(0,\pi)$ (rel. $(\pi,0)$). Lemma \ref{lemma: translation} implies that $\gamma_i^t$ is a LIPA path for $Y_i$.

         We call $\Gamma_1$ and $\Gamma_1^t$ the images of $\gamma_1$ and $\gamma_1^t$. We define $\Gamma_2$ and $\Gamma_2^t$ similarly. 
         If either $\Gamma_1 \cup \Gamma_1^t$ intersects $A(Y_2)$ or $\Gamma_2 \cup \Gamma_2^t$ intersects $A(Y_1)$, then either
         $H(Y_1)\cap A(Y_2) \neq \emptyset$ or $A(Y_1)\cap H(Y_2) \neq \emptyset$ respectively. In both cases, the conclusion holds by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.

         Let us assume that $\Gamma_1 \cup \Gamma_1^t$ and $\Gamma_2 \cup \Gamma_2^t$ do not intersect $A(Y_2)=\{\theta=0\}$ and $A(Y_1)=\{\psi=0\}$ respectively.
         Since $\Gamma_1$ is the image of a LIPA-path of $Y_1$, it connects the points
         \[
            (0,\psi_1) \in A(Y_1) \quad \text{and} \quad (0,\psi_2) \in A(Y_1).
         \]
         Therefore $\Gamma_1^t$ connects the points
         \[
            (0,\psi_1+\pi) \in A(Y_1) \quad \text{and} \quad (0,\psi_2+\pi) \in A(Y_1).
         \]
         Since we assumed that $\Gamma_1 \cup \Gamma_1^t$ is disjointed from $A(Y_2)=\{\psi=0\}$, we can assume that either $\psi_1,\psi_2 \in [0,\pi]$ or $\psi_1,\psi_2\in [\pi,2\pi]$. Similarly, $\Gamma_2$ is the image of a LIPA-path of $Y_2$, then is connects the points
         \[
            (\theta_1,0) \in A(Y_2) \quad (\theta_2,0) \in A(Y_2),
         \]
         and we can assume that either $\theta_1,\theta_2 \in [0,\pi]$ or $\theta_1,\theta_2 \in [\pi,2\pi]$.
         Figure \ref{Figure: sigma small. s=1} shows the union
         \[
            \left(A(Y_1) \cup \Gamma_1\cup \Gamma_1^t\right) \cup \left(A(Y_2) \cup \Gamma_2\cup \Gamma_2^t\right) \subset \R{\Sigma},
         \]
         in $(\theta,\psi)$-coordinates.
         In particular, Figure \ref{Figure: sigma small. s=1} shows that $H(Y_1) \cap H(Y_2) \neq \emptyset$. We conclude that $Y=Y_1 \cup_{\Sigma} Y_2$ is not $SU(2)$-abelian, by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.
     \end{proof}
\end{repprop}

Let $Y$ be a $3$-manifold as in Proposition \ref{prop: sigma =1 ish}, if $Y_1$ and $Y_2$ are \emph{integer} homology solid tori, then $Y$ is an integer homology sphere. Proposition \ref{prop: sigma =1 ish} implies that $Y$ is not $SU(2)$-abelian. This is also proven in \cite{ToroidalZS3HaveIrreducibleRepres} in which the authors proved that every toroidal integer homology $3$-sphere is not $SU(2)$-abelian. In particular, they showed that if a rational homology solid torus $Y$ whose longitude $\lambda_Y$ is integrally null-homologous admits a similar LIPA-path whenever $Y(\lambda_Y)$ non-trivial instanton Floer homology (see \cite[Theorem 3.5]{ToroidalZS3HaveIrreducibleRepres}).

