\begin{repcor}{cor: o1=1 and o2=3 and delta=1}
    Let $Y_1$ and $Y_2$ be two graph manifolds. If neither $Y_1$ nor $Y_2$ is a solid torus, $o_1=1$, $o_2=3$, and $Y=Y_1 \cup_{\Sigma} Y_2$ is a rational homology sphere such that $\Delta(\lambda_1,\lambda_2)= 1$, then $Y$ is not $SU(2)$-abelian.
    \begin{proof}
        The proof is similar to Proposition \ref{prop: sigma =1 ish}.
        Since $\geo{\lambda_1}{\lambda_2}=1$, the set $\{\lambda_1,\lambda_2\}$ is an ordered basis for $\fund{\Sigma}$. We give the space $\R{\Sigma}$ coordinates $(\theta,\psi)$ according to this ordered basis as in \eqref{eq: general coordinates}.
        According to Corollary \ref{cor: A(Y) with rational longitude} implies that $A(Y_1)=\{\psi=0\} \subset \R{\Sigma}$ and
        \[
            A(Y_2)=\bigcup_{k =0,1,2}\left\{\psi= \frac{2\pi k}{3}\right\}  \subset \R{\Sigma}.
        \]
        For $i \in \{1,2\}$ let $\gamma_i,\gamma_i^t,\Gamma_i,\Gamma_i^t$ be as in the proof of Proposition \ref{prop: sigma =1 ish}. If either $\Gamma_1 \cup \Gamma_1^t$ intersects $A(Y_2)$ or $\Gamma_2 \cup \Gamma_2^t$ intersects $A(Y_1)$, then either
         $H(Y_1)\cap A(Y_2) \neq \emptyset$ or $A(Y_1)\cap H(Y_2) \neq \emptyset$ respectively. In both cases, the conclusion holds by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.

         Let us assume that $\Gamma_1 \cup \Gamma_1^t$ and $\Gamma_2 \cup \Gamma_2^t$ do not intersect $A(Y_2)$ and $A(Y_1)$ respectively.
         Since $\Gamma_2$ is the image of a LIPA-path of $Y_2$, it connects the points
         \[
            \left(\theta_1,\frac{ 2 \pi k}{3}\right) \in A(Y_2) \quad \left(\theta_2,\frac{2 \pi k}{3}\right) \in A(Y_2),
         \]
         with $k \in \{0,1,2\}$.
         Since we assumed that $\Gamma_2 \cup \Gamma_2^t$ is disjointed from $A(Y_1)=\{\theta=0\}$, we can assume that either $\theta_1,\theta_2 \in [0,\pi]$ or $\theta_1,\theta_2 \in [\pi,2\pi]$.
         Similarly, $\Gamma_1$ is the image of a LIPA-path of $Y_2$, then is connects the points
         \[
            (0,\psi_1) \in A(Y_1) \quad \text{and} \quad (0,\psi_2) \in A(Y_1).
         \]
         Since we assumed that $\Gamma_1$ is disjoint from $A(Y_2)$, then there exists an $k' \in \{0,1,2\}$ such that
         \[
            \psi_1,\psi_2 \in \left[\frac{2\pi k'}{3}, \frac{2 \pi (k'+1)}{3}\right].
         \]
         Similarly, $\Gamma_1^t=\Gamma_1 +(0,\pi)$ connects the points
         \[
            (0,\psi_1+\pi) \in A(Y_1) \quad \text{and} \quad (0,\psi_2+\pi) \in A(Y_1).
         \]
         Therefore, since we assume that $\Gamma_1^t$ is disconnect from $A(Y_2)$, we have that there exists an $k'' \in \{0,1,2\}$ such that
         \[
            \psi_1+\pi,\psi_2 + \pi \in \left[\frac{2\pi k''}{3}, \frac{2 \pi (k''+1)}{3}\right].
         \]
         This implies that there exists a $k ''' \in \{0,\cdots,5\}$ such that
         \[
         \psi_1,\psi_2 \in \left[ \frac{\pi k'''}{3}, \frac{\pi (k'''+1)}{3} \right].
         \]
         If $\Gamma_1\cup \Gamma_1^t$ interests $\Gamma_2\cup \Gamma_2^t$, then $Y=Y_1 \cup_{\Sigma} Y_2$ is not $SU(2)$-abelian by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}. Let us assume that this intersection is empty. Without loss of generality, we can assume that $\Gamma_1$ connects the points
         \[
            (0,\psi_1) \in A(Y_1) \quad \text{and} \quad (0,\psi_2) \in A(Y_1), \quad \text{with} \quad \psi_1,\psi_2 \in \left[0, \frac{\pi}{3}\right]
         \]
        Since $(\Gamma_1\cup \Gamma_1^t) \cap(\Gamma_2\cup \Gamma_2^t)$ is empty by assumption, we conclude that $\Gamma_2$ connects the points
        \[
            \left(\theta_1,\frac{4 \pi}{3}\right) \in A(Y_2) \quad \text{and} \quad \left(\theta_2,2\pi\right) \in A(Y_1), \quad \text{with} \quad \theta_1,\theta_2 \in \left[0, \pi \right].
         \]
         Figure \ref{Figure o1=1 e o2=3} shows the union
         \[
            \left(A(Y_1) \cup \Gamma_1\cup \Gamma_1^t\right) \cup \left(A(Y_2) \cup \Gamma_2\cup \Gamma_2^t\right) \subset \R{\Sigma},
         \]
         in $(\theta,\psi)$-coordinates. We define
         \[
            \Gamma_2^\dagger = \left\{ (2\pi -\theta, 2\pi - \psi) \middle| (\theta,\psi) \in \Gamma_2 \right\}.
         \]
         Corollary \ref{cor: jewelled repr} implies that $\Gamma_2^\dagger \subset H(Y_2)$, this is the red dotted line drawn in Figure \ref{Figure o1=1 e o2=3}. In particular, $\Gamma_2^\dagger$ connects the points
         \[
            \left(2\pi -\theta_1,\frac{2 \pi}{3}\right) \in A(Y_2) \quad \text{and} \quad \left(2 \pi-\theta_2,0\right) \in A(Y_1), \quad \text{with} \quad \theta_1,\theta_2 \in \left[0, \pi \right].
         \]
         This implies, as is shown in Figure \ref{Figure o1=1 e o2=3}, that the set $\Gamma_2^\dagger$ intersects $\Gamma_1\cup \Gamma_1^t$. This implies that $H(Y_1)\cap H(Y_2) \neq \emptyset$. The conclusion is given by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.
    \end{proof}
\end{repcor}

Let $Y=Y_1 \cup_{\Sigma} Y_2$ be a toroidal manifold either as in Proposition \ref{prop: sigma =1 ish} or as in Corollary \ref{cor: o1=1 and o2=3 and delta=1}.
We denote by $\mathcal{L}(Y_1)$ and $\mathcal{L}(Y_2)$ the \emph{L-space intervals} of $Y_1$ and $Y_2$ respectively, details can be found in \cite{LspaceIntervalGraphManifold}.
As is well-documented, the rational longitude of a $3$-manifold with torus boundary is not an L-space slope. In particular $\lambda_2 \notin \mathcal{L}(Y_2)$. Moreover,
according to \cite[Theorem 1.3]{boyer2023slopedetectiontoroidal3manifolds}, the slope $\lambda_2 \subset \Sigma=\partial Y_1$ is NLS-detected for $Y_1$. This, in particular, means that $\lambda_2 \notin \mathcal{L}^\circ(Y_1)$. Therefore,
\[
    \lambda_2 \notin \mathcal{L}^\circ(Y_1) \cup \mathcal{L}^\circ(Y_2) \subset \{\text{slopes of } \Sigma\}.
\]
By \cite[Theorem 1.1]{boyer2023slopedetectiontoroidal3manifolds}, the manifold $Y=Y_1 \cup_{\Sigma} Y_2$ is not an L-space.
This implies that Proposition \ref{prop: sigma =1 ish} and Corollary \ref{cor: o1=1 and o2=3 and delta=1} are further evidences of Conjecture \ref{conj: SU(2)-ab implies HF L-space}.

\section{Some utensils}
\label{sec. utensilis}
In this section we introduce tools that we shall use in the proof of Theorem \ref{teo: sigma small then not SU(2)-abelian}. Namely, we will define the weight $\mu$ graph manifolds with torus boundary and show that, under the assumption of having a first homology group with small order, we can exclude the $C_2$ pieces in the decomposition of Corollary \ref{cor: the usefull decomposition}.

Let $Y$ be a graph manifold rational homology solid torus. We recall that $\R{\partial Y}$ is a torus and that a rational line of $\R{\partial Y}$ is homeomorphic to a circle $S^1$. We know that $T(Y,\partial Y) = A(Y) \cup H(Y)$.
A line $L \subset \R{\partial Y}$ is \emph{rational} if $L$ is not dense.

If $Y$ is a Seifert fibred space with disk base space, then the regular fiber $h \in \fund{Y}$ is in the center $\mathcal{Z}(\fund{Y})$.
By Fact \ref{Fact: centralizers},
we obtain
\[
    T(Y,\partial Y) \subseteq A(Y) \cup \left\{\eta \in \R{\partial Y} \middle| \eta(h) \in \ZSU\right\},
\]
Therefore, by Corollary \ref{cor: A(Y) with rational longitude}, the space $T(Y,\partial Y) \subset \R{\partial Y}$ is contained in a in the union of at most $o_Y+2$ rational lines of $\R{\partial Y}$, where $o_Y$ is the order of the rational longitude of $Y$.

Let $Y$ be a graph manifold rational homology solid torus.
An an application of Corollary \ref{cor: the usefull decomposition}, Theorem \ref{teo: alg for C3}, and Theorem \ref{teo: alg for C2}, there exists a finite set of distinct rational lines $L_i \subset \R{\partial Y}$ such that
\[
    H(Y) \subseteq \coprod_{i=1}^n L_i.
\]
Let $\{x_1,x_2\}$ be a basis for $\fund{\partial Y}$, we parameterized $\R{\partial Y}$ with coordinates according to this basis as in \eqref{eq: general coordinates}.
We consider the torus $\R{\partial Y}$ as the product of two unitary circles according to this coordinates:
\[
    \R{\partial Y} = \{e^{i \theta}\} \times \{e^{i \psi}\} = S^1 \times S^1.
\]
We equip the torus $\R{\partial Y}$ with the natural Lebesgue measure $m$ such that $m(\R{\partial Y}) = (2\pi)^2$.
We recall that, for $\nicefrac{p}{q} \in \mathbb{Q} \cup \{\nicefrac{1}{0}\}$ and $c \in [0,2\pi]$, the line
\[
    L=L_{\nicefrac{p}{q}}+c= \left\{ (\theta,\psi) \in \R{\partial Y} \middle| p \theta + q\psi = c \right\}
\]
has slope $\nicefrac{p}{q}$.
Therefore, if the line $L \subset \R{\partial Y}$ has slope $\nicefrac{p}{q} \in \mathbb{Q} \cup \{\nicefrac{1}{0}\}$, then $L$ has length, with respect to the measure $m$, equal to $2\pi\sqrt{p^2 + q^2}$.
We equip the line $L$ with the Lebesgue measure $h$
induced by the measure $m$ on $\R{\partial Y}$. We recall that
$h$ is such that $h(L)=2\pi \sqrt{p^2 + q^2}$.

\begin{defn}\label{degn weight mu}
Let $Y$ be a graph manifold rational homology solid torus as above. Let $\{L_i\}_{i=1}^n$ be a finite set of rational line of $\R{\partial Y}$ whose union contains $H(Y)$.
We define a weight $\mu$ on the $L_i$ as follows:
\[
    \mu(L_i)= \begin{dcases}
        \frac{h(H(Y) \cap L_i)}{h(L_i)} & \text{if $L_i$ contains an LIPA-path of $Y$} \\
        0 & \text{otherwise}.
    \end{dcases}
\]
Moreover, we define
\[
    \mu(Y) \coloneq \max_{i=1 , \cdots, n} \left\{ \mu (L_i)\right\}.  
\]
\end{defn}

Roughly speaking, the weight $\mu(L)$ measures the portion of the line $L$ that is covered by a LIPA-path and $\mu(Y)$ is the weight of the longest LIPA-path within $H(Y)$.

As a consequence of Theorem \ref{teo: admissible pieces have the property P}, a graph manifold rational homology solid torus $Y$ has weight $\mu(Y)$ equal to zero if and only if $Y=S^1 \times \mathbb{D}^2$.

\begin{lemma}
    The weight $\mu(Y)$ does not depend on the choice of the basis $\{x_1,x_2\}$.
    \begin{proof}
        Let $L_0 \subset \R{\partial Y}$ be a line such that $\mu(L_0) \neq 0$. We shall prove that $\mu(L_0)$ does not depend of the basis $\{x_1,x_2\}$. Without loss of generality, we assume that $L_0$ is of slope $\nicefrac{0}{1}$. This means that there exists a $c \in [0,2\pi]$ such that
        \[
            L_0 \coloneq \left\{(\theta_1,\psi_1) \in \R{\partial Y} \middle| \theta_1=0, \psi_1=c\right\}.
        \]
        Let $\{y_1,y_2\}$ be a second basis for $\fund{\partial Y}$.
        Let $(\theta_2,\psi_2)$ be the coordinates with respect to the basis $\{y_1,y_2\}$. We denote by $\mu'$ the weight computed using the second basis. Let $n_1,m_1,n_2,m_2$ be integers such that 
        \[
            x_1= n_1y_1+m_1y_2 \quad \text{and} \quad x_2= n_2y_1+m_2y_2.
        \]
        This implies that the following is a homeomorphism:
        \[
            f\colon \R{\partial Y} \to \R{\partial Y} \quad \text{with} \quad \left(\begin{matrix}
                \theta_1 \\
                \psi_1
            \end{matrix}\right) \mapsto \left(\begin{matrix}
                n_1 \theta_2 + m_1 \psi_2 \\
                n_2 \theta_2 + m_2 \psi_2
            \end{matrix}\right).
        \]
        The line $f(L_0)$ is of slope $\nicefrac{m_1}{m_2} \in \mathbb{Q} \cup \{\nicefrac{1}{0}\}$. We denote by $h_0$ the Lebesgue measure on $L_0$ and $h_f$ the Lebesgue measure on $f(L_0)$.
        Notice that $h_0 (L_0)=2\pi$ and $h_f(f(L_0))=2\pi \sqrt{m_1^2+m_2^2}$.
        Let $S \subset L_0$ be a measurable set, it easy to see that
        \[
            h_f\left(f(S)\right) = \sqrt{m_1^2 + m_2^2} \cdot h_0 (S). 
        \]
        Thus,
        \[
            \mu'(f(L_0)) = \frac{h_f\left( H(Y)\cap f(L_0)\right)}{h_f \left( f(L_0) \right)} = \frac{\sqrt{m_1^2+m_2^2} \cdot h_0\left( H(Y)\cap f(L_0)\right)}{2\pi \sqrt{m_1^2+m_2^2}} = \mu(L_0).
        \]
    \end{proof}
\end{lemma}

\begin{exmp}
    The author proved in \cite{Mino} the following identities:
    \begin{itemize}
        \item $\mu \left( \mathbb{D}^2(\nicefrac{2}{1},\nicefrac{2}{1})\right)= 1$,
        \item $\mu \left( \mathbb{D}^2(\nicefrac{2}{1},\nicefrac{3}{1})\right)= \nicefrac{2}{3}$,
        \item $\mu \left( \mathbb{D}^2(\nicefrac{2}{1},\nicefrac{4}{q})\right)= \nicefrac{1}{2}$, where $q \in \mathbb{Z} \setminus 2\mathbb{Z}$.
    \end{itemize}
\end{exmp}

    \begin{lemma}\label{lemma: weight of D2(p1,p2)}
    Let $Y=\mathbb{D}^2 (\nicefrac{p_1}{q_1},\nicefrac{p_2}{q_2})$ with $2 \le p_1 \le p_2$. Then $\mu(Y) \ge \nicefrac{1}{2}$. Moreover, $\mu(Y)= \nicefrac{1}{2}$ if and only if $(p_1,p_2)=(2,4)$. Furthermore, if $(p_1,p_2) \neq (2,4)$, then $\mu(Y) \ge \nicefrac{2}{3}$.
    \begin{proof}
        This is a consequence of \cite[Lemma 7.6, Lemma 7.9, Lemma 7.15]{Mino}.
    \end{proof}
    \end{lemma}

    \begin{lemma}\label{lemma: eta in H(Y)-H(Y) in SFS with 2 sf}
    Let $Y=\mathbb{D}^2(\nicefrac{p_1}{q_1},\nicefrac{p_2}{q_2})$, where $p_i \ge 2$.
    If $\eta \in \R{\partial Y}$ is such that $\eta \in \overline{H(Y)} \setminus H(Y)$, then $\eta \in A(Y)$.
    Furthermore, if 
    $\eta \in \{0,\pi\}^2 \subset \R{\partial Y}$ and $\eta \in \overline{H(Y)} \setminus H(Y)$, then $g \coloneq \gcd(p_1,p_2) \ge 2$.
    \begin{proof}

        Without loss of generality, we can assume that $q_1$ and $q_2$ are odd. We consider $Y=Y_1 \cup_{\Sigma_1} C_3 \cup_{\Sigma_2} Y_2$, where $Y_1$ and $Y_2$ are solid tori.
        We consider $\fund{C_3}$ presented as in \eqref{eq: fundamental group C3} and, for $i \in \{1,2,3\}$, the space $\R{\Sigma_i}$ with coordinates $(\theta_i,\psi_i)$ as in \eqref{eq: coordinates for C3}.
        According to Theorem \ref{teo: alg for C3}, $H(Y)=H_{3,0}\cup H_{3,\pi}$. We recall that, for $i \in \{1,2\}$, Corollary \ref{cor: A(Y) with rational longitude} implies that
        \begin{align}
            \label{eq: per dim equazioni di A(Yi)}
            A(Y_i)= \left\{(\theta_i,\psi_i) \in \R{\Sigma_i} \middle| p_i \theta_i + q_i \psi_1 = 0 \right\}
        \end{align}
        Let $\eta$ be the representation with coordinates $(\varepsilon_1\pi,\varepsilon_2\pi) \in \R{\Sigma_3}$, where $\varepsilon_i \in \{0,1\}$, and let us assume that $\eta \in \overline{H(Y)} \setminus H(Y)$.

        As an application of Theorem \ref{teo: alg for C3}, if $\eta \in \overline{H(Y)}\setminus H(Y))$, then there exist $\theta_1,\theta_2 \in [0,2\pi]$ such that $\theta_i \notin \pi\mathbb{Z}$,
        \begin{align}
            \label{eq: la uso una volta, endpoints}
            \pm 2=\Tr \eta(x_1x_2) \in \partial I(2\cos \theta_1,2\cos \theta_2) = \left\{2\cos (\theta_1+\theta_2),2\cos (\theta_1-\theta_2)\right\},
        \end{align}
        and $(\theta_i,\varepsilon_2 \pi) \in A(Y_i) \cap \{\psi_i = \varepsilon_2\pi\}$. Here the interval $I$ is defined in \eqref{eq: interval I}.

        In particular, the identity in \eqref{eq: la uso una volta, endpoints} implies that either $\theta_1+\theta_2 = \pi \mathbb{Z}$ or $\theta_1-\theta_2 \in \pi \mathbb{Z}$. We notice that, if $(\theta_2,\varepsilon_2 \pi) \in A(Y_2)$, then according to Corollary \ref{cor: jewelled repr}, $(2\pi - \theta_2,\varepsilon_2 \pi) \in A(Y_2)$. Therefore, up to switching $\theta_2$ with $2\pi - \theta_2$, we can assume that $\theta_1+\theta_2 \in \pi \mathbb{Z}$.
        In particular, by Theorem \ref{teo: alg for C3}, $\eta \in A(Y_1) + A(Y_2) =A(Y)$.

        Let us assume that $\varepsilon_2=0$ and therefore $\eta \in \overline{H_{3,0}}\setminus H_{3,0}$. This implies that $\eta(h)=1$.
        The \eqref{eq: per dim equazioni di A(Yi)} implies that for $i \in \{1,2\}$,
        \[
            \theta_i = \frac{2\pi k_i}{p_i} \quad \text{with $k_i \in \{1,\cdots, p_i\}$}.
        \]
        As we stated before, $\theta_1+\theta_2 \in \pi \mathbb{Z}$.
        Without loss of generality, we can say that either $\theta_1+\theta_2 = 2 \pi$ or $\theta_1 + \theta_2 = \pi$.
        We study these two cases separately.
        If $\theta_1+ \theta_2 = 2 \pi$, then
        \[
            \theta_2= 2\pi - \theta_1 = 2\pi \frac{p_1 - k_1}{p_1} = \frac{2\pi k_2}{p_2}.
        \]
        Therefore, for $i \in \{1,2\}$, we obtain that $\theta_i = \frac{2\pi j_i}{g}$ where $g \coloneq\gcd(p_1,p_2)$ and $j_i \in \{1,\cdots, g \}$.
        Since $\theta_i \notin \pi \mathbb{Z}$, then $g \ge 3$.

        If $\theta_1+ \theta_2 = \pi$, then
        \[
            \theta_2= \pi - \theta_1 = 2\pi \frac{p_1 - k_1}{2p_1} = \frac{2\pi k_2}{p_2}.
        \]
        Therefore, $\theta_i = \frac{2\pi j_i}{g'}$ where $g' = \gcd(2p_1,p_2)$ and $j_i \in \{1,\cdots, g' \}$.
        As before, since $\theta_i \notin \pi \mathbb{Z}$, we get that $g' \ge 3$.
        If $g' \equiv_2 1$, then $g=g'$ and we get the conclusion. If $g' \equiv_2 0$, then $g' \ge 4$ and $g \ge 2$.

        Let us assume that $\varepsilon_2=1$ and therefore $\eta \in \overline{H_{3,\pi}}\setminus H_{3,\pi}$. This implies that $\eta(h)=-1$. Again, the \eqref{eq: per dim equazioni di A(Yi)}
        implies that for $i \in \{1,2\}$
        \[
            \theta_i = \frac{ \pi}{p_i} + \frac{2\pi k_i}{p_i} = 2\pi \frac{2k_i +1}{2p_i}  \quad \text{with $k_i \in \{1,\cdots, p_i\}$}.
        \]
        If $\theta_1+ \theta_2 \in \delta \pi$, with $\delta \in \{1,2\}$ then
        \[
            \theta_2 = \delta \pi - \theta_1 = 2\pi \frac{p_1 \delta - 2k_i - 1}{2p_1} = 2\pi \frac{2k_2 +1}{2p_2}.
        \]
        As before, this implies that $\theta_i = \frac{2\pi j_i}{g'}$ where $g' = \gcd(2p_1,2p_2)=2g$ and $j_i \in \{1,\cdots, g'\}$.  
        Since $\theta_i \notin \pi \mathbb{Z}$, then $2g \ge 3$. Hence $g \ge 2$.
    \end{proof}
\end{lemma}

\begin{cor}\label{cor: if eta in H(Y)-H(Y) then P(Y)}
    Let $Y$ be as in Lemma \ref{lemma: eta in H(Y)-H(Y) in SFS with 2 sf}.
    If $\eta \in \{0,\pi\}^2 \subset \R{\partial Y}$ and $\eta \in \overline{H(Y)} \setminus H(Y)$, then $\eta \in P(Y)$.
    \begin{proof}
        We are going to use the same notation of Lemma \ref{lemma: eta in H(Y)-H(Y) in SFS with 2 sf}.
        As we proven in Lemma \ref{lemma: eta in H(Y)-H(Y) in SFS with 2 sf}, if $\eta \in \overline{H(Y)} \setminus H(Y)$, then $\eta \in A(Y)$. In particular, we can assume $g \ge 2$. If $g \ge 3$, then the conclusion is a consequence of \cite[Lemma 6.4]{Mino}.

        Let us assume that $g =2$. We write $p_1=2n_1$ and $p_2=2n_2$ with $\gcd(n_1,n_2)=1$.
        As shown in \cite[Lemma 7.12]{Mino}, if $(\theta_3,\psi_3) \in \overline{H_{3,0}}\setminus H_{3,0}$, then $2 \cos (\theta_3) \neq \pm 2$. This implies that
        $\eta$ cannot be in $\overline{H_{3,0}}\setminus H_{3,0}$. 
        Therefore
        $\eta(h)=-1$ and $\eta \in \overline{H_{3,\pi}}\setminus H_{3,\pi}$.
        According to Theorem \ref{teo: alg for C3},
        there exist $\theta_1,\theta_2 \in [0,2\pi]$ such that $\theta_i \notin \pi\mathbb{Z}$,
        \begin{align*}
            \pm 2=\Tr \eta(x_1x_2) \in \partial I(2\cos \theta_1,2\cos \theta_2) = \left\{2\cos (\theta_1+\theta_2),2\cos (\theta_1-\theta_2)\right\},
        \end{align*}
        and $(\theta_i,\varepsilon_2 \pi) \in A(Y_i) \cap \{\psi_i = \varepsilon_2\pi\}$.
        As we said in the proof of Lemma \ref{lemma: eta in H(Y)-H(Y) in SFS with 2 sf}, we can assume that
        \[
            \theta_1+\theta_2 \in \pi \mathbb{Z}.
        \]
        Since $\eta(h)=-1$, then for $i \in \{1,2\}$, the \eqref{eq: per dim equazioni di A(Yi)} implies that
        \[
        \theta_i = \frac{\pi}{p_i} + \frac{2\pi k_i}{p_i}.
        \]
        Let $o_Y$ be the order of the rational longitude of $Y$.
        We recall, as a consequence of Lemma \cite[Lemma 5.1]{Mino} that $o_Y \equiv_2 0$ if and only if $p_1/2+p_2/2 \equiv_2 0$.
        Since we assumed that $\eta \in \{0,\pi\}^2$ and $\eta \in \overline{H_{3,\pi}}\setminus H_{3,\pi}$, then, without loss of generality, we can assume that $\theta_1+\theta_2= \delta \pi$, with $\delta \in \{1,2\}$.
        Thus,
        \[
            \theta_1+\theta_2 = \pi\frac{2k_1p_2+p_2+2k_2p_1+p_1}{p_1p_2}= \pi\frac{2k_1n_2+n_2+2k_2n_1+n_1}{2n_1n_2}= \delta \pi.
        \]
        If $\theta_1+\theta_2=\delta \pi$, then $2k_1n_2+n_2+2k_2n_1+n_1$ is a multiple of $2n_1n_2$ and in particular it is even. Hence $n_1+n_2=p_1/2+p_2/2 \equiv_20$ and then $o_Y=2$. We have just proven that if $\eta \in \overline{H_{3,\pi}}\setminus H_{3,\pi}$ and $g=2$, then $o_Y=2$ and $\eta(h)=-1$. The conclusion holds by \cite[Lemma 6.4]{Mino}.
    \end{proof}
\end{cor}

For the rest of the section we prove that if $Y$ is an $SU(2)$-abelian graph manifold rational homology sphere with first homology of small order, then $C_2$ does not appear in the decomposition of Corollary \ref{cor: the usefull decomposition}.

\begin{lemma}\label{lemma: gamma non intersecta le linee orizzontali}
Let $Y=Y_1\cup_{\Sigma_1'}C_2$ be graph manifold and $\alpha \subset \Sigma_2$ a slope such that $Y(\alpha)$ is a rational homology sphere. If there exists
irreducible representation $\rho \colon \fund{Y_1} \to SU(2)$ such that $\rho(h_1)=\pm 1$, where $h_1 \subset \Sigma_1 = \partial Y_1$ is the regular fiber of $C_2$, then $Y(\alpha)$ is not $SU(2)$-abelian.
.
\begin{proof}
    As usual, we parameterize $\R{\Sigma_1'}$ and $\R{\Sigma_2'}$ according to the the bases $\{x_1,h_1\}$ and $\{x_2,h_2\}$ as in Section \ref{sec: two important pieces}.
    Therefore, the restriction $\restr{\rho}{\fund{\Sigma_1'}}$ has coordinates $(\theta_1,\varepsilon) \in \R{\Sigma_1'}$, with  $\varepsilon \in \{0,\pi\}$.
    According to Theorem \ref{teo: alg for C2}, since $(\theta_1,\varepsilon) \in H(Y_1)$, the set $\{\psi_2 = \varepsilon \}$ is contained in $H(Y) \subset \R{\Sigma_2'}$.

    Let $n,m \in \mathbb{Z}$ be integers such that
    \[
        \alpha = nx_2+mh_2 \in \fund{\Sigma_2'}.
    \]
    By Lemma \ref{lemma: rational longitude of C2}, the regular fiber $h_2 \subset \Sigma_2'$ is the rational longitude of $Y$.
    Since $Y(\alpha)$ is a rational homology $3$-sphere, $n=\geo{\alpha}{h_2}$ is nonzero. Hence the line
    \[
    L_\alpha = \left\{ n \theta_2+ m \psi_2 =0 \right\} \subset \R{\Sigma_2'}
    \]
    and $\{\psi_2=\varepsilon \}$ have an intersection. This implies that $H(Y) \cap L_\alpha \neq \emptyset$.
    This implies that there exists an irreducible representation $\rho \colon \fund{Y} \to SU(2)$ that kills the slope $\alpha \in \fund{\Sigma_2}'$. 
    Therefore, since
    \[
        \fund{Y(\alpha)} = \frac{\fund{Y}}{\normalsubgroup{\alpha}},
    \]
    the representation $\rho$ gives an irreducible $SU(2)$-representation of $\fund{Y(\alpha)}$.
    \end{proof}
    \end{lemma}

