\begin{rmk}
    Let $\Sigma$ be a closed surface and we denote by $\Sigma_0$ the surface obtained by removing a small open disk from it. Let $Y\neq S^1 \times \mathbb{D}^2$ be a Seifert fibred manifold with torus boundary, that admits a Seifert fibration with $n$ singular fibers and whose base space is $\Sigma_0$. Let $\gamma$ be a slope in $\partial Y$. If $\gamma$ is a regular fiber for a Seifert fibration of $Y$, then $Y(\gamma)$ is a reducible manifold. If $\gamma$ is not a regular fiber, then $Y(\gamma)$ is a closed Seifert fibred manifold with base space $\Sigma$ and with $n+1$ singular fibers. 
    More precisely, $Y(\gamma)$ has $n$ singular fibers with the same orders as $Y$ and one additional singular fiber of order $\Delta(h,\gamma)$, where $h\subset \partial Y$ is a regular fiber.
    \label{rmk: order of the additional fiber of a dehn filling}
\end{rmk}

\begin{prop}\label{prop: C2 and o1=o2=1 then not SUa}
    Let $Y=Y_1\cup_{\Sigma_1'} C_2 \cup_{\Sigma_2'} Y_2$ be a rational homology $3$-sphere such that neither $Y_1$ not $Y_2$ is a solid torus. If $Y$ is a graph manifold such that $o_1=o_2=1$, then $Y$ is not $SU(2)$-abelian.
    \begin{proof}
        Since neither $Y_1$ nor $Y_2$ is a solid torus, they are both LIPA according to Theorem \ref{teo: admissible pieces have the property P}.

        We recall that, as a consequence of Lemma \ref{lemma: rational longitude of C2}, the rational longitude of $Y_1 \cup_{\Sigma_1'} C_2$ is $h_2 \subset \Sigma_2'$. Similarly, the rational longitude of $C_2 \cup_{\Sigma_2'} Y_2$ is $h_1 \subset \Sigma_1'$.
        Since $Y$ is a rational homology $3$-sphere, the manifold
        \[
            N \coloneqq C_2(\Sigma_1',\Sigma_2'; \lambda_1,\lambda_2)
        \]
        is a rational homology $3$-sphere. In particular, $N$ is a Seifert fibred space with base space $\mathbb{RP}^2$.
        If $N$ is not $SU(2)$-abelian, then $Y$ is not $SU(2)$-abelian by Corollary \ref{cor: Y SU(2) allora i due pezzi sono SU(2)-abelian}. Without loss of generality, we can assume that $N$ is $SU(2)$-abelian.
        According to \cite[Proposition 3.5]{Menangerie} and Remark \ref{rmk: order of the additional fiber of a dehn filling}, $N$ is $SU(2)$-abelian if and only if it is either a lens space or $\mathbb{RP}^3 \# \mathbb{RP}^3$. Therefore, $N$ is $SU(2)$-abelian if and only if it has at most one singular fiber. As an application of Remark \ref{rmk: order of the additional fiber of a dehn filling}, either $\geo{\lambda_1}{h_1}=1$ or $\geo{\lambda_2}{h_2}=1$.
        Up to swapping $Y_1$ with $Y_2$, we assume that $\geo{\lambda_1}{h_1}=1$. We consider $\{\lambda_1,h_1\}$ as a basis for $\fund{\Sigma_1'}$ and we give $(\theta_1,\psi_1)$ coordinates $\R{\Sigma_1'}$.
        We give $\R{\Sigma_2'}$ coordinates $(\theta_2,\psi_2)$ as explained in Remark \ref{rmk: bases for C2}.

        Let $\gamma \colon (-1,1) \to H(Y_1)$ be a LIPA-path of $Y_1$. Let $\Gamma=\ima \gamma \subset H(Y_1)$ be its support. Let $\Gamma^t$ be the set $\Gamma$ translated by the vector $(0,\pi)$. Explicitly,
        \[
            \Gamma^t \coloneq \left\{(\theta_1,\psi_1 + \pi) \in \R{\Sigma_1} \middle| (\theta_1,\psi_1) \in \Gamma \right\}.
        \]
        Lemma \ref{lemma: translation} implies that $\Gamma^t \subset H(Y_1)$. We define $T_1 \subset T(Y_1,\partial Y_1)$ as
        \[
            T_1=A(Y_1)\cup\Gamma\cup\Gamma^t \subset\R{\Sigma_1}.
        \]
        Since $o_1=1$, the space $A(Y_1)$ equals $\{\theta_1=0\} \subseteq\R{\Sigma_1}$.
        We recall that, since $Y=Y_1\cup_{\Sigma_1'}C_2 \cup_{\Sigma_2'}Y_2$ is a rational homology $3$-sphere, then $\geo{\lambda_2}{h_2}\neq0$ by Lemma \ref{lemma: rational longitude of C2}.
        If either $\Gamma$ or $\Gamma'$ intersects $\{\psi_1=0\}\cup \{\psi_1=\pi\}$, then the manifold $Y_1 \cup_{\Sigma_1}'C_2(\Sigma_2';\lambda_2)$ is not $SU(2)$-abelian as a consequence of Lemma \ref{lemma: gamma non intersecta le linee orizzontali} and this implies that $Y=Y_1\cup_{\Sigma_1'} C_2 \cup_{\Sigma_2'} Y_2$ is not $SU(2)$-abelian. Therefore we assume that neither $\Gamma$ nor $\Gamma'$ intersects $\{\psi_1=0\}\cup \{\psi_1=\pi\}$. Figure \ref{Figure: teo per C2 sigma 1} shows $T_1 \subset T(Y_1,\partial Y_1)\subset \R{\Sigma_1}$.
        Theorem \ref{teo: alg for C2} defines a subset $T_2$ of $H(Y_1\cup_{\Sigma_1'}C_2)\subset \R{\Sigma_2}$ corresponding to $T_1$. Figure \ref{Figure: teo per C2 sigma 2} shows the set $T_2$ and $A(Y_2)$.

        We define $\partial \Gamma\subset \R{\Sigma_1'}$ as the two points $\overline{\Gamma} \setminus \Gamma \subset \R{\Sigma_1'}$. We define $\partial \Gamma^t\subset \R{\Sigma_1'}$ similarly.
        We recall that $\{0,\pi\}^2 \subset \R{\Sigma_1'}$ is the set of the four ``central" points of $\R{\Sigma_1'}$.
        By definition of $\Gamma^t$ we obtain that
        \[
            \left| \partial \Gamma \cap \{0,\pi\}^2\right| = \left| \partial \Gamma^t \cap \{0,\pi\}^2\right|.
        \]
        In other words, $\Gamma$ has either two, one, or none endpoints in $\{0,\pi\}^2 \subset \R{\Sigma_1'}$ if and only if $\Gamma^t$ has the same number of endpoints in $\{0,\pi\}^2 \subset \R{\Sigma_1'}$.
        Figure \ref{Figure: teo per C2 sigma 2} shows that
        if the two points $\partial \Gamma$
        are not both in $\{0,\pi\}^2$, then the only straight line of $\R{\Sigma_2'}$ containing the origin that does not intersect $T_2 \subseteq H(Y_1\cup_{\Sigma_1'}C_2) \subset \R{\Sigma_2'}$ is $\{\psi_2=0\} \subset \R{\Sigma_2'}$. This implies that if if the two points $\partial \Gamma$
        are not both in $\{0,\pi\}^2$ and $\alpha \subset\Sigma_2'$ is a slope different from the regular fiber $h_2 \subset \Sigma_2'$, then $T_2$ has a nonempty intersection with the line $L_\alpha$,
        where
        \[
            L_\alpha \coloneq \left\{\eta \in \R{\Sigma_2'} \middle| \eta(\alpha)=1\right\}.
        \]
        Therefore, if $\alpha \subset\Sigma_2'$ is a slope as above, Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty} implies that
        the manifold
        \[
            Y_1 \cup_{\Sigma_1'}C_2(\Sigma_2';\alpha),
        \]
        is not $SU(2)$-abelian. Therefore, if the two points $\partial \Gamma$
        are not both in $\{0,\pi\}^2$, then $Y=Y_1\cup_{\Sigma_1'}C_2 \cup_{\Sigma_2'}Y_2$ is not $SU(2)$-abelian by Lemma \ref{lemma: rational longitude of C2} and Corollary \ref{cor: Y SU(2) allora i due pezzi sono SU(2)-abelian}.

        Without loss of generality, we assume that both points in $\partial \Gamma$ are in $\{0,\pi\}^2 \subset \R{\Sigma_1'}$.
        Figure \ref{Figure: teo per C2 sigma 2} also represents in light blue and dotted the line
        \[
           L_{\nicefrac{1}{-1}}= \left\{(\theta_2,\psi_2) \in \R{\Sigma_2'} \middle| \theta_2-\psi_2 =0\right\}.
        \]
        Since $o_2=1$ and as a consequence of Corollary \ref{cor: A(Y) with rational longitude}, the set $A(Y_2)$ is equal to the line $L_{\nicefrac{1}{-1}}$ above if and only if $\lambda_2= x_2 -h_2$ as a slope of $\Sigma_2'$.

        As shown in Figure \ref{Figure: teo per C2 sigma 2}, if $\lambda_2$ is not equal to $x_2 -h_2$ as a slope of $\Sigma_2'$, then $T_2 \subseteq H(Y_1\cup_{\Sigma_1'}C_2)$ has an intersection with $A(Y_2)$.
        Moreover, Figure \ref{Figure: teo per C2 sigma 2} shows that every line of $\R{\Sigma_2'}$ connecting two points of the line $L_{\nicefrac{1}{-1}}$ intersects $T_2 \cup A(Y_1\cup_{\Sigma_1'}C_2)$.
        This implies that either $H(Y_1\cup_{\Sigma_1'}C_2)\cap A(Y_2) \neq \emptyset$ or a LIPA-path of $Y_2$ intersect $H(Y_1\cup_{\Sigma_1'}C_2) \cup A(Y_1\cup_{\Sigma_1'}C_2)$ and  therefore 
        \[
        \left(A(Y_1\cup_{\Sigma_1'}C_2)\cup H(Y_1\cup_{\Sigma_1'}C_2)\right) \cap H(Y_2) \neq 0.
        \]
        In both cases, the conclusion is given by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.
    \end{proof}
\end{prop}

\begin{lemma}\label{lemma: C2 implies sigma 16}
    Let $Y=Y_1\cup_{\Sigma_1'} C_2 \cup_{\Sigma_2'} Y_2$ be a rational homology $3$-sphere such that neither $Y_1$ not $Y_2$ is a solid torus. If $Y$ is $SU(2)$-abelian graph manifold, then $|H_1(Y;\mathbb{Z})| \ge 16$.
    \begin{proof}
    As a consequence of Proposition \ref{prop: C2 and o1=o2=1 then not SUa}, either $o_1 \ge 2$ or $o_2 \ge2$. We assume that $o_1 \ge 2$. Remark \ref{rmk: order of toroidal} implies that the order of the torsion subgroup of $H_1(Y_1;\mathbb{Z})$ is divided by $o_1$.

    Let us focus on $C_2 \cup_{\Sigma_2'}Y_2$. Lemma \ref{lemma: rational longitude of C2} and Corollary \ref{cor: C2 obstruction longitudes} imply that $h_1 \in \fund{\Sigma_1'}$ is the rational longitude of $C_2 \cup_{\Sigma_2'}Y_2$ and it has order two. 
    Let us denote by $t_2'$ the order of the torsion subgroup of $H_1(C_2 \cup_{\Sigma_2'}Y_2;\mathbb{Z})$. Since the order of the rational longitude of $C_2 \cup_{\Sigma_2'}Y_2$ is two, $t_2'$ is divided by two and, in particular, $t_2' \ge 2$.
    Therefore, Remark \ref{rmk: order of toroidal} applied to the the torus $\Sigma_1' \subset Y$ implies that
    \[
        \left| H_1\left(Y_1 \cup_{\Sigma_1'}C_2 \cup_{\Sigma_2'}Y_2;\mathbb{Z}\right) \right| \ge \geo{\lambda_1}{\lambda_2}2t_2't_1o_1 \ge 4o_1^2 \ge 16.
    \]
    \end{proof}
\end{lemma}

\begin{lemma}\label{lemma: the last dec}
    Let $Y$ be an $SU(2)$-abelian graph manifold rational homology $3$-sphere with nontrivial JSJ decomposition. If $|H_1(Y;\mathbb{Z})| \le 7$, then there exists a system of disjoint tori $\tau \subset Y$ such that
    \[
        \overline{Y \setminus \tau} = \left( \bigcup C_3\right) \cup \left(\bigcup \mathbb{D}^2(\nicefrac{p_\ast}{q_\ast})\right),
    \]
    where $\mathbb{D}^2(\nicefrac{p_\ast}{q_\ast})$ is a Seifert fibred manifold with torus boundary and disk base space.
    \begin{proof}
    According to Corollary \ref{cor: the usefull decomposition} and Lemma \ref{lemma: C2 implies sigma 16}, there exists a system of disjoint tori $\tau \subset Y$ such that
    \[
        \overline{Y \setminus \tau} = \left( \bigcup C_3\right) \cup \left(\bigcup M_i\right),
    \]
    where $M_i$ is a Seifert fibred manifold with torus boundary.

    Let $\Sigma \in \tau$ be a torus that splits 
    $Y$ into a graph manifold $Y_1$ and a Seifert fibred manifold $Y_2$. Thus,
    $Y=Y_1 \cup_\Sigma Y_2$. We prove the conclusion by showing that $Y_2$ admits a fibration over a disk.
    Let $\sigma \in\mathbb{N}$ be the order of $H_1(Y;\mathbb{Z})$. Since $Y$ is a rational homology sphere, then $\sigma \neq 0$.
        According to Remark \ref{rmk: order of toroidal},
        \begin{align*}
            \sigma \coloneq \left|H_1(Y;\mathbb{Z})\right|=o_1o_2t_1t_2 \geo{\lambda_1}{\lambda_2},
        \end{align*}
    where $o_i$ is the order of $\lambda_i$ in $H_1(Y_i,\mathbb{Z})$ and $t_i$ is the order of the torsion subgroup of $H_1(Y_i,\mathbb{Z})$. Since $Y$ is a rational homology sphere, $\geo{\lambda_1}{\lambda_2} \ge 1$.

    As explained in Section \ref{section: the topology set up}, $Y_2$ has base space that is either a disk or a punctured $\mathbb{RP}^2$.
    We give the conclusion by showing that if $Y_2$ does not admit a Seifert fibration over a disk, then $|H(Y;\mathbb{Z})| \ge 8$.

    Let us assume that $Y_2$ does not admit a Seifert fibration with disk base space, and therefore that admits a Seifert fibration whose base space is a punctured $\mathbb{RP}^2$.

    If $Y_2$ has no singular fibers, then $Y_2$ admits a Seifert fibration over a disk as shown in \cite[Proposition 10.4.16]{martelli}.
    Therefore, we can assume that $Y_2$ has one or more fibrers.
    This implies that
    \[
        \fund{Y_2} = \langle x_1,\cdots,x_n,y,z,h \,|\, [x_i,h], x_1\cdots x_nyz^2, zhz^{-1}h, x_i^{p_i}h^{q_i}  \rangle.
    \]
    where $n\ge 1$, $p_i \ge 2$, and $\gcd(p_i,q_i)=1$. Details can be found in \cite[Section 2.2]{boyer2017foliations}.
    Is is straightforward to see that $h$ coincide with the rational longitude of $Y_2$ and it has order $2$.
    Therefore,
    \[
        H_1(Y_2;\mathbb{Z}) = \coker \begin{bmatrix}
            p_1 & 0 & \cdots & 0 & 0 & 1\\
            0 & p_2 & \cdots & \cdots & \cdots & \cdots \\
             \cdots & \cdots & \cdots& \cdots& \cdots & \cdots \\
            0 & 0 & \cdots& p_n & 0 & 1 \\
            q_1 & q_2 & \cdots & q_n& 2& 0 \\
            0 & \cdots & \cdots & \cdots & 0 &1 \\
            0 & 0 & \cdots& 0& 0& 2 
        \end{bmatrix}.
    \]
    Thus, the Smith algorithm applied to the matrix above shows that the torsion subgroup of $H_1(Y_2;\mathbb{Z})$ has order $t_2=2 p_1 \cdots p_n \ge 2^{n+1}$.

    Therefore $o_2=2$ and $t_2 \ge 4$. Remark \ref{rmk: order of toroidal} applied to $Y=Y_1\cup_{\Sigma} Y_2$ implies that $\sigma = |H_1(Y;\mathbb{Z})| \ge 8$. This gives the conclusion. 
    \end{proof}
\end{lemma}

\section{The main course}

In \cite[Theorem 1.8]{BorderedHeegaardHomology} it is shown that if $Y$ is a toridal L-space, then either $\dim \widehat{HF}(Y)=5$ or $\dim \widehat{HF}(Y)\ge 7$. Thus, since an L-space is defined as a rational homology $3$-sphere such that $\dim \widehat{HF}(Y)=|H_1(Y;\mathbb{Z})|$, if $Y$ is a toroidal rational homology $3$-sphere whose first homology has order smaller than or equal to $4$, then $Y$ is not an L-space. According to Conjecture \ref{conj: SU(2)-ab implies HF L-space}, we expect $Y$ to not be $SU(2)$-abelian. Therefore, if $Y$ is a toroidal rational homology $3$-sphere, we expect that if the order of $H_1(Y;\mathbb{Z})$ is less than or equal to $4$, then $Y$ is not $SU(2)$-abelian, as it was conjectured in \cite[Conjecture 1.5]{InstantoLSpaceAndSplicing}:
\begin{conj}[{\cite[Conjecture 1.5]{InstantoLSpaceAndSplicing}}]
    There exists an irreducible homomorphism $\fund{Y}\to SU(2)$ for every toroidal rational homology $3$-sphere $Y$ with $|H_1(Y;\mathbb{Z})| \le 4$.
\end{conj}
In this section we prove Theorem \ref{teo: sigma small then not SU(2)-abelian} that positively answers to \cite[Conjecture 1.5]{InstantoLSpaceAndSplicing} in the case of graph manifolds.

In the following $Y_2$ is a Seifert fibred manifold with disk base space and two singular fibers. Following the notation of \cite{Mino}, we denote by $g_2$ the greater common division of the orders of these fibers.

\begin{cor}\label{cor: sigma=2 o1=delta=1 and o2=2}
    Let $Y_1$ be a graph manifold rational homology solid torus and $Y_2$ a Seifert fibred space with two singular fibers and fibred over a disk. If $Y=Y_1 \cup_{\Sigma} Y_2$ is a rational homology sphere such that $\Delta(\lambda_1,\lambda_2) = 1$, $g_2=o_2=1$ and $o_1=2$, then $Y$ is not $SU(2)$-abelian.
    \begin{proof}
        Since $\geo{\lambda_1}{\lambda_2}=1$ the set $\{\lambda_1,\lambda_2\}$ is a basis for $\fund{\Sigma}$.
        We give to $\R{\Sigma}$ coordinates $(\theta,\psi)$ with respect to this ordered basis as in \eqref{eq: general coordinates}. Since $o_1=2$ and $o_2=1$, $A(Y_1)= \{\theta=0\} \cup \{\theta=\pi\}$ and $A(Y_2)=\{\psi=0\}$ by Corollary \ref{cor: A(Y) with rational longitude}.

        Let $\gamma_2$ be a LIPA-path and $\gamma_2^t$ its translation of $(\pi,0)$.
        Lemma \ref{lemma: translation} implies that $\gamma_2^t$ is a LIPA-path for $Y_2$.
        With an abuse of notation, we identify $\ima{\gamma_2}$ and $\ima{\gamma_2^t}=\ima{\gamma_2}+(\pi,0)$ with $\gamma_2$ and $\gamma_2^t$ respectively.
        The path $\gamma_2$ connects two points of $A(Y_2)$, namely
        \[
            (\theta_1,0) \in A(Y_2) \quad \text{and} \quad (\theta_2,0) \in A(Y_2).
        \]
        Therefore, the $\gamma_2^t$ connects the points
        \[
            (\theta_1 +\pi,0) \in A(Y_2) \quad \text{and} \quad (\theta_2+\pi,0) \in A(Y_2).
        \]
        If either $\gamma_2$ or $\gamma_2^t$ intersects $A(Y_1)$, then $A(Y_1) \cap H(Y_2) \neq \emptyset$. As an application of Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}, the manifold $Y=Y_1 \cup_{\Sigma}Y_2$ is not $SU(2)$-abelian.

        Without loss of generality, we can assume that neither $\gamma_2$ nor $\gamma_2^t$ intersects $A(Y_1)$. As we saw in the proof of Proposition \ref{prop: sigma =1 ish}, this implies that either $\theta_1,\theta_2 \in [0,\pi]$ or $\theta_1,\theta_2 \in [\pi,2\pi]$.
        As an application of \cite[Lemma 7.1]{Mino}, we have that $P(Y_2)= \emptyset$. By Lemma \ref{lemma: eta in H(Y)-H(Y) in SFS with 2 sf}, we have that the accumulation points of $\gamma_2$ (resp. $\gamma_2^t$) are disjoint form $\{0,\pi\}^2 \subset \R{\Sigma}$. Therefore, either $\theta_1,\theta_2 \in (0,\pi)$ or $\theta_1,\theta_2 \in (\pi,2\pi)$.
        Figure \ref{Figure o1=1 e o2=2} shows $\gamma_2\cup\gamma_2^t$, $A(Y_1)$ and $A(Y_2)$ in the chosen coordinates.
        In particular, Figure \ref{Figure o1=1 e o2=2} illustrates that a LIPA-path of $Y_1$ intersects either $A(Y_2)$, $\gamma_2$, or $\gamma_2^t$. Therefore, 
        \[
        H(Y_1) \cap (H(Y_2) \cup A(Y_2)) \neq \emptyset.
        \]
        The conclusion is given by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.
    \end{proof}
\end{cor}

In the following $Y_2$ is a Seifert fibred space with disk base space and two singular fibers. Therefore $Y_2$ is of the form $\mathbb{D}^2(\nicefrac{p_1}{q_1},\nicefrac{p_2}{q_2})$ with $2 \le p_1 \le p_2$. We recall that $g_2$ is defined to be the greater common divisor of the orders of the singular fibers, namely $g_2\coloneqq \gcd(p_1,p_2)$.

\begin{lemma}\label{lemma: o2g2o1=1 and sigma <= 5}
    Let $Y_1$ be a graph manifold rational homology solid torus and $Y_2$ a Seifert fibred space with disk base space and two singular fibers.
    Let us further assume that $Y_1 \neq S^1 \times \mathbb{D}^2$, and let $Y=Y_1 \cup_{\Sigma} Y_2$.
    If $3 \le  \Delta(\lambda_1,\lambda_2) \le 5$ and $o_1=o_2=g_2=1$, then $Y$ is not $SU(2)$-abelian.
     \begin{proof}
     The conclusion requires two claims that are proven at the end of this proof.
        Let $\gamma \colon (-1,1)\to \R{\Sigma}$ be a path.
        With an abuse of notation, we identify with $\gamma$ its image in $\R{\Sigma}$.

        Let $\xi \subset$ be a slope such that $\{\xi,\lambda_1\}$ is an ordered basis for $\fund{\Sigma}$.
        We give the space $\R{\Sigma}$ coordinates $(\theta,\psi)$ as in \eqref{eq: general coordinates} with respect to this ordered basis.
        Let $n \in \mathbb{Z}$ be an integers such that
        \[
            \lambda_2= \geo{\lambda_1}{\lambda_2} \xi+ n \lambda_1 \subset \Sigma.
        \]
         Without loss of generality, we can assume that $ -\geo{\lambda_1}{\lambda_2}<n<0$.
        In this case, we write $\lambda_2=\nicefrac{\geo{\lambda_1}{\lambda_2}}{n}$.
        Corollary \ref{cor: A(Y) with rational longitude} implies that
        \[
            A(Y_2) = \left\{ \geo{\lambda_1}{\lambda_2} \theta+ n \psi =0\right\} \subset \R{\Sigma} \quad \text{and} \quad A(Y_1) = \left\{ \psi=0 \right\} \subset \R{\Sigma}.
        \]

        Since $Y_1$ is not a solid torus, then it is LIPA by Theorem \ref{teo: admissible pieces have the property P}.
        Let $\gamma_1 \colon (-1,1) \to H(Y_1)$ be a LIPA path for $Y_1$, we denote by $\gamma_1^t$ the path $\gamma_1$ translated by $(\pi,0)$. The path $\gamma_1^t$ is a LIPA-path for $Y_1$ by Lemma \ref{lemma: translation}. Figure \ref{Figure: sigma small at most 11} shows $\R{\Sigma}$, $A(Y_1)$, $A(Y_2)$ in the case $\lambda_2=-\nicefrac{3}{1}$, $\gamma_1$, and $\gamma_1^t$ in the chosen coordinates.

        If $A(Y_2)$ intersect $\gamma_1 \cup \gamma_1^t$, then $H(Y_1) \cap A(Y_2) \neq \emptyset$ and $Y$ is not $SU(2)$-abelian by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}. Therefore, we assume that $A(Y_2)$ does not intersect the paths $\gamma_1$ and $\gamma_1^t$.

       Let $\mu$ be the weight as in Definition \ref{degn weight mu}.
       By Lemma \ref{lemma: weight of D2(p1,p2)}, $\mu(Y_2) \ge \nicefrac{2}{3}$. Let $L \subset \R{\Sigma}$ be the line containing a LIPA-path of $Y_2$. Let $\nicefrac{p}{q} \in \mathbb{Q} \cup \{\nicefrac{1}{0}\}$ be the slope of $L$. We recall that this means that there exists a $c \in [0,2\pi]$ such that
       \begin{equation}
            \label{eq: una volta Linea del LIPA Y2}
            L=\left\{(\theta,\psi) \in \R{\Sigma} \middle| p \theta+q \psi = c \right\}.
        \end{equation}
        Without loss of generality, we assume that $L$ is the line that realizes the maximal weight $\mu(Y_2)$, namely
        \[
            \mu(L)= \frac{h(L \cap H(Y_2))}{h(L)}= \mu(Y_2) \ge \frac{2}{3}.
        \]
        Here the weight $\mu$ as in Definition \ref{degn weight mu} and $h$ is the Lebesgue measure on $L$ induced by the coordinates $(\theta,\psi)$ as in Section \ref{sec. utensilis}.
        Such a line $L$ exists by Definition \ref{degn weight mu}. As a consequence of Fact \ref{Fact: centralizers}, if $\eta \colon \fund{\Sigma} \to \Ui$ is a representation in
        $H(Y_2)$, then $\eta(h_2) \in \ZSU$ where $h_2 \subset Y_2$ is a regular fiber of $Y_2$. This implies that if $\eta \colon \fund{\Sigma} \to \Ui$ is a representation in $L$, then $\eta(h_2) \in \ZSU$. Thus, $L$ contains two points of $\{0,\pi\}^2 \subset \R{\Sigma}$. In other words, either $c =0$ or $c=\pi$.

        We define 
        \begin{equation}\label{eq: defn S}
            S \coloneqq \{\nicefrac{1}{0},\nicefrac{0}{1}, \pm \nicefrac{1}{1}, \pm \nicefrac{2}{1}, \pm \nicefrac{1}{2}\} \subseteq \mathbb{Q} \cup \{\nicefrac{1}{0}\},
        \end{equation}
        \begin{claim}\label{claim: se non in S allora non SU(2)a}
            Let $\nicefrac{p}{q}$ be the slope of $L$.
            If $\nicefrac{p}{q} \notin S$, then $Y=Y_1\cup_{\Sigma} Y_2$ is not $SU(2)$-abelian.
        \end{claim}

        We show that for every slope in $S$, either the line $L$ does not have that slope or, if it does, $L \cap H(Y_2)$ intersects $A(Y_1) \cup H(Y_1)$. In the latter case, $Y=Y_1\cup_{\Sigma}Y_2$ is not $SU(2)$-abelian by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.

       According to Corollary \ref{cor: A(Y) with rational longitude}, the space $A(Y_2) \subset\R{\Sigma}$ is a line of slope $\geo{\lambda_1}{\lambda_2}/n$.
       Since $L$ contains a LIPA-path of $Y_2$, the line $L$ intersects $A(Y_2)$. We define $m \in \mathbb{Z}$ as
       \[
       |A(Y_2) \cap L| = |pn-\geo{\lambda_1}{\lambda_2}p| \coloneq m.
       \]
       Since $L$ intersects $A(Y_2)$, we obtain that $m \neq 0$.
       In particular, the points of the intersection $A(Y_2) \cap L$ are equally spaced in $L$.
        Therefore $A(Y_2)$ divides the line $L$ in $m$ intervals $I_1, \cdots, I_m$ of equal length:
        \[
            \frac{h(I_j)}{h(L)}= \frac{1}{m} \quad \text{and} \quad L = \bigcup_{i=1}^m I_i.
        \]
        By Lemma \ref{lemma: eta in H(Y)-H(Y) in SFS with 2 sf}, $\overline{H(Y_2)} \setminus H(Y_2) \subset A(Y_2)$.
        Thus, the intersection $L\cap H(Y_2)$ is such that
        \[
             \overline{L\cap H(Y_2)} \setminus L\cap H(Y_2) \subset A(Y_2).
        \]
        Therefore $L\cap H(Y_2)$ is the union of intervals $I_i$.

        Let $l \in \mathbb{N}$ be defined as
        \[
            l \coloneqq \left| L \cap A(Y_2) \cap \{0,\pi\}^2\right| \in \mathbb{N}.
        \]
        In other words, the lines $L$ and $A(Y_2)$ share $l$ ``central" points $\{0,\pi\}^2\subset \R{\Sigma}$.
        \begin{claim}\label{claim mu(m-2-l/m)}
            $\mu(L) \le \max\left\{0, \frac{m-2-l}{m}\right\}$.
        \end{claim}
        We recall that the line $L$ admits the description as in \eqref{eq: una volta Linea del LIPA Y2} with $c \in \{0,\pi\}$.
       The quantity $\frac{m-2-l}{m}$ depends of the choice of $c \in \{0,\pi\}$.

       We now give an idea of the resolution procedure. Given a $n \in \{-\geo{\lambda_1}{\lambda_2}-1,\cdots,-1\}$ with $\gcd(n,\geo{\lambda_1}{\lambda_2})=1$ we consider 
       \[
       \lambda_2=\frac{\geo{\lambda_1}{\lambda_2}}{n} \coloneqq \geo{\lambda_1}{\lambda_2} \xi + n \lambda_1 \subset \Sigma.
       \]
       For each slope in $S$, for each $n$ as above and $c \in \{0,\pi\}$ we compute the quantity $\frac{m-2-l}{m}$, if this is smaller than $\nicefrac{2}{3}$ then, since $\mu(L)=\mu(Y_2)$, the line $L$ cannot have this slope by Lemma \ref{lemma: weight of D2(p1,p2)} and Claim \ref{claim mu(m-2-l/m)}. If $\frac{m-2-l}{m}$ is greater then or equal to $\frac{2}{3}$, then we study the case in Figure \ref{Figure finales p1} and Figure \ref{Figure finales p2}. From these it will result that the manifold $Y_1 \cup_{\Sigma}Y_2$ is not $SU(2)$-abelian.
        Studying all possible combinations we conclude that either $Y_1 \cup_{\Sigma} Y_2$ is not $SU(2)$-abelian, or the slope of the line $L$ is not in $S$, and Claim \ref{claim: se non in S allora non SU(2)a} gives the conclusion.
        We separate the proof in two cases: case $\geo{\lambda_1}{\lambda_2}=3$ and
        case $\geo{\lambda_1}{\lambda_2} \in \{4,5\}$.  

        \underline{Case $\geo{\lambda_1}{\lambda_2}=3$}.
        In this case $\lambda_2= \nicefrac{3}{n}$, where $n \in \{-1,-2\}$.
        Table \ref{table: intersections pt 1} and Table \ref{table: intersections pt 2} imply that $\frac{m-2-l}{m} < \frac{2}{3}$ in all cases but the one for which $\lambda_2=\nicefrac{3}{2}$, $\nicefrac{p}{q}=-\nicefrac{1}{2}$, and $c = \pi$.

        Let us study this case which is represented by Figure \ref{Figure d=3}.
        Since we assumed that $H(Y_1)\cap A(Y_2) = \emptyset$, in Figure \ref{Figure d=3} the LIPA-path $\gamma_1$ is placed in a way that $\gamma_1 \cup \gamma_1^t$ is disjoint from $A(Y_2)$ and in a minimal position in the following sense.
        As we mentioned above, if a subsegment $I_j$ contains one of the points $\{0,\pi\}^2$, then it is not contained in $H(Y_2) \cap L$.
        Similarly, if the LIPA-path $\gamma_1$ passes though a subsegment $I_{j'}$ then either it is not contained in $H(Y_2) \cap L$ or $Y=Y_1 \cup_{\Sigma} Y_2$ is not $SU(2)$-abelian according to Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.
        Therefore, we draw the LIPA-path $\gamma_1$ passing through the subsegment $I_j$ so we do not have to exclude an additional subsegment and to make $H(Y_2) \cap L$ the largest possible.

        A direct computation in the considered case shows that $m=|A(Y_2)\cap L|=8$.
        Figure \ref{Figure d=3} shows that there are at most two subsegments $I_j$ of $L$ each connecting two points of $A(Y_2)$, that do not intersect $\gamma_2 \cup \gamma_2^t$ and whose accumulation points are not in $\{0,\pi\}^2$.
        Each of such subsegments is such that
        \[
        \frac{h(I_j)}{h(L)}=\frac{1}{m}=\frac{1}{8}.
        \]
        Let $\widetilde{L}$ be the union of these two subintervals. This implies that
        \[
            \frac{h\left(\widetilde{L}\right)}{h(L)} = 2\frac{h(I_j)}{h(L)}=\frac{1}{4}< \frac{2}{3}.
        \]
        Since $\mu(Y_2)=\mu(L) \ge \nicefrac{2}{3}$ by Lemma \ref{lemma: weight of D2(p1,p2)}, if $\lambda_2=\nicefrac{3}{2}$, $\nicefrac{p}{q}=-\nicefrac{1}{2}$, and $c = \pi$,
        then $L \cap H(Y_2)$ properly contains $\widetilde{L}$ and at least one the the subinterval $I_j$ that intersect $\gamma_1 \cup \gamma_1^t$. Thus, $H(Y_1) \cap H(Y_2) \neq \emptyset$. Therefore $Y=Y_1 \cup_{\Sigma} Y_2$ is not $SU(2)$-abelian by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.

        Thus, either $Y=Y_1 \cup_{\Sigma} Y_2$ is not $SU(2)$-abelian or  the slope of the line $L$ is not in $S$. Claim \ref{claim: se non in S allora non SU(2)a} gives the conclusion.

        \underline{Case $\geo{\lambda_1}{\lambda_2} \in \{4,5\}$}. These cases follow from the technique showed in the previous cases. Table \ref{table: intersections pt 1} and Table \ref{table: intersections pt 2} show the cases for which $\frac{m-2-l}{m} \ge \frac{2}{3}$. These cases are studied in Figure \ref{Figure finales p1} and Figure \ref{Figure finales p2}.
        All the figures are drawn such that $\gamma_1\cup\gamma_1^t$ is in a minimal position as explained above.
        By studying all the cases reported in Figure \ref{Figure finales p1} and Figure \ref{Figure finales p2} we conclude that either the slope of $L$ is not in $S$, and therefore $Y=Y_1 \cup_{\Sigma} Y_2$ is not $SU(2)$-abelian by Claim \ref{claim: se non in S allora non SU(2)a}, or $L\cap H(Y_2)$ intersects $A(Y_1)\cup H(Y_2)$ which implies that $Y=Y_1\cup_{\Sigma} Y_2$ is not $SU(2)$-abelian by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.
    \end{proof}
\end{lemma}

\begin{proof}[Proof of Claim \ref{claim: se non in S allora non SU(2)a}]
    If $\nicefrac{p}{q} \notin S$, then either $|p| \ge 3$ or $|q| \ge 3$. We deal the two cases separately.

                Let $L'$ be a rational line of $\R{\Sigma}$ of slope $\nicefrac{p'}{q'}$. We start by showing that if $|pq'-p'q| \ge 3$, then $L'\cap H(Y_2) \neq \emptyset$.

                Let $\mu \subset \Sigma$ be the meridian of the chosen fibration of $Y_2=\mathbb{D}^2(\nicefrac{p_1}{q_1},\nicefrac{p_2}{q_2})$ as in \cite[Definition 2.1.1]{Mino}. Therefore, $\{\mu,h_2\}$ is a basis for $\fund{\Sigma}=\fund{\partial Y_2}$ and if $\fund{Y_2}$ is presented as
                \[
                    \fund{Y_2}=\fund{\mathbb{D}^2(\nicefrac{p_1}{q_1},\nicefrac{p_2}{q_2})}= \left\langle x_1,x_2,h_2\middle| x_1^{p_1}h_2^{q_1}, x_2^{p_2}h_2^{q_2},[x_1,h_2],[x_2,h_2] \right\rangle,
                \]
                then $\mu=x_1x_2 \in \fund{Y_2}$.
                Let us assume that $\R{\Sigma}$ has coordinates $(\theta_2,\psi_2)$ as in \eqref{eq: general coordinates} with respect to the basis $\{\mu,h_2\}$.
                As an application of Fact \ref{Fact: centralizers}, if $\eta \in H(Y_2)$, then $\eta(h_2)= \pm 1$. Since $ \mu(L) \neq 0$, there exists $\varepsilon \in \{0,\pi\}$ such that
                \[
                    L= \left\{\psi_2= \varepsilon \right\} \subset \R{\Sigma}.
                \]
                Therefore, there exist $a_1,a_2 \in [0,2\pi]$, with $a_1 <a_2$ such that
                \begin{equation}
                \left\{ (x,\varepsilon) \in \R{\Sigma} \middle| x \in (a_1,a_2)\right\}\subset L \cap H(Y_2).
                 \end{equation}
                 According to Corollary \ref{cor: jewelled repr},
                 \begin{equation}
                \left\{ (x,\varepsilon) \in \R{\Sigma} \middle| x \in (a_1,a_2) \cup (2\pi - a_2,2\pi a_1)\right\}\subset L \cap H(Y_2).
                \label{eq: una volta Claim Lcap s ge 3}
                 \end{equation}
                 Since $\mu(L)=\mu(Y_2) \ge \nicefrac{2}{3}$ by Lemma \ref{lemma: weight of D2(p1,p2)}, we can assume that $|a_2-a_1| \ge \nicefrac{2\pi}{3}$.
                Since $g_2=1$, \cite[Lemma 7.1]{Mino} implies that $P(Y_2)=\emptyset$. By Lemma
                \ref{lemma: eta in H(Y)-H(Y) in SFS with 2 sf},
                $\overline{H(Y_2)}\setminus H(Y_2)$ cannot contain any point of $\{0,\pi\}^2$. Therefore, we can assume that $a_1,a_2 \in (0,\pi)$.

                Let $n = |pq'-p'q|$. Therefore, the line $L$ intersects the line $L'$ in $n$ equidistant points. If $n \ge 3$, the \eqref{eq: una volta Claim Lcap s ge 3} implies that at least one of this intersection point lays in $L \cap H(Y_2)$.

                We recall that $A(Y_1) \subset \R{\Sigma}$ is the line $\{\psi=0\}\subset \R{\Sigma}$ that has slope $\nicefrac{0}{1}$.
                If $|p| \ge 3$, then $A(Y_1) \cap H(Y_2) \neq \emptyset$. The conclusion is given by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.

            We can assume that $|p| \in \{1,2\}$.
            Let us assume that $|q| \ge 3$, we shall prove that $Y=Y_1\cup_{\Sigma}Y_2$ is not $SU(2)$-abelian.
            Without loss of generality, we assume that $p \in \{1,2\}$, therefore, either
            \[
                \frac{p}{q} = \frac{1}{q} \quad \text{or} \quad \frac{p}{q}=\frac{2}{q},
            \]
            with $|q| \ge 3$.

            We recall that $\gamma_1 \colon (-1,1)\to \R{\Sigma}$ is a LIPA-path for $Y_1$.
            The closure $\overline{\gamma_1}$ is homotopic in $\R{\Sigma}$ to the circle $\{\theta=0\}$, see Figure \ref{Figure: sigma small at most 11}.
            Since $\nicefrac{p}{q}$ is either $\nicefrac{1}{q}$ or $\nicefrac{2}{q}$ by assumption,
            we obtain that
                \[
                    \left|L \cap \overline{\gamma_1} \right| = |q|.
                \]
                In particular, the points in $L \cap \overline{\gamma}$ are equally spaced in $L$.
                As we saw before, this implies the one is in $H(Y_2)$ and therefore in $\gamma \cap H(Y_2)$. Hence, if $|q|\ge 3$ then $\gamma \cap H(Y_2) \neq \emptyset$. Therefore $H(Y_1) \cap H(Y_2) \neq \emptyset$. The conclusion holds by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.
            \end{proof}
    \begin{proof}[Proof of Claim \ref{claim mu(m-2-l/m)}]
            By Theorem \ref{teo: admissible pieces have the property P}, $\mu(Y_2)=\mu(L) > 0$.
            As we mentioned in the proof of Lemma \ref{lemma: o2g2o1=1 and sigma <= 5}, the line $L$ contains two points $P_1,P_2 \in \{0,\pi\}^2 \subset\R{\Sigma}$.
            As we said before, the points $\overline{L \cap H(Y_2)} \setminus L \cap H(Y_2)$ are in $A(Y_2)$.
            We recall that $A(Y_2)$ divides $L$ in $m$ subintervals $I_1, \cdots, I_m$ each of the length.
            As an application of Lemma \ref{lemma: eta in H(Y)-H(Y) in SFS with 2 sf}, the accumulation points of $H(Y_2)$ are disjoint from $\{P_1,P_2\}$. Therefore, $L \cap H(Y_2)$ is contained in $\widetilde{L} \subset L$, where $\widetilde{L}$ is the union of the subintervals $I_j$ whose accumulation points are disjoint from $\{P_1,P_2\}$.
            There are at most $m-2$ such subintervals. 
            Notice that, if one (rel. two) point $\{P_1,P_2\}$ is in the intersection
            $L \cap A(Y_2)$, then there are exactly two (rel. four) subinterval $I_j$ with one endpoint in $\{P_1,P_2\}$.
            Thus, when it is not empty, $\widetilde{L}$ is made of at most $m-2-l>0$ subinterval, each of length $h(I_j)=\nicefrac{1}{m}$.
            This implies that
            \[
            \mu(L)= \mu\left( L \cap H(Y_2)\right) \le \frac{h\left( \widetilde{L}\right)}{h(L)} = (m-2-l) \frac{h(I_j)}{h(L)} = \frac{m-2-l}{m}.
            \]
    \end{proof}
\begin{lemma}\label{lemma: o2g2=1 o2=2 and sigma = 2}
    Let $Y_1$ be a graph manifold rational homology solid torus and $Y_2$ a Seifert fibred space with disk base space and two singular fibers.
    Let us further assume that $Y_1 \neq S^1 \times \mathbb{D}^2$, and let $Y=Y_1 \cup_{\Sigma} Y_2$.
    If $\Delta(\lambda_1,\lambda_2) =2$, $o_2=o_1=1$, and either $g_2=1$ or $g_2 =2$, then $Y$ is not $SU(2)$-abelian.
    \begin{proof}
        The proof uses a similar notation to Lemma \ref{lemma: o2g2o1=1 and sigma <= 5}.
        Let $\gamma \colon (-1,1)\to \R{\Sigma}$ be a path.
        With an abuse of notation, we identify with $\gamma$ its image in $\R{\Sigma}$.

        Let $\xi \subset$ be a slope such that $\{\xi,\lambda_1\}$ is an ordered basis for $\fund{\Sigma}$.
        We give the space $\R{\Sigma}$ coordinates $(\theta,\psi)$ as in \eqref{eq: general coordinates} with respect to this ordered basis.
        Without loss of generality, we can assume that the slope $\xi$ is such that
        \[
            \lambda_2=2 \xi -\lambda_1 \subset \Sigma.
        \]
        Therefore by Corollary \ref{cor: A(Y) with rational longitude},
        \[
            A(Y_2) = \left\{ 2 \theta- \psi =0\right\} \subset \R{\Sigma} \quad \text{and} \quad A(Y_1) = \left\{ \psi=0 \right\} \subset \R{\Sigma}.
        \]

        Since neither $Y_1$ not $Y_2$ is not a solid torus, then it is LIPA by Theorem \ref{teo: admissible pieces have the property P}.
        For $i \in \{1,2\}$, we denote by $\gamma_i \colon (-1,1) \to\R{\Sigma}$ be a LIPA path for $Y_i$. We denote $\gamma_1^t$ (rel. $\gamma_2^t$) the path $\gamma_i$ translated by $(\pi,0)$ (rel. $(0,\pi)$). For $i \in \{1,2\}$, the path $\gamma_i^t$ is a LIPA-path of $Y_i$ by Lemma \ref{lemma: translation}.
        If either $\gamma_1$ or $\gamma_1^t$ intersects $A(Y_2)$, then $H(Y_1) \cap A(Y_2) \neq \emptyset$. As an application of Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}, the manifold $Y$ is not $SU(2)$-abelian.
        Therefore, we can assume that neither $\gamma_1$ not $\gamma_1^t$ intersects $A(Y_2)$.
        Figure \ref{Figure. Case d=2, c=pi} shows $\R{\Sigma}$, $A(Y_1)$, $A(Y_2)$ $\gamma_1$, and $\gamma_2^t$ in the chosen coordinates.

        Let $L \subset \R{\Sigma}$ be a line that contains a LIPA-path of $Y_2$, we recall that $L \not \subset A(Y_2)$. According to \cite[Lemma 7.1]{Mino}, $P(Y_2)=\emptyset$ and therefore the accumulation points of $H(Y_2)$ are disjoint from $\{0,\pi\}^2 \subset \R{\Sigma}$ by Lemma \ref{lemma: eta in H(Y)-H(Y) in SFS with 2 sf}. This implies that $H(Y_2) \cap L$ contains a open segment $I$ such that
        \[
            I \not \subset A(Y_2), \quad \partial I \in A(Y_2), \quad \text{and} \quad \overline{I}\cap \{0,\pi\}^2 = \emptyset.
        \]
        Figure \ref{Figure. Case d=2, c=pi} shows that every such a segment intersect either $A(Y_1)$ or $\gamma_1 \cup \gamma_1^t \subseteq H(Y_1)$. This implies that
        \[
            \left(H(Y_2) \cap L\right) \cap \left(A(Y_1) \cup H(Y_1)\right) \neq \emptyset \quad \text{and therefore} \quad H(Y_2) \cap \left(A(Y_1) \cup H(Y_1)\right) \neq \emptyset.
        \]
        The conclusion holds by Theorem \ref{teo: M SU(2)-abeliano se e solo se i pezzi sono empty}.
    \end{proof}
    \end{lemma}
