\title{Multiple Axions Save High-Scale Inflation}

\author[a]{Dan Kondo,}\emailAdd{dan.kondo@ipmu.jp}
\author[a,b,c,1]{and Hitoshi Murayama\,\orcidlink{0000-0001-5769-9471}\note{Hamamatsu Professor}}\emailAdd{hitoshi@berkeley.edu}

