\section{Proof of Theorem \ref{statistic_theorem}}\label{statistic_theorem-proof}
\begin{myproof}[Proof]
    We prove each part of Theorem \ref{statistic_theorem} as follows:
    \begin{enumerate}
        \item  We first consider the estimation of the parameter $\bm \theta$ in the $i$-th dimension, i.e., $\theta_i$.
        Taking the logarithm of the joint probability function \eqref{probability_func} yields
            \begin{align*}
            & \log \mathbb{P}(c^1_i,c^2_i,\cdots,c^M_i;\theta_i)  \\
             = {} & N_i\left(\frac{1}{2}+\frac{\theta_i}{2b}\right)+(M-N_i)\left(\frac{1}{2}-\frac{\theta_i}{2b}\right) \\
             = {} & \frac{1}{2}\left(M\left(1-\frac{\theta_i}{b}\right)+N\frac{2\theta_i}{b}\right)                     \\
             = {} & \frac{1}{2}\left(M+\frac{\theta_i}{b}\left(2N_i-M\right)\right)                                     \\
             = {} & \frac{1}{2}\left(M+\frac{M}{b^2}\theta_i \hat{\theta}_i \right).
            \end{align*}


        By the Factorization Theorem, it can be concluded that the statistic $\hat{\theta}_i$ is a sufficient statistic for $\theta_i$. Since different components are independent of each other, $\hat{\bm{\theta}}$ is a sufficient statistic for $\bm{\theta}$.
        \item The expectation of $\hat{\theta}_{i}$ is calculated as
        \begin{align}
            \mathbb{E}\left[\hat{\theta}_{i}\right]&= \frac{2\mathbb{E}\left[N_i\right]-M}{M}b_i \notag \\
            &= \frac{2M\mathbb{P}(c^m_i=1)-M}{M}b_i \notag \\
            &= \left(2\left(\frac{1}{2}+\frac{1}{2b_i}\theta_{i}\right)-1\right)b_i \label{eq3-22}\\
            &= \theta_i, \notag 
        \end{align}
        where \eqref{eq3-22} comes from \eqref{eq3-6}.
        \item We first need to calculate two key statistics, including
        \begin{align*}
            \mathbb{E}\left[N_i\right]
             & = \sum_{m=1}^{M}\mathbb{P}\left(c_i^m=1\right)                                   \\
             & = \sum_{m=1}^{M}\mathbb{E}\left[\mathbb{P}\left(c_i^m=1|\delta_i^m\right)\right] \\
             & =\sum_{m=1}^{M}\mathbb{E}\left[\frac{b_i+\delta_i^m}{2b_i}\right]                \\
             & =\frac{M}{2}\left(1+\frac{\mathbb{E}\left[\delta_i^m\right]}{b_i}\right)         \\
             & =\frac{M}{2}\left(1+\frac{\theta_i}{b_i}\right)
        \end{align*}

        \begin{align*}
                & \mathbb{E}\left[N_i^2\right] \notag \\

            = {} & \mathbb{E}\left[\sum_{m=1}^{M} \mathbb{I}^2\left\{c_i^m=1\right\} \right. \notag \\
            & + \left.\sum_{i\ne j}\mathbb{I}\left\{c_i^m=1\right\}\mathbb{I}\left\{c_j^m=1\right\}\right]                    \\
            = {} & \sum_{m=1}^{M}\mathbb{E}\left[\mathbb{I}\left\{c_i^m=1\right\}\right] \notag \\
            &+\sum_{i\ne j}\mathbb{E}\left[\mathbb{I}\left\{c_i^m=1\right\}\mathbb{I}\left\{c_j^m=1\right\}\right] \\
            = {} & M \mathbb{P}\left(c_i^m=1\right) +M(M-1)\mathbb{E}^2\left[\mathbb{I}\left\{c_i^m=1\right\}\right]                                                                         \\
            = {} & M\left(\frac{b_i+\theta_i}{2b_i}\right)+M(M-1)\left(\frac{b_i+\theta_i}{2b_i}\right)^2                                                                            \\
            = {} & M\left(\frac{b_i+\theta_i}{2b_i}\right)\left(1+\left(M-1\right)\frac{b_i+\theta_i}{2b_i}\right)                                                                          \\
            = {} & M\left(\frac{b_i+\theta_i}{2b_i}\right)\left(\frac{\left(M+1\right)b_i+\left(M-1\right)\theta_i}{2b_i}\right).        
        \end{align*}

        By calculating the variance, we get
        \begin{align}
            & \mathbb{E}\left[\left(\theta_{i}-\hat{\theta}_{i}\right)^2\right] \notag \\
            = {} & \mathbb{E}\left[\frac{2N_i-M}{M}b_i\right]^2-\theta_{i}^2                                                     \notag \\
            = {} & \left(\frac{b_i}{M}\right)^2\mathbb{E}\left[4N_i^2-4N_iM+M^2\right]-\theta_{i}^2                             \notag \\
            = {} & \left(\frac{b_i}{M}\right)^2\cdot \left(4\mathbb{E}\left[N_i^2\right]-4M\mathbb{E}\left[N_i\right]+M^2\right)
            -\theta_{i}^2                                                                                                     \notag \\
            = {} & \frac{b_i^2-\theta_i^2}{M}. \label{eq3-37}
        \end{align}
        From this, we can obtain the transmission error as
        \begin{align*}
            \mathbb{E}\left[\left\|\bm{\theta}-\hat{\bm{\theta}}\right\|^2\right]
             & = \mathbb{E}\left[\sum_{i=1}^{d}\left(\theta_{i}-\hat{\theta}_{i}\right)^2\right] \\
             & = \frac{\sum_{i=1}^{d}\left(b_i^2-\theta_i^2\right)}{M}, 
        \end{align*}
        where $d$ is the length of the vector.
    \end{enumerate}

\end{myproof}

\section{Proofs of Lemma \ref{lemma-5}, Lemma \ref{lemma-6} and Lemma \ref{theo_convergence}}\label{lemma-5-proof}
\begin{myproof}[Proof of Lemma \ref{lemma-5}]
    We define $\bm e^{m}_{t+1}= \nabla f_{m}(\bm w^{m}_{t+1})+\lambda(\bm w^{m}_{t+1}-\bm w_{t})$, then the client $m$'s local training  satisfies
    \begin{align}
        \|\bm e^{m}_{t+1}\| & \leq\gamma\|\nabla f_{m}(\bm w_{t})\|, \label{eq3-66}
    \end{align}
   which comes from the $\gamma$-inexact solution in Definition \ref{inexact}.
    Define $\bar{\bm w}_{t+1}=\mathbb{E}_{m}\left[\bm w^{m}_{t+1}\right]= \frac{1}{R}\sum_{m=1}^{R}  \bm w^m_{t+1}$, we get
    \begin{align*}
        \bar{\bm w}_{t+1}-\bm w_t=\frac{-1}{\lambda}\mathbb{E}_m\left[\nabla f_m(\bm w^m_{t+1})\right]+\frac{1}{\lambda}\mathbb{E}_m\left[\bm e^m_{t+1}\right].
    \end{align*}
    With $\bar{\lambda}=\lambda-L_{-}>0$, we obtain
    \begin{align}
        \nabla^2h_m-\bar{\lambda}\bm I
         & =  \nabla^2f_m+\lambda \bm I -(\lambda-L_{-})\bm I \notag \\
         & =  \nabla^2f_m+L_{-}\bm I                         \notag  \\
         & \succeq \bm 0, \label{eq3-67}
    \end{align}
    where \eqref{eq3-67} comes from the Assumption \ref{assup_smoothness} and shows that $h_m$ is $\bar \lambda$-strongly convex.
    Further define $\tilde{\bm w}^m_{t+1}=\arg\min_{\bm w}h_m(\bm w;{\bm w}_t)$, then we get
    \begin{align}
        \bar{\lambda}\|\tilde{\bm w}^m_{t+1}-\bm w^m_{t+1}\|
         & \le \|\nabla h(\tilde{\bm w}^m_{t+1})-\nabla h({\bm w}^m_{t+1}) \| \notag \\
         & = \|\nabla h({\bm w}^m_{t+1}) \|                                  \notag  \\
         & = \|\bm e^{m}_{t+1}\|                                         \notag      \\
         & \le \gamma\|\nabla f_{m}(\bm w_{t})\|. \label{3-70}
    \end{align}

Similarly, using the $\bar{\lambda}$-strong convexity of $h_m$, we obtain
\begin{align}
    \bar{\lambda}\|\tilde{\bm w}^m_{t+1}-\bm w_{t}\|
    & \le \|\nabla h_m({\bm w}_{t}) \|                               \notag  \\
    & = \| \nabla f_m({\bm w}_{t})+\lambda({\bm w}_{t}-{\bm w}_{t})\| \notag \\
    & = \| \nabla f_m({\bm w}_{t})\|. \label{3-73}
\end{align}
By applying the triangle inequality to \eqref{3-70} and \eqref{3-73}, we get
\begin{align}
    \|\bm w^m_{t+1}-\bm w_t\|\leq\frac{1+\gamma}{\bar{\lambda}}\|\nabla f_m(\bm w_t)\|. \label{eq3-79}
\end{align}
From this, we can derive
\begin{align}
    \|\bar{\bm w}_{t+1}-\bm w_t\|
    & \leq\mathbb{E}_m[\|\bm w^m_{t+1}-\bm w_t\|]  \label{eq3-80}                                    \\
    & \leq\frac{1+\gamma}{\bar{\lambda}}\mathbb{E}_m[\|\nabla f_m(\bm w_t)\|]      \notag     \\
    & \leq\frac{1+\gamma}{\bar{\lambda}}\sqrt{\mathbb{E}_m[\|\nabla f_m(\bm w_t)\|^2]} \label{eq3-82} \\
    & \leq\frac{B(1+\gamma)}{\bar{\lambda}}\|\nabla F(\bm w_t)\|, \label{eq3-83}
\end{align}
where \eqref{eq3-80} follows from Jensen's inequality; \eqref{eq3-82} follows from the inequality $\sqrt{\mathbb{E}\left[A^2\right]}\ge \mathbb{E}\left[A\right]$; \eqref{eq3-83} follows from Assumption \ref{assup_dissimilarity}.

Further define $\bm G_{t+1}$ to describe $\bar{\bm w}_{t+1}-\bm w_{t}=\frac{-1}{\lambda}\left(\nabla F(\bm w_{t})+\bm G_{t+1}\right)$, then we have
\begin{align*}
    \bm G_{t+1}=\mathbb{E}_m\left[\nabla f_m(\bm w^m_{t+1})-\nabla f_m(\bm w_t)-\bm e^m_{t+1}\right],
\end{align*}
whose upper bound satisfies
\begin{align}
     \|\bm G_{t+1}\| 
     \le {} & \mathbb{E}_m \left\|\left[\nabla f_m(\bm w^m_{t+1})-\nabla f_m(\bm w_t)-\bm e^m_{t+1}\right] \right\|                     \notag   \\
     \le {} & \mathbb{E}_m\left[ \left\|\nabla f_m(\bm w^m_{t+1})-\nabla f_m(\bm w_t)\|+\|\bm e^m_{t+1} \right\|\right]             \notag       \\
     \le {} & \mathbb{E}_m\left[L\|\bm w^m_{t+1}-\bm w^m_t\|+\|\bm e^m_{t+1}\|\right]                                                   \notag   \\
     \le {} & \left(\frac{L(1+\gamma)}{\bar{\lambda}}+\gamma\right)\times\mathbb{E}_m\left[\|\nabla f_m(\bm w_t)\|\right]  \label{eq3-88} \\
     \le {} & \left(\frac{L(1+\gamma)}{\bar{\lambda}}+\gamma\right)B\|\nabla F(\bm w_t)\|, \label{eq3-89}
\end{align}
where \eqref{eq3-88} follows from \eqref{eq3-79} and \eqref{eq3-66}, and \eqref{eq3-89} is derived in the same manner as \eqref{eq3-83}.

Since $ F $ is a convex combination of the local loss functions $ f_m $, it is also $ L $-Lipschitz smooth, which gives us
\begin{align}
    F(\bar{\bm w}_{t+1})
    \leq {} & F(\bm w_{t})+\langle\nabla F(\bm w_{t}),\bar{\bm w}_{t+1}-\bm w_{t}\rangle \notag  \\
    &+\frac{L}{2}\|\bar{\bm w}_{t+1}-\bm w_{t}\|^{2}   \label{eq3-94}                                                                                \\
    \leq {} & F(\bm w_{t})-\frac1\lambda\|\nabla F(\bm w_{t})\|^{2}-\frac1\lambda\langle\nabla F(\bm w_{t}),\bm G_{t+1}\rangle \notag  \\ 
    &+\frac{L(1+\gamma)^{2}B^{2}}{2\bar{\lambda}^{2}}\|\nabla F(\bm w_{t})\|^{2}                \label{eq3-95} \\
    \leq {} & F(\bm w_{t})-\left(\frac{1-\gamma B}{\lambda}-\frac{LB(1+\gamma)}{\bar{\lambda}\lambda}\right. \notag \\
    & \left. -\frac{L(1+\gamma)^{2}B^{2}}{2\bar{\lambda}^{2}}\right)\times\left\|\nabla F(\bm w_{t})\right\|^{2}, \label{eq3-96}
\end{align}
where substituting the definition of $\bm G_{t+1}$ and \eqref{eq3-83} into \eqref{eq3-94} yields \eqref{eq3-95}, and \eqref{eq3-96} follows from the Cauchy-Schwarz inequality, i.e.,
\begin{align*}
    & -\langle\nabla F(\bm w_{t}),\bm G_{t+1}\rangle \notag \\
    \le {} & \left\|\langle\nabla F(\bm w_{t}),\bm G_{t+1}\rangle \right\|                                                    \\
    \le {} & \left\|\nabla F(\bm w_{t})\right\|\left\|\bm G_{t+1}\right\|                                                    \\
    \le {} & \left\|\nabla F(\bm w_{t})\right\| \left(\frac{L(1+\gamma)}{\bar{\lambda}}+\gamma\right)B\|\nabla F(\bm w_t)\| \\
    = {} & \left(\frac{L(1+\gamma)}{\bar{\lambda}}+\gamma\right)B\|\nabla F(\bm w_t)\|^2.
\end{align*}
\end{myproof}


\begin{myproof}[Proof of Lemma \ref{lemma-6}]
    For simplicity, we omit the superscript $t$ in the following analysis. The $i$-th component of $\hat{\bm \theta}$ satisfies
\begin{align*}
    \hat{\theta}_i
    = {} & \frac{2\left(\sum_{m\in \mathcal{R}}\mathbb{I}\left\{c^m_{i}=1\right\}+\sum_{m\in \mathcal{B}}\mathbb{I}\left\{z^m_{i}=1\right\}\right)-M}{M}b_i                                                                \\
    = {} & \frac{1}{M} \left(2\left(\sum_{m=1}^{M}\mathbb{I}\left\{c^m_{i}=1\right\}+\sum_{i\in \mathcal{B}}\mathbb{I}\left\{z^m_{i}>c^m_{i}\right\} \right.\right. \notag\\
    &- \left.\left. \sum_{i\in \mathcal{B}}\mathbb{I}\left\{z^m_{i}<c^m_{i}\right\}\right)-M\right)b_i,
\end{align*}
where $c^m_{i}$ represents honest quantization results, and $z^m_i$ represents malicious messages, which can take 0 or 1 arbitrarily.

Since the server is unaware of the attacks, it is reasonable to assume that the aggregated values remain unbiased, and the deviation caused by Byzantine attacks satisfies
\begin{align*}
    & \mathbb{E}\left[ \left(\theta_i-\hat{\theta_i}\right)^2\right] \notag \\
    = {} & \mathbb{E}\left[\frac{1}{M} \left(2 \left(\sum_{m=1}^{M}\mathbb{I}\left\{c^m_{i}=1\right\}+\sum_{i\in \mathcal{B}}\mathbb{I}\left\{z^m_{i}>c^m_{i}\right\} \right.\right.\right. \notag \\
    &-\left.\left.\left. \sum_{i\in \mathcal{B}}\mathbb{I}\left\{z^m_{i}<c^m_{i}\right\}\right)-M\right)b_i\right]^2-{\theta_i}^2               \\
    = {} & \mathbb{E}\left[\frac{2\sum_{m=1}^{M}\mathbb{I}\left\{c^m_{i}=1\right\}-M}{M}b_i \right. \notag \\
    & +\left. \frac{2 \left(\sum_{i\in \mathcal{B}}\mathbb{I}\left\{z^m_{i}>c^m_{i}\right\}-\sum_{i\in \mathcal{B}}\mathbb{I}\left\{z^m_{i}<c^m_{i}\right\}\right)}{M}b_i\right]^2 \notag \\
    &-{\theta_i}^2 \\
    \le {} & 2\mathbb{E}\left[\frac{2 \sum_{m=1}^{M}\mathbb{I}\left\{c^m_{i}=1\right\}-M}{M}b_i\right]^2             \notag                                                                                                                                                         \\
    & + 2\mathbb{E}\left[\frac{2}{M} \left(\sum_{i\in \mathcal{B}}\mathbb{I}\left\{z^m_{i}>c^m_{i}\right\} \right.\right. \notag \\
    &\left.\left.-\sum_{i\in \mathcal{B}}\mathbb{I}\left\{z^m_{i}<c^m_{i}\right\}\right)b_i\right]^2-{\theta_i}^2                                                                 \\
    \le {} & 2\left(\mathbb{E}\left[\frac{2 \sum_{m=1}^{M}\mathbb{I}\left\{c^m_{i}=1\right\}-M}{M}b_i\right]^2-{\theta_i}^2\right) \notag \\
    &+2\mathbb{E}\left[2\beta b_i\right]^2+{\theta_i}^2                                                                                          \\
    \le {} & \frac{2\left(b_i^2-\theta_i^2\right)}{M}+8\beta^2 b_i^2+{\theta_i}^2,              
\end{align*}
where the last inequality follows from the analysis of parameter estimation in \eqref{eq3-37}.

Further extrapolating the result to a vector notation, we have
\begin{align}
    & \mathbb{E}\left[\left\|\bm \theta-\hat{\bm \theta}\right\|\right] \notag \\
    \le {} & \sqrt{\mathbb{E}\left[\sum_{i=1}^{d}\left(\theta_i-\hat{\theta}_i\right)^2\right]}             \label{eq3-106}                 \\
    \le {} & \sqrt{\sum_{i=1}^{d} \frac{2\left(b_i^2-\theta_i^2\right)}{M}+8\beta^2 b_i^2+{\theta_i}^2}                              \notag        \\
    \le {} & \sqrt{\|\bm \theta\|^2+8\beta^2\|\bm b\|^2+\frac{2}{M}\left(\|\bm b\|^2-\|\bm \theta\|^2\right)}                       \notag        \\
    \le {} & \|\bm \theta\|+2\sqrt{2}\beta\|\bm b\|+\sqrt{\frac{2}{M}\left(\|\bm b\|^2-\|\bm \theta\|^2\right)}            \label{eq3-104}  \\
    \le {} & \|\bm \theta\|+2\sqrt{2}\beta\|\bm b\|+\sqrt{\frac{4\|\bm b\|_1}{M}\left(1+\frac{1}{\epsilon}\right)\Delta_1},  \label{eq3-105}
\end{align}
where \eqref{eq3-106} follows from the Jensen's inequality; \eqref{eq3-104} follows from the Cauchy-Schwarz inequality; \eqref{eq3-105} follows from the DP requirement in Theorem \ref{dptheorem}, i.e.,
\begin{align*}
    \|\bm b\|^2-\|\bm \theta\|^2
    & = \sum_{i=1}^{d}\left( b_i+\theta_i \right)\left(b_i-\theta_i\right) \\
    & \le 2\left(1+\frac{1}{\epsilon}\right)\Delta_1\sum_{i=1}^{d}b_i      \\
    & = 2\left(1+\frac{1}{\epsilon}\right)\Delta_1 \|\bm b\|_1.
\end{align*}
\end{myproof}

\begin{myproof}[Proof of Lemma \ref{theo_convergence}]
    We utilize Lemma \ref{lemma-5} and Lemma \ref{lemma-6} to prove Lemma \ref{theo_convergence}. 
    Lemma \ref{lemma-5} derives an upper bound of FL convergence rate with lossless FedAvg aggregation on regular clients. However, under the influence of the PRoBit+ transmission mechanism, we need to further consider the impact of quantized transmission and Byzantine attacks.
The quantized aggregated parameter $\bm w_{t+1}$ and the lossless aggregated parameter $\bar{\bm w}_{t+1}$ satisfy
\begin{align}
    & F(\bm w_{t+1})-F(\bar{\bm w}_{t+1}) \notag \\
    \leq {} & L_0\|\bm w_{t+1}-\bar{\bm w}_{t+1}\| \notag   \\
    = {} & L_0\|(\bar{\bm w}_{t+1}-\bm w_t)-(\bm w_{t+1}-\bm w_t)\| \notag \\
    = {} & L_0\|\bm \theta_t-\hat{\bm \theta}^t\|, \label{eqn-1}
\end{align}
where $\bm \theta_t=\bar{\bm w}_{t+1}-\bm w_t$ is the FedAvg aggregation result and $\hat{\bm \theta}^t$ is the PRoBit+ aggregation result with Byzantine attacks and privacy protection. 
Substituting the result of Lemma \ref{lemma-6} back into \eqref{eqn-1}, we get
\begin{align}
    & \mathbb{E}\left[F(\bm w_{t+1})\right]-\mathbb{E}\left[F(\bar{\bm w}_{t+1})\right] \notag \\
    \leq {} & L_0\left(\|\bm \theta_t\|+2\sqrt{2}\beta\|\bm b_t\|+\sqrt{\frac{4\|\bm b_t\|_1}{M}\left(1+\frac{1}{\epsilon}\right)\Delta_1}\right)                \notag                          \\
    \leq {} & \frac{L_0B(1+\gamma)}{\alpha\bar{\lambda}}\|\nabla F(\bm w_t)\|^2 \notag \\
    &+L_0\left(2\sqrt{2}\beta\|\bm b_t\|+\sqrt{\frac{4\|\bm b_t\|_1}{M}\left(1+\frac{1}{\epsilon}\right)\Delta_1}\right). \label{eq3-116}
\end{align}
where \eqref{eq3-116} comes from \eqref{eq3-83} and the rule of stopping the training parameters at the steady-state point, thus the training parameters satisfying $\|\nabla F(\bm w_t)\|> \alpha$.
Combine the above result with Lemma \ref{lemma-5}, we have
\begin{align}
    & \mathbb{E}\left[F(\bm w_{t+1})\right] \notag \\
    \leq {} & \mathbb{E}\left[F(\bm w_{t})\right]-\left(\frac{1-\gamma B}{\lambda}-\left(\frac{L_0}{\alpha}+\frac{L}{\lambda}\right)\frac{B(1+\gamma)}{\bar{\lambda}} \right. \notag \\
    & \left.-\frac{L(1+\gamma)^{2}B^{2}}{2\bar{\lambda}^{2}}\right)\times\left\|\nabla F(\bm w_{t})\right\|^{2} \notag \\
    & +2L_0\left(\sqrt{2}\beta\|\bm b_t\|+\sqrt{\frac{\Delta_1}{M}\left(1+\frac{1}{\epsilon}\right)\|\bm b_t\|_1}\right).
    \label{eq3-118}
\end{align}
\end{myproof}

\section{Proof of Theorem \ref{theorem-3}}\label{theorem-3-proof}

\begin{myproof}[Proof of Theorem \ref{theorem-3}]
    Analyzing the last term of \eqref{eq3-118}, we get
    \begin{align}
        \|\bm b_t\| & = \left\|\bm \theta_t+\bm \zeta\right\|                                                                 \notag     \\
                    & \le \left\|\bm \theta_t\right\|+\left\|\bm\zeta\right\|                                                 \notag    \\
                    & \le \frac{B(1+\gamma)}{\bar{\lambda}}\|\nabla F(\bm w_t)\|+\left\|\bm\zeta\right\|     \label{eq3-123}     \\
                    & \le \frac{B(1+\gamma)}{\bar{\lambda}\alpha}\|\nabla F(\bm w_t)\|^2+\left\|\bm\zeta\right\|, \label{eq3-122}
    \end{align}
    where \eqref{eq3-123} follows from \eqref{eq3-83}, and \eqref{eq3-122} comes from the definition of the steady-state point.
    Therefore, we have
    \begin{align}
        \sqrt{\|\bm b_t\|_1}
         & \le \sqrt{\sqrt{d}\|\bm b_t\|}      \label{eq3-124}                                                                          \\
         & \le \sqrt{\frac{dB(1+\gamma)}{\bar{\lambda}}\|\nabla F(\bm w_t)\|+d\left\|\bm\zeta\right\|}           \notag                        \\
         & \le \sqrt{\frac{dB(1+\gamma)}{\bar{\lambda}}\|\nabla F(\bm w_t)\|}+\sqrt{d\left\|\bm\zeta\right\|}               \notag             \\
         & \le \sqrt{\frac{dB(1+\gamma)}{\bar{\lambda}\alpha^3}}\|\nabla F(\bm w_t)\|^2+\sqrt{d\left\|\bm\zeta\right\|}, \label{eq3-127}
    \end{align}
    where \eqref{eq3-124} follows from the Cauchy-Schwarz inequality. Substituting \eqref{eq3-122} and \eqref{eq3-127} back into \eqref{eq3-118} yields
    \begin{align}
        &\mathbb{E}\left[F(\bm w_{t+1})\right]
        \leq \mathbb{E}\left[F(\bm w_{t})\right]-\rho\left\|\nabla F(\bm w_{t})\right\|^{2} \notag \\
        &+2L_0\left(\sqrt{2}\beta\left\|\bm \zeta\right\|+\sqrt{\frac{\Delta_1}{M}\left(1+\frac{1}{\epsilon}\right)d\left\|\bm\zeta\right\|}\right),
        \label{eq3-129}
    \end{align}
    where
    \begin{align*}
        \rho \triangleq {} & \frac{1-\gamma B}{\lambda}
        -2L_0\sqrt{\frac{\Delta_1}{M}\left(1+\frac{1}{\epsilon}\right)\frac{dB(1+\gamma)}{\bar{\lambda}\alpha^3}} \notag \\
        &-\left(\frac{L_0}{\alpha}+\frac{2\sqrt{2}\beta L_0}{\alpha^2}+\frac{L}{\lambda}\right)\frac{B(1+\gamma)}{\bar{\lambda}} \notag \\
        &-\frac{L(1+\gamma)^{2}B^{2}}{2\bar{\lambda}^{2}} \\
        = {} & \frac{1}{\lambda}-\mathcal{O}\left(B^2\right).
    \end{align*}
    By selecting appropriate $\gamma$, $\lambda$, and $M$ to ensure $\rho>0$, it follows from \eqref{eq3-129} that
    \begin{align*}
        &\frac{1}{T}\sum_{t=1}^{T}\left\|\nabla F(\bm w_{t})\right\|^{2} \le \frac{1}{\rho}\left(\frac{F(\bm w_0)-F^\star}{T}\right. \notag \\
        &+\left. 2L_0\left(\sqrt{2}\beta\left\|\bm \zeta\right\|+\sqrt{\frac{\Delta_1}{M}\left(1+\frac{1}{\epsilon}\right)d\left\|\bm\zeta\right\|}\right)\right).
    \end{align*}
\end{myproof}
}



