    \begin{algorithm}[H]
       \caption{Pseudo-code for Training the $f_{\boldsymbol{\theta}}(\cdot)$}
       \label{alg:VE}
    \begin{algorithmic}[1]
       \STATE   {\bfseries Input:} $f_{\boldsymbol{\theta}}, f_{\boldsymbol{m}}$: initialized encoder and momentum encoder, $queue$: dictionary as a queue of $K$ keys, $m$: momentum, $aug$: random augmentation method, $\tau$: temperature and $\lambda>0$.
       \STATE $f_{\boldsymbol{\theta}}$.params = $f_{\boldsymbol{m}}$.params
       \FOR{$x \in D$}
       \STATE  $x_q, x_k$ = aug($x$), aug($x$) 
       \STATE $ q,k = f_{\boldsymbol{\theta}}(x_q), f_{\boldsymbol{m}}(x_k)$.detach() 
       \STATE $H_q, H_k$ = softmax($q$), softmax($k$)
       \STATE $Q = (H_q+ H_k) / 2$
       \STATE $l_{pos}, l_{neg} = \langle q,k \rangle,  q@k^T$ \\
