       \STATE loss.backward()
       \STATE update($f_{\boldsymbol{\theta}}$.params)
       \STATE \small $f_{\boldsymbol{m}}$.params = m × $f_{\boldsymbol{m}}$.params + (1-m) × $f_{\boldsymbol{\theta}}$.params\\
       \STATE \normalsize enqueue(queue, k)
       \STATE dequeue(queue)
       \normalsize \color{black} \ENDFOR
       \STATE  {\bfseries Output:} $f_{\boldsymbol{\theta}}$
    \end{algorithmic}
    \end{algorithm}
