\subsection{Variational Estimates for \texorpdfstring{$\mathrm{I}(X;Y)$}{} and \texorpdfstring{$\mathrm{H}(X | Y)$}{}} \label{sec:compute_var}



We employ an auxiliary DNN composed of an encoder $f_{\boldsymbol{\theta}}(\cdot)$ and a classifier $g_{\boldsymbol{\psi}}(\cdot)$ to help us finding variational estimates for both $\mathrm{I}(X;Y)$ and $\mathrm{H}(X|Y)$. The encoder transforms the input $X$ into a feature representation $\hat{X}$, and the classifier maps $\hat{X}$ to a probability vector $\hat{Y}$. In this setup, the random variables $\{Y, X, \hat{X}, \hat{Y}\}$ form a Markov chain in the order shown in \cref{fig:MarkovChain} (see \citet{10900607} for more details). Now, in \cref{sec:compute_I} and \cref{sec:compute_H}, we show how this auxiliary DNN can be leveraged to derive variational estimates for $\mathrm{I}(X;Y)$ and $\mathrm{H}(X |Y)$, respectively. Then, in \cref{Sec:trainVE}, we train both  $f_{\boldsymbol{\theta}}(\cdot)$ and $g_{\boldsymbol{\psi}}(\cdot)$ to give us the estimates. 

\subsubsection{Variational Estimates for \texorpdfstring{$\mathrm{I}(X;Y)$}{}} \label{sec:compute_I}



Equipped with $f_{\boldsymbol{\theta}}(\cdot)$ and classifier $g_{\boldsymbol{\psi}}(\cdot)$, in this section we propose a method to find a variational estimation for $\mathrm{I}(X;Y)$. We start by decomposing $\mathrm{I}(X;Y)$ as follows:
\begin{align} \label{Eq:Decompose_I}
\mathrm{I}(X;Y) = \mathrm{I}(\hat{X}; Y) + \mathrm{I}(Y;X|\hat{X}).
\end{align}

The first term on the right-hand side of \cref{Eq:Decompose_I}, namely $\mathrm{I}(\hat{X}; Y)$, is difficult to compute directly. To overcome this difficulty, we introduce the following Proposition:

\begin{proposition}\label{Lemma:ProofInjectiveEq}
Consider a linear classifier $g_{\boldsymbol{\psi}}: \{\hat{X}\rightarrow \hat{Y}| \hat{Y} = \boldsymbol{\psi} \hat{X}\}$, parameterized by $\boldsymbol{\psi}\in \mathbb{R}^{n\times m}$ with $m\geq n$. If $\boldsymbol{\psi}$ has full column rank, then
\begin{align}
    \mathrm{I}(\hat{X}; Y) \;=\; \mathrm{I}(\hat{Y}; Y).
\end{align}    
\end{proposition}
Now, we can write
\begin{align}
    % \mathrm{I}(X;Y) = \mathrm{I}(\hat{X}; Y) + \mathrm{I}(Y;X|\hat{X})\\
    \mathrm{I}(\hat{Y}; Y) &= \mathrm{H}(Y) - \mathrm{H}(Y|
    \hat{Y})\\ \label{eq:yhat}
    &\geq \mathrm{H}(Y) - \mathrm{H}(Y|
    \hat{Y}, Y) \\ \label{eq:yhat2}
    & = \mathrm{H}(Y) + \mathbb{E}_Y \log P_{Y|
    \hat{Y}},
\end{align}
where the inequality in \cref{eq:yhat} becomes equality if $\mathrm{P}_{Y|\hat{Y}} = \mathrm{P}_{Y}$, i.e., the classifier is Bayes-optimal. Now, the quantities in \cref{eq:yhat2} can be easily computed; specifically, $\mathrm{H}(Y)$ is simply the entropy of the ground truth distribution, which is constant for a given dataset., and $\mathbb{E}_Y \log P_{Y|\hat{Y}}$ is the average of cross-entropy of the output, In practice, we use one-hot probabilities to estimate the Bayes probabilities \citep{ye2024bayes}. 

The second term on the right-hand side of \cref{Eq:Decompose_I}, namely $\mathrm{I}(Y; X | \hat{X})$, is difficult to compute directly. In what follows, we propose to minimize this term so that $\mathrm{I}(\hat{X}; Y)$ forms a tight lower bound on $\mathrm{I}(X;Y)$. To motivate this, we first present \cref{prop:I}.


\begin{wrapfigure}{r}{0.6\textwidth}
  \begin{minipage}{0.6\textwidth}
  \vspace{-1.0cm}
    \begin{algorithm}[H]
       \caption{Pseudo-code of IGDS}
       \label{alg:IGDS}
    \begin{algorithmic}[1]
       \STATE   {\bfseries Input:} The number of iterations $N$, $\boldsymbol{y}$, noise levels $\{ \Tilde{\sigma} \}$, pre-trained encoder $f(\cdot)$ and classifier $g(\cdot)$, $\eta>0$, $\beta>0$, $\tau>0$, IPC n, target label $y$.
       \STATE $\boldsymbol{x}_N \sim \mathcal{N} (\mathbf{0}, \mathbf{I})$
       \FOR{$t=N-1, N-2,\dots,0$}
       \STATE  $\hat{\boldsymbol{s}} \leftarrow \boldsymbol{s}_{\theta} (\boldsymbol{x}_t,t)$ 
       \STATE $ \Tilde{\boldsymbol{x}}_0 \leftarrow \frac{1}{\sqrt{\bar\alpha_t}}\left(\boldsymbol{x}_t+(1-\bar\alpha_t)\hat{\boldsymbol{s}} \right)$
       \STATE $\boldsymbol{z} \sim \mathcal{N} (\mathbf{0}, \mathbf{I})$.
       \STATE  $\boldsymbol{x}_{t-1}^\prime \leftarrow \frac{\sqrt{\alpha_t}(1-\bar{\alpha}_{t-1})}{1 - \bar{\alpha}_t}\boldsymbol{x}_t + \frac{\sqrt{\bar{\alpha}_{t-1}}\beta_t}{1 - \bar{\alpha}_t}\Tilde{\boldsymbol{x}}_0 +  {\tilde{\sigma}_t \boldsymbol{z}}$.
       \STATE $\hat{\boldsymbol{x}}_{t-1} = f(\boldsymbol{x}_{t-1}^\prime)$\\
       \STATE $H_{\hat{\boldsymbol{x}}_{t-1}}=SoftMax({\boldsymbol{x}}_{t-1}/\tau)$ \\
       \STATE $Q_{t-1} = \frac{1}{n}\sum H_{\hat{\boldsymbol{x}}_{t-1}}$
       \STATE $\hat{\boldsymbol{y}}_{t-1}=g({\hat{\boldsymbol{x}}}_{t-1})$ \\
       \STATE $\mathcal{L}_{IGDS} = \mathbb{E}\log P_{\hat{y}|y} + \mathrm{H}(\hat{y}) + \beta \mathrm{KL} (H_{\hat{\boldsymbol{x}}_{t-1}}||Q_{t-1})$\\
       \STATE $\boldsymbol{x}_{t-1} \leftarrow \boldsymbol{x}_{t-1}^\prime + \eta \nabla_{\boldsymbol{x}_{t}}  ~  \mathcal{L}_{IGDS}$. \\
       \normalsize \color{black} \ENDFOR
       \STATE  {\bfseries Output:} $\boldsymbol{x}_0$
    \end{algorithmic}
    \end{algorithm}
    \vspace{-1.5cm}
  \end{minipage}
\end{wrapfigure}


\begin{proposition} \label{prop:I}
     For an encoder $f_{\boldsymbol{\theta}}(\cdot)$ parametrized by $\boldsymbol{\theta}$
     \begin{align}
         \min_{\boldsymbol{\theta}} \mathrm{I}(Y;X|\hat{X}) \equiv \max_{\boldsymbol{\theta}} \mathrm{I}(X;\hat{X}).
     \end{align}
\end{proposition}
As per \cref{prop:I}, we shall train $f_{\boldsymbol{\theta}}(\cdot)$ and  $g_{\boldsymbol{\psi}}(\cdot)$ to maximize $\mathrm{I}(X;\hat{X})$. The details of this training process are provided in \cref{Sec:trainVE}. In this manner, we find a variational estimation for $\mathrm{I}(X;Y)$ which we denote by $\underline{\mathrm{I}}(X;Y)$. Particularly, 
\begin{align} \label{I_VIA}
\underline{\mathrm{I}}(X;Y) = \mathrm{H}(\hat{Y}) + \mathbb{E}_Y \log P_{\hat{Y}|Y}.
\end{align}
\subsubsection{Variational Estimates for \texorpdfstring{$\mathrm{H}(X | Y)$}{}} \label{sec:compute_H}





The term $\mathrm{H}(X|Y)$ can be expanded as
\begin{align}
     \mathrm{H}(X|Y) &= \mathrm{I}(X;\hat{X}|Y) + \mathrm{H}(X|\hat{X},Y). 
\end{align}





To compute $\mathrm{I}(X;\hat{X}|Y)$, we introduce the following Proposition.
\begin{proposition} \label{lem:soft}
Assume that the feature representation $\hat{X}$ has zero mean \citep{7410480, Hinton2015DistillingTK}. Then, $\mathrm{I}(X;\hat{X}|Y) = \mathrm{I}(X;\sigma(\hat{X})|Y)$.    
\end{proposition}
Despite $\mathrm{I}(X;\hat{X}|Y)$, the term $\mathrm{I}(X;\sigma(\hat{X})|Y)$ can indeed be calculated analytically using the same approach as used in \citep{10900607, ye2024bayes}:
\begin{align} \label{Eq:LowerBoundOfCMI}
\mathrm{I}(X;\sigma(\hat{X})|Y)  &= \sum_{y\in[C]} P_Y(y)  ~\mathrm{I}(X;\sigma(\hat{X})|y)\\
 & =  \sum_{y\in[C]} P_Y(y) ~ \mathbb{E}_{X|Y}\mathrm{KL}(\sigma(\hat{X})||Q^y)\\
 & =   \mathbb{E}_{X,Y}\mathrm{KL}(\sigma(\hat{X})||Q^Y),  \label{Eq:CMI}
\end{align}





where $Q^y$ can be computed as $\frac{1}{|D_y|}\sum_{x\in D_y} \sigma(\hat{X})$ \citep{10900607}. 

In addition, the term $\mathrm{H}(X|\hat{X},Y)$ is not easy to compute, so we introduce the following proposition to minimize it such that $\mathrm{I}(X;\hat{X}|Y)$ becomes a tight lower bound for $\mathrm{H}(X|Y)$.

\begin{proposition} \label{prop:H}
     For an encoder $f_{\boldsymbol{\theta}}(\cdot)$ parametrized by $\theta$
     \begin{align}
         \min_\theta \mathrm{H}(X|\hat{X},Y) \equiv \max_\theta \mathrm{I}(X;\hat{X}).
     \end{align}
\end{proposition}
As such, we have found a variational estimation for $\mathrm{H}(X|Y)$ which we denote by $\underline{\mathrm{H}}(X|Y)$. Particularly, 
\begin{align} \label{H_VIA}
\underline{\mathrm{H}}(X|Y) = \mathbb{E}_{X,Y}\mathrm{KL}(\sigma(\hat{X})||Q^Y).
\end{align}


\subsubsection{Training Variational Estimator}
\label{Sec:trainVE}




According to \cref{prop:I} and \cref{prop:H}, obtaining tight lower bounds for $\mathrm{I}(X;Y)$ and $\mathrm{H}(X | Y)$, denoted as $\underline{\mathrm{I}}(X;Y)$ and $\underline{\mathrm{H}}(X | Y)$ respectively, requires training $f_{\boldsymbol{\theta}}(\cdot)$ and $g_{\boldsymbol{\psi}}(\cdot)$ to maximize $\mathrm{I}(X;\hat{X})$. We refer to this DNN, which consists of the concatenation of $f_{\boldsymbol{\theta}}(\cdot)$ and $g_{\boldsymbol{\psi}}(\cdot)$, as the variational estimator (VE) since it provides tight estimations $\underline{\mathrm{I}}(X;Y)$ and $\underline{\mathrm{H}}(X | Y)$. The training procedure for the VE is described in this subsection. To establish the theoretical foundation for this approach, we first introduce the following theorem.

\begin{theorem} \label{th:VE}
Consider the mapping $\hat{X}= f_{\boldsymbol{\theta}}(X)$, where $f_{\boldsymbol{\theta}}(\cdot)$ is an encoder parametrized by $\boldsymbol{\theta}$. Then,  
\begin{align} 
\max_{\boldsymbol{\theta}} \mathrm{I}(X; \hat{X}) \equiv \min_{\boldsymbol{\theta}} \big[\mathrm{H}(\tilde{Y}|\hat{X}) - \mathrm{I}(X;\hat{X}|\tilde{Y})\big],  
\end{align}
where $\tilde{Y}$ is an auxiliary random variable denoting the task type.

\end{theorem}

