    \begin{proof} 
    \text{Using the chain rule, the mutual information } \\
    \text{$\mathrm{I}(X;\tilde{Y}, \hat{X})$ can be expanded in two different ways:}
\begin{subequations} 
\begin{align}
\mathrm{I}(X;\tilde{Y}, \hat{X}) & = \mathrm{I}(X;\tilde{Y}|\hat{X}) + \mathrm{I}(X;\hat{X}) \label{eq:I1}\\
\mathrm{I}(X;\tilde{Y}, \hat{X}) & = \mathrm{I}(X;\hat{X}|\tilde{Y}) + \mathrm{I}(X;\tilde{Y}). \label{eq:I2}
\end{align}    
\end{subequations}
By setting the right hand side of \cref{eq:I1} and \cref{eq:I2} equal to each other, we obtain
\begin{align}
    \mathrm{I}(X; \hat{X}) & = \mathrm{I}(X;\tilde{Y}) -\mathrm{I}(X;\tilde{Y}|\hat{X}) +\mathrm{I}(X;\hat{X}|\tilde{Y}) \\
    & = \mathrm{I}(X;\hat{X}; \tilde{Y}) + \mathrm{I}(X;\hat{X}|\tilde{Y}) \label{Eq:InteractionInfor}\\
    & = \mathrm{I}(\hat{X}; \tilde{Y}) + \mathrm{I}(X;\hat{X}|\tilde{Y}) \label{Eq:InteractionInforMarkov}\\
    & = \mathrm{H}(\tilde{Y}) - \mathrm{H}(\tilde{Y}|\hat{X}) + \mathrm{I}(X;\hat{X}|\tilde{Y}), \label{Eq:decoupleEntropy}
\end{align}
where \cref{Eq:InteractionInfor} follows from the definition of interaction information, and \cref{Eq:InteractionInforMarkov} holds because $\tilde{Y}\rightarrow X\rightarrow \hat{X}$ forms a Markov chain. 
\end{proof}

As per \cref{th:VE}, to maximize $\mathrm{I}(X; \hat{X})$ one can instead maximize the three terms: $\mathrm{H}(\tilde{Y})$,   $-\mathrm{H}(\tilde{Y}|\hat{X})$, and $\mathrm{I}(X;\hat{X}|\tilde{Y})$.
In the following, we discuss how to maximize these three terms. 


\noindent $\bullet$ $\mathrm{H}(\tilde{Y})$ depends only on the statistics of the random variable $\tilde{Y}$. In addition, since it is an auxiliary random variable, it can be defined such that $\mathrm{H}(\tilde{Y})$ is maximized. The following Proposition establishes a condition under which $\mathrm{H}(\tilde{Y})$ is maximized.


\begin{proposition} \label{Lemma:MaxHX}
    Given a dataset $\mathcal{D}$, the entropy $\mathrm{H}(\tilde{Y})$ is maximized when each individual sample $x\in \mathcal{D}$ is associated with a unique $\tilde{y}$, and the probability distribution of $\mathrm{P}_{\tilde{Y}} = \frac{1}{|\mathcal{D}|},\ \forall\tilde{y}$.
\end{proposition}
As per \cref{Lemma:MaxHX}, $\mathrm{H}(\tilde{Y})$ is maximized when the task is formulated as an instance discrimination task. 




 \noindent $\bullet$ To maximize $-\mathrm{H}(\tilde{Y}|\hat{X})$, we first note that $\mathrm{H}(\tilde{Y}|\hat{X}) = -\sum P(\hat{x},y) \log P(y|\hat{x})$. Since we formulate the problem as an instant discrimination task, and following \citep{galvez2023role, oord2018representation}, we approximate the conditional probability $P(y|\hat{x})$ as
\begin{align}
    P(\tilde{y}_i|\hat{x}_j) \approx \frac{\exp(\langle \hat{x}_i, \hat{x}_j\rangle / \tau)}{\sum_k \exp(\langle \hat{x}_i, \hat{x}_k\rangle / \tau)},
\end{align}
where $\tau$ is a predetermined hyperparameter, usually referred to as the temperature \citep{he2020momentum}. Then, 
\begin{align}
    \mathrm{H}(\tilde{Y}|\hat{X}) &\leq \mathrm{H}(\tilde{Y}|\hat{X}, \hat{Y}|X) =  -\mathbb{E} \log\left[\frac{\exp(\langle \hat{x}_i, \hat{x}_i\rangle / \tau)}{\sum_k \exp(\langle \hat{x}_i, \hat{x}_k\rangle / \tau)}\right], \label{Eq:InfoNCE}
\end{align}

where the expectation is take over $P_{\tilde{Y}|\hat{X}}$. The conditional entropy can be minimized by minimizing \cref{Eq:InfoNCE}.


\noindent $\bullet$ $\mathrm{I}(X;\hat{X}|\tilde{Y})$ can be maximized by iteratively maximizing \cref{Eq:CMI} and updating the $Q^y = \frac{1}{|D_y|}\sum_{x\in D_y} \sigma(\hat{X})$.
\begin{remark}
\label{Remark:MIdecouple1}
  We acknowledge the similarity between VE and information bottleneck theory \citep{tishby2000information, michael2018on}. In \cref{Appendix:VEandBI}, we elaborate on this connection and derive the objective function using an alternative approach.
\end{remark}

