\section{Weighed Sampling to Generated Subsets with Different \texorpdfstring{$\underline{\mathrm{H}}(X|Y)$}{} values}
\label{Appendix:WeighedSampling}
In this section, we describe how to perform weighted sampling to generate the subset of a dataset with different $\underline{\mathrm{H}}(X|Y)$ values. Given a dataset $\mathcal{D}$ of size $n$ with $C$ classes, $\mathcal{D} = \{(\boldsymbol{x}_i, y_i)\}_{i=1}^n$, where each $\boldsymbol{x}_i \in \mathbb{R}^d$ and $y_i \in [C]$, a pretrained encoder $f(\cdot)$ trained using the VE method on $\mathcal{D}$, and a classifier  $g(\cdot)$, we first filter out all misclassified samples to ensure that the remaining samples’ contextual information can be captured by  $g(f(\cdot))$. In the Shannon sense, the contextual information for each sample within class $y$ is quantified using the $\mathrm{KL}$ divergence $\mathrm{KL}(\sigma(x)||Q^y)$, where $\sigma(x)$ is a probability vector obtained by applying the softmax function to the feature map $\hat{x}$, and $Q^y$ is estimated as $\frac{1}{|D_y|}\sum_{x\in D_y} H$. Given a target $\alpha_{\underline{H}(\cdot|y)}$ value, we compute the probability $\tilde{P}_{X|Y}(\cdot| y)$ of each sample being selected as follows:

\begin{align}
    \tilde{P}_{X|Y}(x| y) = \frac{\exp({-(\mathrm{KL}(\sigma(x)||Q^y)-\alpha_{\underline{H}(\cdot|y)})^2})}{\sum_{x' \in D^y} \exp({-(\mathrm{KL}(\sigma(x')||Q^y)-\alpha_{\underline{H}(\cdot|y)})^2})},
\end{align}
then, IPC samples are drawn from each class according to the probability $\tilde{P}_{X|Y}(\cdot|y)$. We visualize the samples that map to $Q^Y$ using the pretrained encoder $f(\cdot)$ in Figure \ref{fig:CentriodsVis} to enhance understanding of the semantic meaning of prototype information and contextual information.

\section{Proof of Propositions} \label{sec:proofs}
\subsection{Proof of \cref{Lemma:ProofInjectiveEq}}
\label{Appendix:ProofInjective}

\begin{proof}
    We first prove that for any injective function $f$, 
    \begin{align}
        \mathrm{I}(X; Y) = \mathrm{I}(f(X); Y),
    \end{align}
    To do so, we begin by expanding the mutual information $\mathrm{I}(\cdot ; \cdot)$, and introducing the variable $Z = f(X)$:
    \begin{align}
    \mathrm{I}(X; Y) -\mathrm{I}(f(X); Y) &=\mathrm{H}(Y|f(X))- \mathrm{H}(Y|X)  \\
    &= \mathrm{H}(X|f(X)).
    \end{align}
    Since $f$ is injective, for any output $z = f(X)$, there exists a unique $x$ such that $f(x) = z$. Therefore, 
    \begin{align}
      P(X=x|f(X)=z) = \begin{cases}
      1 & \text{if $z = f(x)$},\\
      0 & \text{otherwise}.
    \end{cases} 
    \end{align}
    The conditional entropy is then given by:
    \begin{align}
        \mathrm{H}(X|f(X)) & = \mathbb{E}_{f(X)} [\mathrm{H}(X|f(X) = z)]\\
        & = \mathbb{E}_{f(X)} 0\\
        & = 0.
    \end{align}
    Thus if $f$ is injective, we conclude that $I(Y,f(X)) = I(Y,X)$.

    Next, we show that for a matrix $\theta\in \mathbb{R}^{m,n}, m\geq n$, if $\theta$ has full column rank, then the linear mapping $\{\hat{X}\rightarrow \hat{Y}$, where $\hat{Y} = \theta \hat{X}\}$, is injective.

    A function is injective if:
    \begin{align}
        \theta x_1 = \theta x_2 \Rightarrow x_1 = x_2,
    \end{align}
    Rearranging, introducing $v = x_1-x_2$ we get: $\theta v =0$.
    For injectivity, we must show that the only solution to $\theta v=0$ is $v=0$.

    The set of all solutions to $\theta v =0$ is the null space of $\theta$, denoted as:
    \begin{align}
        Null(\theta) = \{v\in \mathbb{R}^n|\theta v = 0\}.
    \end{align}
    If the linear mapping is injective, the only vector in the null space must be the zero vector, \ie $Null(\theta) = \{0\}$, which means $\theta$ has full column rank.
\end{proof}

We verify that the classifier's matrix after training has full column rank.

\subsection{Proof of \cref{prop:I}}

$\min_\theta \mathrm{I}(Y;X|\hat{X}) \equiv \max_\theta \mathrm{I}(X;\hat{X})  $
\begin{proof}
    \begin{align}
        \mathrm{I}(Y;X|\hat{X})=&\mathrm{I}(Y;X|\hat{X}) \\
        = &\mathrm{H}(X|\hat{X}) - \mathrm{H}(X|Y,\hat{X})\\
         =& \mathrm{H}(X)- \mathrm{H}(X|Y) + \nonumber\\
        &\mathrm{H}(X|\hat{X})- \mathrm{H}(X) \\
         =& \mathrm{I}(X;Y) - \mathrm{I}(X;\hat{X}),
    \end{align}
where $\mathrm{I}(X;Y)$ is a constant, which only depends on the nature of the sampling process, \ie how the dataset is collected and constructed.
\end{proof}

\subsection{Proof of \cref{lem:soft}}
Assume that the feature representation $\hat{X}$ has zero mean. Then, $\mathrm{I}(X;\hat{X}|Y) = \mathrm{I}(X;\sigma(\hat{X})|Y)$. 

\begin{proof}
    The softmax function for an input vector $x\in \mathbb{R}^N$ is define as

\begin{align}
    softmax(x)[i] = \frac{e^{x[i]}}{\sum_{j\in [N]}e^{x[j]}}.
\end{align}

Following the proof of \cref{Lemma:ProofInjectiveEq} in \cref{Appendix:ProofInjective}, we aim to show that the softmax function is injective if its domain is in the subspace with zero mean. Assume two vectors $\ x;y \in \mathbb{R}^N$, such that 
\begin{align}
    \sum_{i\in[N]} x_i = 0,\quad \sum_{i\in[N]}y_i = 0,\\
    \frac{e^{x[i]}}{\sum_{j\in [N]}e^{x[j]}} = \frac{e^{y[i]}}{\sum_{j\in [N]}e^{y[j]}}. \label{Eq:softmaxEq}
\end{align}

Rewriting \cref{Eq:softmaxEq}, 

\begin{align}
    e^{x[i]}{\sum_{j\in [N]}e^{y[j]}} = e^{y[i]} {\sum_{j\in [N]}e^{x[j]}},\ \  \forall i\in[N]. \label{Eq:SoftMaxRearrange}
\end{align}

We define the ratio of $\sum_{j\in [N]}e^{x[j]}$ and $\sum_{j\in [N]}e^{y[j]}$ as:

\begin{align}
    \Theta = \frac{\sum_{j\in [N]}e^{x[j]}}{\sum_{j\in [N]}e^{y[j]}}. \label{Eq:SoftMaxRatio}
\end{align}

Substitute the \cref{Eq:SoftMaxRatio} into \cref{Eq:SoftMaxRearrange} and take logarithm on both sides:

\begin{align}
    x_i = \log \Theta + y_i.
\end{align}
Since both $x$ and $y$ have zero mean, we have:

\begin{align}
    \sum_{i\in[N]} x_i =\sum_{i\in[N]} \log \Theta + y_i = 0,\\
    N\log \Theta = 0,\  \Theta = 1.
\end{align}

Thus $x_i = y_i,\ \forall i\in[N]$. 
\end{proof}

\subsection{Proof of \cref{prop:H}}
\label{Appendix:ProofofEquOptProb}
For a encoder $f$ parametrized by $\theta$.\\

$\min_\theta \mathrm{H}(X|\hat{X},Y) \equiv \max_\theta \mathrm{I}(X;\hat{X})$
\begin{proof}
    \begin{align}
        \mathrm{I}(X;\hat{X}) &= \mathrm{H}(X) - \mathrm{H}(X|\hat{X})\\
        &= \mathrm{H}(X) - \mathrm{H}(X|\hat{X},Y) \label{eq:addCondition}
        % & = \mathrm{H}(X) -  \mathrm{H}(X|\hat{X},Y),
    \end{align}
where $\mathrm{H}(X)$ is a constant, which equals the amount of information in the dataset, \cref{eq:addCondition} is due to $Y\rightarrow X \rightarrow \hat{X}$ forms a Markov chain. 
\end{proof}


\subsection{Proof of \cref{Lemma:MaxHX}}
\label{Sec:ProofMaxHX}
\begin{proof}
    Consider a random variable $Y$, with $N$ classes. Its entropy is given by 
    \begin{align}
        \mathrm{H}(Y) = -\sum_{n\in [N]}P_n \log P_n.
    \end{align}
    Without losing generality, suppose we split the first sample point $y_1$ into two sample points $\hat{y}_a$ and $\hat{y}_b$, such that 
    \begin{align}
        P[{y_1}] &= P[{\hat{y}_a}]+P[{\hat{y}_b}], \\
        &s.t.\ P[{\hat{y}_a}]>0; P[{\hat{y}_b}]>0,
    \end{align}
    This transformation produces a new random variable $\hat{Y}$ with $N+1$ sample points. The change in entropy is then
    \begin{align}
        &\mathrm{H}(\hat{Y})-\mathrm{H}(Y) \\
        = &-P[\hat{y}_b]\log P[\hat{y}_b]-P[\hat{y}_a]\log P[\hat{y}_a]+ P[y_1]\log P[y_1] \\
        = & -P[\hat{y}_b]\log P[\hat{y}_b]-P[\hat{y}_a]\log P[\hat{y}_a]+ \{P[\hat{y}_b]+P[\hat{y}_a]\}\log \{ P[\hat{y}_b]+P[\hat{y}_a] \}\\
        = &-P[\hat{y}_b]\big\{\log P[\hat{y}_b]-\log \{ P[\hat{y}_b]+P[\hat{y}_a] \}\big\}-P[\hat{y}_a]\big\{\log P[\hat{y}_a]-\log \{ P[\hat{y}_b]+P[\hat{y}_a] \}\big\}\\
         >  &0.
    \end{align}
    Thus $\mathrm{H}(\hat{Y}) > \mathrm{H}(Y)$, that is, splitting a single sample point into two distinct points increases the entropy of a random variable. In other words, given a set of samples, the entropy $\mathrm{H}(Y)$ is maximized when each sample is assigned to a unique class. Conversely, for a fixed number of sample points, the entropy is maximized when their probabilities are uniformly distributed. Therefore, the entropy $\mathrm{H}(Y)$ is maximized if the problem is formulated as instance discrimination.
\end{proof}

