\end{center}
\end{figure}
We depict the Venn diagram of which show the relationships between the $\mathrm{H}(X)$, prototype information $\mathrm{I}(X;Y)$, contextual information $\mathrm{H}(X|Y)$ and $\mathrm{I}(\hat{X}; X)$ by the encoder trained by information bottleneck (a) and VE (b) in \cref{Fig:InfoRelation}. 

Information bottleneck aims to minimize the following objective function:
\begin{align}
    \min \mathrm{I}(X; \hat{X}) - \beta \mathrm{I}(\hat{X}; Y),
\end{align}
which can be interoperated as finding a compressed representation $\hat{X}$ of $X$ that retains as much information about $Y$ as possible, while minimizing the information retained from $X$.

While the target of VE differs from the information bottleneck, as it aims to maximize the mutual information $ \mathrm{I}(X; \hat{X})$, as though, the compressed representation $\hat{X}$ retains as much information about $X$ as possible.

\subsection{Alternative Approach to Simplify the Prototype Information}

With a slight abuse of notation, in this section, we refer to $\hat{Y}$  as the label predicted from the feature $\hat{X}$.

\begin{align}
    \mathrm{I}(\hat{X}; Y) &= \mathrm{H}(Y) - \mathrm{H}(Y|\hat{X}) \\
    & \geq \mathrm{H}(Y) -  \mathrm{H}(E) - P(E)\log(|Y|-1) \label{Line:Fano}\\
    & \geq \mathrm{H}(Y) -  \mathrm{H}(E) -  \log(|Y|-1) \mathbb{E}_{X}\Bigg[1-  \sum_{i=1}^{|Y|} P_{Y|X}(i|x)P_{\hat{Y}|X}(i|x)\Bigg] \\
    & =  \mathrm{H}(Y) -  \mathrm{H}(E) - \log(|Y|-1) \mathbb{E}_{X}\Bigg[\sum_{i=1}^{|Y|}  P_{Y|X}(i|x)  \Big[1-P_{\hat{Y}|X}(i|x)\Big]\Bigg] \\
    & \geq \mathrm{H}(Y) -  \mathrm{H}(E) - \log(|Y|-1)  \mathbb{E}_{X}\Bigg[\sum_{i=1}^{|Y|}- P_{Y|X}(i|x)  \log P_{\hat{Y}|X}(i|x) \Bigg] \\
    & = \mathrm{H}(Y) -  \mathrm{H}(E) - \log(|Y|-1)   \mathbb{E}_{X} [\mathrm{H}( P_{Y|X}(i|x), P_{\hat{Y}|X}(i|x))],
\end{align}
where \cref{Line:Fano} follows from \citep{fano1961transmission}, $\log(|Y|-1)$ is a constant, and $\mathrm{H}(E)$ approaches zero when no prediction error occurs.


