%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Explicit formula for $j=s$}\label{sec5}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In this section we will prove an explicit formula for $\E(n\times m, p^s,p^j)$, when $j=s$. It is clear that $\E(n\times 1,p^s,p^s)=1$ since the only possible matrix is the zero matrix.
But, already for the $n\times 2$-case things start to be more complicated compared to the $j<s$ case. The formula can be stated in many different forms, but we will use the form that will be used in the general theorem later in this section.
\begin{proposition}\label{prop:nx2:sej}
	Consider $n\times 2$-matrices modulo $p^s$, where $n\geq 2$. The number of such matrices that have $p^s$ homogeneous solutions is
	\[
		\E(n\times 2,p^s,p^s)=\varphi_n(p^s)\varphi_{n-1}(1)p^{s-1}\binom{2}{1}_p
		+\varphi_{n}(p^{s-1})\varphi_{n-1}(p)p\binom{s-1}{1}_p.
	\]
\end{proposition}
\begin{proof}
	From Proposition \ref{prop:p_reduce} we get
	\[
		\E(n\times 2,p^s,p^s)=\E(n\times 2,p^{s-1},p^{s-2})+\tildeE(n\times 2,p^s,p^s).
	\]
	From Proposition \ref{prop:nx2:gen} we get
	\[
		\E(n\times 2,p^{s-1},p^{s-2})=\varphi_n(p^{s-1})\varphi_{n-1}(p)p\binom{s-1}{1}_p
	\]
	and finally by Proposition \ref{prop:nx2}
	\[
		\tildeE(n\times 2,p^s,p^s)=\varphi_n(p^s)(p^s+p^{s-1})=\varphi_n(p^s)p^{s-1}\binom{2}{1}_p.\qedhere
	\]
\end{proof}

We now consider the general $n\times m$ case where $n\geq m$.

\begin{theorem}\label{thm:main_slj}
Let $n\geq m$.
The number of $n\times m$-matrices that have $p^s$ homogeneous solutions modulo $p^s$ is
	\begin{equation}\label{eq1:thm:main_slj}
		\E(n\times m,p^s,p^s)=\sum_{k=0}^{m-1}\Phi(p^s,k)\binom{m}{k}_p\binom{s-1}{m-1-k}_p p^{a(m,k)s+b(m,k)},
	\end{equation}
	where
	\[
		\Phi(p^s,k)=\varphi_{n-(m-1)}(p^{m-1-k})\prod_{u=k}^{m-2}\varphi_{n-u}(p^{s-1})\prod_{v=0}^{k-1}\varphi_{n-v}(p^s)
	\]
	and
	\[
		a(m,k)=(\frac{m(m-1)}{2}-(m-1-k))\textrm{, }b(m,k)=\frac{(m-k)(m-3k-1)}{2}.
	\]
\end{theorem}

\begin{proof}
	From Proposition \ref{prop:p_reduce} we know
	\[
		\E(n\times m,p^s,p^s)=\tildeE(n\times m,p^s,p^s)+\E(n\times m, p^{s-1},p^{s-m})
	\]
	and from Theorem \ref{thm:main_sgj} we get
	\begin{multline*}
		\E(n\times m, p^{s-1},p^{s-m})\\
		=\varphi_n(p^{s-1})\cdots \varphi_{n-m+2}(p^{s-1})\varphi_{n-m+1}(p^{m-1})
		p^{s\frac{(m-1)(m-2)}{2}+\frac{m(m-1)}{2}}\binom{s-1}{m-1}_p\\
		=\Phi(p^s,0)p^{s a(m,0)+b(m,0)}\binom{m}{0}_p\binom{s-1}{m-1-0}.
	\end{multline*}
	Hence, $\E(n\times m, p^{s-1},p^{s-m})$ is the first term (for $k=0$) in the  sum of \eqref{eq1:thm:main_slj}. So we have left to prove that
	\begin{equation}\label{eq2:thm:main_slj}
		\tildeE(n\times m,p^s,p^s)=\sum_{k=1}^{m-1}\Phi(p^s,k)\binom{m}{k}_p\binom{s-1}{m-1-k}p^{a(m,k)s+b(m,k)}.
	\end{equation}

%Proof by induction


We will prove this by induction on $m$. In fact we will prove that
\begin{multline}\label{eq3:thm:main_slj}
	\tildeE_{m-k}(n\times m, p^s,p^s)\\
	=\sum_{i=1}^{\min(k,m-1)}\Phi_m(p^s,i) p^{s a(m,i)+b(m,i)+(k-i)}
	\binom{s-1}{m-(i+1)}_p\binom{k-1}{i-1}_p
\end{multline}
for $1\leq k\leq m$.

By the formula for $\tildeE_{m-k}$ in \eqref{eq3:thm:main_slj} we can find the desired formula for $\tildeE$ 
in \eqref{eq2:thm:main_slj}. 
In fact, 
\begin{multline*}
	\tildeE(n\times m,p^s,p^s)=\sum_{k=1}^{m}\tildeE_{m-k}(n\times m,p^s,p^s)\\
	=\sum_{k=1}^{m-1} \sum_{i=1}^k\Phi_m(p^s,i) p^{s a(m,i)+b(m,i)+(k-i)}
	\binom{s-1}{m-(i+1)}_p\binom{k-1}{i-1}_p\\
	+\sum_{i=1}^{m-1}\Phi_m(p^s,i) p^{s a(m,i)+b(m,i)+(m-i)}
	\binom{s-1}{m-(i+1)}_p\binom{m-1}{i-1}_p\\
	=\sum_{i=1}^{m-1}\sum_{k=i}^{m}\Phi_m(p^s,i) p^{s a(m,i)+b(m,i)}\binom{s-1}{m-(i+1)}_p p^{k-i}\binom{k-1}{i-1}_p\\
	=\sum_{i=1}^{m-1}\Phi_m(p^s,i) p^{s a(m,i)+b(m,i)}\binom{s-1}{m-(i+1)}_p
	\sum_{k=i}^{m}p^{k-i}\binom{k-1}{i-1}_p.
\end{multline*}
By the properties of the Gaussian coefficients, see \eqref{eq:q-bin_sum} in Section \ref{sec2}, we get
\begin{multline*}
	\sum_{k=i}^{m}p^{k-i}\binom{k-1}{i-1}_p=\sum_{d=0}^{m-i}p^d\binom{d+i-1}{i-1}_p
	\\
	=\sum_{d=0}^{m-i}p^d\binom{d+i-1}{d}_p=\binom{i-1+(m-i)+1}{m-i}_p=\binom{m}{i}_p.
\end{multline*}
Hence,
\[
\tildeE(n\times m,p^s,p^s)=\sum_{i=1}^{m-1}\Phi_m(p^s,i) p^{s a(m,i)+b(m,i)}\binom{s-1}{m-(i+1)}_p\binom{m}{i}_p.
\]
and the theorem will follow.

We now turn to the induction proof of \eqref{eq3:thm:main_slj}
%Base case
For $m=2$ we have (see Proposition \ref{prop:nx2})
\begin{align*}
	\tildeE_{1}(n\times 2,p^s,p^s)=\varphi_n(p^s)p^{s-1}\\
	\tildeE_0(n\times 2,p^s,p^s)=\varphi_n(p^s)p^{s}
\end{align*}
and this corresponds to formulas in \eqref{eq3:thm:main_slj} for $m=2$, $k=1,2$.

Let our induction hypothesis be
\begin{multline*}
	\tildeE_{m-1-k}((n-1)\times (m-1),p^s,p^s)\\
	=\sum_{i=1}^k \Phi_{n-1,m-1}(p^s,i)p^{sa(m-1,i)+b(m-1,i)+k-i}
	\binom{s-1}{(m-1)-(i+1)}_p\binom{k-1}{i-1}_p
\end{multline*}
for $1\leq k\leq m-2$ and for $k=m-1$
\begin{multline*}
\tildeE_0((n-1)\times (m-1),p^s,p^s)\\
=\sum_{i=1}^{m-2} \Phi_{n-1,m-1}(p^s,i)p^{sa(m-1,i)+b(m-1,i)+m-1-i}
	\binom{s-1}{(m-1)-(i+1)}_p\binom{m-2}{i-1}_p.
\end{multline*}

From Proposition \ref{prop:recursion_i} and Theorem \ref{thm:main_sgj} we have
\begin{multline*}
	\tildeE_{m-1}(n\times m,p^s,p^s)=\varphi_n(p^s)(p^{s-1})^{m-1}\E((n-1)\times (m-1),p^{s-1},p^{s-(m-1)})\\
	=\varphi_n(p^s)(p^{s-1})^{m-1}\varphi_{n-1}(p^{s-1})\cdots \varphi_{n-m+2}(p^{s-1})\varphi_{n-m+1}(p^{m-2})\\
	\times p^{(s-1)\frac{(m-1)(m-2)}{2}-(s-(m-1))(m-2)}\binom{s-1}{s-(m-1)}_p\\
	=\Phi_{n,m}(p^s,1)p^{sa(m,1)+b(m,1)}\binom{s-1}{m-2}_p.
\end{multline*}
Again by Proposition \ref{prop:recursion_i} and the induction hypothesis we get for $2 \leq k\leq m-1$
\begin{multline*}
	\tildeE_{m-k}(n\times m,p^s,p^s)=\varphi_n(p^s) (p^{s-1})^{m-k}(p^s)^{k-1}\\
	\times \left(\E((n-1)\times (m-1),p^{s-1},p^{s-(m-1)})+\sum_{t=1}^{k-1}\tildeE_{m-1-t}((n-1)\times (m-1),p^s,p^s)\right)\\
	=\varphi_n(p^s) (p^{s-1})^{m-k}(p^s)^{k-1}\left(\Phi_{n-1,m-1}(p^s,0)p^{s a(m-1,0)+b(m-1,0)}\right.\\	
\left. +\sum_{t=1}^{k-1}\sum_{i=1}^t \Phi_{n-1,m-1}(p^s,i)p^{sa(m-1,i)+b(m-1,i)+(t-i)}
\binom{s-1}{m-1-(i+1)}_p \binom{t-1}{i-1}_p \right)\\
=\Phi_{n,m}(p^s,1)p^{s a(m,1)+b(m,1)+k-1}\binom{s-1}{m-2}_p\\
+\sum_{t=1}^{k-1}\sum_{i=1}^t 
\Phi_{n,m}(p^s,i+1)p^{s a(m,i+1)+b(m,i+1)+k-(i+1) +t-i}\binom{s-1}{m-1-(i+1)}_p \binom{t-1}{i-1}_p\\
=\Phi_{n,m}(p^s,1)p^{s a(m,1)+b(m,1)+k-1}\binom{s-1}{m-2}_p\\
+\sum_{i=1}^{k-1} \Phi_{n,m}(p^s,i+1)p^{s a(m,i+1)+b(m,i+1)+k-(i+1)}\binom{s-1}{m-1-(i+1)}_p
\sum_{t=i}^{k-1}p^{t-i}\binom{t-1}{i-1}_p.
\end{multline*}	
From \eqref{eq:q-bin_sum} in Section \ref{sec2} we now get
\[
	\sum_{t=i}^{k-1}p^{t-i}\binom{t-1}{i-1}_p=\binom{k-1}{i}_p
\]
and by letting $j=i+1$
\begin{multline*}
	\tildeE_{m-k}(n\times m,p^s,p^s)
	=\Phi_{n,m}(p^s,1)p^{s a(m,1)+b(m,1)+k-1}\binom{s-1}{m-2}_p+\\
	\sum_{j=2}^{k} \Phi_{n,m}(p^s,j)p^{s a(m,j)+b(m,j)+k-j}\binom{s-1}{m-1-j}_p\binom{s-1}{j-1}_p\\
	=\sum_{j=1}^{k} \Phi_{n,m}(p^s,j)p^{s a(m,j)+b(m,j)+k-j}\binom{s-1}{m-1-j}_p\binom{s-1}{j-1}_p.
\end{multline*}
A similar computation shows that
\[
	\tildeE_{0}(n\times m,p^s,p^s)=\sum_{j=1}^{m-1} \Phi_{n,m}(p^s,j)p^{s a(m,j)+b(m,j)+m-j}\binom{s-1}{m-1-j}_p\binom{s-1}{j-1}_p.
\]	
We have proved \eqref{eq2:thm:main_slj} by induction and the proof is complete.
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Applications to counting the number of solutions}\label{sec6}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In this section we let $m=n$ and consider the quadratic system $A x\equiv 0\pmod{p^s}$.
Let $\eta(A,p^s)$ denote the number of solutions. In \cite{NilssonNyqvist2009} a formula for $\eta(A,p^s)$ is derived by using Gaussian elimination and reductions, in short the formula is
\[
	\eta(A,p^s)=\gcd(\det(A), p^{s+e}),
\]
for some non-negative integer $e$.

We can easily see that the formula $\eta(A,p^s)=\gcd(\det(A),p^s)$ is true if and only if $\eta(A,p^s)=p^j$ for some $j\leq s$. Hence, the probability that the number of homogeneous solutions to the random $n\times n$-matrix is given by 
$\gcd(\det(A),p^s)$ is
\[
	\P(\eta\leq p^s)=\frac{1}{p^{s n^2}}\sum_{j=0}^{s}\E(n\times n, p^s,p^j).
\]

We will prove in Theorem \ref{thm:main_sum} below that 
\begin{equation}\label{eq:main}
	\sum_{j=0}^{s}\E(n\times n, p^s,p^j)=p^{sn^2}(1-p^{-s-3}+\mathcal{O}(p^{-s-4})),
\end{equation}
where $\mathcal{O}$ is the usual big-Oh notation.
Hence, the probability that the number of solutions to $Ax\equiv 0\pmod{p^s}$ is less or equal to $p^s$ is
\[
	\P(\eta\leq p^s)=1-p^{-s-3}+\mathcal{O}(p^{-s-4}). 
\]

We will divide the proof of \eqref{eq:main} into two main parts. First we will estimate 
$\sum_{j=0}^{s-1}\E(n\times n, p^s,p^j)$ in Proposition \ref{prop:nxn_sgj} and then we estimate $\E(n\times n, p^s,p^s)$ in Proposition \ref{prop:nxn_slj}. We start with some notions that will be used throughout the section.
\begin{definition}
	We set for $1\leq k\leq n$, 
	\[
		S_{n,k}=\prod_{u=k}^n (p^u-1)
	\]
	and                                                                                            
\[
	A_{n,k}=n+(n+1)+\ldots + k=\frac{(n-k+1)(n+k)}{2}.
\]
We also set $A_n=A_{n,1}$ and $S_n=S_{n,1}$.
\end{definition}


We will need estimates of the products of the generalized Euler functions that appear in Theorem \ref{thm:main_sgj} and Theorem \ref{thm:main_slj}.
\begin{lemma}\label{lma:nxn_sgj}
		We have for $j< s$
		\[
			\varphi_1(p^{s-j})\prod_{u=2}^n \varphi_u(p^s)=p^{(s-1)A_n - j}S_{n,1}.
		\]
\end{lemma}
\begin{proof}
From the definition of $\varphi$ we get
	\begin{multline*}
		\varphi_1(p^{s-j})\prod_{u=2}^n \varphi_u(p^s)
			=p^{s-j-1}(p-1)\prod_{u=2}^n (p^{su}-p^{(s-1)u})\\
			=p^{s-j-1}\prod_{u=2}^n p^{(s-1)u}\prod_{u=1}^n (p^u-1)
			=p^{(s-1)A_{n}-j}S_{n,1}.
	\end{multline*}
\end{proof}

Recall that $\Phi(p^s,k)$ in Theorem \ref{thm:main_slj} is defined as
\[
	\Phi(p^s,k)=\varphi_{n-(m-1)}(p^{m-1-k})\prod_{u=k}^{m-2}\varphi_{n-u}(p^{s-1})\prod_{v=0}^{k-1}\varphi_{n-v}(p^s).
\]
For $n=m$ we get
\begin{equation}\label{eq:Phi_nlm}
	\Phi(p^s,k)=\varphi_{1}(p^{n-1-k})\prod_{u=k}^{n-2}\varphi_{n-u}(p^{s-1})\prod_{v=0}^{k-1}\varphi_{n-v}(p^s).
\end{equation}

\begin{lemma}\label{lma:nxn_slj}
	We have
	\[
		\Phi_{n}(p^s,k)=
		\begin{cases}
			p^{s A_{n,2}-2 A_{n,1}}S_{n,1}, \textrm{ if } k=0\\
			p^{s A_{n-2}-A_n - A_{n-k-1}}S_{n,1},\textrm{ if } 1\leq k\leq n-2\\
			p^{(s-1)A_{n,2}} S_{n,2},\textrm{ if } k=n-1.
		\end{cases}
	\]
\end{lemma}
\begin{proof}
For $k=0$ we get from \eqref{eq:Phi_nlm} that
	\begin{multline*}
		\Phi_{n}(p^s,0)=\varphi_1(p^{n-1})\prod_{a=2}^{n} \varphi_a(p^{s-1})\\
		=p^{n-2}(p-1)\prod_{a=2}^n (p^{(s-1)a}-p^{(s-2)a})
		=p^{n-2}\prod_{a=2}^n p^{(s-2)a} S_{n,1}\\
		=p^{s A_{n,2}-2 A_{n,1}}S_{n,1}.
	\end{multline*}
	For $1\leq k\leq n-2$,
	\begin{multline*}
		\Phi(p^s,k)=\varphi_1(p^{n-1-k})\prod_{a=2}^{n-k}\varphi_a(p^{s-1})\prod_{b=n-k+1}^n \varphi_b(p^s)\\
		=p^{n-k-2}(p-1)\prod_{a=2}^{n-k}(p^{(s-1)a}-p^{(s-2)a})\prod_{b=n-k+1}^n (p^{sb}-p^{(s-1)b})\\  
		=p^{n-k-2}p^{(s-2)A_{n-k,2}}p^{(s-1)A_{n,n-k+1}}S_{n,1}\\
		=p^{s A_{n,2}-2 A_{n-k,1}-A_{n,n-k}+n-k} S_{n,1}
		=p^{s A_{n-2}-A_n - A_{n-k-1}}S_{n,1}.
	\end{multline*}
	Finally, for $k=n-1$,
	\begin{multline*}
		\Phi_{n}(p^s,n-1)=\prod_{b=2}^n\varphi_b(p^s)=\prod_{b=2}^n (p^{sb}-p^{(s-1)b})\\
		=p^{(s-1)A_{n,2}}\prod_{b=2}^n(p^b-1)=p^{(s-1)A_{n,2}} S_{n,2}.
	\end{multline*}
\end{proof}
We will also need an expansion of $S_{n,k}$. 
\begin{lemma}\label{nxn:Snk}
	Let $n\geq k \geq 1$ be integers. We have
	\begin{equation}\label{eq:gen_bin}
		\prod_{u=k}^n(p^u-1)=\sum_{j=0}^{n-k+1}(-1)^j p^{A_{n-j,k}}\binom{n-k+1}{j}_p,
	\end{equation}
	where for $0\leq j\leq n-k$
	\[
		A_{n-j,k}=(n-j)+(n-j-1)+\ldots+ (k+1)+ k
	\]
	and for $j=n-k+1$ we let $A_{k-1,k}=0$.
\end{lemma}
\begin{proof}
	We prove this by downwards induction on $k$.
	For $k=n$ the right-hand side of \eqref{eq:gen_bin} is
	\[
		\sum_{j=0}^{1}(-1)^j p^{A_{n-j,n}}\binom{1}{j}_p=p^n-1.
	\]
	Hence true for $k=n$.
	Assume now that true for some specific $k$.
	\begin{multline}
		\prod_{u=k-1}^n(p^u-1)=(p^{k-1}-1)\prod_{u=k}^n (p^u-1)\\
		=(p^{k-1}-1)\sum_{j=0}^{n-k+1}(-1)^j p^{A_{n-j,k}}\binom{n-k+1}{j}_p\\
		\label{eq:sum_gen_bin_2}
		=\sum_{j=0}^{n-k+1}(-1)^j p^{A_{n-j,k}+(k-1)}\binom{n-k+1}{j}_p\\
		-\sum_{j=0}^{n-k+1}(-1)^j p^{A_{n-j,k}}\binom{n-k+1}{j}_p.
	\end{multline}
	If we note that
	\begin{multline*}
		A_{n-j,k}=(n-j)+(n-j-1)+\ldots + k\\
		=(n-(j+1))+ \ldots + k + (k-1) +[n-j-k+1]
	\end{multline*}
	we can rewrite the second sum as
	\begin{multline*}
		\sum_{j=0}^{n-k+1}(-1)^j p^{A_{n-j,k}}\binom{n-k+1}{j}_p\\
		=\sum_{j=0}^{n-k+1}(-1)^j p^{A_{n-(j+1),k-1}}p^{n-j-k+1}\binom{n-k+1}{j}_p\\
		=\sum_{i=1}^{n-k+2}(-1)^{i-1}p^{A_{n-i,k-1}}p^{n-j-k+2}\binom{n-k+1}{i-1}_p.
	\end{multline*}
	Going back to \eqref{eq:sum_gen_bin_2} we get
	\begin{multline*}
		\prod_{u=k-1}^n(p^u-1)
		=p^{A_{n,k-1}}+(-1)^{n-k+2}\\
		+\left(\sum_{j=1}^{n-k+1}(-1)^{j}p^{A_{n-j,k-1}}\left[\binom{n-k+1}{j}+p^{n-j-k+2}\binom{n-k+1}{j-1}\right]\right) 
		\\
		=\sum_{j=0}^{n-k+2} (-1)^j p^{A_{n-j,k-1}}\binom{n-k+2}{j}_p.
	\end{multline*}
	This the the right-hand side of \eqref{eq:gen_bin} when $k$ is replaced by $k-1$.
\end{proof}
We can now get a simplified expression for $\sum_{j=0}^{s-1}\E(n\times n,p^s,p^j)$.
\begin{proposition}\label{prop:nxn_sgj}
With the same notations as before we have
\[
	\sum_{j=0}^{s-1}\E(n\times n,p^s,p^j)=p^{s(n^2-n)-A_{n-1}}S_{n+s-1,s}\\
	=p^{sn^2}\sum_{j=0}^{n}p^{-js-A_{j-1}}\binom{n}{j}_{1/p}.
\]
\end{proposition}
\begin{proof}
First note that
\[
	\binom{n+j-1}{j}_p = p^{(n-1)j}\binom{n+j-1}{j}_{1/p}.
\]
From Theorem \ref{thm:main_sgj} and Lemma \ref{lma:nxn_sgj} we get
\begin{multline*}
	\sum_{j=0}^{s-1}\E(n\times n,p^s,p^j)=\sum_{j=0}^{s-1}p^{sn^2-A_n-j n}S_{n,1}\binom{n+j-1}{j}_p\\
	=p^{s n^2 -A_n} S_{n,1}\sum_{j=0}^{s-1}p^{-jn}\binom{n+j-1}{j}_p
	=p^{s n^2 -A_n} S_{n,1}\sum_{j=0}^{s-1}(1/p)^{j}\binom{n+j-1}{j}_{1/p}\\
	=p^{s n^2 -A_n} S_{n,1}\binom{n+s-1}{s-1}_{1/p}.
\end{multline*}
Here we used \eqref{eq:q-bin_sum} from Section \ref{sec2}  in the last step. Moreover,
\begin{multline*}
	p^{s n^2 -A_n} S_{n,1}\binom{n+s-1}{s-1}_{1/p}
	=p^{s n^2 -A_n} S_{n,1}p^{-(s-1)n}\binom{n+s-1}{n}_{p}\\
	=p^{s n^2-s n -A_{n-1}} S_{n+s-1,s}.
\end{multline*}
By Lemma \ref{nxn:Snk} we get
\[
	S_{n+s-1,s}=\sum_{j=0}^n (-1)^j p^{A_{n+s-1-j,2}}\binom{n}{j}_p.
\]
Observing that 
\[
	A_{n+s-1-j,s}=A_{n-(j+1)}+s(n-j)
\]
for $0\leq j\leq n-1$ and setting $A_{s-1,s}=0$.
we get
\begin{multline*}
	\sum_{j=0}^{s-1}\E(n\times n,p^s,p^j)=p^{sn^2}\sum_{j=0}^n(-1)^j p^{-sn-A_{n-1}}p^{A_{n-(j+1)}+s(n-j)}\binom{n}{j}_p\\
	=p^{sn^2}\sum_{j=0}^n(-1)^j p^{-A_{j-1}-s j}\binom{n}{j}_{1/p},
\end{multline*}
by using that $\binom{n}{j}_p=p^{j(n-j)}\binom{n}{j}_{1/p}$.
\end{proof}

We now try to find a simplified expression for $\E(n\times n, p^s, p^s)$.
\begin{lemma}\label{lma:nxn_Vandermonde}
	We have
	\[
		\sum_{k=\max(0,n-s)}^{n-1}p^{k(s-n+k)}\binom{n}{k}_p\binom{s-1}{n-1-k}_p=\binom{n+s-1}{s}_p.
	\]
\end{lemma}
\begin{proof}
	We re-write the left-hand side as
	\begin{multline*}
		\sum_{i=1}^s p^{(n-i)(s-i)}\binom{n}{n-i}_p\binom{s-1}{i-1}_p
		=\sum_{i=1}^s p^{(n-i)(s-i)}\binom{n}{i}_p\binom{s-1}{s-i}_p\\
		=\sum_{i=0}^s p^{(n-i)(s-i)}\binom{n}{i}_p\binom{s-1}{s-i}_p,
	\end{multline*}
	since $\binom{s-1}{s}_p=0$.
	The so called $q$-Vandermonde identity (also stated in \eqref{eq:q_bin_prod})
	\[
		\sum_{k=0}^h\binom{n}{k}_q\binom{m}{h-k}_q q^{(n-k)(h-k)}=\binom{m+n}{h}_q,
	\]
	can now be used. Let $q=p$, $m=s-1$ and $h=s$ in this formula then
	\[
	\sum_{i=0}^s p^{(n-i)(s-i)}\binom{n}{i}_p\binom{s-1}{s-i}_p=\binom{s-1 +n}{s}_p.
	\]
\end{proof}
\begin{proposition}\label{prop:nxn_slj}
	With the above notations
	\begin{multline*}
		 \frac{\E(n\times n,p^s,p^s)}{p^{sn^2}}=(p^n-1)\sum_{j=0}^{n-1}(-1)^j p^{-n-(j+1)s-A_j}\binom{n-1}{j}_{1/p}\\
		 + p^{-s}\binom{n}{1}_{1/p}\sum_{i=0}^{n-1}(-1)^i p^{-A_{i+1}}\binom{n-1}{i}_{1/p}.
	\end{multline*}
\end{proposition}
\begin{proof}
	For $k=0$ we get the term
	\begin{multline*}
		\Phi(p^s,0)\binom{n}{0}_p\binom{s-1}{n-1}_p p^{s A_{n-2}+A_{n-1}}=
		p^{s A_{n,2}-2 A_n +n}p^{s A_{n-2}+A_{n-1}}S_{n,1}\binom{s-1}{n-1}_p\\
		=p^{s(A_{n,2}+A_{n-2})- A_n}S_{n,1}\binom{s-1}{n-1}_p\\
		=p^{s(n^2-n)-A_n}S_{n,1}\binom{s-1}{n-1}_p
	\end{multline*}
	For $1\leq k \leq n-2$ we get from Lemma \ref{lma:nxn_slj} that
	\begin{multline*}
		\Phi(p^s,k)\binom{n}{k}_p\binom{s-1}{n-1-k}_p p^{s a(n,k)+ b(n,k)}\\
		=p^{s A_{n,2}-A_n-A_{n-k-1}}S_{n,1}\binom{n}{k}_p\binom{s-1}{n-1-k}_p 
		p^{s (A_{n-2}+k) + A_{n-k-1}-k(n-k)}\\
		=p^{s(n^2-n+k)-A_n-k(n-k)}S_{n,1}\binom{n}{k}_p\binom{s-1}{n-1-k}_p\\
		=p^{s(n^2-n)-A_n+k(s-n+k)}S_{n,1}\binom{n}{k}_p\binom{s-1}{n-1-k}_p.
	\end{multline*}

	Finally for $k=n-1$ we get
	\begin{multline*}
		\Phi(p^s,n-1)\binom{n}{n-1}_p\binom{s-1}{0}_p p^{sa(n,n-1)+b(n,n-1))}\\
		=p^{s A_{n,2} - A_{n,2}}S_{n,2}\binom{n}{1}_p p^{sA_{n-1}-(n-1)}
		=p^{s(n^2-n +(n-1))-A_{n}-(n-1)}p S_{n,2}\binom{n}{1}_p.
	\end{multline*}
	We get
	\begin{multline*}
		\E(n\times n,p^s,p^s)=p^{s(n^2-n)-A_n}S_{n,2}\left( (p-1)\sum_{k=0}^{n-2}p^{k(s-n+k)}\binom{n}{k}_p\binom{s-1}{n-1-k}_p\right.\\
		\left.+(p-1) \cdot p^{s(n-1)-(n-1)}\binom{n}{1}_p\binom{s-1}{0}_p-p^{s(n-1)-(n-1)}\binom{n}{1}_p\binom{s-1}{0}_p\right)\\
		=p^{s(n^2-n)-A_n}\left(S_{n,1}\sum_{k=0}^{n-1}p^{k(s-n+k)}\binom{n}{k}_p\binom{s-1}{n-1-k}_p
		+ S_{n,2}p^{(s-1)(n-1)}\binom{n}{1}_p\right)\\
		=p^{s n^2-A_n}\left(S_{n,1}\binom{n+s-1}{s}_p+S_{n,2}p^{(s-1)(n-1)}\binom{n}{1}_p\right),
	\end{multline*}
	by Lemma \ref{lma:nxn_Vandermonde}. Moreover,
	\[
		S_{n,1}\binom{n+s-1}{s}_p=S_{n,1}\binom{n+s-1}{n-1}=(p^n-1)S_{n+s-1,s+1}
	\]
	and by Lemma \ref{nxn:Snk} we get
	\begin{multline}
		\E(n\times n,p^s,p^s)=p^{s(n^2-n)-A_n}\left((p^n-1)\sum_{j=0}^{n-1}(-1)^j p^{A_{n+s-1-j,s+1}}\binom{n-1}{j}_p\right.\\
		+\left.p^{(s-1)(n-1)}\binom{n}{1}_p\sum_{i=0}^{n-1}(-1)^i p^{A_{n-i,2}}\binom{n-1}{i}_p \right)\\
		=p^{s(n^2-n)-A_n}\left((p^n-1)\sum_{j=0}^{n-1}(-1)^j p^{A_{n+s-1-j,s+1}}p^{j(n-1-j)}\binom{n-1}{j}_{1/p} \right.\\
		\left.+ p^{(s-1)(n-1)}p^{n-1}\binom{n}{1}_{1/p}\sum_{i=0}^{n-1}(-1)^i p^{A_{n-i,2}}p^{i(n-1-i)}\binom{n-1}{i}_{1/p} \right).\label{eq:nn1}
	\end{multline}
	Noting that
	\begin{multline*}
		-sn-A_n+A_{n+s-1-j,s+1}-j(n-1-j)\\=-sn-A_n+A_{n-j-1}+ns-(j+1)s -j(n-1-j)
		=-n-(j+1)s-A_j
	\end{multline*}
	and
	\begin{multline*}
	 -sn -A_n + (s-1)(n-1) +(n-1)+A_{n-i,2} +i(n-1-i)\\=-s-n+1 +(n-1)-ni + A_{i-1}-1 +i n-2A_i
	=-s-A_{i+1}
	\end{multline*}
	we can simplify \eqref{eq:nn1} to
	\begin{multline}
		\E(n\times n, p^s,p^s)=p^{sn^2} \left((p^n-1)\sum_{j=0}^{n-1}(-1)^j p^{-n-(j+1)s-A_j}\binom{n-1}{j}_{1/p}\right.\\
		\left. + p^{-s}\binom{n}{1}_{1/p}\sum_{i=0}^{n-1}(-1)^i p^{-A_{i+1}}\binom{n-1}{i}_{1/p}\right).
	\end{multline}
	\end{proof}

We are now ready to prove the main result of this section.
\begin{theorem}\label{thm:main_sum}
The number of $n\times n$-matrices $A$ over $\Z_{p^s}$ such that $Ax=0$ has at most $p^s$ solutions is 
\[
	\sum_{j=0}^{s}\E(n\times n,p^s,p^j)=p^{sn^2}(1- p^{-s-3}+\mathcal{O}(p^{-s-4})).
\]
If the elements in the matrix are chosen uniformly the probability that the number of solutions $\eta$ is at most $p^s$ is
\[
	\P(\eta\leq p^s)=1- p^{-s-3}+\mathcal{O}(p^{-s-4}).
\] 
\end{theorem}
\begin{proof}
	In the estimations below we have used $s\geq 1$ and $n\geq 2$.
	From Proposition \ref{prop:nxn_sgj} we have
	\begin{equation}
		\label{eq:final1}
		\frac{1}{p^{sn^2}}\sum_{j=0}^{s}\E(n\times n,p^s,p^j)=1-p^{-s}\binom{n}{1}_{1/p}+p^{-2s-1}\binom{n}{2}_{1/p}+\mathcal{O}(p^{-s-5}).
	\end{equation}
	From Proposition \ref{prop:nxn_slj} we get 
	\begin{multline}\label{eq:final2}
		\frac{\E(n\times n, p^s,p^s)}{p^{sn^2}}=(p^n-1)\sum_{j=0}^{n-1}(-1)^j p^{-n-(j+1)s-A_j}\binom{n-1}{j}_{1/p}\\
		 + p^{-s}\binom{n}{1}_{1/p}\sum_{i=0}^{n-1}(-1)^i p^{-A_{i+1}}\binom{n-1}{i}_{1/p}\\
		=\sum_{j=0}^{n-1}(-1)^jp^{-(j+1)s-A_j}\binom{n-1}{1}_{1/p}-p^n\sum_{j=0}^{n-1}(-1)^jp^{-(j+1)s-A_j}\binom{n-1}{1}_{1/p}\\
		+p^{-s}(1+p^{-1}+\ldots +p^{-n+1})\left(p^{-1}-p^{-3}\binom{n-1}{1}_{1/p}\right) +\mathcal{O}(p^{-s-4})\\
		=p^{-s}-p^{-2s-1}\binom{n-1}{1}_{1/p} -p^{-n-s}+p^{-s-1}(1+p^{-1}+\ldots +p^{-n+1})\\
		-p^{-s-3}(1+p^{-1}+\ldots +p^{-n+1})(1+p^{-1}+\ldots + p^{-n+2}) +\mathcal{O}(p^{-s-4})\\
		=p^{-s}\binom{n}{1}_{1/p}-p^{-2s-1}\binom{n-1}{1}_{1/p}-p^{-s-3}+\mathcal{O}(p^{s-4}).
	\end{multline}

	By adding \eqref{eq:final1} and \eqref{eq:final2} we finally get
	\begin{multline*}
	 1+p^{-2s-1}\left(\binom{n}{2}_{1/p}-\binom{n-1}{1}_{1/p}\right)-p^{-s-3}+\mathcal{O}(p^{-s-4})\\
	=1-p^{-s-3}+\mathcal{O}(p^{-s-4})
	\end{multline*}
	since
	\[
		\binom{n}{2}_{1/p}-\binom{n-1}{1}_{1/p}=1+p^{-1}+2 p^{-2}+\ldots -1-p^{-1}-p^{-2}-\ldots=p^{-2}+\mathcal{O}(p^{-3})
	\]
	and $2s+3\geq s+4$ for $s\geq 1$.
\end{proof}
\begin{corollary}
	The probability that the formula $\gcd(\det(A),p^s)$ gives the number of solutions to $Ax\equiv 0\pmod{p^s}$ is
	$1- p^{-s-3}+\mathcal{O}(p^{-s-4}).$
\end{corollary}
This follows directly from the theorem and the discussion in the beginning of this section.

\section{Discussion}

% Repeat results 
In this paper we have considered system of equations $Ax=0$ over $\Z_{p^s}$, where $A$ is an $n\times m$-matrix. Especially we have been interested in finding the number of matrices $\E(n\times m,p^s,p^j)$ such that the system have $p^j$ solutions for $0\leq j\leq s$.
We have found different recursive relations for $\E$ as well as explicit formulas for the case $n\geq m$. 
In fact, the recursive relations still hold in the $n< m$ case, but the author has not yet found nice explicit formulas in the general case. However, one could easily prove that
\[
	\E(1\times m, p^s,p^{s(m-1)+r})=\varphi(p^{s-r})p^{(s-r-1)(m-1)}\binom{m}{1}_p
\]
for $0\leq r\leq s-1$.

The author has nor been able to find simple explicit formulas for the $j>s$ case. 
Again the recursive formulas in Section \ref{sec3} can be used to compute $\E(n\times m,p^s,p^j)$ for explicit values of the parameters. But, general expressions seem to be complicated. Note also that for the $n<m$ case, the number of solutions is always 
greater than $p^s$, so $j>s$ is the only interesting case. 
%General modulo          
In this paper we only considered the system of equations modulo a prime power. But by using the Chinese Remainder Theorem we can easily get results for a general modulus $N$. Let $N=\prod p_i^{s_i}$, where $p_i$ different primes. Then
\[
	\E(n\times m,\prod_i p_i^{s_i},\prod_i p_i^{j_i})=\prod_i \E(n\times m,p_i^{s_i},p_i^{j_i}).
\]
Note that the number of possible solutions to $Ax\equiv 0\pmod{N}$ is $\prod_i p^{j_i}$, where
$0\leq j_i\leq s_i m$.


Regarding the results from Section \ref{sec6}. Also here it is possible to somewhat generalize the results to a general modulus $N$. Note that
\[
\gcd(\det(A),\prod_i p_i^{s_i})=\prod_i \gcd(\det(A),p^{s_i})
\]
and that the number of solutions 
\[
	\eta(A,\prod_i p_i^{s_i})=\prod_i\eta(A,p_i^{s_i})=\prod_i\gcd(\det(A),p^{s_i+e_i}),
\]
for some non-negative integers $e_i$.
The formula $\gcd(\det(A),N)$ gives the number of solutions if and only if all the reduced systems modulo $p_i^{s_i}$ have at most $p_i^{s_i}$ solutions. Heuristically the probability that the formula is correct is something like
$1-\sum_i p_i^{-s_i-3}$ but the true estimate depends however much on the number of prime factors and the size of them. 



