\appendix
\section{Proofs of the mathematical identities used}
First recall the generating function of the Legendre polynomials \cite{Askey_1999}
\begin{equation}
\frac{1}{\sqrt{1-2tx+t^2}}=\sum_{n=0}^\infty P_n(x)t^n.
\label{eq3}
\end{equation}
If we take $x=\cos{\theta}=\frac{1}{2}\left (e^{i\theta}+e^{-i\theta}\right)$, then
\begin{equation}
1-2tx+t^2=(t-e^{i\theta})(t-e^{-i\theta})=(1-te^{i\theta})(1-te^{-i\theta}).
\label{eq4}
\end{equation}
Now we can use the binomial theorem \cite{Askey_1999}
\begin{equation}
(1-x)^{-a}=\sum_{n=0}^\infty \frac{(a)_n}{n!}\,x^n,\;\;\;(a)_n=a(a+1)(a+2)\cdots(a+n-1),
\label{eq5}
\end{equation}
and get
\begin{equation}
\frac{1}{\sqrt{1-2tx+t^2}}=\sum_{m=0}^\infty\sum_{k=0}^\infty \frac{\Bigl (\frac{1}{2}\Bigr )_m\Bigl(\frac{1}{2}\Bigr)_k}{m!k!}\,t^{m+k}e^{i(m-k)\theta}.
\label{eq6}
\end{equation}
The double sum can be rearranged by introducing $n=m+k$ and noting that, for a fixed $n$, $k$ changes from $0$ to $n$ (since $m=n-k\ge 0$):
\begin{equation}
\frac{1}{\sqrt{1-2tx+t^2}}= \sum_{n=0}^\infty\sum_{k=0}^n
\frac{\Bigl(\frac{1}{2}\Bigr)_k\Bigl(\frac{1}{2}\Bigr)_{n-k}}{k!(n-k)!}\,e^{i(n-2k)\theta}\,t^{n}. 
\label{eq7}
\end{equation}
Comparing with (\ref{eq3}) and remembering that the left side is real, we get 
\begin{equation}
P_n(\cos{\theta})=\sum_{k=0}^n\frac{\Bigl(\frac{1}{2}\Bigr)_k\Bigl(\frac{1}{2}\Bigr)_{n-k}}{k!(n-k)!}\,\cos{(n-2k)\theta}.
\label{eq8}
\end{equation}
This relation is a special case of expression 6.4.11 for Gegenbauer polynomials from \cite{Askey_1999}.

The second identity is easier to establish. Using $\cos{\theta}=\frac{1}{2}(e^{i\theta}+e^{-i\theta})$ and the binomial theorem, we get
\begin{equation}
\cos^n{\theta}=\frac{1}{2^n}\sum_{k=0}^n \binom{n}{k}e^{i(n-2k)\theta}=
\frac{1}{2^n}\sum_{k=0}^n \binom{n}{k}\cos{(n-2k)\theta}.
\label{A_eq11}
\end{equation}

