\title{The Principle of Redundant Reflection}
\shorttitle{REDUNDANT REFLECTION} 
\author{Martin Metodiev\href{https://orcid.org/0009-0000-9432-3756}{\textcolor[HTML]{A6CE39}{\includegraphics[scale=1]{ORCID-iD_icon_16x16.png}}}\footremember{uca}{Université Clermont Auvergne, Laboratoire de Mathématiques Blaise Pascal}, Maarten Marsman\footremember{uva}{University of Amsterdam, Department of Psychology, Nieuwe Achtergracht 129B, 1018VZ Amsterdam, The Netherlands}, Lourens Waldorp\footrecall{uva}, \\Quentin F. Gronau\footremember{uon}{University of Newcastle, Australia}, and Eric-Jan Wagenmakers\footrecall{uva}}
