    \kappa_{ij}^\phi>0 \hspace{0.5cm}&\Longrightarrow \hspace{0.5cm}x^*_{ij}=0,\label{eq:lem_kappa_ij^phi_1}\\
    \kappa_{ij}^\phi<0 \hspace{0.5cm}&\Longrightarrow\hspace{0.5cm} x^*_{ij}=w_{ij},\label{eq:lem_kappa_ij^phi_2}\\
    0< x^*_{ij}<w_{ij}\hspace{0.5cm} &\Longrightarrow\hspace{0.5cm} \kappa_{ij}^\phi=0,\label{eq:lem_kappa_ij^phi_3}
\end{align}
